/****** Object:  UserDefinedFunction [dbo].[SelectAdminMenuItemsIdList]    Script Date: 6/16/2026 1:20:32 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



create FUNCTION [dbo].[SelectAdminMenuItemsIdList]
(	 
	@MenuItemId int
	,@Limit int	
)
RETURNS nvarchar(max) 
AS
BEGIN
	
	declare @cnt int
	declare @Query nvarchar(max)
	
	set @Query= 'select MenuItemId from AdminMenuItems where MenuItemId = ' + CAST(@MenuItemId as nvarchar(20))	+ ' union '  
	
	while @Limit > 1
	begin
		set @cnt=1
		while @cnt < @Limit
		begin
			set @Query=@Query + 'select MenuItemId from AdminMenuItems where PageParentId IN ('
			set @cnt=@cnt+1
		End
		
		set @Query=@Query + CAST(@MenuItemId as nvarchar(20))
		
		set @cnt=1
		while @cnt < @Limit
		begin
			set @Query=@Query + ')'
			set @cnt=@cnt+1
		End
		
		SET @Limit = @Limit - 1
		
		if(@Limit > 1)
		begin
			set @Query=@Query + '  union  '
		end
	end	
	
	RETURN @Query
	
END













