SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
  
CREATE PROCEDURE [dbo].[AdminDashBoardOrderDetails]  
     (@Items int  
     ,@Qstatus int OUTPUT  
  ,@MembersActiveCount bigint OUTPUT  
  ,@MembersActiveSumAmount decimal(15,2) OUTPUT  
  ,@MembersInActiveCount bigint OUTPUT  
  ,@MembersInActiveSumAmount decimal(15,2) OUTPUT  
  ,@DonationsWeeklyAmount decimal(15,2) OUTPUT  
  ,@DonationsMonthlyAmount decimal(15,2) OUTPUT  
  ,@DonationsWeeklyCount bigint OUTPUT  
  ,@DonationsMonthlyCount bigint OUTPUT)  
          
AS  
BEGIN  
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
 -- interfering with SELECT statements.  
   
 SET NOCOUNT ON;  
  
    -- Insert statements for procedure here  
      
    BEGIN TRY    
    
  -- Members Recently submitted  
  
  IF(@Items <> 0)  
  BEGIN  
    
   SELECT Top(1)   
    M.MemberId    
    ,M.ChapterId     
    ,Title     
    ,Email     
    ,Password     
    ,FirstName     
    ,LastName     
    ,ProfileImage     
    ,Occupation     
    ,SpouseFirstName     
    ,SpouseLastName     
    ,SpouseOccupation     
    ,SpouseEmail     
    ,SpouseCell     
    ,M.Address     
    ,M.City     
    ,M.State     
    ,M.ZipCode     
    ,M.HomePhone     
    ,MobilePhone     
    ,IsApproved     
    ,IsLockedOut     
    ,IsActivated     
    ,DateActivated     
    ,RegistrationGUID     
    ,FailedPasswordAttemptCount    
    ,LastPasswordChangedDate     
    ,LastActivityDate     
    ,MT.MembershipTypeId     
    ,IsVolunteer     
    ,IsTeluguorigin     
    ,Comments     
    ,ReferredBy    
    ,Amount     
    ,TransactionId     
    ,MO.PaymentStatusId     
    ,MO.PaymentMethodId     
    ,(SELECT PaymentMethod FROM PaymentMethods pm1 WHERE pm1.PaymentMethodId=MO.PaymentMethodId)    
    ,(SELECT PaymentStatus FROM PaymentStatus ps WHERE ps.PaymentStatusId=MO.PaymentStatusId)    
    ,AdminComment     
    ,UserComment  
    ,PS.PaymentStatus  
    ,PM.PaymentMethod  
    ,OrderDate     
    ,ExpiryDate    
    ,BankName     
    ,ChequeNo     
    ,ChequeDate     
    ,InsertedTime     
    ,M.UpdatedTime     
    ,Fax    
    ,WebsiteAddress    
    ,Address2    
    ,MT.MembershipType     
    ,MemberSkils    
    FROM Members M    
    INNER JOIN MembershipTypes MT ON MT.MembershipTypeId=M.MembershipTypeId      
    LEFT JOIN MembershipOrders MO ON MO.MemberId=M.MemberId   
    LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId      
    LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=MO.PaymentMethodId      
   -- WHERE M.MemberId <> 0 and M.IsApproved = 1 and PS.PaymentStatus = 'Completed' and MO.ExpiryDate >= CAST(GETUTCDATE() as nvarchar(50))  

     WHERE   
    M.MemberId <> 0   
    AND M.IsApproved = 1   
    AND PS.PaymentStatus = 'Completed'  
 --   AND MO.ExpiryDate >= CAST(GETUTCDATE() AS nvarchar(50)
	
ORDER BY   
    M.InsertedTime DESC  
      
  END  
  
  
  IF(@Items <> 0)  
  BEGIN  
    
   SELECT Top(@Items)   
    M.MemberId    
    ,M.ChapterId     
    ,Title     
    ,Email     
    ,Password     
    ,FirstName     
    ,LastName     
    ,ProfileImage     
    ,Occupation     
    ,SpouseFirstName     
    ,SpouseLastName     
    ,SpouseOccupation     
    ,SpouseEmail     
    ,SpouseCell     
    ,M.Address     
    ,M.City     
    ,M.State     
    ,M.ZipCode     
    ,M.HomePhone     
    ,MobilePhone     
    ,IsApproved     
    ,IsLockedOut     
    ,IsActivated     
    ,DateActivated     
    ,RegistrationGUID     
    ,FailedPasswordAttemptCount    
    ,LastPasswordChangedDate     
    ,LastActivityDate     
    ,MT.MembershipTypeId     
    ,IsVolunteer     
    ,IsTeluguorigin     
    ,Comments     
    ,ReferredBy    
    ,Amount     
    ,TransactionId     
    ,MO.PaymentStatusId     
    ,MO.PaymentMethodId     
    ,(SELECT PaymentMethod FROM PaymentMethods pm1 WHERE pm1.PaymentMethodId=MO.PaymentMethodId)    
    ,(SELECT PaymentStatus FROM PaymentStatus ps WHERE ps.PaymentStatusId=MO.PaymentStatusId)    
    ,AdminComment     
    ,UserComment  
    ,PS.PaymentStatus  
    ,PM.PaymentMethod  
    ,OrderDate     
    ,ExpiryDate    
    ,BankName     
    ,ChequeNo     
    ,ChequeDate     
    ,InsertedTime     
    ,M.UpdatedTime     
    ,Fax    
    ,WebsiteAddress    
    ,Address2    
    ,MT.MembershipType     
    ,MemberSkils    
    FROM Members M    
    INNER JOIN MembershipTypes MT ON MT.MembershipTypeId=M.MembershipTypeId      
    LEFT JOIN MembershipOrders MO ON MO.MemberId=M.MemberId   
    LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId      
    LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=MO.PaymentMethodId      
    --WHERE M.MemberId <> 0 and MO.ExpiryDate < CAST(GETUTCDATE() as nvarchar(50));  
    WHERE M.MemberId <> 0   
  AND MO.ExpiryDate < CAST(GETUTCDATE() AS nvarchar(50))  
ORDER BY M.InsertedTime Desc;  
  
     
      
  END  
  
  --Donation Recently submitted  
  IF(@Items <> 0)  
  BEGIN  
    
   SELECT Top(@Items)   
      
       D.ServiceDonationId  
       ,D.MemberId  
      ,D.ServiceId  
      ,(select ServiceTitle from services where ServiceId=D.ServiceId) as DonationCause  
      ,D.IsActive  
      ,D.Amount  
      ,D.TransactionId  
      ,D.PaymentStatusId  
      ,D.PaymentMethodId  
      ,D.OrderDate  
      ,D.PaymentBy  
      ,D.UpdatedDate  
      ,D.UpdatedBy  
      ,PM.PaymentMethod  
      ,PS.PaymentStatus  
      ,K.FirstName  
      ,K.LastName  
      ,K.Email   
      ,K.PhoneNo   
      FROM ServiceDonations D  
      LEFT JOIN ServiceDonationInfo K ON D.ServiceDonationId=K.ServiceDonationId   
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId  
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId   
          WHERE D.ServiceDonationId <> 0   
        AND D.Amount <> 0  
      ORDER BY D.OrderDate DESC;  
  
        
  
        
      
  END  
  
  --Events Recently submitted  
  IF(@Items <> 0)  
  BEGIN  
  
   SELECT    E.EventId    
              ,E.ChapterId    
     ,E.EventName     
     ,E.StartDate     
     ,E.EndDate     
     ,E.RegistrationStartDate     
     ,E.RegistrationEndDate     
     ,E.BannerUrl     
     ,E.EventCategoryId     
     ,E.MemberCount     
     ,E.Location     
     ,E.City     
     ,E.StateName     
     ,E.ZipCode     
     ,E.EventDetails     
     ,E.ContactEmail     
     ,E.IsRegistration     
     ,E.PageTitle     
     ,E.MetaDescription      
     ,E.MetaKeywords     
     ,E.TopLine     
     ,E.UpdatedBy     
     ,E.UpdatedTime   
     ,E.IsActive   
     ,Flyer     
    ,(Select EC.EventCategory From EventCategories EC where EC.EventCategoryId = E.EventCategoryId) as EventCategory    
     ,(Select Count(*) From EventUserInfo EI where EI.EventId = E.EventId) as UsersCount    
     FROM Events  E     
  
     WHERE E.EventId <> 0 AND E.EventId in (Select Ed.EventId from Events ED Where (CONVERT (DATE,ED.StartDate)  >= CONVERT (DATE,GETDATE()) OR ED.StartDate IS NULL OR CONVERT (DATE, ED.StartDate)  <=  CONVERT (DATE, GETDATE()) OR ED.StartDate IS NULL OR 
ED.EndDate IS NULL) AND ED.EndDate > CONVERT (DATE, GETDATE() ))ORDER BY E.StartDate ASC;  
  
 
  END  
  
  SELECT @MembersActiveCount = COUNT(*) FROM Members M LEFT JOIN MembershipOrders MO ON MO.MemberId=M.MemberId LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId      
    WHERE M.MemberId <> 0 and M.IsApproved = 1 and PS.PaymentStatus = 'Completed' ;  

  SELECT @MembersActiveSumAmount = SUM(MO.Amount) FROM Members M LEFT JOIN MembershipOrders MO ON MO.MemberId=M.MemberId LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId      
    WHERE M.MemberId <> 0 and M.IsApproved = 1 and PS.PaymentStatus = 'Completed' and MO.ExpiryDate >= CAST(GETUTCDATE() as nvarchar(50));  
  
  
     SELECT @MembersInActiveCount = COUNT(*) FROM Members M LEFT JOIN MembershipOrders MO ON MO.MemberId=M.MemberId LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId      
    WHERE M.MemberId <> 0 and MO.ExpiryDate < CAST(GETUTCDATE() as nvarchar(50));  
    
  SELECT @MembersInActiveSumAmount = SUM(MO.Amount) FROM Members M LEFT JOIN MembershipOrders MO ON MO.MemberId=M.MemberId LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId      
    WHERE M.MemberId <> 0 and MO.ExpiryDate < CAST(GETUTCDATE() as nvarchar(50));  
  
  
      SELECT @DonationsWeeklyAmount = SUM(D.Amount) FROM ServiceDonations D  
      LEFT JOIN ServiceDonationInfo K ON D.ServiceDonationId=K.ServiceDonationId   
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId  
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId   
      WHERE D.ServiceDonationId <> 0   
      AND D.Amount <> 0 AND D.OrderDate  > CONVERT(date, getdate() - 7);  
  
  
      SELECT @DonationsMonthlyAmount = SUM(D.Amount) FROM ServiceDonations D  
      LEFT JOIN ServiceDonationInfo K ON D.ServiceDonationId=K.ServiceDonationId   
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId  
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId   
      WHERE D.ServiceDonationId <> 0   
      AND D.Amount <> 0 AND D.OrderDate  > CONVERT(date, getdate() - 30);  
  
      SELECT @DonationsWeeklyCount = COUNT(*) FROM ServiceDonations D  
      LEFT JOIN ServiceDonationInfo K ON D.ServiceDonationId=K.ServiceDonationId   
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId  
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId   
      WHERE D.ServiceDonationId <> 0   
      AND D.Amount <> 0 AND D.OrderDate  > CONVERT(date, getdate() - 7);  
  
  
      SELECT @DonationsMonthlyCount =  COUNT(*) FROM ServiceDonations D  
      LEFT JOIN ServiceDonationInfo K ON D.ServiceDonationId=K.ServiceDonationId   
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId  
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId   
      WHERE D.ServiceDonationId <> 0   
      AND D.Amount <> 0 AND D.OrderDate  > CONVERT(date, getdate() - 30);  

  SELECT 'Chapters' AS TableName, COUNT(*) AS TotalCount FROM Chapters
UNION ALL
SELECT 'Events', COUNT(*) FROM Events
UNION ALL 
SELECT 'Members', COUNT(*) FROM Members
UNION ALL
SELECT 'Donations', COUNT(*) FROM ServiceDonations
UNION ALL
SELECT 'Committees', COUNT(*) FROM Committees
UNION ALL
SELECT 'Volunteers', COUNT(*) FROM Volunteers
UNION ALL
SELECT 'Website Banners', COUNT(*) FROM WebsiteBanners
UNION ALL
SELECT 'Promo Codes', COUNT(*) FROM PromoCodes
;

    
  SELECT @Qstatus = 1;      
    
    END TRY      
    BEGIN CATCH      
  SELECT @Qstatus = -1;      
    END CATCH  
END  
  
  
  
  
  
  
  
  
  
  
  
GO
