SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create PROCEDURE [dbo].[AdminRegistrationCount]
	(@EventId bigint,
    @QStatus int OUTPUT)    
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
   SET NOCOUNT ON;

    -- Insert statements for procedure here

   BEGIN TRY  
	SELECT (select SUM(Count) from EventRegistrationCounts where EventRegistrationTypeId=RT.EventRegistrationTypeId) AS RegistrationCount,
EX.EventRegistrationTypeId,
       RT.Eventid,
       RT.RegistrationTitle as RegistrationType,
       SUM(EX.Amount) as Amount,
       RT.nonmemberamount as Amounts,
       COUNT(CASE WHEN ERC.Status = 'Yes' THEN 1 END) AS Checkin,
	     COUNT(ERT.EventRegTicketId) -
    COUNT(CASE WHEN ERC.Status = 'Yes' THEN 1 END) AS NotCheckedIn
FROM EventUserInfo EU
LEFT JOIN EventRegistrationCounts EX ON EX.EventUserInfoId = EU.EventUserInfoId
LEFT JOIN EventRegistrationTypes RT ON RT.EventRegistrationTypeId = EX.EventRegistrationTypeId and EU.Eventid=RT.Eventid
LEFT JOIN EventRegTickets ERT ON ERT.EventUserInfoId = EU.EventUserInfoId
LEFT JOIN EventRegCheckIn ERC ON ERC.EventRegTicketId = ERT.EventRegTicketId
WHERE EU.PaymentStatusId = 1
  AND EX.Eventid = @EventId
GROUP BY RT.RegistrationTitle, RT.nonmemberamount,RT.Eventid,EX.EventRegistrationTypeId,RT.EventRegistrationTypeId
ORDER BY Amounts ASC;

	
		    SELECT @QStatus = 1;
		
    END TRY
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH		
	 
END

















