				  ,(SELECT CAST((SELECT CAST(RoleName as nvarchar(80)) + ',' FROM Roles R  WHERE RoleId IN (SELECT RoleId FROM UserRoles WHERE RoleId=R.RoleId AND UserId=U.UserId) FOR XML PATH('')) AS NVARCHAR(max))) as RoleName
			  	  ,ChapterId	  
			      FROM Users U  
			      WHERE U.Email = @Email
		 SELECT @QStatus = 1;
		 
    END TRY
    
    BEGIN CATCH
		 SELECT @QStatus = -1;
