/****** Object:  StoredProcedure [dbo].[AllocateSeatForTicket]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create PROCEDURE [dbo].[AllocateSeatForTicket]
    @EventRegTicketId BIGINT,
    @SeatNo NVARCHAR(100),
    @InsertedBy NVARCHAR(256),
    @Notify BIT = 0, -- 1 = Send Email, 0 = No
	@QStatus int output
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        -- 1. Update seat allocation in EventRegTickets
        UPDATE EventRegTickets
        SET SeatNo = @SeatNo,
            InsertedBy = @InsertedBy
        WHERE EventRegTicketId = @EventRegTicketId;

        -- 2. Insert an EventComment log (optional, for tracking)
        INSERT INTO EventComments (EventUserInfoId, Status, Comment, InsertedDate, InsertedBy)
        SELECT 
            T.EventUserInfoId,
            'SeatAllocated',
            'Seat ' + @SeatNo + ' allocated for Ticket ' + T.TicketId,
            GETDATE(),
            @InsertedBy
        FROM EventRegTickets T
        WHERE T.EventRegTicketId = @EventRegTicketId;

        -- 3. Return notification flag so app can trigger email
        SELECT 
            @EventRegTicketId AS TicketId,
            @SeatNo AS SeatNo,
            @Notify AS NotifyStatus;

			SELECT @QStatus =- 1;

    END TRY
    BEGIN CATCH
        DECLARE @ErrorMessage NVARCHAR(4000), @ErrorSeverity INT, @ErrorState INT;
        SELECT 
            @ErrorMessage = ERROR_MESSAGE(),
            @ErrorSeverity = ERROR_SEVERITY(),
            @ErrorState = ERROR_STATE();
        RAISERROR(@ErrorMessage, @ErrorSeverity, @ErrorState);

		SELECT @QStatus = -1;
    END CATCH
END

