GO

CREATE PROCEDURE [dbo].[ApiEventsGetListByVariable] 
	 (@EventStatusId bigint
	 ,@StartDate nvarchar(126)
	 ,@EndDate nvarchar(126)
	 ,@EventType nvarchar(126)
	 ,@Search nvarchar(126)
	 ,@Sort nvarchar(216)
	 ,@PageNo int
     ,@Items int
     ,@Total int OUTPUT
	 ,@ChapterId bigint 
	 ,@MemberId bigint )
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from

			SET NOCOUNT ON;
			
			DECLARE @Start int, @End INT ;
			DECLARE @Query nvarchar(max);
		    
			CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
						,EventId bigint 
						,ChapterId bigint
						,EventName nvarchar(128)
						,StartDate datetime
						,EndDate datetime
						,RegistrationStartDate datetime
						,RegistrationEndDate datetime
						,BannerUrl nvarchar(156)
						,EventCategoryId bigint
						,MemberCount int
						,Location nvarchar(512)
						,City nvarchar(64)
						,StateName nvarchar(64)
						,ZipCode nvarchar(25)
						,EventDetails nvarchar(max)
						,ContactEmail nvarchar(64)
						,IsRegistration bit
						,PageTitle nvarchar(512) 
						,MetaDescription nvarchar(max) 
						,MetaKeywords nvarchar(max)
						,TopLine nvarchar(512)
						,UpdatedBy nvarchar(30)
						,UpdatedTime datetime
						,EventCategory nvarchar(156)
						,UsersCount bigint)
			
			SELECT @Start = (@PageNo - 1) * @Items     
			SELECT @End = @Start + @Items 
			
			SET @Query = 'INSERT INTO #temp 
				  SELECT  Distinct E.EventId
				        ,E.ChapterId 
						,E.EventName 
						,A.StartDate 
						,A.EndDate 
						,E.RegistrationStartDate 
						,E.RegistrationEndDate 
						,E.BannerUrl 
						,E.EventCategoryId 
						,E.MemberCount 
						,E.Location 
						,E.City 
						,E.StateName 
						,E.ZipCode 
						,E.EventDetails 
						,E.ContactEmail 
						,E.IsRegistration 
						,E.PageTitle 
						,E.MetaDescription  
						,E.MetaKeywords 
						,E.TopLine 
						,E.UpdatedBy 
						,E.UpdatedTime
						,EC.EventCategory 
						,(Select Count(*) From EventUserInfo EI where EI.EventId = E.EventId) as UsersCount
				FROM Events  E 
				LEFT JOIN EventCategories EC ON E.EventCategoryId = EC.EventCategoryId 
				LEFT JOIN ChapterEvents CE ON CE.EventId = E.EventId '

				IF(@EventType = 'upcoming')
				BEGIN
					SET @Query = @Query + ' LEFT Join (Select EventId, StartDate, EndDate, ROW_NUMBER() OVER(Partition By EventId ORDER BY StartDate ASC) AS RowNo From EventDates
											Where Convert(Date, EndDate) >= Convert(Date, GetDate())) A on A.RowNo = 1 AND A.EventId = E.EventId '
				END
				ELSE
				BEGIN
					SET @Query = @Query + ' LEFT JOIN (Select EventId, StartDate, EndDate, ROW_NUMBER() OVER(Partition By EventId ORDER BY StartDate DESC) AS RowNo From EventDates) A ON A.RowNo = 1 AND A.EventId = E.EventId  '
				END
				 
				SET @Query = @Query + ' 
				WHERE E.EventId <> 0 '
			
			
				IF(@ChapterId <> 0)
					BEGIN
						If(@ChapterId <> 1) 
							BEGIN
								Set @Query = @Query + ' AND CE.ChapterId = ' + CAST(@ChapterId as nvarchar(64))
							END
					END
				IF(@Search <> '')
					BEGIN
						SET @Query = @Query + ' AND  EventName LIKE ''%' + @Search + '%'''
					END
				IF(@EventType = 'upcoming')
					BEGIN
						SET @Query = @Query + ' AND  (CONVERT (DATE,A.StartDate)  >= CONVERT (DATE,GETDATE()) OR A.StartDate IS NULL OR CONVERT (DATE, A.StartDate)  <=  CONVERT (DATE, GETDATE()) OR A.StartDate IS NULL OR A.EndDate IS NULL) AND A.EndDate >= CONVERT (DATE, GETDATE())' 
					
					END
				ELSE IF(@EventType = 'past')
					BEGIN
						SET @Query = @Query + ' AND CONVERT (DATE, A.EndDate)  < CONVERT (DATE, GETDATE())'
					END
				ELSE IF(@EventType = 'current')
					BEGIN
						SET @Query = @Query + ' AND E.EventId in (Select Ed.EventId from EventDates ED Where CONVERT (DATE, ED.StartDate)  <=  CONVERT (DATE, GETDATE()) AND CONVERT (DATE, ED.EndDate)  >= CONVERT (DATE, GETDATE()))'
					END
			
				IF(@Sort <> '')
				BEGIN
					SET @Query = @Query + ' ORDER BY A.StartDate ASC'
				END
				ELSE
				BEGIN
				SET @Query = @Query + ' ORDER BY A.StartDate DESC'
				END

				EXEC sp_ExecuteSQL @Query;
			 
				SELECT @Total = COUNT(Rid) from #temp 
					
				SELECT  *  FROM #temp WHERE Rid > @Start AND  Rid <= @End
			
				DROP TABLE #temp
	 
END









