BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY		
				  
				
		/*============================================*/
		/*              InnerPages Details			  */
		/*============================================*/
		
		SELECT * FROM InnerPages WHERE IsActive=1 AND dbo.RemoveSpecialChar(Heading, '^a-z0-9') = dbo.RemoveSpecialChar('Welcome Text in HomePage', '^a-z0-9') 
		
		/*============================================*/		
		/*         WebsiteBanners  Details            */  
		/*============================================*/
		
		SELECT * FROM WebsiteBanners WHERE IsActive=1 ORDER BY OrderNo DESC
		
		/*============================================*/
		/*				Upcoming Events Details				  */
		/*============================================*/
		
		SELECT  TOP(6) * FROM Events WHERE (StartDate <= GETDATE() AND EndDate >= GETDATE()) OR (StartDate > GETDATE()) ORDER BY StartDate ASC
		
		
		/*============================================*/
		/*              Sponsors Details			  */
		/*============================================*/
		
		SELECT * FROM Sponsors S	
		INNER JOIN SponsorCategories SC on SC.SponsorCategoryId = S.SponsorCategoryId	
		WHERE S.IsActive = 1 
		ORDER BY  SC.SponsorCategoryId ASC
		
		/*====================================================================*/
		/*								 Video Gallery 		 				  */
		/*====================================================================*/

		Select Top(6) * From Videos Where IsActive = 1 Order By UpdatedTime DESC

		/*============================================*/
		/*				Past Events Details			  */
		/*============================================*/
		
		SELECT  TOP(6) * FROM Events WHERE CONVERT (DATE, EndDate)  < CONVERT (DATE, GETDATE()) ORDER BY StartDate ASC


		/*============================================*/
		/*				Current Events Details		  */
		/*============================================*/
		
		SELECT  TOP(6) * FROM Events WHERE CONVERT (DATE, StartDate)  <=  CONVERT (DATE, GETDATE()) AND CONVERT (DATE, EndDate)  >= CONVERT (DATE, GETDATE()) ORDER BY StartDate ASC
		
		
		SELECT @QStatus = 1;
				
	END TRY
    
    BEGIN CATCH  
       SELECT @QStatus = -1;
    END CATCH 
END








