					,UpdatedBy=@UpdatedBy
					,UpdatedTime=@UpdatedTime
					,BaseUrl=@BaseUrl	
					,UploadPath=@UploadPath		
					,UserUploadPath=@UserUploadPath	
					,UserSiteUrl=@UserSiteUrl		
					,ServerMapUrl=@ServerMapUrl	
