/****** Object:  StoredProcedure [dbo].[AppUserNotificationsInsert]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[AppUserNotificationsInsert] 
    (@NotificationID bigint
	,@Title nvarchar(512)
	,@Body nvarchar(512)
	,@ActivityTobeopen nvarchar(512)
	,@Values nvarchar(512)
	,@DeviceID nvarchar(512)
    ,@NotificationUserId bigint
	,@AppuserId nvarchar(512)
	,@UpdatedBy nvarchar(64)
	,@UpdatedTime datetime
	,@imageurl nvarchar(1024) output
	,@QStatus int output
	) 
AS
BEGIN
	
	SET NOCOUNT ON;

	--BEGIN TRY 
	
		INSERT INTO Notification
		(
			Title,
			Body,
			ActivityTobeopen,
			[Values],
			UpdatedBy,
			UpdatedTime
		)
		VALUES
		(
			@Title,
			@Body,
			@ActivityTobeopen,
			@Values,
			@UpdatedBy,
			@UpdatedTime
		)
		
		SET @NotificationID = SCOPE_IDENTITY();

		IF (@AppuserId <> '')
		BEGIN
			
			DECLARE @AppuserIds bigint
			DECLARE @DeviceIDs nvarchar(512)
			

			DECLARE @table1 TABLE (RowID int not null primary key identity(1,1), col1 bigint)  
			INSERT INTO @table1 (col1) SELECT CONVERT(bigint, part) FROM SplitString(@AppuserId)

			DECLARE @table2 TABLE (RowID int not null primary key identity(1,1), col2 nvarchar(512))  
			INSERT INTO @table2 (col2) SELECT part FROM SplitString(@DeviceID)

			--DECLARE @table3 TABLE (RowID int not null primary key identity(1,1), col3 bigint)  
			--INSERT INTO @table3 (col3) SELECT part FROM SplitString(@NotificationID)


			DECLARE @RowsToProcess int = @@ROWCOUNT
			DECLARE @CurrentRow int = 1

			WHILE @CurrentRow < @RowsToProcess + 1
			BEGIN	
					
				SELECT @AppuserId = col1 FROM @table1 WHERE RowID = @CurrentRow
				SELECT @DeviceID = col2 FROM @table2 WHERE RowID = @CurrentRow
			-- SELECT @NotificationID = col3 FROM @table3 WHERE RowID = @CurrentRow
				INSERT INTO NotificationUser  (NotificationID,AppuserId, DeviceID)
				VALUES (@NotificationID,@AppuserId,@DeviceID)
	    
				SET @CurrentRow = @CurrentRow + 1
			END

			SELECT @QStatus = 1;
		END	 
	
	
	
	
	IF(@imageurl <> 'NA')
		BEGIN
			UPDATE Notification
			   SET  imageurl= CAST(@NotificationID  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@Title, '^a-z0-9') + '.' + @imageurl
			   WHERE NotificationID = @NotificationID
			  
			  SELECT @imageurl = CAST(@NotificationID AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@Title, '^a-z0-9') + '.' + @imageurl	
		END	
		ELSE
		BEGIN
		  SELECT @imageurl=''
		END	
	
	
	
	
	
	
	--END TRY
    
  --  BEGIN CATCH
		--SELECT @QStatus = -1;
  --  END CATCH	
END



