/****** Object:  StoredProcedure [dbo].[AppUsersGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE PROCEDURE [dbo].[AppUsersGetListByVariable]
	 (@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
	SET NOCOUNT ON;
	
	--BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    -- Insert statements for procedure here
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1),
				UserID bigint ,
                 Name nvarchar(512),
                 Email nvarchar(512), 
                Phone nvarchar(512),
                DeviceID nvarchar(512),
                AppVersion nvarchar(512),
                 AppType nvarchar(512),
                 OneSignalID nvarchar(512),
                  Status Bit,
                 Field1 nvarchar(512),
                Field2 nvarchar(512),
                UpdatedBy nvarchar(64) ,

                UpdatedTime datetime )
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             UserID
		        ,Name
				,Email
				,Phone
				,DeviceID 
				,AppVersion
				,AppType 
				,OneSignalID
				,Status
				,Field1
				,Field2
				
				,UpdatedBy
				,UpdatedTime
	             FROM AdminAppUsers 
		WHERE UserID <> 0 '
		
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  Name LIKE ''%' + @Search + '%'''
		END
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	--END TRY
    
 --   BEGIN CATCH  
 --      SELECT @Total = -1; 		   
 --   END CATCH   
END

















































