	,@Email nvarchar(512)
	,@Phone nvarchar(512)
	,@DeviceID nvarchar(512)
	,@AppVersion nvarchar(512)
	,@AppType nvarchar(512)
	,@OneSignalID nvarchar(512)
	,@Status Bit
	,@Field1 nvarchar(512)
	,@Field2 nvarchar(512)
	,@UpdatedBy nvarchar(64)
	,@UpdatedTime datetime
	,@TempleReligiousEvents nvarchar(64)
	,@CulturalEvent nvarchar(64)
	,@TempleAnnouncement nvarchar(64)
	,@QStatus int output) 
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
	SET NOCOUNT ON;

    -- Insert statements for procedure here
    
    --BEGIN TRY
    --BEGIN TRANSACTION
    
        -- Check if the DeviceID already exists
        IF((SELECT COUNT(*) FROM AdminAppUsers WHERE Email = @Email) = 0)
        BEGIN
            INSERT INTO AdminAppUsers VALUES
                       ( @Name
    					,@Email
    					,@Phone 
    					,@DeviceID
    					,@AppVersion 
    					,@AppType
    					,@OneSignalID
    					,@Status
    					,@Field1
    					,@Field2
    					,@UpdatedBy
    					,@UpdatedTime
						,@TempleReligiousEvents
					    ,@CulturalEvent
					   ,@TempleAnnouncement
						
						
						)	
    			
    		--SET @UserID=SCOPE_IDENTITY()	
			SELECT @UserID = SCOPE_IDENTITY()
				
    			
    		SELECT @QStatus = 1;
        END
        
	ELSE
	BEGIN
		UPDATE AdminAppUsers
		   SET  
		             Name=@Name
					,Email=@Email
					,Phone=@Phone
					,DeviceID= @DeviceID
					,AppVersion=@AppVersion
					,AppType =@AppType
					,OneSignalID=@OneSignalID
					,Status=@Status
					,Field1=@Field1
					,Field2=@Field2
					,UpdatedBy=@UpdatedBy
					,UpdatedTime=@UpdatedTime
					,TempleReligiousEvents = @TempleReligiousEvents
					,CulturalEvent= @CulturalEvent
					,TempleAnnouncement= @TempleAnnouncement


		 WHERE Email = @Email
		 		 
		SELECT @QStatus = 2;	
	END
	
	
	
  --  COMMIT TRANSACTION
  --  END TRY
    
  --  BEGIN CATCH    
  --  ROLLBACK TRANSACTION
		--SELECT @QStatus = -1;    
  --  END CATCH    
END

