create PROCEDURE [dbo].[AWSEventsUpdateStatus]
    (@EventId bigint
    ,@QStatus int output)  
        
AS
BEGIN

	SET NOCOUNT ON;

    BEGIN TRY    
    BEGIN TRANSACTION
    
		IF((SELECT IsActive FROM Events WHERE EventId = @EventId) = 1)
			BEGIN
				UPDATE Events SET IsActive = 0 WHERE EventId = @EventId
			END
		ELSE
			BEGIN
				UPDATE Events SET IsActive = 1 WHERE EventId = @EventId
			END		
		
		SELECT @QStatus = 1;
		
	COMMIT TRANSACTION
    END TRY

    BEGIN CATCH
         ROLLBACK TRANSACTION
		 SELECT @QStatus = -1;	 
    END CATCH
    	
END














