CREATE PROCEDURE [dbo].[BalalaParticipantsUpdate]
    (@BalalaParticipantId bigint
    ,@EventId bigint 
	,@BalalaRegistrationId bigint
	,@FirstName nvarchar(156)
	,@LastName nvarchar(156)
	,@Email nvarchar(156)
	,@Age nvarchar(50)
	,@Mobile nvarchar(15)
	,@IsApproved bit 
	,@UpdatedBy nvarchar(64)
	,@UpdatedTime datetime
	,@QStatus int output)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
    
		IF((SELECT COUNT(*) FROM BalalaParticipants WHERE BalalaParticipantId = @BalalaParticipantId) <> 0)
		BEGIN
			UPDATE BalalaParticipants
			   SET
						EventId				=	@EventId
						,BalalaRegistrationId	=	@BalalaRegistrationId
