						,LastName			=	@LastName 
						,Email				=	@Email 
						,Age				=	@Age 
						,Mobile				=	@Mobile 
						,IsApproved			=	@IsApproved 
						,UpdatedBy			=	@UpdatedBy 
						,UpdatedTime		=	@UpdatedTime
			WHERE BalalaParticipantId           =   @BalalaParticipantId
		SELECT @QStatus = 2;
		END
		
	COMMIT TRANSACTION   
    END TRY
    
    BEGIN CATCH 
		ROLLBACK TRANSACTION     
		SELECT @QStatus = -1;    
    END CATCH   
    
END











