CREATE PROCEDURE [dbo].[BalalaRegistrationsInsert]
	(@BalalaRegistrationId	bigint output
	,@ChapterId	bigint	
	,@RegestrationID	nvarchar(512)	
	,@FirstName	nvarchar(512)	
	,@LastName	nvarchar(512)	
	,@EmailId	nvarchar(1024)	
	,@DOB	datetime	
	,@ParentFirstName	nvarchar(512)	
	,@ParentLastName	nvarchar(512)	
	,@ParentRelation	nvarchar(512)	
	,@ParentEmail	nvarchar(1024)	
	,@SchoolGrade	nvarchar(256)	
	,@Gender	nvarchar(125)	
	,@PrimaryPhoneNumber	nvarchar(125)	
	,@AlternativePhoneNumber	nvarchar(125)	
	,@Address1	nvarchar(MAX)	
	,@Address2	nvarchar(MAX)	
	,@City	nvarchar(256)	
	,@State	nvarchar(256)	
	,@ZipCode	nvarchar(125)	
	,@CompetitionCategory1	nvarchar(512)	
	,@CompetitionCategory2	nvarchar(512)	
	,@TotalAmount	decimal(15, 2)	
	,@IsActive	bit	
	,@TransactionId	nvarchar(128)	
	,@PaymentStatusId	bigint	
	,@PaymentMethodId	bigint	
	,@OrderDate	datetime	
	,@PaymentBy	nvarchar(2048)	
	,@InsertedBy	nvarchar(30)	
	,@InsertedDate	datetime	
	,@UpdatedBy	nvarchar(30)	
	,@UpdatedDate	datetime	
	,@QStatus int output
	,@EventId bigint
	,@RegistrationCategoryId bigint)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;

    IF((SELECT COUNT(*) FROM BalalaRegistrations WHERE BalalaRegistrationId = @BalalaRegistrationId) = 0)
    BEGIN
        INSERT INTO BalalaRegistrations VALUES
            (@ChapterId		
			,@RegestrationID		
			,@FirstName		
			,@LastName	
			,@EmailId
			,@DOB		
			,@ParentFirstName	
			,@ParentLastName
			,@ParentRelation		
			,@ParentEmail
			,@SchoolGrade		
			,@Gender		
			,@PrimaryPhoneNumber
			,@AlternativePhoneNumber	
			,@Address1	
			,@Address2	
			,@City		
			,@State	
			,@ZipCode		
			,@CompetitionCategory1		
			,@CompetitionCategory2	
			,@TotalAmount	
			,@IsActive		
			,@TransactionId	
			,@PaymentStatusId		
			,@PaymentMethodId		
			,@OrderDate		
			,@PaymentBy	
			,@InsertedBy
			,@InsertedDate		
			,@UpdatedBy		
			,@UpdatedDate
			,@EventId
			,@RegistrationCategoryId)
			
		SET @BalalaRegistrationId=SCOPE_IDENTITY()		
			
		SELECT @QStatus = 1;	
	END
	ELSE
		BEGIN
			    UPDATE BalalaRegistrations
			    SET ChapterId=@ChapterId,		      
				RegestrationID = @RegestrationID,		
				FirstName = @FirstName	,	
				LastName = @LastName,	
				EmailId = @EmailId,
				DOB = @DOB		,
				ParentFirstName = @ParentFirstName	,
				ParentLastName = @ParentLastName,
				ParentRelation = @ParentRelation	,	
				ParentEmail = @ParentEmail,
				SchoolGrade = @SchoolGrade	,	
				Gender = @Gender	,	
				PrimaryPhoneNumber = @PrimaryPhoneNumber,
				AlternativePhoneNumber = @AlternativePhoneNumber	,
				Address1 = @Address1	,
				Address2 = @Address2	,
				City = @City	,	
				State = @State	,
				ZipCode = @ZipCode,		
				CompetitionCategory1 = @CompetitionCategory1,		
				CompetitionCategory2 = @CompetitionCategory2,	
				TotalAmount = @TotalAmount,	
				IsActive = @IsActive,		
				TransactionId = @TransactionId,	
				PaymentStatusId = @PaymentStatusId,		
				PaymentMethodId = @PaymentMethodId,		
				OrderDate = @OrderDate,		
				PaymentBy = @PaymentBy,	
				InsertedBy = @InsertedBy,
				InsertedDate = @InsertedDate,		
				UpdatedBy = @UpdatedBy,		
				UpdatedDate = @UpdatedDate,
				EventId = @EventId,
				RegistrationCategoryId = @RegistrationCategoryId
			    WHERE BalalaRegistrationId = @BalalaRegistrationId
		 		 
			    SELECT @QStatus = 2;	
		END 
END












