/****** Object:  StoredProcedure [dbo].[CancelMemberSubscription]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[CancelMemberSubscription]    
    @MemberId   BIGINT,    
    @QStatus    INT OUTPUT    
AS    
BEGIN    
    SET NOCOUNT ON;    
    
    -- =============================================    
    -- Cancel MemberSubscriptions    
    -- =============================================    
    IF EXISTS (SELECT 1 FROM [dbo].[MemberSubscriptions] WHERE [MemberId] = @MemberId)    
    BEGIN    
        -- Row exists → UPDATE to Cancelled    
        UPDATE [dbo].[MemberSubscriptions]    
        SET     
            [RecurringType]      = 'Cancelled',    
            [RecurringAmount]    = 0,    
            [RecurringStartTime] = NULL    
        WHERE    
            [MemberId] = @MemberId;    
    
        SET @QStatus = CASE WHEN @@ROWCOUNT > 0 THEN 1 ELSE 0 END;    
    END    
    ELSE    
    BEGIN    
        -- No row found → No subscription exists    
        SET @QStatus = 2;    
    END    
    
  
END
