/****** Object:  StoredProcedure [dbo].[ChaptersGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE  PROCEDURE [dbo].[ChaptersGetListByVariable]  

	 (@Search nvarchar(128)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
	 
     ,@Total int output
	 ,@ChapterId bigint
	 
	 )

AS

BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from

	SET NOCOUNT ON;
	BEGIN TRY
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
						  ,ChapterId bigint
						  ,ChapterName  nvarchar(512)
						  ,ShortName  nvarchar(512)
						  ,ShortDescription  nvarchar(max)
						  ,Description  nvarchar(max)
						  ,Address  nvarchar(1024)
						  ,City  nvarchar(512)
						  ,State  nvarchar(512)
						  ,ZipCode  nvarchar(512)
						  ,IsActive bit
						  ,OrderNo bigint
						  ,UpdatedBy nvarchar(512)
						  ,UpdatedDate datetime)
						
	SELECT @Start = (@PageNo - 1) * @Items  

	SELECT @End = @Start + @Items 

	SET @Query = 'INSERT INTO #temp Select
	 
				 C.ChapterId
				,C.ChapterName
				,C.ShortName
				,C.ShortDescription
				,C.Description
				,C.Address
				,C.City
				,C.State
				,C.ZipCode
				,C.IsActive
				,C.OrderNo
				,C.UpdatedBy
				,C.UpdatedDate
				from Chapters  C
				WHERE  C.ChapterId <> 0 '







		   IF(@ChapterId <> 1)
			BEGIN
				SET @Query = @Query + ' AND C.ChapterId = ' + CAST(@ChapterId AS nvarchar(30));
			END     

		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  C.ChapterName LIKE ''%' + @Search + '%'' OR C.ShortName LIKE ''%' + @Search + '%'' OR C.City LIKE ''%' + @Search + '%'' OR C.State LIKE ''%' + @Search + '%'''
		END
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END

		EXEC sp_ExecuteSQL @Query;

		print @Query

		SELECT @Total = COUNT(Rid) from #temp 

		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End

		DROP TABLE #temp
	END TRY

    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   

END











