CREATE PROCEDURE [dbo].[ChaptersUpdateStatus]
    (@ChapterId bigint
    ,@QStatus int output)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY    
    BEGIN TRANSACTION
    
		IF((SELECT IsActive FROM Chapters WHERE ChapterId = @ChapterId) = 1)
			BEGIN
