/****** Object:  StoredProcedure [dbo].[CommitteeCategoriesGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[CommitteeCategoriesGetListByVariable]
	 (@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    -- Insert statements for procedure here
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,CommitteeCategoryId bigint
				,CategoryName nvarchar(512)
				,Type nvarchar(128)
				,DisplayOrder int
				,IsActive bit
				,Year nvarchar(256)
				,UpdatedBy nvarchar(64)
				,UpdatedTime datetime
				,CommitteeMemberCount bigint
				)

				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp  SELECT 
		          C.CommitteeCategoryId
		         ,C.CategoryName
				 ,C.Type
				 ,C.DisplayOrder
				 ,C.IsActive
				 ,C.Year
				 ,C.UpdatedBy
				 ,C.UpdatedTime
				 ,(SELECT COUNT(*) FROM CommitteeMembers CM WHERE CM.CommitteeCategoryId = C.CommitteeCategoryId) AS CommitteeMemberCount
		FROM CommitteeCategories C		
		WHERE C.CommitteeCategoryId <> 0 '
		
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  C.CategoryName LIKE ''%' + @Search + '%'''
		END
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END












