SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[CommitteeCategoriesInsert]
    (@CommitteeCategoryId bigint
    ,@CategoryName nvarchar(512)
    ,@Type nvarchar(128)
    ,@DisplayOrder int
    ,@IsActive bit
	,@Year nvarchar(256)
    ,@UpdatedBy nvarchar(64)
    ,@UpdatedTime datetime
	,@QStatus int output
	,@ChapterIds nvarchar(2048))  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
    IF((SELECT COUNT(*) FROM CommitteeCategories WHERE CommitteeCategoryId = @CommitteeCategoryId or CategoryName=@CategoryName) = 0)
			BEGIN
				INSERT INTO CommitteeCategories VALUES
					(@CategoryName
					,@Type
					,@DisplayOrder
					,@IsActive
					,@Year
					,@UpdatedBy
					,@UpdatedTime)	
			
					SET @CommitteeCategoryId=SCOPE_IDENTITY()
			
				SELECT @QStatus = 1;	
			END
	ELSE
			BEGIN
				UPDATE CommitteeCategories
				   SET CategoryName=@CategoryName,
					   Type=@Type,
					   DisplayOrder=@DisplayOrder,
					   IsActive=@IsActive,
					   Year = @Year,
					   UpdatedBy=@UpdatedBy,
					   UpdatedTime=@UpdatedTime
				 WHERE CommitteeCategoryId = @CommitteeCategoryId
		 		 
				 SELECT @QStatus = 2;	
			END




	IF(@ChapterIds<>'')
			BEGIN
				DECLARE @RowCount1 AS int
				DECLARE @CurrentRow1 AS int	
				DECLARE @table1 TABLE (RowID int not null primary key identity(1,1), col1 int )  

				INSERT into @table1 (col1) SELECT part FROM SplitString(@ChapterIds)

				DELETE ChapterCommittees WHERE CommitteeCategoryId = @CommitteeCategoryId

				IF((Select Count(*) From @table1) <> 0)
					BEGIN
						Set @RowCount1 = (Select Count(*) From @table1)
						SET @CurrentRow1 = 1
						WHILE @CurrentRow1 < @RowCount1 + 1 
						BEGIN
							INSERT INTO ChapterCommittees VALUES
							((select col1 from @table1 where RowID = @CurrentRow1)
							,@CommitteeCategoryId
							,1
							,1
							,@UpdatedBy
							,@UpdatedTime)

							SET @CurrentRow1 = @CurrentRow1 + 1
						END
					END
			END
    COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH    
		ROLLBACK TRANSACTION
			SELECT @QStatus = -1;    
    END CATCH    
END











