		SET NOCOUNT ON;
		    

		SELECT CommitteeCategoryId
			  ,CategoryName
			  ,YearId  
			  ,PageLevel
			  ,PageParentId
			  ,IdPath 
			  ,Position
			  ,IsActive
			  ,UpdatedBy
			  ,UpdatedDate
			  ,InsertedBy
			  ,InsertedDate
			  ,(SELECT IsActive FROM CommitteeCategoryMaster CM WHERE CM.CommitteeCategoryId = c.PageParentId) AS ParentActive 
