CREATE PROCEDURE [dbo].[CommitteeCategoryMasterInsert]
    (@CommitteeCategoryId bigint
    ,@CategoryName nvarchar(512) 
	,@YearId bigint 
	,@PageParentId bigint 
	,@Position int						
	,@IsActive bit
	,@InsertedBy nvarchar(64)
	,@InsertedDate datetime
	,@UpdatedBy nvarchar(64)
	,@UpdatedDate datetime
	,@ChapterIds nvarchar(2048)
	,@QStatus int OUTPUT
	)  
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
    --BEGIN TRY
    --BEGIN TRANSACTION
		DECLARE @IdPath nvarchar(512)
		DECLARE @PageLevel int
		
		IF((SELECT COUNT(*) FROM CommitteeCategoryMaster WHERE CommitteeCategoryId = @CommitteeCategoryId) = 0)
			BEGIN
				INSERT INTO CommitteeCategoryMaster VALUES
						(@CategoryName
						,@YearId
						,NULL
						,@PageParentId
						,NULL 
						,@Position
						,@IsActive
						,@InsertedBy
						,@InsertedDate
						,@UpdatedBy
						,@UpdatedDate
						)
			 
				 SELECT @CommitteeCategoryId =  SCOPE_IDENTITY()
			 
				 IF(@PageParentId IS NULL)
					 BEGIN
						UPDATE CommitteeCategoryMaster SET IdPath = CAST(@CommitteeCategoryId as nvarchar(20)), PageLevel = 1  WHERE CommitteeCategoryId = @CommitteeCategoryId			
					 END
				 ELSE
					 BEGIN
						SELECT @IdPath = IdPath, @PageLevel = PageLevel + 1 FROM CommitteeCategoryMaster WHERE CommitteeCategoryId = @PageParentId
						UPDATE CommitteeCategoryMaster SET IdPath = @IdPath + '/' + CAST(@CommitteeCategoryId as nvarchar(20)), PageLevel = @PageLevel WHERE CommitteeCategoryId = @CommitteeCategoryId						 
					 END
			 
				 SELECT @QStatus = 1;	
			END
		ELSE
			BEGIN
				UPDATE CommitteeCategoryMaster
				   SET  CategoryName = @CategoryName
					   ,YearId=@YearId 
					   ,PageParentId=@PageParentId 
					   ,Position = @Position
					   ,UpdatedBy=@UpdatedBy
					   ,UpdatedDate=@UpdatedDate
					  
				WHERE CommitteeCategoryId = @CommitteeCategoryId
			
				 IF(@PageParentId IS NULL)
					 BEGIN
						UPDATE CommitteeCategoryMaster SET IdPath = CAST(@CommitteeCategoryId as nvarchar(20)), PageLevel = 1  WHERE CommitteeCategoryId = @CommitteeCategoryId			
					 END
				 ELSE
					 BEGIN
						SELECT @IdPath = IdPath, @PageLevel = PageLevel + 1 FROM CommitteeCategoryMaster WHERE CommitteeCategoryId = @PageParentId
						UPDATE CommitteeCategoryMaster SET IdPath = @IdPath + '/' + CAST(@CommitteeCategoryId as nvarchar(20)), PageLevel = @PageLevel WHERE CommitteeCategoryId = @CommitteeCategoryId						 
					 END
			 		 
				SELECT @QStatus = 2;	
			--	COMMIT TRANSACTION
			END



				IF(@ChapterIds<>'')
	Begin
		DECLARE @RowCount1 AS int
		DECLARE @CurrentRow1 AS int	
		DECLARE @table1 TABLE (RowID int not null primary key identity(1,1), col1 int )  
		INSERT into @table1 (col1) SELECT part FROM SplitString(@ChapterIds)

		DELETE ChapterCommittees WHERE CommitteeCategoryId = @CommitteeCategoryId

		IF((Select Count(*) From @table1) <> 0)
		BEGIN
			Set @RowCount1 = (Select Count(*) From @table1)
			SET @CurrentRow1 = 1
			WHILE @CurrentRow1 < @RowCount1 + 1 
			BEGIN
				INSERT INTO ChapterCommittees VALUES
				((select col1 from @table1 where RowID = @CurrentRow1)
				,@CommitteeCategoryId
				,1
				,1
				,@UpdatedBy
				,@UpdatedDate)

				SET @CurrentRow1 = @CurrentRow1 + 1
			END
		END

	


end









    
    --END TRY
    
  --  BEGIN CATCH    
	 --   ROLLBACK TRANSACTION
		--SELECT @QStatus = -1;    
  --  END CATCH    
    
END










