CREATE PROCEDURE [dbo].[CommitteeMembersInsert]  
(
    @CommitteeMemberId BIGINT,
    @ChapterId BIGINT,
    @MemberId BIGINT,
    @CommitteeCategoryId BIGINT,
    @DisplayOrder INT,
    @Designation NVARCHAR(512),
    @Description NVARCHAR(512),
    @QStatus INT OUTPUT
)
AS
BEGIN

    SET NOCOUNT ON;

    IF ((SELECT COUNT(*) 
         FROM CommitteeMembers 
         WHERE CommitteeMemberId = @CommitteeMemberId) = 0)
    BEGIN
        INSERT INTO CommitteeMembers
        (
            ChapterId,
            MemberId,
            CommitteeCategoryId,
            DisplayOrder,
            Designation,
            IsActive,
            Description
        )
        VALUES
        (
            @ChapterId,
            @MemberId,
            @CommitteeCategoryId,
            @DisplayOrder,
            @Designation,
            1,
            @Description
        );

        SELECT @QStatus = 1;
    END
    ELSE
    BEGIN
        UPDATE CommitteeMembers
        SET
            ChapterId = @ChapterId,
            MemberId = @MemberId,
            CommitteeCategoryId = @CommitteeCategoryId,
            DisplayOrder = @DisplayOrder,
            Designation = @Designation,
            Description = @Description
        WHERE CommitteeMemberId = @CommitteeMemberId;

        SELECT @QStatus = 2;
    END
END
