CREATE PROCEDURE [dbo].[CommitteeMembersList]  
  (@CommitteeCategoryId BIGINT  
  ,@Search nvarchar(126)  
     ,@Sort nvarchar(126)  
  ,@PageNo int  
     ,@Items int  
     ,@Total int output  
  ,@ChapterId BIGINT)  
AS  
BEGIN  
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
   
 SET NOCOUNT ON;  
  
 DECLARE @Start int, @End INT ;  
 DECLARE @Query nvarchar(max);  
      
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)  
    ,MemberId bigint  
    ,Name nvarchar(512)  
    ,MobilePhone nvarchar(512)  
    ,Address nvarchar(512)  
    ,City nvarchar(512)  
    ,State nvarchar(512)  
    ,Email nvarchar(512)  
    ,ProfileImage nvarchar(512)  
    ,DisplayOrder int  
    ,IsApproved bit  
    ,Description nvarchar(max)  
    ,UpdatedBy nvarchar(64)  
    ,UpdatedTime datetime  
    ,CommitteeMemberId bigint  
    ,CommitteeCategoryId bigint  
    ,CategoryName nvarchar(512)  
    ,ChapterId Bigint)  
  
      
 SELECT @Start = (@PageNo - 1) * @Items    
      
 SELECT @End = @Start + @Items   
   
 SET @Query = 'INSERT INTO #temp SELECT  
              C.MemberId  
             ,(C.FirstName + '' '' + C.LastName) As Name  
    ,C.MobilePhone  
    ,C.Address  
    ,C.City  
    ,C.State  
    ,C.Email  
    ,C.ProfileImage  
    ,CM.DisplayOrder  
    ,CM.IsActive  
    ,C.Comments  
    ,(C.FirstName + '' '' + C.LastName)UpdatedBy  
    ,C.UpdatedTime  
    ,CM.CommitteeMemberId  
    ,CM.CommitteeCategoryId  
    ,CC.CategoryName  
    ,CM.ChapterId  
    FROM Members C   
    INNER JOIN CommitteeMembers CM ON CM.MemberId=C.MemberId   
    INNER JOIN CommitteeCategoryMaster CC ON CC.CommitteeCategoryId=CM.CommitteeCategoryId    
    WHERE C.MemberId <> 0 and CC.CategoryName is not null'  
    
    
  IF(@CommitteeCategoryId <> 0)  
  BEGIN  
   SET @Query=@Query + ' AND CM.CommitteeCategoryId = ' + CAST(@CommitteeCategoryId AS nvarchar(30))  
  END    
  IF(@ChapterId <> 0)   
  BEGIN  
   SET @Query=@Query + ' AND CM.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))  
  END  
  IF(@Search <> '')  
  BEGIN  
   SET @Query = @Query + ' AND  ((C.FirstName + '''' + C.LastName)  LIKE ''%' + @Search + '%'' OR C.Email LIKE ''%' + @Search + '%'' OR C.MobilePhone LIKE ''%' + @Search + '%'' OR CC.CategoryName LIKE ''%' + @Search + '%'')'  
  END  
  IF(@Sort <> '')  
  BEGIN  
   SET @Query = @Query + ' ORDER BY ' + @Sort  
  END  
   
  EXEC sp_ExecuteSQL @Query;  
  print @Query;  
    
  SELECT @Total = COUNT(Rid) from #temp   
      
  SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End  
   
  DROP TABLE #temp  
  
END  
  
  
  
  


