CREATE PROCEDURE [dbo].[CommitteesGetListById]
	@CommitteeCategoryId int,
	@ChapterId bigint,
    @QStatus int output
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY
        If(@CommitteeCategoryId != 0)
			BEGIN
				SELECT distinct MemberId , (FirstName + '' + LastName) As Name,*
		
				FROM Members C where MemberId NOT IN (select MemberId from CommitteeMembers where CommitteeCategoryId= @CommitteeCategoryId) AND ChapterId = @ChapterId Order By Name ASC
			
			END
		Else 
			BEGIN
			--SELECT distinct MemberId , (FirstName + '' + LastName) As Name,* FROM Members C  AND ChapterId = @ChapterId Order By Name ASC

			SELECT DISTINCT 
    MemberId, 
    (FirstName + ' ' + LastName) AS Name,
    * 
FROM 
    Members C  
WHERE 
    ChapterId = @ChapterId 
ORDER BY 
    Name ASC;

			END
		SELECT @QStatus = 1;
			
    END TRY

    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH
    	
END











































