CREATE PROCEDURE [dbo].[CommitteesGetListByVariable]
	 (@CommitteeCategoryId BIGINT
	 ,@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,CommitteeId bigint
				,Name nvarchar(512)
				,PhoneNo nvarchar(512)
				,Address nvarchar(512)
				,City nvarchar(512)
				,State nvarchar(512)
				,Email nvarchar(512)
				,ImageUrl nvarchar(512)
				,DisplayOrder int
				,IsActive bit
				,Description nvarchar(max)
				,UpdatedBy nvarchar(64)
				,UpdatedTime datetime
				,CommitteeMemberCount bigint)

				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT
	             C.CommitteeId
	            ,C.Name
				,C.PhoneNo
				,C.Address
				,C.City
				,C.State
				,C.Email
				,C.ImageUrl
				,C.DisplayOrder
				,C.IsActive
				,C.Description
				,C.UpdatedBy
				,C.UpdatedTime
				,(SELECT COUNT(*) FROM CommitteeMembers CM WHERE CM.CommitteeId =C.CommitteeId) AS CommitteeMemberCount
				FROM Committees C 
				WHERE C.CommitteeId <> 0 '
		
		
		IF(@CommitteeCategoryId <> 0)
		BEGIN
			SET @Query=@Query + ' AND CM.CommitteeCategoryId = ' + CAST(@CommitteeCategoryId AS nvarchar(30))
		END  
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  C.Name LIKE ''%' + @Search + '%'''
		END
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END








































