CREATE PROCEDURE [dbo].[CommitteesInsert]
    (@CommitteeId bigint
	,@Name nvarchar(512)
	,@PhoneNo nvarchar(512)
	,@Address nvarchar(512)
	,@City nvarchar(512)
	,@State nvarchar(512)
	,@Email nvarchar(512)
	,@ImageUrl nvarchar(512) output
	,@DisplayOrder int
	,@IsActive bit
	,@Description nvarchar(max)
	,@UpdatedBy nvarchar(64)
	,@UpdatedTime datetime
	,@QStatus int output)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
    IF((SELECT COUNT(*) FROM Committees WHERE CommitteeId = @CommitteeId) = 0)
    BEGIN
        INSERT INTO Committees VALUES
            (@Name
			,@PhoneNo
			,@Address
			,@City
			,@State
			,@Email
			,NULL
			,@DisplayOrder
			,@IsActive
			,@Description
			,@UpdatedBy
			,@UpdatedTime)
			
		SET @CommitteeId=SCOPE_IDENTITY()		
			
		SELECT @QStatus = 1;	
	END
	ELSE
	BEGIN
		UPDATE Committees
		   SET Name =@Name,
			   PhoneNo=@PhoneNo,
			   Address=@Address,
			   City=@City,
			   State=@State,
			   Email=@Email,
			   DisplayOrder=@DisplayOrder,
			   IsActive=@IsActive ,
			   Description=@Description,
			   UpdatedBy=@UpdatedBy,
			   UpdatedTime=@UpdatedTime
		 WHERE CommitteeId = @CommitteeId
		 		 
		 SELECT @QStatus = 2;	
	END
		IF(@ImageUrl <> 'NA')
			BEGIN
				UPDATE Committees SET  ImageUrl= CAST(@CommitteeId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@Name, '^a-z0-9') + '.' + @ImageUrl
				WHERE CommitteeId = @CommitteeId	
			  
			    SELECT @ImageUrl = CAST(@CommitteeId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@Name, '^a-z0-9') + '.' + @ImageUrl	
			END	
	    ELSE
			BEGIN
			  SELECT @ImageUrl=''
			END	
    COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH    
    ROLLBACK TRANSACTION
		SELECT @QStatus = -1;    
    END CATCH    
END











































