CREATE PROCEDURE [dbo].[CovidVaccineGetListByVariable]
	 (@ChapterId bigint
	 ,@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,CovidVaccineId bigint
				,MemberId bigint
				,ChapterId bigint
				,Email nvarchar(1024)
				,COVIDVaccinefor nvarchar(MAX)
				,IsActive	bit	
				,InsertedBy	nvarchar(256)	
				,InsertedDate	datetime	
				,UpdatedBy	nvarchar(256)	
				,UpdatedDate	datetime					
				,ChapterName nvarchar(512))
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             E.CovidVaccineId
				,E.MemberId
				,E.ChapterId
	            ,E.Email
	            ,E.COVIDVaccinefor	          
				,E.IsActive			
			    ,E.InsertedBy
	            ,E.InsertedDate
	            ,E.UpdatedBy
	            ,E.UpdatedDate
				,C.ChapterName
	             FROM CovidVaccine E
				 Left JOIN Chapters C ON C.ChapterId = E.ChapterId
		WHERE E.CovidVaccineId <> 0'
		
		IF(@ChapterId <> 0)
		BEGIN
			SET @Query=@Query + 'AND E.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))
		END  

		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  E.Email LIKE ''%' + @Search + '%'''
		END

		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY E.InsertedDate DESC'
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END









