CREATE PROCEDURE [dbo].[CovidVaccineUpdateStatus]
    (@CovidVaccineId bigint
    ,@QStatus int output)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY    
    BEGIN TRANSACTION
    
		IF((SELECT IsActive FROM CovidVaccine WHERE CovidVaccineId = @CovidVaccineId) = 1)
			BEGIN
				UPDATE CovidVaccine SET IsActive = 0 WHERE CovidVaccineId = @CovidVaccineId
			END
		ELSE
			BEGIN
				UPDATE CovidVaccine SET IsActive = 1 WHERE CovidVaccineId = @CovidVaccineId
			END		
		
		SELECT @QStatus = 1;
		
	COMMIT TRANSACTION
    END TRY

    BEGIN CATCH
    
         ROLLBACK TRANSACTION
		 SELECT @QStatus = -1;
		 
    END CATCH
    	
END














