CREATE PROCEDURE [dbo].[CulturalParticipantsInsert]
		(@ParticipantID				bigint
		,@CulturalRegistrationId	bigint
		,@FirstName					nvarchar(1024)
		,@LastName					nvarchar(1024)
		,@Email						nvarchar(2048)
		,@PhoneNumber				nvarchar(128)
		,@Age						int
		,@Gender					nchar(20)
		,@Address					nvarchar(1024)
		,@InsertedBy				nvarchar(128)
		,@InsertedDate				datetime
		,@UpdatedBy					nvarchar(128)
		,@UpdatedDate				datetime
		,@QStatus					int output)
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
    
		IF((SELECT COUNT(*) FROM CulturalParticipants WHERE ParticipantID = @ParticipantID) = 0)
			BEGIN
		
				INSERT INTO CulturalParticipants VALUES

						(@CulturalRegistrationId
						,@FirstName
						,@LastName
						,@Email
						,@PhoneNumber
						,@Age
						,@Gender
						,@Address
						,@InsertedBy
						,@InsertedDate
						,@UpdatedBy
						,@UpdatedDate)

						SET @ParticipantID  =  SCOPE_IDENTITY()

						SELECT @QStatus = 1;
					
			END
		ELSE 
			BEGIN
				UPDATE CulturalParticipants
				   SET 

					CulturalRegistrationId  = @CulturalRegistrationId,
					FirstName				= @FirstName,
					LastName				= @LastName,
					Email					= @Email,
					PhoneNumber				= @PhoneNumber,
					Age						= @Age,
					Gender					= @Gender,
					Address					= @Address,
					InsertedBy				= @InsertedBy,
					InsertedDate			= @InsertedDate,
					UpdatedBy				= @UpdatedBy,
					UpdatedDate				= @UpdatedDate

				 WHERE ParticipantID = @ParticipantID
			 		 
				 SELECT @QStatus = 2;
			 
			 END
		 
		COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH  
    
		ROLLBACK TRANSACTION   
		SELECT @QStatus = -1;    
		
    END CATCH   
    
END



























