/****** Object:  StoredProcedure [dbo].[CulturalRegistrationsExportToExcel]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[CulturalRegistrationsExportToExcel]
(
    @Search NVARCHAR(126),
    @Sort NVARCHAR(216),
    @ChapterId BIGINT,
    @Total INT OUTPUT
)
AS
BEGIN

    SET NOCOUNT ON;

    DECLARE @Query NVARCHAR(MAX);

    SET @Query = '
    
    SELECT
	E.EventName
         ,C.FirstName
        ,C.LastName
        ,C.Address1
        ,C.Address2
        ,C.City
        ,C.State
        ,C.ZipCode
        ,C.Email
        ,C.PhoneNo
        ,C.AAALifetimeMember
        ,C.CoordinatorName
        ,C.ContactPhone
        ,C.ContactEmail
        ,C.OrganizationName
        ,C.PerformanceCategory
        ,C.SpecifyCategory
        ,C.NameofthePerformance
        ,C.PerformanceDuration
        ,C.NumberofParticipants
        ,C.ParticipantAgeGroup
        ,C.SpecialRequirements
        ,C.BriefDescriptionofthePerformance

        ,PS.PaymentStatus

,CONVERT(VARCHAR(23), C.PaymentDate, 121) AS PaymentDate
        ,PM.PaymentMethod

        ,C.TransactionId
        ,C.AmountPaid
        ,C.Zelle
        ,C.ZellePartnerName
        ,C.ChequeHolderName

        ,C.Eventid
        

    FROM CulturalRegistrations C

    LEFT JOIN PaymentMethods PM
        ON PM.PaymentMethodId = C.PaymentMethodId

    LEFT JOIN PaymentStatus PS
        ON PS.PaymentStatusId = C.PaymentStatusId

    LEFT JOIN Events E
        ON E.Eventid = C.Eventid

    WHERE C.CulturalRegistrationId <> 0
    ';

    IF (@ChapterId <> 0)
    BEGIN
        SET @Query = @Query + '
        AND C.ChapterId = ' + CAST(@ChapterId AS NVARCHAR(30));
    END

    IF (@Search <> '')
    BEGIN
        SET @Query = @Query + '
        AND (
                C.FirstName + '' '' + C.LastName LIKE ''%' + @Search + '%''
                OR C.Email LIKE ''%' + @Search + '%''
                OR C.PhoneNo LIKE ''%' + @Search + '%''
            )';
    END

    IF (@Sort <> '')
    BEGIN
        SET @Query = @Query + '
        ORDER BY ' + @Sort;
    END
    ELSE
    BEGIN
        SET @Query = @Query + '
        ORDER BY C.CulturalRegistrationId DESC';
    END

    EXEC sp_executesql @Query;

    SET @Total = 1;

END

GO
