CREATE PROCEDURE [dbo].[CulturalRegistrationsFullDetailsGetById]  
 (@CulturalRegistrationId bigint  
    ,@QStatus int OUTPUT)      
          
AS  
BEGIN  
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
   
   SET NOCOUNT ON;  
  
  
   BEGIN TRY    
         SELECT  (select top(1) Eventname from events where eventid=C.eventid) As EventName,
		   (select top(1) PaymentStatus from PaymentStatus where PaymentStatusId=C.PaymentStatusId) As PaymentStatus,
		 
		 * from CulturalRegistrations C where  CulturalRegistrationId =  @CulturalRegistrationId
      
         SELECT ParticipantID  
        ,CulturalRegistrationId  
        ,FirstName  
        ,LastName  
        ,Email  
        ,PhoneNumber  
		,Age  
        ,UpdatedBy  
        ,UpdatedDate  
         FROM CulturalParticipants WHERE CulturalRegistrationId = @CulturalRegistrationId
           
         SELECT *,PM.PaymentMethod,PS.PaymentStatus FROM CulturalRegistrations CR   
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=CR.PaymentMethodId   
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=CR.PaymentStatusId    
      WHERE CulturalRegistrationId=@CulturalRegistrationId
  
      SELECT @QStatus = 1;  
    
    END TRY  
  
    BEGIN CATCH  
   SELECT @QStatus = -1;  
    END CATCH    
    
END  
  


  
  
  
  
  
  
  
  
  
  

