CREATE PROCEDURE [dbo].[CulturalRegistrationsGetListByVariable]        
  (@State nvarchar(126) ,  
   @EventId  bigint    
  ,@Search nvarchar(126)        
     ,@Sort nvarchar(126)        
  ,@PageNo int        
     ,@Items int      
   ,@ChapterId bigint       
     ,@Total int output)        
AS        
BEGIN        
        
 -- SET NOCOUNT ON added to prevent extra result sets from        
 -- interfering with SELECT statements.        
         
 SET NOCOUNT ON;        
         
 --BEGIN TRY        
         
 DECLARE @Start int, @End INT ;        
 DECLARE @Query nvarchar(max);        
         
    -- Insert statements for procedure here        
            
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)        
             ,CulturalRegistrationId bigint        
    ,ChapterId bigint        
    ,FirstName nvarchar(512)        
    ,LastName nvarchar(512)        
    ,Address1 nvarchar (max)        
    ,Address2 nvarchar (max)        
    ,City     nvarchar(256)         
    ,State    nvarchar(256)        
    ,ZipCode  nvarchar(126)        
    ,Email    nvarchar(1024)        
    ,PhoneNo  nvarchar(126)        
    ,AAALifetimeMember nvarchar(126)        
    ,CoordinatorName   nvarchar(126)        
    ,ContactPhone      nvarchar(126)        
    ,ContactEmail      nvarchar(126)        
    ,OrganizationName  nvarchar(126)        
    ,PerformanceCategory  nvarchar(126)        
    ,SpecifyCategory      nvarchar(126)        
    ,NameofthePerformance  nvarchar(126)        
    ,PerformanceDuration   nvarchar(126)        
    ,NumberofParticipants   nvarchar(126)        
    ,ParticipantAgeGroup    nvarchar(126)        
    ,SpecialRequirements    nvarchar(126)        
    ,BriefDescriptionofthePerformance   nvarchar(max)        
    ,PaymentStatusId bigint        
 ,PaymentStatus nvarchar(128)      
    ,PaymentDate datetime        
    ,PaymentMethodId bigint        
 ,PaymentMethod nvarchar(128)      
    ,OtherPaymentId nvarchar(max)        
    ,TransactionId nvarchar(128)        
    ,AmountPaid decimal        
    ,Zelle nvarchar(1024)        
    ,ReceiptUrl nvarchar(max)        
    ,ZellePartnerName nvarchar(1024)        
    ,ChequeHolderName nvarchar(1024)        
    ,IsActive bit        
    ,InsertedBy nvarchar(30)        
    ,InsertedDate datetime        
    ,UpdatedBy nvarchar(30)        
    ,UpdatedDate datetime    
     ,Eventid bigint        
 ,EventName nvarchar(MAX) )        
            
 SELECT @Start = (@PageNo - 1) * @Items          
            
 SELECT @End = @Start + @Items         
         
 SET @Query = 'INSERT INTO #temp SELECT         
     C.CulturalRegistrationId        
     ,C.ChapterId        
     ,C.FirstName        
     ,C.LastName        
     ,C.Address1        
     ,C.Address2        
     ,C.City        
     ,C.State        
     ,C.ZipCode        
     ,C.Email        
     ,C.PhoneNo        
     ,C.AAALifetimeMember        
     ,C.CoordinatorName        
     ,C.ContactPhone        
     ,C.ContactEmail        
     ,C.OrganizationName        
     ,C.PerformanceCategory        
     ,C.SpecifyCategory        
     ,C.NameofthePerformance        
     ,C.PerformanceDuration        
     ,C.NumberofParticipants        
     ,C.ParticipantAgeGroup        
     ,C.SpecialRequirements        
     ,C.BriefDescriptionofthePerformance        
     ,C.PaymentStatusId        
  ,(Select PS.PaymentStatus From PaymentStatus PS where PS.PaymentStatusId = C.PaymentStatusId) as PaymentStatus      
     ,C.PaymentDate        
     ,C.PaymentMethodId        
  ,(Select PM.PaymentMethod From PaymentMethods PM where PM.PaymentMethodId = C.PaymentMethodId) as PaymentMethod      
     ,C.OtherPaymentId        
     ,C.TransactionId        
     ,C.AmountPaid        
     ,C.Zelle        
     ,C.ReceiptUrl        
     ,C.ZellePartnerName        
     ,C.ChequeHolderName        
     ,C.IsActive        
     ,C.InsertedBy        
     ,C.InsertedDate        
     ,C.UpdatedBy        
     ,C.UpdatedDate       
   ,C.Eventid        
,(Select E.EventName     
  From Events E    
  where E.Eventid = C.Eventid) as EventName    
    FROM CulturalRegistrations C      
  WHERE C.CulturalRegistrationId <> 0 '        
        
         
      
   IF(@ChapterId <> 0)      
 BEGIN      
  SET @Query = @Query + ' AND C.ChapterId = ' + CAST(@ChapterId AS nvarchar(30));      
 END        
          
  IF(@Search <> '')        
  BEGIN        
   SET @Query = @Query + ' AND  C.FirstName+'' ''+C.LastName LIKE ''%' + @Search + '%'''        
  END        
       -- ✅ Add EventId filter  
    IF(@EventId <> 0)      
    BEGIN      
        SET @Query = @Query + ' AND C.EventId = ' + CAST(@EventId AS nvarchar(30));      
    END        
           
  IF(@State <> '')        
  BEGIN        
   SET @Query = @Query + ' AND  C.State LIKE ''%' + @State + '%'''        
  END        
        
  IF(@Sort <> '')        
  BEGIN        
   SET @Query = @Query + ' ORDER BY ' + @Sort        
  END        
         
  EXEC sp_ExecuteSQL @Query;        
          
  SELECT @Total = COUNT(Rid) from #temp         
            
  SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End        
         
  DROP TABLE #temp        
        
 --END TRY        
            
 --   BEGIN CATCH          
 --      SELECT @Total = -1;              
 --   END CATCH           
END 
