 ,@ChequeHolderName  nvarchar(1024)
 ,@Zelle nvarchar(1024)
 ,@QStatus int output)        
              
AS      
BEGIN      
      
 -- SET NOCOUNT ON added to prevent extra result sets from      
 -- interfering with SELECT IsLockedOutments.      
       
 SET NOCOUNT ON;      
      
    -- Insert IsLockedOutments for procedure here      
          
    --BEGIN TRY      
    BEGIN TRANSACTION      
        
	UPDATE CulturalRegistrations  
	SET   
	 FirstName    = @FirstName,  
	 LastName    = @LastName,  
	 Address1    = @Address1,  
	 Address2    = @Address2,  
	 City     = @City,  
	 State     = @State,  
	 ZipCode     = @ZipCode,  
	 Email     = @Email,  
	 PhoneNo     = @PhoneNo,  
	 PaymentStatusId   = @PaymentStatusId,  
	 PaymentMethodId   = @PaymentMethodId,  
	 TransactionId   = @TransactionId,  
	 AmountPaid    = @AmountPaid,  
	 UpdatedBy    = @UpdatedBy,  
	 UpdatedDate    = @UpdatedDate,  
     EventId     = @EventId ,
	 ZellePartnerName = @ZellePartnerName,
	 ChequeHolderName = @ChequeHolderName,
	  Zelle = @Zelle
  
  WHERE CulturalRegistrationId = @CulturalRegistrationId;  
  
         
   IF(@ReceiptUrl <> 'NA')      
    BEGIN      
      UPDATE CulturalRegistration SET ReceiptUrl = CAST(@CulturalRegistrationId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@FirstName, '^a-z0-9') + '.' + @ReceiptUrl  WHERE CulturalRegistrationId = @CulturalRegistrationId       
      SELECT @ReceiptUrl = CAST(@CulturalRegistrationId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@FirstName, '^a-z0-9') + '.' + @ReceiptUrl      
    END       
        
        
    BEGIN    
    SELECT @ReceiptUrl=''    
   END     
         
  SELECT @QStatus = 2;    
   
       
    COMMIT TRANSACTION      
 


    --END TRY      
          
  --  BEGIN CATCH          
  --  ROLLBACK TRANSACTION      
  --SELECT @QStatus = -1;          
  --  END CATCH          
END




