/****** Object:  StoredProcedure [dbo].[DonationBulkImport]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [dbo].[DonationBulkImport]
    (@ShipmentsXML nvarchar(max),
     @Summary nvarchar(max) output,
     @QStatus int output)
AS
BEGIN
    SET NOCOUNT ON;

    -- BEGIN TRY
    -- BEGIN TRANSACTION

    IF (@ShipmentsXML <> '')
    BEGIN
        DECLARE @XML1 AS XML

        SELECT @XML1 = @ShipmentsXML

        CREATE TABLE #temp1 (Rid INT PRIMARY KEY IDENTITY(1, 1),
		    ChapterId  nvarchar(max),
            FirstName nvarchar(max),
            LastName nvarchar(max),
            Email nvarchar(max),
			PhoneNo nvarchar(max),
			Country nvarchar(max),
			ZipCode nvarchar(max),
			Address nvarchar(max),
            ServiceTitle nvarchar(max),
            TransactionId nvarchar(max),
            PaymentStatus nvarchar(max),
            PaymentMethod nvarchar(max),
            Amount nvarchar(max),
			OrderDate nvarchar(max)

        )

        DECLARE @RowCount1 AS int
        DECLARE @CurrentRow1 AS int

        INSERT INTO #temp1 (
            ChapterId,
            FirstName,
            LastName,
            Email,
			PhoneNo,
			Country,
            ZipCode,
            Address,
            ServiceTitle,
            TransactionId,
            PaymentStatus,
            PaymentMethod,
            Amount,
			OrderDate 

        )
        SELECT

		    M.Item.value('ChapterId[1]', 'nvarchar(max)'),
            M.Item.value('FirstName[1]', 'nvarchar(max)'),
            M.Item.value('LastName[1]', 'nvarchar(max)'),
            M.Item.value('Email[1]', 'nvarchar(max)'),
		    M.Item.value('PhoneNo[1]', 'nvarchar(max)'),
            M.Item.value('Country[1]', 'nvarchar(max)'),
            M.Item.value('ZipCode[1]', 'nvarchar(max)'),
            M.Item.value('Address[1]', 'nvarchar(max)'),
            M.Item.value('ServiceTitle[1]', 'nvarchar(max)'),
            M.Item.value('TransactionId[1]', 'nvarchar(max)'),
			M.Item.value('PaymentStatus[1]', 'nvarchar(max)'),
			M.Item.value('PaymentMethod[1]', 'nvarchar(max)'),
		    M.Item.value('Amount[1]', 'nvarchar(max)'),
			M.Item.value('OrderDate[1]', 'nvarchar(max)')

        FROM @XML1.nodes('/ArrayOfServiceDonations/ServiceDonations') AS M(Item)

        SET @RowCount1 = @@ROWCOUNT

        SET @CurrentRow1 = 1

		DECLARE @successCount bigint

		 DECLARE @FailedCount bigint
		  


		SET @successCount =0
		SET @FailedCount=0

		
		DECLARE @InsertedSummary NVARCHAR(MAX) = ''
         DECLARE @FailedSummary NVARCHAR(MAX) = ''



        WHILE @CurrentRow1 < @RowCount1 + 1
        BEGIN
            DECLARE @ServiceDonationId bigint

           -- IF ((SELECT COUNT(*) FROM Members WHERE Email = (SELECT Email FROM #temp1 WHERE Rid = @CurrentRow1)) = 0)
		   If((Select Count(*) From ServiceDonationInfo  Where  Email = (Select Email From #temp1 Where Rid = @CurrentRow1)) = 0)

			--IF((Select Email From #temp1 Where Rid = @CurrentRow1) <> '')

			
            BEGIN
                INSERT INTO ServiceDonations (
                   


					    ServiceId,
                        Amount,
                        TransactionId,
                        PaymentStatusId,
						PaymentMethodId,
					    UpdatedDate,
						OrderDate
                          )
                SELECT
                    
						(SELECT ServiceId FROM Services WHERE ServiceTitle = (SELECT ServiceTitle FROM #temp1 WHERE Rid = @CurrentRow1)),
						
                        Amount,
                        TransactionId,
						(SELECT PaymentStatusId FROM PaymentStatus WHERE PaymentStatus = (SELECT PaymentStatus FROM #temp1 WHERE Rid = @CurrentRow1)),
						(SELECT PaymentMethodId FROM PaymentMethods WHERE PaymentMethod = (SELECT PaymentMethod FROM #temp1 WHERE Rid = @CurrentRow1)),
						
						GetDate(),
						OrderDate

                FROM #temp1
                WHERE Rid = @CurrentRow1

                --SELECT @MemberId = Scope_Identity();
				SET @ServiceDonationId=SCOPE_IDENTITY()	

                INSERT INTO ServiceDonationInfo(ServiceDonationId,ChapterId,FirstName,LastName,Email,PhoneNo,Country,ZipCode,Address)
                SELECT
				    @ServiceDonationId,
                    ChapterId,
					FirstName,
					LastName,
					Email,
					PhoneNo,
					Country,
					ZipCode,
					Address
                FROM #temp1
                WHERE Rid = @CurrentRow1


				SET @InsertedSummary = @InsertedSummary + (SELECT Email FROM #temp1 WHERE Rid = @CurrentRow1) + CHAR(13)
                SET @successCount = @successCount + 1

				--SET @Summary = @Summary + (SELECT Email FROM #temp1 WHERE Rid = @CurrentRow1) + ' Inserted ServiceDonation Successfully \r\n';
                --SET @successCount = @successCount + 1;
               -- SET @Summary = @Summary + (SELECT FirstName FROM #temp1 WHERE Rid = @CurrentRow1) + 'Inserted ServiceDonation Successfully \r\n'
        END


		 ELSE 
				BEGIN
					-- SET @Summary = @Summary + (SELECT Email FROM #temp1 WHERE Rid = @CurrentRow1) + ' Inserted ServiceDonation Failed\r\n'
					 --SET @FailedCount = @FailedCount + 1;

					 SET @FailedSummary = @FailedSummary + (SELECT Email FROM #temp1 WHERE Rid = @CurrentRow1) + CHAR(13)
                        SET @FailedCount = @FailedCount + 1
				END


				--SET @Summary = @Summary + CHAR(13) + 'Total Success: ' + CAST(@successCount AS VARCHAR) + CHAR(13) + 'Total Failed: ' + CAST(@FailedCount AS VARCHAR);



            SET @CurrentRow1 = @CurrentRow1 + 1
        END



		SET @Summary = 
'ServiceDonation added successfully:' + CHAR(13) + CHAR(10) +
@InsertedSummary + CHAR(13) + CHAR(10) +
'ServiceDonation addition failed:' + CHAR(13) + CHAR(10) +
@FailedSummary + CHAR(13) + CHAR(10) +
'Final Summary:' + CHAR(13) + CHAR(10) +
'Success Count: ' + CAST(@successCount AS VARCHAR) + CHAR(13) + CHAR(10) +
'Failed Count: ' + CAST(@FailedCount AS VARCHAR);






        DROP TABLE #temp1

        SELECT @QStatus = 1;
    END

    -- COMMIT TRANSACTION
    -- END TRY

    -- BEGIN CATCH
    -- ROLLBACK TRANSACTION
    -- SELECT @QStatus = -1;
    -- END CATCH
END




