/****** Object:  StoredProcedure [dbo].[DonationCategoriesGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[DonationCategoriesGetListByVariable]
	 (@ChapterId bigint
	 ,@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,DonationCategoryId bigint
				,ChapterId bigint
				,CategoryName nvarchar(128)
				,OrderNo int
				,IsActive bit
				,ChapterName nvarchar(256))
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             DC.DonationCategoryId
				,DC.ChapterId
	            ,DC.CategoryName
	            ,DC.OrderNo
	            ,DC.IsActive
				,C.ChapterName
				FROM DonationCategories DC
				INNER JOIN Chapters C ON C.ChapterId = DC.ChapterId 
		        WHERE DC.DonationCategoryId <> 0'
		
		IF(@ChapterId <> 0)
			BEGIN
				SET @Query=@Query + 'AND DC.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))
			END  
		IF(@Search <> '')
			BEGIN
				SET @Query = @Query + ' AND  DC.CategoryName LIKE ''%' + @Search + '%'''
			END
		IF(@Sort <> '')
			BEGIN
				SET @Query = @Query + ' ORDER BY ' + @Sort
			END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

END











