CREATE PROCEDURE [dbo].[DonationCategoriesInsert]
    (@DonationCategoryId bigint
	,@ChapterId bigint
	,@CategoryName nvarchar(128)
	,@OrderNo int
	,@IsActive bit
	,@QStatus int output)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
    IF((SELECT COUNT(*) FROM DonationCategories WHERE DonationCategoryId = @DonationCategoryId OR CategoryName=@CategoryName) = 0)
		BEGIN
			INSERT INTO DonationCategories VALUES
				(@ChapterId
				,@CategoryName
				,@OrderNo
				,@IsActive)		
			
			SELECT @QStatus = 1;	
		END
	ELSE 
		BEGIN
			IF((SELECT COUNT(*) FROM DonationCategories WHERE CategoryName=@CategoryName AND DonationCategoryId <> @DonationCategoryId) = 0)
				BEGIN
				UPDATE DonationCategories
				   SET 
					   ChapterId=@ChapterId
					 ,CategoryName =@CategoryName,
					   OrderNo=@OrderNo
				 WHERE DonationCategoryId = @DonationCategoryId
		 		 
				 SELECT @QStatus = 2;	
				END
			 ELSE
				BEGIN
				SELECT @QStatus = 3; 
				END 
			END
    COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH    
    ROLLBACK TRANSACTION
		SELECT @QStatus = -1;    
    END CATCH    
END
























