/****** Object:  StoredProcedure [dbo].[DonorRegistrationsExportToExcel]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DonorRegistrationsExportToExcel] 
	 (@Search nvarchar(126)
	 ,@Sort nvarchar(216)
	 ,@PaymentStatusId bigint
	 ,@PaymentMethodId bigint	 
     ,@Total int OUTPUT)
        
AS
BEGIN

			SET NOCOUNT ON;
			
			DECLARE @Start int, @End INT ;
			DECLARE @Query nvarchar(max);
			

			SET @Query = '
				   SELECT 
	             E.DonorId		
	            ,E.FirstName
	            ,E.LastName
				,DI.Spouse  as SpouseName
				,(E.Email) AS EmailAddress
				,(E.Address) AS Address
				,DI.City
				,DI.State
				,DI.ZipCode
				,E.PhoneNo
				,MI.FrequencyofDonation as DonationFrequency
				,MI.Amount  as DonationAmount
				,MI.NoofPayments
				,MI.Field1 as RecurringDonation
				,(MI.NoofPayments*MI.Field1 + MO.Amount)as TotalAmount
		  		,Case 
				When  M.IsApproved=''1'' then ''Y''
				When  M.IsApproved=''0'' then ''N''
				end as Status
	            FROM Donors E
				LEFT JOIN Members M ON E.MemberId = E.MemberId
				Inner JOIN DonationInfo DI ON E.DonorId = DI.DonorId
				LEFT JOIN MembersInfo MI ON MI.MemberId=E.MemberId 
		        LEFT JOIN MembershipOrders MO ON MO.MemberId=E.MemberId
				WHERE E.DonorId <> 0'

			IF(@PaymentMethodId<>0)
				BEGIN
					SET @Query=@Query + ' AND E.PaymentMethodId = ' + CAST(@PaymentMethodId as nvarchar(50))
				END

			IF(@PaymentStatusId<>0)
				BEGIN
					SET @Query=@Query + ' AND E.PaymentStatusId = ' + CAST(@PaymentStatusId as nvarchar(50))
				END	

			IF(@Search <> '')
				BEGIN
					SET @Query = @Query + ' AND  E.FirstName LIKE ''%' + @Search + '%'' OR E.Email LIKE ''%' + @Search + '%'''
				END
			
			IF(@Sort <> '')
				BEGIN
					SET @Query = @Query + ' ORDER BY ' + @Sort
				END
			
			EXEC sp_ExecuteSQL @Query;
			SELECT @Total = 1;
	
	 
END









