/****** Object:  StoredProcedure [dbo].[DonorsGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[DonorsGetListByVariable] 
	 (@Search nvarchar(126)
	 ,@PaymentMethod bigint
	 ,@PaymentStatus bigint
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output
	 ,@ChapterId bigint
	 ,@MemberId bigint)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,DonorId bigint
				,ChapterId bigint
				,MemberId bigint
				,FirstName nvarchar(128)
				,LastName nvarchar(128)
				,Email nvarchar(128)
				,PhoneNo nvarchar(20)
				,IsActive bit
				,DonationProgram nvarchar(2048)
				,OrderDate datetime
				,Amount decimal(15,2)
				,TransactionId nvarchar(128)
				,PaymentMethod nvarchar(156)
				,PaymentStatus nvarchar(156)
				,InsertedDate datetime
				,ChapterName nvarchar(512))
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             D.DonorId
				 ,D.ChapterId
				,D.MemberId
	            ,D.FirstName
	            ,D.LastName
	            ,D.Email
	            ,D.PhoneNo
	            ,D.IsActive
				,D.DonationProgram
	            ,D.OrderDate
				,D.Amount
	            ,D.TransactionId
	            ,PM.PaymentMethod
	            ,PS.PaymentStatus
	            ,D.InsertedDate 
				,C.ChapterName 
	            FROM Donors D 
	            LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId
	            LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId
				INNER JOIN Chapters C ON C.ChapterId = D.ChapterId	
	            WHERE D.DonorId <> 0 '
		
		IF(@ChapterId <> 0)
			BEGIN
				SET @Query=@Query + 'AND D.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))
			END  

		
		IF(@Search <> '')
			BEGIN
				SET @Query = @Query + ' AND  D.FirstName LIKE ''%' + @Search + '%'' OR  D.LastName LIKE ''%' + @Search + '%'' OR  D.Email LIKE ''%' + @Search + '%'' OR  D.PhoneNo LIKE ''%' + @Search + '%'' OR  D.TransactionId LIKE ''%' + @Search + '%'''
			END

		IF(@PaymentMethod <>0)
			BEGIN
			SET @Query = @Query + ' AND  PM.PaymentMethod ='+ Cast(@PaymentMethod as nvarchar(50))
			END

		IF(@PaymentStatus <>0)
			BEGIN
			SET @Query = @Query + ' AND  PS.PaymentStatus ='+ Cast(@PaymentStatus as nvarchar(50))
		    END

		IF(@Sort <> '')
			BEGIN
				SET @Query = @Query + ' ORDER BY ' + @Sort
			END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp
  
END







