CREATE PROCEDURE [dbo].[DonorsInsert]
    (@DonorId bigint output
	,@ChapterId bigint
	,@MemberId bigint
	,@FirstName nvarchar(128)
	,@LastName nvarchar(128)
	,@Email nvarchar(128)
	,@PhoneNo nvarchar(20)
	,@Address nvarchar(1024)
	,@DonationProgram nvarchar(2048)
	,@DonationCause nvarchar(2048)
	,@IsActive bit
	,@Amount decimal(15,2)
	,@TransactionId nvarchar(128)
	,@PaymentStatusId bigint
	,@PaymentMethodId bigint
	,@OrderDate datetime
	,@PaymentBy nvarchar(2048)
	,@InsertedBy nvarchar(30)
	,@InsertedDate datetime
	,@UpdatedBy nvarchar(30)
	,@UpdatedDate datetime
	,@QStatus int output
	,@DonorInfoId bigint
	,@Country nvarchar(512)
	,@City  nvarchar(512)
	,@State  nvarchar(512)
	,@ZipCode  nvarchar(512)
	,@Spouse  nvarchar(512)
	,@FrequencyofDonation nvarchar(512)
	,@NoofPayments bigint
	,@TypeofCard   nvarchar(512)
	,@CardNumber  nvarchar(512)
	,@ExipryMonth  nvarchar(512)
	,@ExipryYear  nvarchar(512)
	,@Cvv  nvarchar(512)
	,@SameBilling  nvarchar(512)
	,@BillingAdress   nvarchar(max)
	,@BillingCountry nvarchar(512)
	,@BillingCity nvarchar(512)
	,@BillingState nvarchar(512)
	,@BillingZipCode nvarchar(512)
	,@KnowledgeAcurate nvarchar(512)
	,@Field1 nvarchar(max)
	,@Field2 nvarchar(max)
	,@Field3  nvarchar(max))  




        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    IF((SELECT COUNT(*) FROM Donors WHERE DonorId = @DonorId) = 0)
		BEGIN
			INSERT INTO Donors VALUES
			      ( @ChapterId
				   ,@MemberId
				   ,@FirstName
					,@LastName 
					,@Email
					,@PhoneNo 
					,@Address 
					,@DonationProgram
					,@DonationCause 
					,@IsActive 
					,@Amount
					,NULL
					,NULL
					,NULL
					,NULL
					,@PaymentBy
					,@InsertedBy 
					,@InsertedDate 
					,@UpdatedBy
					,@UpdatedDate)
		     SET @DonorId=SCOPE_IDENTITY()
		
			 INSERT INTO DonationInfo  Values
			 (@DonorId
			,@Country
			,@City
			,@State
			,@ZipCode
			,@Spouse
			,@FrequencyofDonation
			,@NoofPayments
			,@TypeofCard
			,@CardNumber
			,@ExipryMonth
			,@ExipryYear
			,@Cvv
			,@SameBilling
			,@BillingAdress
			,@BillingCountry
			,@BillingCity
			,@BillingState
			,@BillingZipCode
			,@KnowledgeAcurate
			,@Field1
			,@Field2
			,@Field3)

			SELECT @QStatus = 1;
			END

		ELSE 
		BEGIN	

				UPDATE Donors
			   SET 
			        ChapterId           =   @ChapterId,
					FirstName			=	@FirstName,
					LastName			=	@LastName,
					Email				=	@Email,
					PhoneNo				=	@PhoneNo,
					Address				=	@Address,
					DonationProgram		=	@DonationProgram,
					DonationCause		=	@DonationCause,
				    Amount				=	@Amount,
					TransactionId		=	@TransactionId ,
					PaymentStatusId		=	@PaymentStatusId ,
					PaymentMethodId		=	@PaymentMethodId ,
					OrderDate			=	@OrderDate ,
					PaymentBy			=	@PaymentBy,
					UpdatedBy			=	@UpdatedBy,
					UpdatedDate			=	@UpdatedDate
			  WHERE DonorId				=   @DonorId


		IF((SELECT COUNT(*) FROM DonationInfo WHERE DonorId = @DonorId) = 0)
		BEGIN


				 INSERT INTO DonationInfo  Values
				(
				 @DonorId
				,@Country
				,@City
				,@State
				,@ZipCode
				,@Spouse
				,@FrequencyofDonation
				,@NoofPayments
				,@TypeofCard
				,@CardNumber
				,@ExipryMonth
				,@ExipryYear
				,@Cvv
				,@SameBilling
				,@BillingAdress
				,@BillingCountry
				,@BillingCity
				,@BillingState
				,@BillingZipCode
				,@KnowledgeAcurate
				,@Field1
				,@Field2
				,@Field3)

		END
			 UPDATE DonationInfo SET 
			        Country             =   @Country,
					City			    =	@City,
					State			    =	@State,
					ZipCode				=	@ZipCode,
					Spouse				=	@Spouse,
					FrequencyofDonation =   @FrequencyofDonation,
					NoofPayments		=	@NoofPayments,
					TypeofCard          =   @TypeofCard,
					CardNumber		    =	@CardNumber,
					ExipryMonth		    =	@ExipryMonth,
				    ExipryYear			=	@ExipryYear,
					Cvv		            =	@Cvv ,
					SameBilling         =   @SameBilling,
					BillingAdress		=	@BillingAdress ,
					BillingCountry		=	@BillingCountry ,
					BillingCity			=	@BillingCity ,
					BillingState		=	@BillingState,
					BillingZipCode		=	@BillingZipCode,
					KnowledgeAcurate	=   @KnowledgeAcurate,
					Field1				=	@Field1,
					Field2				=	@Field2,
					Field3				=	@Field3
			 WHERE  DonorId				=   @DonorId

		SELECT @QStatus = 2;	

		END

END








