CREATE PROCEDURE [dbo].[DonorsUpdate]
    (@DonorId bigint 
	,@Amount decimal(15,2)
	,@TransactionId nvarchar(128)
	,@PaymentStatusId bigint
	,@PaymentMethodId bigint
	,@PaymentStatus nvarchar(2048)
	,@PaymentMethod nvarchar(2048)
	,@OrderDate datetime
	,@UpdatedBy nvarchar(30)
	,@UpdatedDate datetime
	,@QStatus int output)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
			        IF(@PaymentStatus IS NOT NULL)
					BEGIN
						SELECT @PaymentStatusId = PaymentStatusId FROM PaymentStatus WHERE PaymentStatus = @PaymentStatus

						IF(@PaymentStatusId IS NULL OR @PaymentStatusId='')
							BEGIN
								 INSERT INTO PaymentStatus VALUES(@PaymentStatus,1)
								 SELECT @PaymentStatusId=SCOPE_IDENTITY()
							END
						IF(@PaymentMethod IS NOT NULL)
							BEGIN
							SELECT @PaymentMethodId = PaymentMethodId FROM PaymentMethods WHERE PaymentMethod = @PaymentMethod
							END
				    END
    		
			UPDATE Donors SET 
				    Amount				=	@Amount,
					TransactionId		=	@TransactionId ,
					PaymentStatusId		=	@PaymentStatusId ,
					PaymentMethodId		=	@PaymentMethodId ,
					OrderDate			=	@OrderDate ,
					UpdatedBy			=	@UpdatedBy,
					UpdatedDate			=	@UpdatedDate

			 WHERE DonorId = @DonorId
			 		 
			 SELECT @QStatus = 1;
		
		COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH  
		ROLLBACK TRANSACTION   
		SELECT @QStatus = -1;    
    END CATCH   
    
END


























