/****** Object:  StoredProcedure [dbo].[EventCheckInInsert]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


create PROCEDURE [dbo].[EventCheckInInsert]
    @EventRegCountId BIGINT,
    @EventUserInfoId BIGINT,
    @EventRegistrationTypeId BIGINT,
    @Status NVARCHAR(125),  -- "Yes" / "No" / "Pending"
    @Comments NVARCHAR(MAX) = NULL,
    @CheckInDate DATETIME,
    @InsertedBy NVARCHAR(256),
    @EventId BIGINT,
    @EventCommentId BIGINT = NULL,
    @EmployeeRefUrl NVARCHAR(500) = NULL,
    @EmployeeCode NVARCHAR(100) = NULL,
    @QStatus INT OUTPUT,
	@EventRegTicketId bigint
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY    

        -------------------------------
        -- Step 1: Insert/Update CheckIn
        -------------------------------

		SET @EventRegistrationTypeId = (SELECT EventRegistrationTypeId FROM EventRegTickets WHERE EventRegTicketId = @EventRegTicketId);

        IF((SELECT COUNT(*) 
            FROM EventRegCheckIn 
            WHERE EventRegTicketId = @EventRegTicketId) = 0)
        BEGIN
            INSERT INTO dbo.EventRegCheckIn
            (
                EventRegCountId,
                EventUserInfoId,
                EventRegistrationTypeId,
                Status,
                Comments,
                CheckInDate,
                InsertedDate,
                InsertedBy,
                EventId,
				EventRegTicketId
            )
            VALUES
            (
                @EventRegCountId,
                @EventUserInfoId,
                @EventRegistrationTypeId,
                @Status,
                @Comments,
                @CheckInDate,
                @CheckInDate,
                @InsertedBy,
                @EventId,
				@EventRegTicketId
            );

            SELECT SCOPE_IDENTITY() AS NewEventCheckInId;
            SELECT @QStatus = 1; -- check-in inserted
        END
        ELSE
        BEGIN
            UPDATE dbo.EventRegCheckIn
            SET Status      = @Status, 
                Comments    = @Comments, 
                CheckInDate = @CheckInDate
            WHERE EventRegTicketId = @EventRegTicketId;

            SELECT @QStatus = 2; -- check-in updated
        END

        -------------------------------
        -- Step 2: Insert/Update EventComments
        -------------------------------
        IF(@EventCommentId IS NOT NULL)
        BEGIN
            IF((SELECT COUNT(*) 
                FROM EventComments 
                WHERE EventCommentId = @EventCommentId 
                  AND EventUserInfoId = @EventUserInfoId) = 0)
            BEGIN
                INSERT INTO EventComments
                (
                    EventUserInfoId,
                    Status,       -- this will hold Overall Check-In status
                    Comment,      -- final comments
                    InsertedBy,
                    InsertedDate,
                    EmployeeRefUrl,
                    EmployeeCode
                )
                VALUES
                (
                    @EventUserInfoId,
                    @Status,       -- temporarily same as current status
                    @Comments,
                    @InsertedBy,
                    @CheckInDate,
                    @EmployeeRefUrl,
                    @EmployeeCode
                );

                SELECT @QStatus = 3; -- new comment inserted
            END
            ELSE
            BEGIN
                UPDATE EventComments
                SET Comment        = @Comments,
                    EmployeeRefUrl = @EmployeeRefUrl,
                    EmployeeCode   = @EmployeeCode
                WHERE EventCommentId = @EventCommentId;

                SELECT @QStatus = 4; -- comment updated
            END
        END

        -------------------------------
        -- Step 3: Maintain Overall Status in EventComments
        -------------------------------
     IF NOT EXISTS (
    SELECT 1
    FROM EventRegTickets T
    LEFT JOIN EventRegCheckIn C 
        ON C.EventRegTicketId = T.EventRegTicketId
    WHERE T.EventRegCountId = @EventRegCountId
      AND (C.Status IS NULL OR C.Status <> 'Yes')
)
BEGIN
IF((SELECT COUNT(*) FROM EventComments WHERE EventUserInfoId = @EventUserInfoId) = 1)
BEGIN
    -- ✅ All tickets under this EventRegCount are checked-in
    UPDATE EventComments
    SET Status  = 'OverallCompleted',
        Comment = ISNULL(@Comments, '') + ' | All tickets checked-in successfully',
        InsertedDate = GETDATE()
    WHERE EventUserInfoId = @EventUserInfoId;
	END
	ELSE
	BEGIN
	INSERT INTO EventComments 
	VALUES (@EventUserInfoId, 'OverallCompleted', null, ISNULL(@Comments, '') + ' | All tickets checked-in successfully', null, 'Cultural Admin', GETDATE(), null, null)
	END
END

    END TRY

    BEGIN CATCH
        SELECT @QStatus = -1;
    END CATCH
END
