/****** Object:  StoredProcedure [dbo].[EventCompetitionsGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[EventCompetitionsGetListByVariable] 
	 (@PageNo int
     ,@Items int
     ,@Search nvarchar(126)
     ,@Total int output
     ,@Sort nvarchar(126)
	 ,@EventId bigint)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);

    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,EventCompetitionId bigint
				,CompetitionName nvarchar(256)
				,Price decimal(15,2)
				,DisplayOrder int
				,IsActive bit
				,Field1 nvarchar(256)
				,Field2 nvarchar(256)
				,Field3 nvarchar(256)
				,InsertedBy nvarchar(64)
				,InsertedDate datetime
				,UpdatedBy nvarchar(64)
				,UpdatedDate datetime
				,NonMemberAmount decimal(15,2)
				,EventId bigint
				,EventName  nvarchar(128)
				)
	
	SELECT @Start = (@PageNo - 1) * @Items     
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
		 SELECT  MT.EventCompetitionId 
		        ,MT.CompetitionName
				,MT.Price 
				,MT.DisplayOrder
				,MT.IsActive
				,MT.Field1
				,MT.Field2
				,MT.Field3
				,MT.InsertedBy
				,MT.InsertedDate
				,MT.UpdatedBy
				,MT.UpdatedDate
				,MT.NonMemberAmount
				,MT.EventId
				,(SELECT EventName FROM Events E WHERE E.EventId = MT.EventId) AS EventName
				FROM EventCompetitions MT  		
				WHERE MT.EventCompetitionId <> 0 AND MT.EventId in (Select Ed.EventId from EventDates ED Where (CONVERT (DATE,ED.StartDate)  >= CONVERT (DATE,GETDATE()) OR ED.StartDate IS NULL OR CONVERT (DATE, ED.StartDate)  <=  CONVERT (DATE, GETDATE()) OR ED.StartDate IS NULL OR ED.EndDate IS NULL) AND ED.EndDate > CONVERT (DATE, GETDATE()))'
	
	IF(@Search <> '')
    BEGIN
		SET @Query = @Query + ' AND  MT.CompetitionName LIKE ''%' + @Search + '%'''
    END

	IF(@EventId <> 0)
    BEGIN
		SET @Query = @Query + ' AND MT.EventId= '+CAST(@EventId as nvarchar(250))
    END
	
	IF(@Sort <> '')
	BEGIN
		SET @Query = @Query + ' ORDER BY ' + @Sort
	END
		
	EXEC sp_ExecuteSQL @Query;
	
	SELECT @Total = COUNT(Rid) from #temp 
			
	SELECT Rid
		  	,EventCompetitionId
			,CompetitionName 
			,Price
			,DisplayOrder
			,IsActive
			,Field1
            ,Field2
			,Field3
			,InsertedBy
			,InsertedDate   
			,UpdatedBy   
			,UpdatedDate
			,NonMemberAmount
			,EventId
			,EventName
	  FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
	  DROP TABLE #temp

END
















