CREATE PROCEDURE [dbo].[EventCompetitionsInsert]
    (@EventCompetitionId bigint
	,@CompetitionName nvarchar(256)
	,@Price decimal(15,2)
	,@DisplayOrder int
	,@IsActive bit
	,@Field1 nvarchar(256)
	,@Field2 nvarchar(256)
	,@Field3 nvarchar(256)
	,@InsertedBy nvarchar(64)
	,@InsertedDate datetime
	,@UpdatedBy nvarchar(64)
	,@UpdatedDate datetime
	,@QStatus int output
	,@NonMemberAmount decimal(15,2)
	,@EventId bigint)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY
		BEGIN TRANSACTION
    
			IF((SELECT COUNT(*) FROM EventCompetitions WHERE EventCompetitionId = @EventCompetitionId) = 0)
			BEGIN
		
				INSERT INTO EventCompetitions VALUES
						(@CompetitionName
						,@Price
						,@DisplayOrder
						,@IsActive
						,@Field1
						,@Field2
						,@Field3
						,@InsertedBy
						,@InsertedDate
						,@UpdatedBy
						,@UpdatedDate
						,@NonMemberAmount
						,@EventId)
				SELECT @QStatus = 1;
			
			END
		
		ELSE 
		   BEGIN
				  UPDATE EventCompetitions SET
					 CompetitionName=@CompetitionName
					 ,Price=@Price
					 ,DisplayOrder=@DisplayOrder
					 ,UpdatedBy=@UpdatedBy
					 ,UpdatedDate=@UpdatedDate
					 ,NonMemberAmount = @NonMemberAmount
					 ,EventId = @EventId
					 WHERE EventCompetitionId = @EventCompetitionId	 
					SELECT @QStatus = 2;
			 END
		 
    COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH 
    
        ROLLBACK TRANSACTION   
		SELECT @QStatus = -1;    
		
    END CATCH   
    
END

















