		IF((SELECT COUNT(*) FROM EventRegistrationTypes WHERE EventRegistrationTypeId = @EventRegistrationTypeId) = 1)
		BEGIN
			UPDATE EventRegistrationTypes SET OrderNo = @OrderNo WHERE EventRegistrationTypeId = @EventRegistrationTypeId
			SELECT @QStatus = 1;
		END
		ELSE
		BEGIN
			SELECT @QStatus = 3;
		END	
	COMMIT TRANSACTION
    END TRY

    BEGIN CATCH
    
         ROLLBACK TRANSACTION
		 SELECT @QStatus = -1;
		 
    END CATCH
    	
END











