/****** Object:  StoredProcedure [dbo].[EventRegTicketsstatuscountUpdate]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[EventRegTicketsstatuscountUpdate]
(
    @EventUserInfoId BIGINT,
    @QStatus INT OUTPUT,
    @EventRegistrationTypeId BIGINT,
    @CheckinCount INT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -- Table variable to store ticket IDs
        DECLARE @Ids TABLE (EventRegTicketId BIGINT);

        INSERT INTO @Ids (EventRegTicketId)
        SELECT TOP (@CheckinCount) EventRegTicketId
        FROM EventRegTickets
        WHERE EventUserInfoId = @EventUserInfoId
          AND EventRegistrationTypeId = @EventRegistrationTypeId and Status <> 'yes'
        ORDER BY GeneratedDate;

        -- Update only those IDs
        UPDATE EventRegTickets
        SET Status = 'yes'
        WHERE EventRegTicketId IN (SELECT EventRegTicketId FROM @Ids);

        SET @QStatus = 1;
    END TRY
    BEGIN CATCH
        SET @QStatus = -1;
    END CATCH    
END








