SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[EventsGetById]
	(@EventId bigint
	,@EventName nvarchar(1024)
    ,@QStatus int OUTPUT)    
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
   SET NOCOUNT ON;

   BEGIN TRY 
   
		IF(@EventId=0)
			BEGIN
				SET @EventId= (SELECT EventId FROM Events WHERE dbo.RemoveSpecialChar(EventName, '^a-z0-9')= dbo.RemoveSpecialChar(@EventName, '^a-z0-9'))
			END

		Declare @StartDate datetime;
		Declare @EndDate datetime;

		Select @StartDate = StartDate, @EndDate = EndDate from 
		(Select EventId, StartDate, EndDate, ROW_NUMBER() OVER(Partition By EventId ORDER BY StartDate ASC) AS RowNo From EventDates
		Where Convert(Date, EndDate) >= Convert(Date, GetDate())) A where A.RowNo = 1 AND A.EventId = @EventId 

        IF(@StartDate is NULL AND @EndDate is NULL)
		  BEGIN
		  Select @StartDate = StartDate, @EndDate = EndDate from (Select EventId, StartDate, EndDate, ROW_NUMBER() OVER(Partition By EventId ORDER BY StartDate DESC) AS RowNo From EventDates) A where A.RowNo = 1 AND A.EventId = @EventId 
		  END


   IF(@EventId!=0)
		BEGIN
		--@StartDate As StartDate,@EndDate As EndDate,
			SELECT  E.*,EC.EventCategory,C.ChapterName
			FROM Events  E 
			LEFT JOIN EventCategories EC ON E.EventCategoryId = EC.EventCategoryId
			left JOIN Chapters C  ON C.ChapterId = E.ChapterId
			WHERE EventId  = @EventId

			SELECT ER.*, (SELECT SUM(COUNT) FROM EventRegistrationCounts WHERE EventRegistrationTypeId = ER.EventRegistrationTypeId AND EventId=@EventId) AS EventRegCount FROM EventRegistrationTypes ER WHERE EventId=@EventId 

			Select * from ChapterEvents Where EventId=@EventId 

			SELECT * FROM EventDates WHERE EventId=@EventId 

			SELECT *, (Select RC.CategoryName from RegistrationCategories RC Where RC.RegistrationCategoryId = ER.RegistrationCategoryId) AS CategoryName FROM EventRegCategoriesList ER WHERE ER.EventId=@EventId 
	    END
		    SELECT @QStatus = 1;
    END TRY

    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH		
	 
END
























GO
