/****** Object:  StoredProcedure [dbo].[EventsGetList]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EventsGetList]
	(
	 @Type nvarchar(256)
    ,@Search nvarchar(126)
    ,@Sort nvarchar(216)
    ,@PageNo int
    ,@Items int
	,@Total int OUTPUT
	,@ChapterId bigint)    
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
   SET NOCOUNT ON;

   BEGIN TRY 
			SET NOCOUNT ON;
			
			DECLARE @Start int, @End INT ;
			DECLARE @Query nvarchar(max);
			  
			  CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
						,EventId bigint
						,ChapterId bigint
						,EventName nvarchar(128)
						,StartDate datetime
						,EndDate datetime
						,RegistrationStartDate datetime
						,RegistrationEndDate datetime
						,BannerUrl nvarchar(156)
						,EventCategoryId bigint
						,MemberCount int
						,Location nvarchar(512)
						,City nvarchar(64)
						,StateName nvarchar(64)
						,ZipCode nvarchar(25)
						,EventDetails nvarchar(max)
						,ContactEmail nvarchar(64)
						,IsRegistration bit
						,PageTitle nvarchar(512) 
						,MetaDescription nvarchar(max) 
						,MetaKeywords nvarchar(max)
						,TopLine nvarchar(512)
						,UpdatedBy nvarchar(30)
						,UpdatedTime datetime
						,Flyer nvarchar(156)
						,EventCategory nvarchar(156))
			
			SELECT @Start = (@PageNo - 1) * @Items     
			SELECT @End = @Start + @Items 
			
			SET @Query = 'INSERT INTO #temp 
				 SELECT  E.EventId
				        ,E.ChapterId 
						,E.EventName 
						,E.StartDate 
						,E.EndDate 
						,E.RegistrationStartDate 
						,E.RegistrationEndDate 
						,E.BannerUrl 
						,E.EventCategoryId 
						,E.MemberCount 
						,E.Location 
						,E.City 
						,E.StateName 
						,E.ZipCode 
						,E.EventDetails 
						,E.ContactEmail 
						,E.IsRegistration 
						,E.PageTitle 
						,E.MetaDescription  
						,E.MetaKeywords 
						,E.TopLine 
						,E.UpdatedBy 
						,E.UpdatedTime
						,E.Flyer
						,EC.EventCategory
						FROM Events  E 
						INNER JOIN EventCategories EC ON E.EventCategoryId = EC.EventCategoryId 
						WHERE EventId <> 0'


					
			IF(@ChapterId <> 0)
			BEGIN
				SET @Query=@Query + 'AND E.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))
			END  

			IF(@Search <> '')
				BEGIN
					SET @Query = @Query + ' AND  EventName LIKE ''%' + @Search + '%'''
				END

			IF(@Type = 'upcoming')
				BEGIN
					SET @Query = @Query + ' AND  CONVERT (DATE,E.StartDate)  >= CONVERT (DATE,GETDATE()) OR E.StartDate IS NULL AND CONVERT (DATE, E.StartDate)  <=  CONVERT (DATE, GETDATE()) OR E.StartDate IS NULL OR E.EndDate IS NULL '
				END

			ELSE IF(@Type = 'past')
				BEGIN
					SET @Query = @Query + ' AND CONVERT (DATE, E.EndDate)  < CONVERT (DATE, GETDATE())'
				END

			ELSE IF(@Type = 'current')
				BEGIN
					SET @Query = @Query + ' AND CONVERT (DATE, E.StartDate)  <=  CONVERT (DATE, GETDATE()) AND CONVERT (DATE, E.EndDate)  >= CONVERT (DATE, GETDATE())'
				END
			  
			  
		    SELECT @Total = 1;

			IF(@Sort <> '')
			BEGIN
				SET @Query = @Query + ' ORDER BY ' + @Sort
			END

			EXEC sp_ExecuteSQL @Query;
			
			SELECT @Total = COUNT(Rid) from #temp 
					
			SELECT  *  FROM #temp WHERE Rid > @Start AND  Rid <= @End
			
			  DROP TABLE #temp
		
    END TRY
    BEGIN CATCH
		 SELECT @Total = -1;
    END CATCH		
	 
END













