CREATE PROCEDURE [dbo].[EventsGetListByVariable]      
  (@EventStatusId bigint        
  ,@StartDate nvarchar(126)        
  ,@EndDate nvarchar(126)        
  ,@EventType nvarchar(126)        
  ,@Search nvarchar(126)        
  ,@Sort nvarchar(216)        
  ,@PageNo int        
  ,@Items int        
  ,@Total int OUTPUT        
  ,@ChapterId bigint        
  ,@MemberId bigint)        
                
AS        
BEGIN        
        
 -- SET NOCOUNT ON added to prevent extra result sets from        
       
         
 --BEGIN TRY         
         
   SET NOCOUNT ON;        
           
   DECLARE @Start int, @End INT ;        
   DECLARE @Query nvarchar(max);        
              
   CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)        
      ,EventId bigint         
      ,ChapterId bigint        
      ,EventName nvarchar(128)        
      ,StartDate datetime        
      ,EndDate datetime        
      ,RegistrationStartDate datetime        
      ,RegistrationEndDate datetime        
      ,BannerUrl nvarchar(156)        
      ,EventCategoryId bigint        
      ,MemberCount int        
      ,Location nvarchar(512)        
      ,City nvarchar(64)        
      ,StateName nvarchar(64)        
      ,ZipCode nvarchar(25)        
      ,EventDetails nvarchar(max)        
      ,ContactEmail nvarchar(64)        
      ,IsRegistration bit   
   ,IsCulturalRegistration BIT  
      ,PageTitle nvarchar(512)         
      ,MetaDescription nvarchar(max)         
      ,MetaKeywords nvarchar(max)        
      ,TopLine nvarchar(512)        
      ,UpdatedBy nvarchar(30)        
      ,UpdatedTime datetime        
   ,IsActive bit       
      ,Flyer nvarchar(156)        
     ,EventCategory nvarchar(156)        
      ,UsersCount bigint     
         ,CUsersCount bigint      
  
         
   )        
           
   SELECT @Start = (@PageNo - 1) * @Items             
   SELECT @End = @Start + @Items         
           
   SET @Query = 'INSERT INTO #temp         
     SELECT    E.EventId        
              ,E.ChapterId        
     ,E.EventName         
     ,E.StartDate         
     ,E.EndDate         
     ,E.RegistrationStartDate         
     ,E.RegistrationEndDate         
     ,E.BannerUrl         
     ,E.EventCategoryId         
     ,E.MemberCount         
     ,E.Location         
     ,E.City         
     ,E.StateName         
     ,E.ZipCode         
     ,E.EventDetails         
     ,E.ContactEmail         
     ,E.IsRegistration     
    ,E.IsCulturalRegistration   
     ,E.PageTitle         
     ,E.MetaDescription          
     ,E.MetaKeywords         
     ,E.TopLine         
     ,E.UpdatedBy         
     ,E.UpdatedTime       
     ,E.IsActive       
     ,Flyer         
    ,(Select EC.EventCategory From EventCategories EC where EC.EventCategoryId = E.EventCategoryId) as EventCategory        
     ,(Select Count(*) From EventUserInfo EI where EI.EventId = E.EventId) as UsersCount      
      ,(Select Count(*) From CulturalRegistrations CR where CR.EventId = E.EventId) as CUsersCount     
     FROM Events  E         
      
     WHERE E.EventId <> 0 '        
      
      
   IF(@EventStatusId <> 0)        
  BEGIN        
   SET @Query=@Query + 'AND E.StatusId = ' + CAST(@EventStatusId AS nvarchar(30))        
  END          
      
      
       
 IF(@ChapterId <> 0)      
   BEGIN      
       IF(@ChapterId = 1000)      
    BEGIN      
    SET @Query=@Query + 'AND E.EventId NOT in (Select EventId from ChapterEvents)'      
    END      
    ELSE       
    BEGIN      
    SET @Query=@Query + 'AND E.EventId in (Select EventId from ChapterEvents Where ChapterId = ' + CAST(@ChapterId AS nvarchar(30))+')'      
    END      
   END        
      
      
      
      
      
   IF(@Search <> '')        
  BEGIN        
   SET @Query = @Query + ' AND  EventName LIKE ''%' + @Search + '%'''        
  END        
   IF(@EventType = 'upcoming')        
  BEGIN            
   SET @Query = @Query + ' AND E.EventId in (Select Ed.EventId from Events ED Where (CONVERT (DATE,ED.StartDate)  >= CONVERT (DATE,GETDATE()) OR ED.StartDate IS NULL OR CONVERT (DATE, ED.StartDate)  <=  CONVERT (DATE, GETDATE()) OR ED.StartDate IS NULL OR
  
    
 ED.EndDate IS NULL) AND ED.EndDate > CONVERT (DATE, GETDATE())) '            
  END        
   ELSE IF(@EventType = 'past')        
  BEGIN        
   SET @Query = @Query + ' AND E.EventId in (Select Ed.EventId from Events ED Where CONVERT (DATE, ED.EndDate)  < CONVERT (DATE, GETDATE()))'        
  END        
   ELSE IF(@EventType = 'current')        
  BEGIN        
   SET @Query = @Query + ' AND E.EventId in (Select Ed.EventId from Events ED Where CONVERT (DATE, ED.StartDate)  <=  CONVERT (DATE, GETDATE()) AND CONVERT (DATE, ED.EndDate)  >= CONVERT (DATE, GETDATE()))'        
  END        
            
   IF(@StartDate <> '' OR @EndDate <> '')        
   BEGIN        
  IF(@StartDate <> '' AND @EndDate <> '')        
   BEGIN        
    SET @Query = @Query + ' AND  (StartDate BETWEEN ''' + @StartDate + ''' AND ''' + @EndDate + ''')  AND (EndDate BETWEEN ''' + @StartDate + ''' AND ''' + @EndDate + ''')'        
   END        
            
  IF(@StartDate <> '' AND @EndDate = '')        
   BEGIN        
    SET @Query = @Query + ' AND  ''' + @StartDate + ''' BETWEEN StartDate AND EndDate'        
   END        
      
  IF(@StartDate = '' AND @EndDate <> '')        
   BEGIN        
    SET @Query = @Query + ' AND  ''' + @EndDate + ''' BETWEEN StartDate AND EndDate'        
   END        
    END        
           
   IF(@Sort <> '')        
    BEGIN        
    IF(@EventType = 'upcoming')        
   BEGIN        
   SET @Query = @Query + ' ORDER BY E.StartDate ASC '          
   END        
  ELSE IF(@EventType = 'past')        
   BEGIN        
   SET @Query = @Query + ' ORDER BY E.StartDate DESC'        
   END        
   END        
            
   EXEC sp_ExecuteSQL @Query;        
   Print @Query;      
            
   SELECT @Total = COUNT(Rid) from #temp         
             
   SELECT  *  FROM #temp WHERE Rid > @Start AND  Rid <= @End        
           
     DROP TABLE #temp        
            
 ----News Active and InActive      
 --Update News set IsActive = 0 where   CONVERT(DATE, ExpiryDate) < CONVERT(DATE, GETDATE())       
 --IF EXISTS ((select * from News where (CONVERT(DATE, ExpiryDate) < CONVERT(DATE, GETDATE()))) )      
 -- BEGIN      
 --  Update News set IsActive = 0 where   CONVERT(DATE, ExpiryDate) < CONVERT(DATE, GETDATE())       
 -- END      
      
 --IF((SELECT COUNT(*) FROM News WHERE IsActive = 1) = 0)       
 -- Begin      
 --  update News set IsActive = 1 where NewsId = 10019       
 -- End      
 --Else      
 -- Begin      
 --  update News set IsActive = 0 where NewsId = 10019       
 -- End      
      
    --END TRY        
      
    --BEGIN CATCH        
    --  SELECT @Total = -1;        
    --END CATCH        
          
END        
      
      
      
      
