CREATE PROCEDURE [dbo].[EventsInsert]        
    (@EventId bigint         
    ,@ChapterId bigint        
    ,@EventName nvarchar(128)        
    ,@StartDate datetime        
    ,@EndDate datetime        
    ,@RegistrationStartDate datetime        
    ,@RegistrationEndDate datetime        
    ,@BannerUrl nvarchar(156) output        
    ,@Flyer nvarchar(156) output        
    ,@EventCategoryId bigint        
    ,@MemberCount int        
    ,@Location nvarchar(512)        
    ,@City nvarchar(64)        
    ,@StateName nvarchar(64)        
    ,@ZipCode nvarchar(25)        
    ,@EventDetails nvarchar(max)        
    ,@ContactEmail nvarchar(64)        
    ,@IsRegistration bit         
    ,@PageTitle nvarchar(512)         
    ,@MetaDescription nvarchar(max)         
    ,@MetaKeywords nvarchar(max)         
    ,@TopLine nvarchar(512)        
    ,@UpdatedBy nvarchar(30)        
    ,@UpdatedTime datetime        
    ,@XMLRegistrations nvarchar(max)        
    ,@IsCulturalRegistration bit        
    ,@QStatus int output        
    ,@ChapterIds nvarchar(2048)        
    ,@XMLDates nvarchar(max)        
    ,@XMLRegistrationsCat nvarchar(max)        
    ,@EarlyBirdCutOfDate datetime        
    ,@IsEarlyBird bit        
    ,@IsMemberAmount bit        
    ,@IsNonMemberAmount bit    
    ,@IsQrcode nvarchar(126)     
    ,@IsActive bit      
    )          
AS        
BEGIN        
    SET NOCOUNT ON;        
        
    IF((SELECT COUNT(*) FROM Events WHERE EventId = @EventId) = 0)        
    BEGIN        
        -- ✅ INSERT columns explicitly listed to avoid position mismatch  
        INSERT INTO Events   
        (  
            ChapterId, EventName, StartDate, EndDate,  
            RegistrationStartDate, RegistrationEndDate,  
            BannerUrl,                          -- set to NULL first, updated below  
            EventCategoryId, MemberCount,  
            Location, City, StateName, ZipCode,  
            EventDetails, ContactEmail,  
            IsRegistration, PageTitle, MetaDescription,  
            MetaKeywords, TopLine, UpdatedBy, UpdatedTime,  
            IsCulturalRegistration,  
            Flyer,                              -- ✅ correct position  
            EarlyBirdCutOfDate, IsEarlyBird,  
            IsMemberAmount, IsNonMemberAmount,  
            IsActive, IsQRCode  
        )  
        VALUES        
        (  
            @ChapterId, @EventName, @StartDate, @EndDate,  
            @RegistrationStartDate, @RegistrationEndDate,  
            NULL,                               -- BannerUrl updated below  
            @EventCategoryId, @MemberCount,  
            @Location, @City, @StateName, @ZipCode,  
            @EventDetails, @ContactEmail,  
            @IsRegistration, @PageTitle, @MetaDescription,  
            @MetaKeywords, @TopLine, @UpdatedBy, @UpdatedTime,  
            @IsCulturalRegistration,  
            NULL,                               -- Flyer updated below  
            @EarlyBirdCutOfDate, @IsEarlyBird,  
            @IsMemberAmount, @IsNonMemberAmount,  
            @IsActive, @IsQrcode  
        )  
             
        SELECT @EventId = SCOPE_IDENTITY()           
               
        IF(@BannerUrl <> 'NA')        
        BEGIN        
            UPDATE Events SET BannerUrl = CAST(@EventId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@EventName, '^a-z0-9') + '.' + @BannerUrl WHERE EventId = @EventId        
            SELECT @BannerUrl = CAST(@EventId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@EventName, '^a-z0-9') + '.' + @BannerUrl         
        END          
  
        IF(@Flyer <> 'NA')        
        BEGIN        
            UPDATE Events SET Flyer = CAST(@EventId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@EventName, '^a-z0-9') + '.' + @Flyer WHERE EventId = @EventId        
            SELECT @Flyer = CAST(@EventId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@EventName, '^a-z0-9') + '.' + @Flyer         
        END          
             
        SELECT @QStatus = 1;        
    END        
    ELSE            BEGIN          
        UPDATE Events        
        SET          
             ChapterId              = @ChapterId        
            ,EventName              = @EventName        
            ,StartDate              = @StartDate        
            ,EndDate                = @EndDate        
            ,RegistrationStartDate  = @RegistrationStartDate         
            ,RegistrationEndDate    = @RegistrationEndDate        
            ,EventCategoryId        = @EventCategoryId        
            ,MemberCount            = @MemberCount         
            ,Location               = @Location         
            ,City                   = @City         
            ,StateName              = @StateName        
            ,ZipCode                = @ZipCode        
            ,EventDetails           = @EventDetails         
            ,ContactEmail           = @ContactEmail          
            ,IsRegistration         = @IsRegistration        
            ,PageTitle              = @PageTitle        
            ,MetaDescription        = @MetaDescription        
            ,MetaKeywords           = @MetaKeywords        
            ,TopLine                = @TopLine        
            ,UpdatedBy              = @UpdatedBy        
            ,UpdatedTime            = @UpdatedTime        
            ,IsCulturalRegistration = @IsCulturalRegistration         
            ,EarlyBirdCutOfDate     = @EarlyBirdCutOfDate        
            ,IsEarlyBird            = @IsEarlyBird        
            ,IsMemberAmount         = @IsMemberAmount        
            ,IsNonMemberAmount      = @IsNonMemberAmount      
            ,IsQrcode               = @IsQrcode  
            ,IsActive               = @IsActive    
        WHERE EventId = @EventId        
             
        IF(@BannerUrl <> 'NA')        
        BEGIN        
            UPDATE Events SET BannerUrl = CAST(@EventId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@EventName, '^a-z0-9') + '.' + @BannerUrl WHERE EventId = @EventId        
            SELECT @BannerUrl = CAST(@EventId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@EventName, '^a-z0-9') + '.' + @BannerUrl         
        END         
             
        IF(@Flyer <> 'NA')        
        BEGIN        
            UPDATE Events SET Flyer = CAST(@EventId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@EventName, '^a-z0-9') + '.' + @Flyer WHERE EventId = @EventId        
            SELECT @Flyer = CAST(@EventId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@EventName, '^a-z0-9') + '.' + @Flyer         
        END         
             
        SELECT @QStatus = 2;         
    END  
   --Registrations    
    IF(@XMLRegistrations!='')    
  BEGIN    
   DECLARE @XML AS XML             
    SELECT @XML = @XMLRegistrations    
    
    /*---------------EventRegistrationTypes Insert -------*/    
            
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1),    
       EventRegistrationTypeId nvarchar(max),    
     RegistrationTitle nvarchar(max),    
     MemberAmount nvarchar(max),    
     NonMemberAmount nvarchar(max),    
     RegCount bigint,    
     OrderNo int,    
     MemberCount  bigint,    
     EarlyBirdMemberAmount nvarchar(max),    
     EarlyBirdNonMemberAmount nvarchar(max)    
     )    
        
    DECLARE @RowCount AS int    
    DECLARE @CurrentRow AS int     
        
    INSERT INTO #temp(EventRegistrationTypeId,RegistrationTitle,MemberAmount,NonMemberAmount,RegCount,OrderNo,MemberCount,EarlyBirdMemberAmount,EarlyBirdNonMemberAmount)    
     select     
     M.Item.value('EventRegistrationTypeId[1]','nvarchar(max)'),    
     M.Item.value('RegistrationTitle[1]','nvarchar(max)'),    
     M.Item.value('MemberAmount[1]','nvarchar(max)'),    
     M.Item.value('NonMemberAmount[1]','nvarchar(max)'),    
     M.Item.value('RegCount[1]','bigint'),    
     M.Item.value('OrderNo[1]','int'),    
     M.Item.value('MemberCount[1]','bigint'),    
     M.Item.value('EarlyBirdMemberAmount[1]','bigint'),    
     M.Item.value('EarlyBirdNonMemberAmount[1]','bigint')    
    
    
     FROM @XML.nodes('/ArrayOfEventRegistrationTypes/EventRegistrationTypes') AS M(Item)    
         
    SET @RowCount = @@ROWCOUNT     
    SELECT @RowCount    
    SET @CurrentRow = 1    
    WHILE @CurrentRow < @RowCount + 1    
    BEGIN     
     IF((SELECT RegistrationTitle FROM #temp WHERE Rid = @CurrentRow) IS NOT NULL AND  (SELECT RegistrationTitle FROM #temp WHERE Rid = @CurrentRow)<>'')    
     BEGIN    
       IF((SELECT COUNT(*) FROM EventRegistrationTypes WHERE EventRegistrationTypeId = (SELECT EventRegistrationTypeId FROM #temp WHERE Rid = @CurrentRow))=0)    
       BEGIN    
        INSERT INTO EventRegistrationTypes     
        SELECT           
         @EventId,    
         RegistrationTitle,    
         MemberAmount,    
         NonMemberAmount,    
         RegCount,    
         OrderNo,    
          1,    
          @UpdatedBy    
         ,@UpdatedTime    
         ,MemberCount    
         ,EarlyBirdMemberAmount    
         ,EarlyBirdNonMemberAmount    
         ,null    
            
         FROM #temp WHERE Rid = @CurrentRow     
        END      
        ELSE    
        BEGIN    
        UPDATE EventRegistrationTypes SET     
        RegistrationTitle=(SELECT RegistrationTitle FROM #temp WHERE Rid = @CurrentRow)    
        WHERE EventRegistrationTypeId = (SELECT EventRegistrationTypeId FROM #temp WHERE Rid = @CurrentRow)     
        END         
      END       
     SET @CurrentRow = @CurrentRow + 1    
    
    END     
        
    DROP TABLE #temp    
  END    
    
    
  --Registrations    
    IF(@XMLDates!='')    
  BEGIN    
   DECLARE @XML1 AS XML             
    SELECT @XML1 = @XMLDates    
    
    /*---------------EventRegistrationTypes Insert -------*/    
            
    CREATE TABLE #temp1(Rid1 INT PRIMARY KEY IDENTITY(1,1),    
       EventDatesId nvarchar(max),    
        EventId nvarchar(max),    
     StartDate nvarchar(max),    
     EndDate nvarchar(max),    
     Field1 nvarchar(max),    
     Field2 nvarchar(max),    
     OrderNo int     
     )    
        
    DECLARE @RowCount2 AS int    
    DECLARE @CurrentRow2 AS int     
        
    INSERT INTO #temp1(EventDatesId,EventId,StartDate,EndDate)    
     select     
     M.Item.value('EventDatesId[1]','nvarchar(max)'),    
     M.Item.value('EventId[1]','nvarchar(max)'),    
     M.Item.value('StartDate[1]','nvarchar(max)'),    
     M.Item.value('EndDate[1]','nvarchar(max)')    
     FROM @XML1.nodes('/ArrayOfEventDates/EventDates') AS M(Item)    
         
    SET @RowCount2 = @@ROWCOUNT     
    SELECT @RowCount2    
    SET @CurrentRow2 = 1    
    WHILE @CurrentRow2 < @RowCount2 + 1    
    BEGIN     
     IF((SELECT EventId FROM #temp1 WHERE Rid1 = @CurrentRow2) IS NOT NULL AND  (SELECT EventId FROM #temp1 WHERE Rid1 = @CurrentRow2)<>'')    
     BEGIN    
       IF((SELECT COUNT(*) FROM EventDates WHERE EventDatesId = (SELECT EventDatesId FROM #temp1 WHERE Rid1 = @CurrentRow2))=0)    
       BEGIN    
        INSERT INTO EventDates     
        SELECT           
         @EventId,    
         StartDate,    
         EndDate,    
         NULL,    
         NULL,    
         1,    
         1,    
         @UpdatedBy,    
         @UpdatedTime,    
         @UpdatedBy    
        ,@UpdatedTime    
         FROM #temp1 WHERE Rid1 = @CurrentRow2    
        END      
        ELSE    
        BEGIN    
        UPDATE EventDates SET     
        StartDate=(SELECT StartDate FROM #temp1 WHERE Rid1 = @CurrentRow2),    
        EndDate=(SELECT EndDate FROM #temp1 WHERE Rid1 = @CurrentRow2)    
        WHERE EventDatesId = (SELECT EventDatesId FROM #temp1 WHERE Rid1 = @CurrentRow2)     
        END         
      END       
     SET @CurrentRow2 = @CurrentRow2 + 1    
    
    END     
        
    DROP TABLE #temp1    
  END    
    
    
  IF(@XMLRegistrationsCat!='')    
  BEGIN    
   DELETE EventRegCategoriesList WHERE EventId= @EventId    
   DECLARE @XML2 AS XML             
    SELECT @XML2 = @XMLRegistrationsCat    
    
    /*---------------EventRegistrationTypes Insert -------*/    
                CREATE TABLE #temp3(Rid3 INT PRIMARY KEY IDENTITY(1,1),    
     RegistrationCategoryId nvarchar(max),    
     MemberAmount nvarchar(max),    
     NAmount nvarchar(max))    
        
    DECLARE @RowCount3 AS int    
    DECLARE @CurrentRow3 AS int     
        
    INSERT INTO #temp3(RegistrationCategoryId,MemberAmount,NAmount)    
     select     
     M.Item.value('RegistrationCategoryId[1]','nvarchar(max)'),    
     M.Item.value('MemberAmount[1]','nvarchar(max)'),    
     M.Item.value('NAmount[1]','nvarchar(max)')    
     FROM @XML2.nodes('/ArrayOfRegistrationCategories/RegistrationCategories') AS M(Item)    
         
    SET @RowCount3 = @@ROWCOUNT     
    SELECT @RowCount3    
    SET @CurrentRow3 = 1    
    WHILE @CurrentRow3 < @RowCount3 + 1    
    BEGIN     
    
        
    
     IF((SELECT RegistrationCategoryId FROM #temp3 WHERE Rid3 = @CurrentRow3) IS NOT NULL AND  (SELECT RegistrationCategoryId FROM #temp3 WHERE Rid3 = @CurrentRow3)<>'')    
     BEGIN    
        INSERT INTO EventRegCategoriesList     
        SELECT           
         RegistrationCategoryId,    
         @EventId,    
         MemberAmount,    
         NAmount    
    
         FROM #temp3 WHERE Rid3 = @CurrentRow3     
              
                 
      END       
     SET @CurrentRow3 = @CurrentRow3 + 1    
    
    END     
        
    DROP TABLE #temp3    
  END    
    
 IF(@ChapterIds<>'')  
 Begin  
  DECLARE @RowCount1 AS int  
  DECLARE @CurrentRow1 AS int   
  DECLARE @table1 TABLE (RowID int not null primary key identity(1,1), col1 int )    
  INSERT into @table1 (col1) SELECT part FROM SplitString(@ChapterIds)  
  
  DELETE ChapterEvents WHERE EventId = @EventId  
  
  IF((Select Count(*) From @table1) <> 0)  
  BEGIN  
   Set @RowCount1 = (Select Count(*) From @table1)  
   SET @CurrentRow1 = 1  
   WHILE @CurrentRow1 < @RowCount1 + 1   
   BEGIN  
    INSERT INTO ChapterEvents VALUES   
    ((select col1 from @table1 where RowID = @CurrentRow1)  
    ,@EventId)  
  
    SET @CurrentRow1 = @CurrentRow1 + 1  
   END  
  END   
  
end  
    -- ── rest of SP unchanged (XMLRegistrations, XMLDates etc.) ──  
END
GO
