CREATE PROCEDURE [dbo].[EventsUpdateStatus]
       (@EventId bigint
       ,@QStatus bigint OUTPUT)
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from

	SET NOCOUNT ON;
	
	BEGIN TRY
	
		IF((SELECT IsRegistration FROM Events WHERE EventId = @EventId) = 'True')
			BEGIN
			UPDATE Events SET IsRegistration = 'False' WHERE EventId = @EventId
			END
		ELSE
			BEGIN
			UPDATE Events SET IsRegistration = 'True' WHERE EventId = @EventId
			END
			
	    SELECT @QStatus = 1;
	
	END TRY
	
    BEGIN CATCH
    
		 SELECT @QStatus = -1;
		 
    END CATCH  
    
END


















