CREATE PROCEDURE [dbo].[EventUserInfoDelete]
    (@EventUserInfoId bigint
    ,@QStatus int output)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;

    BEGIN TRY
    BEGIN TRANSACTION
        
		DELETE FROM EventUserInfo WHERE EventUserInfoId = @EventUserInfoId
		DELETE FROM EventRegistrationCounts WHERE EventUserInfoId = @EventUserInfoId
		SELECT @QStatus = 1;
	
	COMMIT TRANSACTION	
    END TRY

    BEGIN CATCH	
		 ROLLBACK TRANSACTION  
		 SELECT @QStatus = -1;
    END CATCH
    	
END











