/****** Object:  StoredProcedure [dbo].[EventUserInfoFullDetailsGetById]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[EventUserInfoFullDetailsGetById]   
 (@EventUserInfoId bigint    
    ,@QStatus int OUTPUT    
 ,@EventId bigint)        
            
AS    
BEGIN    
    
 -- SET NOCOUNT ON added to prevent extra result sets from    
     
   SET NOCOUNT ON;    
    
   --BEGIN TRY      
           SELECT  DISTINCT  EUI.EventUserInfoId    
      ,E.EventId     
      ,E.EventName    
      ,E.StartDate    
      ,E.EndDate     
      ,E.Location     
      ,E.IsQRCode      
      ,EUI.FirstName    
      ,EUI.LastName    
      ,EUI.Email    
      ,EUI.Gender    
      ,EUI.Address    
      ,EUI.City    
      ,EUI.State    
      ,EUI.Mobile    
      ,EUI.ItemName     
      ,EUI.ItemCategory     
      ,EUI.ItemDescription     
      ,EUI.OtherPaymentId     
      ,EUI.ItemDuration     
      ,EUI.IsApproved    
      ,EUI.DocumentUrl    
      ,EUI.UpdatedBy    
      ,EUI.UpdatedTime     
      ,EC.EventCategory    
      ,EC.EventCategoryId     
      ,EUI.Comments       
      ,EUI.Zelle     
      ,EUI.ReceiptUrl    
      ,EUI.ZellePartnerName    
      ,EUI.ChequeHolderName    
      ,(select top(1) Status from EventComments where EventUserInfoId = @EventUserInfoId ORDER by InsertedDate desc) as Status    
      ,(select top(1) Comment from EventComments where EventUserInfoId = @EventUserInfoId ORDER by InsertedDate desc) as Comment,    
      (SELECT TOP (1) Field1  FROM EventComments WHERE EventUserInfoId = @EventUserInfoId ORDER BY InsertedDate DESC) AS CheckinCount    
      FROM Events  E     
      INNER JOIN EventUserInfo EUI ON E.EventId = EUI.EventId     
      INNER JOIN EventCategories EC ON EC.EventCategoryId = E.EventCategoryId     
      WHERE  EUI.EventUserInfoId=@EventUserInfoId    
        
         SELECT EventParticipantId    
        ,EventId    
        ,EventUserInfoId    
        ,FirstName    
        ,LastName    
        ,Email    
        ,Age    
        ,Mobile    
        ,IsApproved    
        ,UpdatedBy    
        ,UpdatedTime    
         FROM EventParticipants WHERE EventUserInfoId = @EventUserInfoId    
             
         SELECT *,PM.PaymentMethod,PS.PaymentStatus FROM EventUserInfo MO     
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=MO.PaymentMethodId     
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId      
      WHERE EventUserInfoId=@EventUserInfoId    
    
    
       SELECT     
        ERC.EventRegCountId,    
        ERC.EventId,    
        ERC.EventUserInfoId,    
        ERC.EventRegistrationTypeId,    
        ERT.RegistrationTitle,    
   ERT.EarlyBirdMemberAmount,    
        ERC.Count,    
        ERC.Amount,    
    
        -- Total Tickets    
        COUNT(ERTK.EventRegTicketId) AS TotalTickets,    
    
        -- Checked-In Tickets    
        SUM(CASE WHEN EC.Status = 'Yes' THEN 1 ELSE 0 END) AS CheckedInCount,    
    
        -- Overall Status    
        CASE     
         WHEN COUNT(ERTK.EventRegTicketId) = 0 THEN 'No Tickets'    
         WHEN SUM(CASE WHEN EC.Status = 'Yes' THEN 1 ELSE 0 END) = COUNT(ERTK.EventRegTicketId)     
           THEN 'Completed'    
            ELSE 'Pending'    
        END AS OverallStatus,    
    
        -- Check-In Details (like 2/3)    
        CAST(SUM(CASE WHEN EC.Status = 'Yes' THEN 1 ELSE 0 END) AS VARCHAR(10))     
         + '/' + CAST(COUNT(ERTK.EventRegTicketId) AS VARCHAR(10)) AS CheckInDetails,    
    
        MAX(EC.CheckInDate) AS LastCheckInDate,    
        --(SELECT TOP (1) Field1  FROM EventComments WHERE EventUserInfoId = @EventUserInfoId ORDER BY InsertedDate DESC) AS CheckinCount    
         -- Checked-In Tickets    
        SUM(CASE WHEN ERTK.Status = 'Yes' THEN 1 ELSE 0 END) AS CheckinCount    
       FROM EventRegistrationCounts ERC    
       INNER JOIN EventRegistrationTypes ERT     
        ON ERT.EventRegistrationTypeId = ERC.EventRegistrationTypeId    
       LEFT JOIN EventRegTickets ERTK     
    
        ON ERTK.EventRegCountId = ERC.EventRegCountId    
       LEFT JOIN EventRegCheckIn EC     
        ON EC.EventRegTicketId = ERTK.EventRegTicketId    
       WHERE ERC.EventUserInfoId IN (@EventUserInfoId)    
       GROUP BY     
        ERC.EventRegCountId,    
           
 ERC.EventId,    
        ERC.EventUserInfoId,    
        ERC.EventRegistrationTypeId,    
        ERT.RegistrationTitle,    
   ERT.EarlyBirdMemberAmount,    
        ERC.Count,    
        ERC.Amount    
    
      --Select ERC.*,ERT.RegistrationTitle from EventRegistrationCounts ERC INNER JOIN EventRegistrationTypes ERT on ERT.EventRegistrationTypeId = ERC.EventRegistrationTypeId where ERC.EventUserInfoId IN (@EventUserInfoId)     
      
    
    
       Select ERC.*,ERT.RegistrationTitle, EC.Status as CheckInStatus, EC.Comments, EC.CheckInDate from EventRegTickets ERC     
      INNER JOIN EventRegistrationTypes ERT on ERT.EventRegistrationTypeId = ERC.EventRegistrationTypeId    
      LEFT JOIN EventRegCheckIn EC on EC.EventRegTicketId = ERC.EventRegTicketId    
      where ERC.EventUserInfoId IN (@EventUserInfoId)     
    
      SELECT @QStatus = 1;    
      
   -- END TRY    
    
   -- BEGIN CATCH    
   --SELECT @QStatus = -1;    
   -- END CATCH      
      
END    
GO
