/****** Object:  StoredProcedure [dbo].[EventUserInfoGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROCEDURE [dbo].[EventUserInfoGetListByVariable]  
  (@Search nvarchar(126)  
  ,@EventId bigint  
  ,@EventCategory nvarchar(64)  
  ,@Sort nvarchar(216)  
  ,@PageNo int  
     ,@Items int  
     ,@Total int OUTPUT)  
          
AS  
BEGIN  
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
   
 BEGIN TRY   
   
   SET NOCOUNT ON;  
     
   DECLARE @Start int, @End INT ;  
   DECLARE @Query nvarchar(max);  
        
   CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)  
      ,EventUserInfoId bigint  
      ,EventId bigint   
      ,EventName nvarchar(128)  
      ,FirstName nvarchar(156)  
      ,LastName nvarchar(156)  
      ,Email nvarchar(156)  
      ,Gender nvarchar(50)  
      ,Address nvarchar(156)  
      ,City nvarchar(156)  
      ,State nvarchar(156)  
      ,Mobile nvarchar(15)  
      ,ItemName nvarchar(1024)  
      ,ItemCategory nvarchar(1024)  
      ,ItemDescription nvarchar(1024)  
      ,ItemDuration int  
      ,IsApproved bit  
      ,DocumentUrl nvarchar(156)  
      ,UpdatedBy nvarchar(64)  
      ,UpdatedTime datetime   
      ,InsertedTime datetime  
      ,EventCategory nvarchar(156)  
      ,PaymentMethod nvarchar(156)  
      ,PaymentStatus nvarchar(156)  
      ,AmountPaid decimal(15,2)  
      ,TransactionId nvarchar(64)  
      ,PaymentDate datetime  
      ,Status nvarchar(156)  
      ,Comment nvarchar(156))  
     
   SELECT @Start = (@PageNo - 1) * @Items       
   SELECT @End = @Start + @Items   
     
   SET @Query = 'INSERT INTO #temp   
     SELECT  DISTINCT  EUI.EventUserInfoId  
      ,E.EventId   
      ,E.EventName        
      ,EUI.FirstName  
      ,EUI.LastName  
      ,EUI.Email  
      ,EUI.Gender  
      ,EUI.Address  
      ,EUI.City  
      ,EUI.State  
      ,EUI.Mobile  
      ,EUI.ItemName   
      ,EUI.ItemCategory   
      ,EUI.ItemDescription   
      ,EUI.ItemDuration   
      ,EUI.IsApproved  
      ,EUI.DocumentUrl  
      ,EUI.UpdatedBy  
      ,EUI.UpdatedTime  
      ,EUI.InsertedTime    
      ,EC.EventCategory   
      ,PM.PaymentMethod   
      ,PS.PaymentStatus   
      ,EUI.AmountPaid  
      ,EUI.TransactionId  
      ,EUI.PaymentDate   
      ,(Select top(1) Status from EventComments Where EventUserInfoId = EUI.EventUserInfoId) as Status  
      ,(Select top(1) Comment from EventComments Where EventUserInfoId = EUI.EventUserInfoId) as Comment  
      FROM Events  E   
	  -- INNER JOIN Events EUI ON E.EventId = EUI.EventId   
      INNER JOIN EventUserInfo EUI ON E.EventId = EUI.EventId   
      LEFT JOIN EventCategories EC ON EC.EventCategoryId = E.EventCategoryId   
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId = EUI.PaymentMethodId   
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId = EUI.PaymentStatusId    
      WHERE E.EventId= ' + CAST(@EventId as nvarchar(max))  
      
     
   IF(@Search <> '')  
   BEGIN  
    SET @Query = @Query + ' AND  EUI.FirstName LIKE ''%' + @Search + '%'' OR  EUI.LastName LIKE ''%' + @Search + '%'''  
   END  
  
   IF(@EventCategory <> '')  
   BEGIN  
    SET @Query = @Query + ' AND  EC.EventCategory LIKE ''%' + @EventCategory + '%'''  
   END  
     
   IF(@Sort <> '')  
   BEGIN  
    SET @Query = @Query + ' ORDER BY ' + @Sort  
   END  
      
   EXEC sp_ExecuteSQL @Query;  
     
   SELECT @Total = COUNT(Rid) from #temp   
       
   SELECT  *  FROM #temp WHERE Rid > @Start AND  Rid <= @End  
     
   DROP TABLE #temp  
      
    END TRY  
  
    BEGIN CATCH  
   SELECT @Total = -1;  
    END CATCH  
    
END  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  


GO
/****** Object:  StoredProcedure [dbo].[EventUserInfoIndividualGetById]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create PROCEDURE [dbo].[EventUserInfoIndividualGetById]
(@EventUserInfoId BIGINT,
 @QStatus INT OUTPUT,
 @EventId BIGINT,
 @EventRegTicketId BIGINT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -- Other selects (EventUserInfo, Participants, Payments) stay as they are above...

        -- ✅ Combined Ticket + Summary in ONE result set
        SELECT 
    -- Personal / Event Details
    EUI.EventUserInfoId,
    E.EventId,
    E.EventName,
    EUI.FirstName,
    EUI.LastName,
    EUI.Email,
    EUI.Gender,
    EUI.Address,
    --EUI.Address2,
    EUI.City,
    EUI.State,
    --EUI.ZipCode,
    EUI.Mobile,
    EUI.ItemName,
    EUI.ItemCategory,
    EUI.ItemDescription,
    EUI.OtherPaymentId,
    EUI.ItemDuration,
    EUI.IsApproved,
    EUI.DocumentUrl,
    EUI.UpdatedBy,
    EUI.UpdatedTime,
    ECAT.EventCategory,
    ECAT.EventCategoryId,
    EUI.Comments,
    EUI.Zelle,
    EUI.ReceiptUrl,
    EUI.ZellePartnerName,
    EUI.ChequeHolderName,
	 EUI.UpdatedTime,
    PM.PaymentMethod,
    PS.PaymentStatus,
    EC.Status AS TicketStatus,
    EC.Comments AS TicketComments,
    EC.CheckInDate,
    ERC.EventRegCountId,
    ERC.EventRegistrationTypeId,
    ERT.RegistrationTitle,
    ERC.Count AS PurchasedCount,
    ERC.Amount AS PaidAmount,
    ERTK.EventRegTicketId,
	ERTK.SequenceNo,
	ERTK.TicketId

FROM EventRegTickets ERTK
INNER JOIN EventRegistrationCounts ERC
    ON ERC.EventRegCountId = ERTK.EventRegCountId
INNER JOIN EventRegistrationTypes ERT
    ON ERT.EventRegistrationTypeId = ERC.EventRegistrationTypeId
INNER JOIN EventUserInfo EUI
    ON EUI.EventUserInfoId = ERC.EventUserInfoId
INNER JOIN Events E
    ON E.EventId = EUI.EventId
INNER JOIN EventCategories ECAT
    ON ECAT.EventCategoryId = E.EventCategoryId
LEFT JOIN EventRegCheckIn EC
    ON EC.EventRegTicketId = ERTK.EventRegTicketId
LEFT JOIN PaymentMethods PM
    ON PM.PaymentMethodId = EUI.PaymentMethodId
LEFT JOIN PaymentStatus PS
    ON PS.PaymentStatusId = EUI.PaymentStatusId
WHERE ERTK.EventRegTicketId = @EventRegTicketId
  AND EUI.EventUserInfoId = @EventUserInfoId;


        SET @QStatus = 1;
    END TRY
    BEGIN CATCH
        SET @QStatus = -1;
    END CATCH
END
GO
