CREATE PROCEDURE [dbo].[EventUserInfoUpdate]  
    (@EventUserInfoId bigint      
 ,@FirstName nvarchar(156)  
 ,@LastName nvarchar(156)  
 ,@Email nvarchar(156)  
 ,@Gender nvarchar(50)  
 ,@Address nvarchar(156)  
 ,@City nvarchar(156)  
 ,@State nvarchar(156)  
 ,@Mobile nvarchar(15)  
 ,@ItemName nvarchar(1024)  
 ,@ItemCategory nvarchar(1024)  
 ,@ItemDescription nvarchar(1024)  
 ,@ItemDuration int  
 ,@IsApproved bit  
 ,@DocumentUrl nvarchar(156)   
 ,@UpdatedBy nvarchar(64)  
 ,@UpdatedTime datetime  
 ,@EventOrderId bigint  
 ,@EventId bigint  
 ,@PaymentStatusId bigint  
 ,@PaymentDate datetime  
 ,@PaymentMethodId bigint  
 ,@TransactionId nvarchar(64)  
 ,@AmountPaid decimal(15,2)  
 ,@IsAttended bit  
 ,@ChildCount int  
 ,@AdultCount int  
 ,@CoupleCount int  
 ,@FamilyCount int  
 ,@VIPCount int  
 ,@VIPSingleAdultCount int  
 ,@VIPCoupleCount int  
 ,@VIPChildCount int  
 ,@InsertedBy nvarchar(30)  
 ,@InsertedDate datetime  
 ,@QStatus int output  
 ,@Zelle nvarchar(512)  
  ,@ReceiptUrl nvarchar(max) output  
  ,@ZellePartnerName nvarchar(512)  
  ,@ChequeHolderName nvarchar(512))    
          
AS  
BEGIN  
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
  
 SET NOCOUNT ON;  
      
    BEGIN TRY  
    BEGIN TRANSACTION  
      
  IF((SELECT COUNT(*) FROM EventUserInfo WHERE EventUserInfoId = @EventUserInfoId) <> 0)  
  BEGIN  
   UPDATE EventUserInfo  
      SET  
     FirstName  = @FirstName   
     ,LastName  = @LastName   
     ,Email   = @Email   
     ,Gender   = @Gender   
     ,Address  = @Address   
     ,City   = @City   
     ,State   = @State   
     ,Mobile   = @Mobile   
     ,ItemName  = @ItemName  
     ,ItemCategory = @ItemCategory  
     ,ItemDescription=   @ItemDescription  
     ,ItemDuration = @ItemDuration    
     ,DocumentUrl = @DocumentUrl   
     ,UpdatedBy  = @UpdatedBy   
     ,UpdatedTime = @UpdatedTime  
     ,PaymentStatusId = @PaymentStatusId   
     ,PaymentDate  = @PaymentDate   
     ,PaymentMethodId = @PaymentMethodId   
     ,TransactionId  = @TransactionId   
     ,AmountPaid   = @AmountPaid   
     ,IsAttended   = @IsAttended  
     ,Zelle = @Zelle  
      ,ZellePartnerName  = @ZellePartnerName  
      ,ChequeHolderName  = @ChequeHolderName  
  
  
   WHERE EventUserInfoId       =   @EventUserInfoId  
  
    
    IF(@ReceiptUrl <> 'NA')    
    BEGIN    
      UPDATE EventUserInfo SET ReceiptUrl = CAST(@EventUserInfoId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@FirstName, '^a-z0-9') + '.' + @ReceiptUrl  WHERE EventUserInfoId = @EventUserInfoId     
      SELECT @ReceiptUrl = CAST(@EventUserInfoId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@FirstName, '^a-z0-9') + '.' + @ReceiptUrl    
    END     
      
      
       
    BEGIN  
    SELECT @ReceiptUrl=''  
   END   
       
  SELECT @QStatus = 2;  
     
  END  
    
 COMMIT TRANSACTION     
    END TRY  
      
    BEGIN CATCH   
  ROLLBACK TRANSACTION       
  SELECT @QStatus = -1;      
    END CATCH     
      
END  
  
  
  
  
  
  
  
  
  
  
GO
