CREATE PROCEDURE [dbo].[ExhibitsRegistrationInsert]
    (@ExhibitId bigint output
	,@FirstName nvarchar(128)
	,@LastName nvarchar(128) 
	,@Phone nvarchar(64)
	,@Email nvarchar(512)
	,@Address1 nvarchar(256)
	,@Address2 nvarchar(256)
	,@City nvarchar(256)
	,@State nvarchar(256)	
	,@Zip nvarchar(64)
	,@NoOfBooths bigint
	,@SigeOfBooth nvarchar(126)
	,@Category  nvarchar(126) 
	,@BusinessName  nvarchar(126) 
	,@Amount Decimal(15,2)
	,@IsActive bit 	
	,@OrderNo bigint 
	,@InsertedBy nvarchar(30)
	,@InsertedDate datetime
	,@UpdatedBy nvarchar(30)
	,@UpdatedDate datetime
	,@QStatus int output)  
     
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;

    
    BEGIN TRY
		BEGIN TRANSACTION
				IF((SELECT COUNT(*) FROM ExhibitsRegistrations WHERE ExhibitId = @ExhibitId) = 0)
					BEGIN
						INSERT INTO ExhibitsRegistrations VALUES
							   ( @FirstName
								,@LastName 
								,@Phone
								,@Email
								,@Address1
								,@Address2
								,@City
								,@State
								,@Zip
								,@NoOfBooths
								,@SigeOfBooth
								,@Category
								,@BusinessName
								,0
								,Null
								,Null
								,Null
								,Null
								,Null 
								,Null
								,Null
								,Null
								,Null
								,@IsActive
								,@OrderNo 
								,@InsertedBy 
								,@InsertedDate 
								,@UpdatedBy
								,@UpdatedDate)	

					SET @ExhibitId = SCOPE_IDENTITY()
					SELECT @QStatus = 1;
				END

			ELSE 
				BEGIN	
					UPDATE ExhibitsRegistrations SET 
						FirstName			=	@FirstName,
						LastName			=	@LastName,  
						Address1			=	@Address1,
						Address2			=	@Address2,
						City				=	@City,
						State				=	@State,
						Zip					=	@Zip,
						NoOfBooths			=	@NoOfBooths,
						SigeOfBooth			=	@SigeOfBooth,
						Category			=	@Category,
						BusinessName		=	@BusinessName,
						Amount				=	@Amount,
						OrderNo				=	@OrderNo, 
						UpdatedBy			=	@UpdatedBy,
						UpdatedDate			=	@UpdatedDate

				 WHERE ExhibitId = @ExhibitId
			SELECT @QStatus = 2;	
			END
			COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH  
    
		ROLLBACK TRANSACTION   
		SELECT @QStatus = -1;    
		
    END CATCH   
    
END












