/****** Object:  StoredProcedure [dbo].[ExhibitsRegistrationsExportToExcel]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ExhibitsRegistrationsExportToExcel]
	 (@Search nvarchar(126)
	 ,@Sort nvarchar(216)
	 ,@PaymentStatusId bigint
	 ,@PaymentMethodId bigint	 
     ,@Total int OUTPUT)
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	BEGIN TRY 
	
			SET NOCOUNT ON;
			
			DECLARE @Start int, @End INT ;
			DECLARE @Query nvarchar(max);
			
			SET @Query = '
				  SELECT 
					 E.FirstName As [First Name]				
					,E.LastName AS [Last Name]	           
					,E.Phone
					,(E.Email) AS [Email Address]				
					,(E.Address1) AS [Mailing Address]		
					,(E.Address2) AS [Names for Admission Passes]		
					,E.City
					,E.State
					,E.Zip
					,E.NoOfBooths
					,E.SigeOfBooth
					,E.Category
					,E.BusinessName
					,E.Amount
					--,(E.AmountPaid) AS PaidAmount
					--,(E.AmountDue) AS DueAmount				
					,TransactionId 
					,(SELECT PaymentMethod FROM PaymentMethods pm1 WHERE pm1.PaymentMethodId=E.PaymentMethodId) AS [Payment Method]
					,(CASE WHEN (SELECT PaymentStatus FROM PaymentStatus ps WHERE ps.PaymentStatusId=E.PaymentStatusId) = ''Completed'' Then ''Payment Successful'' ELSE ''Payment Failed'' END) AS PaymentStatus
					,E.PaymentBy AS [Payment Reason]
					,E.PaymentDate AS [Payment Date]				
					--,E.IsActive
					--,E.OrderNo				
					,E.InsertedBy
					,E.InsertedDate
					FROM ExhibitsRegistrations E
					WHERE E.ExhibitId <> 0'
			 
			
			IF(@PaymentMethodId<>0)
			BEGIN
				SET @Query=@Query + ' AND E.PaymentMethodId = ' + CAST(@PaymentMethodId as nvarchar(50))
			END

			IF(@PaymentStatusId<>0)
			BEGIN
				SET @Query=@Query + ' AND E.PaymentStatusId = ' + CAST(@PaymentStatusId as nvarchar(50))
			END	
			
							
			IF(@Search <> '')
			BEGIN
				SET @Query = @Query + ' AND  E.FirstName LIKE ''%' + @Search + '%'' OR E.Email LIKE ''%' + @Search + '%'''
			END
			
			IF(@Sort <> '')
			BEGIN
				SET @Query = @Query + ' ORDER BY ' + @Sort
			END
			
			EXEC sp_ExecuteSQL @Query;
			SELECT @Total = 1;
			
    END TRY
    BEGIN CATCH
		 SELECT @Total = -1;
    END CATCH
	 
END













