SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[ExhibitsRegistrationsGetListByVariable]
	 (@Search nvarchar(126)
	 ,@PaymentStatusId bigint
	 ,@PaymentMethodId bigint
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,ExhibitId bigint
				,FirstName nvarchar(128)
				,LastName nvarchar(128)
				,IsActive bit
				,Amount decimal(15,2)
				,PaymentDate datetime
				,TransactionId nvarchar(128)
				,Category nvarchar(128)
				,BusinessName nvarchar(128)
				,PaymentStatus nvarchar(156)
				,PaymentMethod nvarchar(156)
				,InsertedDate datetime
				,UpdatedDate datetime)
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             D.ExhibitId
	            ,D.FirstName
	            ,D.LastName
	            ,D.IsActive
	            ,D.Amount
	            ,D.PaymentDate
				,D.TransactionId
				,D.Category
                ,D.BusinessName
				,(select PaymentStatus from PaymentStatus Where PaymentStatusId = D.PaymentStatusId) As PaymentStatus
				,(SELECT PM.PaymentMethod FROM PaymentMethods PM WHERE PM.PaymentMethodId=D.PaymentMethodId) AS PaymentMethod
	            ,D.InsertedDate 
	            ,D.UpdatedDate 
	             FROM ExhibitsRegistrations D 
	             WHERE D.ExhibitId <> 0 '
		
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  D.FirstName LIKE ''%' + @Search + '%'' OR  D.LastName LIKE ''%' + @Search + '%'''
		END

		IF(@PaymentMethodId<>0)
		BEGIN
			SET @Query=@Query + ' AND D.PaymentMethodId = ' + CAST(@PaymentMethodId as nvarchar(50))
		END

		IF(@PaymentStatusId<>0)
		BEGIN
			SET @Query=@Query + ' AND D.PaymentStatusId = ' + CAST(@PaymentStatusId as nvarchar(50))
		END

		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END














