/****** Object:  StoredProcedure [dbo].[ExportMembersGetList]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[ExportMembersGetList] 
	 (@ChapterId bigint
	 ,@MembershipTypeId bigint
	 ,@PaymentStatusId bigint
	 ,@StartDate nvarchar(126)
	 ,@EndDate nvarchar(126)
	-- ,@ExpiryDate nvarchar(126)
	 ,@IsVolunteer nvarchar(50)
	 ,@Search nvarchar(126)
     ,@Sort nvarchar(126)
     ,@Total int output)
AS
BEGIN

	
	
	SET NOCOUNT ON;
	
	--BEGIN TRY
	
	DECLARE @Query nvarchar(max);
    
	SET @Query = '
	SELECT  
				  M.MemberSkils AS MemberId
				 ,M.FirstName 
				 ,M.LastName 
				 ,M.Email
				 ,M.MobilePhone
				 ,M.State
				 ,M.City
				 ,M.Address
				 ,M.Address2
				 ,M.ZipCode
				 ,MT.MembershipType
				 ,M.MaritalStatus AS MaritalStatus
				 ,M.gender AS Gender
				 ,M.SpouseFirstName
				 ,M.SpouseLastName
				 ,M.SpouseEmail
				 ,M.SpouseCell
				 ,MT.MembershipType
				 ,Mo.Amount
				 ,Mo.TransactionId
				 ,Mo.OrderDate
				 ,PS.PaymentStatus
				 ,PM.PaymentMethod
				 ,Mo.ExpiryDate
				,M.InsertedTime as MemberSince
		  		,Case 
				When  M.IsApproved=''1'' then ''Active''
				When  M.IsApproved=''0'' then ''Deactive''
				end as Status 
				FROM Members M
				INNER JOIN MembershipTypes MT ON MT.MembershipTypeId=M.MembershipTypeId 
				LEFT JOIN MembersInfo MI ON MI.MemberId=M.MemberId 
				LEFT JOIN MembershipOrders MO ON MO.MemberId=M.MemberId
				LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId		
				LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=MO.PaymentMethodId
				WHERE M.MemberId <> 0'
		

		IF(@ChapterId <> 0)
	BEGIN
		SET @Query = @Query + ' AND M.ChapterId = ' + CAST(@ChapterId AS nvarchar(30));
	END 
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND (M.FirstName LIKE ''%' + @Search + '%'' OR M.LastName LIKE ''%' + @Search + '%'' OR  M.SpouseFirstName LIKE ''%' + @Search + '%'' OR  M.City LIKE ''%' + @Search + '%'')'
		END
		
		IF(@MembershipTypeId<>0)
		BEGIN
			SET @Query=@Query + ' AND M.MembershipTypeId = ' + CAST(@MembershipTypeId as nvarchar(50))
		END

		IF(@PaymentStatusId <>0)
		BEGIN
			SET @Query=@Query + ' AND MO.PaymentStatusId = ' + CAST(@PaymentStatusId as nvarchar(50))
		END

		IF(@IsVolunteer<>'')
		BEGIN
			SET @Query=@Query + ' AND M.IsVolunteer = ' + @IsVolunteer 
		END

		IF(@StartDate <> '' OR @EndDate <> '')
		BEGIN
			IF(@StartDate <> '' AND @EndDate <> '')
			BEGIN
				SET @Query = @Query + ' AND  (M.InsertedTime BETWEEN ''' + @StartDate + ''' AND ''' + @EndDate + ''')'
			END
			
			IF(@StartDate <> '' AND @EndDate = '')
			BEGIN
				SET @Query = @Query + ' AND  M.InsertedTime = '+CAST(@StartDate as nvarchar(50))
			END
		END
			
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = 1;
				

	--END TRY
    
 --   BEGIN CATCH  
 --      SELECT @Total = -1; 		   
 --   END CATCH   
END











