/****** Object:  StoredProcedure [dbo].[ExporttoEventUserInfo]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE PROCEDURE [dbo].[ExporttoEventUserInfo]
     (@Search nvarchar(126)
     ,@EventId bigint
     ,@Sort nvarchar(216)
     ,@Total int OUTPUT)
        
AS
BEGIN
    SET NOCOUNT ON;
    
    DECLARE @Start int, @End INT;
    DECLARE @Query nvarchar(max);
    DECLARE @columns NVARCHAR(MAX) = '';

    IF(@columns <> '')
    BEGIN
        SET @columns = LEFT(@columns, LEN(@columns) - 1);
    END
    ELSE
    BEGIN
        SET @columns = '';
    END

    IF(@columns <> '')
    BEGIN
        SET @Query = '
            SELECT * FROM (
                SELECT
                     E.EventName          -- FIX: added comma after EventName
                    ,ET.RegistrationTitle
                    ,ETK.TicketId
                    ,ERC.Count AS TotalCount
                    ,EUI.FirstName
                    ,EUI.LastName
                    ,EUI.Email
                    ,EUI.City
                    ,EUI.State
                    ,EUI.Mobile
                    ,EUI.TransactionId
                    ,PM.PaymentMethod
                    ,PS.PaymentStatus
                    ,EUI.AmountPaid
                    ,EUI.InsertedTime AS RegisteredDate
                    ,ERC.Count AS Count
                    ,(SELECT TOP(1) Status  FROM EventComments WHERE EventUserInfoId = EUI.EventUserInfoId) AS Status
                    ,(SELECT TOP(1) Comment FROM EventComments WHERE EventUserInfoId = EUI.EventUserInfoId) AS Comment

                FROM Events E
                INNER JOIN EventUserInfo EUI ON E.EventId = EUI.EventId
                INNER JOIN EventCategories EC ON EC.EventCategoryId = E.EventCategoryId
                INNER JOIN EventRegistrationTypes ET ON ET.EventId = E.EventId
                INNER JOIN EventRegistrationCounts ERC ON ERC.EventRegistrationTypeId = ET.EventRegistrationTypeId 
                    AND ERC.EventUserInfoId = EUI.EventUserInfoId
                LEFT JOIN EventRegTickets ETK ON ETK.EventRegCountId = ERC.EventRegCountId
                LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId = EUI.PaymentMethodId
                LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId = EUI.PaymentStatusId

                WHERE E.EventId = ' + CAST(@EventId AS nvarchar(max)) + '
            ) A'

        SELECT @Total = 1;
    END
    ELSE
    BEGIN
        SET @Query = '
            SELECT
                 E.EventName             -- FIX: added comma after EventName
                ,ET.RegistrationTitle
                ,ETK.TicketId
                ,ERC.Count AS TotalCount
                ,EUI.FirstName
                ,EUI.LastName
                ,EUI.Email
                ,EUI.City
                ,EUI.State
                ,EUI.Mobile
               -- ,EUI.ItemCategory AS [Competition Name]
               -- ,EUI.ItemName AS [No of Participants]
                ,EUI.TransactionId
                ,PM.PaymentMethod
                ,PS.PaymentStatus
                ,EUI.AmountPaid
                ,EUI.InsertedTime AS RegisteredDate
                ,ET.RegistrationTitle
                ,ERC.Count AS Count
                ,EUI.Comments
                ,(SELECT TOP(1) Status  FROM EventComments WHERE EventUserInfoId = EUI.EventUserInfoId) AS Status
                ,(SELECT TOP(1) Comment FROM EventComments WHERE EventUserInfoId = EUI.EventUserInfoId) AS Comment

            FROM Events E
            INNER JOIN EventUserInfo EUI ON E.EventId = EUI.EventId
            INNER JOIN EventCategories EC ON EC.EventCategoryId = E.EventCategoryId
            LEFT JOIN EventRegistrationTypes ET ON ET.EventId = E.EventId
            LEFT JOIN EventRegistrationCounts ERC ON ERC.EventRegistrationTypeId = ET.EventRegistrationTypeId 
                AND ERC.EventUserInfoId = EUI.EventUserInfoId
            LEFT JOIN EventRegTickets ETK ON ETK.EventRegCountId = ERC.EventRegCountId  -- FIX: moved after ERC join
            LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId = EUI.PaymentMethodId
            LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId = EUI.PaymentStatusId

            WHERE E.EventId = ' + CAST(@EventId AS nvarchar(max)) + '
            '

        SELECT @Total = 2;
    END

    -- Search filter
    IF(@Search <> '')
    BEGIN
        SET @Query = @Query + ' AND (EUI.FirstName LIKE ''%' + @Search + '%'' OR EUI.LastName LIKE ''%' + @Search + '%'')'
    END

    -- Pivot or Order
    IF(@columns <> '')
    BEGIN
        SET @Query = @Query + '
            PIVOT (
                max(Count) FOR RegistrationTitle IN (' + @columns + ')
            ) b'
    END
    ELSE
    BEGIN
        SET @Query = @Query + ' ORDER BY EUI.InsertedTime DESC'
    END

    EXEC sp_executesql @Query;
END
GO
