SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

Create PROCEDURE [dbo].[ExporttoEventUserInfo2025Bkp]
	 (@Search nvarchar(126)
	 ,@EventId bigint
	 ,@Sort nvarchar(216)
     ,@Total int OUTPUT)
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	BEGIN TRY 
	
			SET NOCOUNT ON;
			
			DECLARE @Start int, @End INT ;
			DECLARE @Query nvarchar(max);
			DECLARE @columns NVARCHAR(MAX) = '';
			
			SELECT 
				@columns+=QUOTENAME(RegistrationTitle) + ','
			FROM 
				EventRegistrationTypes Where EventId=@EventId
			ORDER BY 
				RegistrationTitle;

			IF(@columns <> '')
				BEGIN
				SET @columns = LEFT(@columns, LEN(@columns) - 1);
				END
			ELSE
				BEGIN
				SET @columns = '';
				END
			IF(@columns <> '')
				BEGIN
					SET @Query = '
						 Select * From ( SELECT E.EventName						
								,EUI.FirstName
								,EUI.LastName
								,EUI.Email
								,EUI.City
								,EUI.State
								,EUI.Mobile
								,EUI.ItemCategory as [Competition Name]
								,EUI.ItemName as [No of Participants]						
								,EUI.TransactionId
								,PM.PaymentMethod
								,PS.PaymentStatus
								,EUI.AmountPaid
								,EUI.InsertedTime AS RegisteredDate
								,ET.RegistrationTitle
								,ERC.Count AS Count 
								,(Select Status from EventComments Where EventUserInfoId = EUI.EventUserInfoId) as Status
								,(Select Comment from EventComments Where EventUserInfoId = EUI.EventUserInfoId) as Comment						  
								FROM Events  E 
								INNER JOIN EventUserInfo EUI ON E.EventId = EUI.EventId 
								INNER JOIN EventCategories EC ON EC.EventCategoryId = E.EventCategoryId 
								--LEFT JOIN EventOrderDetails EO ON EO.EventUserInfoId = EUI.EventUserInfoId
								INNER JOIN EventRegistrationTypes ET ON ET.EventId = E.EventId 
								INNER JOIN EventRegistrationCounts ERC ON ERC.EventRegistrationTypeId = ET.EventRegistrationTypeId AND ERC.EventUserInfoId = EUI.EventUserInfoId 
								LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId = EUI.PaymentMethodId 
								LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId = EUI.PaymentStatusId 
								WHERE E.EventId= ' + CAST(@EventId as nvarchar(max))+' '

						SELECT @Total = 1;
			 END
		ELSE
			 BEGIN
					 SET @Query = '
						 SELECT E.EventName						
								,EUI.FirstName
								,EUI.LastName
								,EUI.Email
								,EUI.City
								,EUI.State
								,EUI.Mobile
								,EUI.ItemCategory as [Competition Name]
								,EUI.ItemName as [No of Participants]						
								,EUI.TransactionId
								,PM.PaymentMethod
								,PS.PaymentStatus
								,EUI.AmountPaid
								,EUI.InsertedTime AS RegisteredDate
								,ET.RegistrationTitle
								,ERC.Count AS Count 	
								,EUI.Comments	
								,(Select Status from EventComments Where EventUserInfoId = EUI.EventUserInfoId) as Status
								,(Select Comment from EventComments Where EventUserInfoId = EUI.EventUserInfoId) as Comment
								FROM Events  E 
								INNER JOIN EventUserInfo EUI ON E.EventId = EUI.EventId 
								INNER JOIN EventCategories EC ON EC.EventCategoryId = E.EventCategoryId 
								--LEFT JOIN EventOrderDetails EO ON EO.EventUserInfoId = EUI.EventUserInfoId
								LEFT JOIN EventRegistrationTypes ET ON ET.EventId = E.EventId 
								LEFT JOIN EventRegistrationCounts ERC ON ERC.EventRegistrationTypeId = ET.EventRegistrationTypeId AND ERC.EventUserInfoId = EUI.EventUserInfoId 
								LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId = EUI.PaymentMethodId 
								LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId = EUI.PaymentStatusId 
								WHERE E.EventId= ' + CAST(@EventId as nvarchar(max))+' '

						SELECT @Total = 2;
			END
			
			IF(@Search <> '')
			BEGIN
				SET @Query = @Query + ' AND (EUI.FirstName LIKE ''%' + @Search + '%'' OR  EUI.LastName LIKE ''%' + @Search + '%'')'
			END
			
			IF(@columns <> '')
				BEGIN
				   Set @Query = @Query + ' ) APIVOT (max(Count) FOR RegistrationTitle in ('+ @columns +')) b '
				END
			ELSE
				BEGIN
				SET @Query = @Query + ' ORDER BY EUI.InsertedTime DESC'
				END

			EXEC sp_ExecuteSQL @Query;
			
			
    END TRY
    BEGIN CATCH
		 SELECT @Total = -1;
    END CATCH
	 
END









































