CREATE PROCEDURE [dbo].[ExporttoTeluguAmmayiFinal]
	 (@ChapterId bigint
	 ,@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output
	 ,@EventId bigint 
	 ,@RegistrationCategoryId bigint
	 ,@PaymentStatusId bigint
	 ,@CompetitionCategory1 nvarchar(512) )
AS
        
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	BEGIN TRY 
	
			SET NOCOUNT ON;
			
			DECLARE @Start int, @End INT ;
			DECLARE @Query nvarchar(max);
			DECLARE @columns NVARCHAR(MAX) = '';
			
			
			SET @Query = 'SELECT 
						 E.TeluguAmmaiRegistrationId AS [R ID]					            
						,E.FirstName AS [First Name]
						,E.LastName AS [Last Name]
						,E.EmailId As [Email Id]
						,E.DOB
						,E.PrimaryPhoneNumber AS [Primary PhoneNo]
						,E.AlternativePhoneNumber AS [Alt PhoneNo]
						,E.SchoolGrade AS [Weight]
						,E.Gender AS [Height]
						,E.Age				
						,E.CompetitionCategory1 AS [Competition Type]
						,C.ChapterName AS [Chapter Name]	
						,E.Address1 AS [Address-1]
						,E.Address2 AS [Address-2]
						,E.City
						,E.State
						,E.District				
						,E.CompetitionCategory2 AS [Additional Info]							
						,E.TransactionId
						,PS.PaymentStatus AS [Payment Status]
						,E.OrderDate AS [Order Date]
						,E.TotalAmount AS [Amount]								
						,(SELECT EventName FROM Events EV WHERE EV.EventId=E.EventId) AS [Event Name]
						,PaymentBy AS [USCF Membership ID]
						 FROM TeluguAmmaiRegistrations E
						 Left JOIN Chapters C ON C.ChapterId = E.ChapterId
						 Left JOIN PaymentStatus PS ON PS.PaymentStatusId = E.PaymentStatusId
						 Left JOIN  RegistrationCategories RC ON RC.RegistrationCategoryId=E.RegistrationCategoryId  		
						 WHERE E.TeluguAmmaiRegistrationId <> 0'
				
	    IF(@ChapterId <> 0)
		BEGIN
			SET @Query=@Query + 'AND E.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))
		END  

		IF(@PaymentStatusId <> 0)
		BEGIN
			SET @Query=@Query + 'AND E.PaymentStatusId = ' + CAST(@PaymentStatusId AS nvarchar(30))
		END  

		IF(@CompetitionCategory1 <> '')
		BEGIN
			set @CompetitionCategory1 = replace(@CompetitionCategory1, ',', ''',''')
			SET @Query = @Query + ' AND E.CompetitionCategory1 in ('''+@CompetitionCategory1+''')'
		END

		IF(@EventId<>0)
		BEGIN
			SET @Query=@Query + ' AND E.EventId = ' + CAST(@EventId as nvarchar(50))
		END

		IF(@RegistrationCategoryId<>0)
		BEGIN
			SET @Query=@Query + ' AND E.RegistrationCategoryId = ' + CAST(@RegistrationCategoryId as nvarchar(50))
		END

		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  E.FirstName LIKE ''%' + @Search + '%'''
		END

		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY E.InsertedDate DESC'
		END


			EXEC sp_ExecuteSQL @Query;
			SELECT @Total = 1;
			
    END TRY
    BEGIN CATCH
		 SELECT @Total = -1;
    END CATCH
	 
END









































