CREATE PROCEDURE [dbo].[ExportVolunteersGetList]
	 (@VolunteerCategoryId bigint
	 ,@EventId bigint
	 ,@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@chapterId bigint
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Query nvarchar(max);
    
	SET @Query = '   SELECT  V.FirstName 
							,V.LastName 
							,V.Email 
							,V.HoursSpent
							,VC.CategoryName
							--,E.EventName
							,V.PhoneNo
							--,V.IsActive 
							,V.UpdatedBy 
							FROM Volunteers V
							LEFT JOIN VolunteerCategories VC ON VC.VolunteerCategoryId= V.VolunteerCategoryId 
							LEFT Join EventVolunteers EV ON EV.VolunteerId = V.VolunteerId	
							LEFT JOIN Events E ON E.EventId = EV.EventId 	 
							WHERE V.VolunteerId <> 0 '
		



		  IF(@ChapterId <> 0)  
	  BEGIN  
	   SET @Query=@Query + 'AND V.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))  
	  END  
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  V.FirstName LIKE ''%' + @Search + '%'' OR  V.LastName LIKE ''%' + @Search + '%'' OR  V.Email LIKE ''%' + @Search + '%'''
		END
		
		IF(@VolunteerCategoryId<>0)
		BEGIN
			SET @Query=@Query + ' AND V.VolunteerCategoryId = ' + CAST(@VolunteerCategoryId as nvarchar(50))
		END

		IF(@EventId <>0)
		BEGIN
			SET @Query=@Query + ' AND EV.EventId = ' + CAST(@EventId as nvarchar(50))
		END
			
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = 1;
				

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END










