/****** Object:  StoredProcedure [dbo].[FEAksharaDeepikaGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FEAksharaDeepikaGetListByVariable]
	 (@ChapterId bigint
	 ,@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output
	 ,@Type nvarchar(512)
	 ,@Year bigint)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,AksharaDeepikaId bigint
				,ChapterId bigint
				,Title nvarchar(256)
				,BannerUrl nvarchar(128)
				,DocumentUrl nvarchar(max)
				,OrderNo int
				,IsActive bit
				,Field1 nvarchar(max)
				,Field2 nvarchar(max)
				,Field3 nvarchar(max)
				,InsertedBy nvarchar(64)
				,InsertedTime datetime
				,UpdatedBy nvarchar(64)
				,UpdatedTime datetime
				,ChapterName nvarchar(512))
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             E.AksharaDeepikaId
				,E.ChapterId
	            ,E.Title
	            ,E.BannerUrl
	            ,E.DocumentUrl
	            ,E.OrderNo
	            ,E.IsActive
				,E.Field1
				,E.Field2
				,E.Field3
			    ,E.InsertedBy
	            ,E.InsertedTime
	            ,E.UpdatedBy
	            ,E.UpdatedTime
				,C.ChapterName
	             FROM AksharaDeepika E
				 Left JOIN Chapters C ON C.ChapterId = E.ChapterId
		WHERE E.AksharaDeepikaId <> 0 AND E.IsActive = 1'
		
		IF(@Type <> '')
		BEGIN
					
					IF(@Type = 'PDF')
					BEGIN
					SET @Query = @Query + ' AND  E.Field1 <> '''''
					END
					ELSE
					BEGIN
					SET @Query = @Query + ' AND  E.DocumentUrl <> '''''
					END 
		END 

		IF(@Year <> 0)
		BEGIN
