CREATE PROCEDURE [dbo].[FECommitteesGetList]      
 (@Year nvarchar(128)     
 ,@ChapterId bigint      
 ,@QStatus int OUTPUT)          
              
AS      
BEGIN      
      
 -- SET NOCOUNT ON added to prevent extra result sets from      
       
   SET NOCOUNT ON;      
      
   Declare @CID bigint       
      
   BEGIN TRY     
     
    SELECT Distinct  C.MemberId      
    ,(C.FirstName + ' ' + C.LastName) As Name      
    ,C.MobilePhone      
    ,C.Address      
    ,C.City      
    ,C.State      
    ,C.Email      
    ,C.ProfileImage      
    ,CM.DisplayOrder      
    ,C.IsApproved      
    ,C.Occupation      
    ,CC.UpdatedBy      
   -- ,CC.UpdatedTime      
    ,CC.CategoryName      
    ,CC.CommitteeCategoryId      
   -- ,CC.Type       
    ,CM.Designation  
	,CM.Description
       ,CC.* FROM  Members C      
       INNER JOIN CommitteeMembers CM ON CM.MemberId = C.MemberId      
       INNER JOIN CommitteeCategoryMaster CC ON CC.CommitteeCategoryId= CM.CommitteeCategoryId      
       LEFT JOIN ChapterCommittees CO ON CO.CommitteeCategoryId= CM.CommitteeCategoryId  
      
     --WHERE CC.Year = @Year AND CM.IsActive=1    
     WHERE CC.YearId =@Year  AND CM.IsActive=1              
      -- WHERE dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') = dbo.RemoveSpecialChar(@Year, '^a-z0-9') AND CM.IsActive=1       
       ORDER BY CM.DisplayOrder ASC      
  
  
  
  
  
     Select CC.*,       
     (Select COUNT(*) From CommitteeMembers CM Where CM.CommitteeCategoryId = CC.CommitteeCategoryId) as CommitteeCount       
     From CommitteeCategoryMaster CC       
     LEFT Join ChapterCommittees CO ON CO.CommitteeCategoryId = CC.CommitteeCategoryId      
    WHERE CC.YearId = @Year  
    -- AND CC.IsActive=1      
     --Where dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') <> dbo.RemoveSpecialChar('Leadership', '^a-z0-9')      
  -- AND CC.IsActive=1        
     AND CO.ChapterId =@ChapterId AND CC.IsActive=1 and CC.CommitteeCategoryId in(Select CM.CommitteeCategoryId From CommitteeMembers CM Where CM.CommitteeCategoryId = CC.CommitteeCategoryId)  
     ORDER BY Position ASC  
  
  
  
  
  select DISTINCT  Yearid from CommitteeCategoryMaster  
  
         
   
     SELECT @QStatus = 1;      
    END TRY      
      
    BEGIN CATCH      
   SELECT @QStatus = -1;      
    END CATCH       
        
END      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
      
  
