/****** Object:  StoredProcedure [dbo].[FECommitteesGetList2026]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
           
CREATE PROCEDURE [dbo].[FECommitteesGetList2026]        
 (@Year int  ,           
 @ChapterId bigint            
    ,@QStatus int OUTPUT            
 ,@Type nvarchar(128))                
                    
AS            
BEGIN            
            
 -- SET NOCOUNT ON added to prevent extra result sets from            
 -- interfering with SELECT statements.            
             
   SET NOCOUNT ON;            
            
    -- Insert statements for procedure here            
            
   Declare @CID bigint             
            
               
   BEGIN TRY              
            
    SELECT Distinct  C.MemberId            
    ,(C.FirstName + ' ' + C.LastName) As Name            
    ,C.MobilePhone            
    ,C.Address            
    ,C.City            
    ,C.State            
    ,C.Email            
    ,C.ProfileImage            
    ,CM.DisplayOrder            
    ,C.IsApproved            
    ,C.Occupation            
    ,CC.UpdatedBy            
    ,CC.UpdatedTime            
    ,CC.CategoryName            
    ,CC.CommitteeCategoryId            
    ,CC.Type             
    ,CM.Designation               
     ,CC.* FROM  Members C            
     INNER JOIN CommitteeMembers CM ON CM.MemberId = C.MemberId            
     INNER JOIN CommitteeCategories CC ON CC.CommitteeCategoryId= CM.CommitteeCategoryId            
     LEFT JOIN ChapterCommittees CO ON CO.CommitteeCategoryId= CM.CommitteeCategoryId            
     WHERE dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') = dbo.RemoveSpecialChar(@Type, '^a-z0-9')             
     AND CM.IsActive=1 AND CC.Year = @Year            
     --AND CM.ChapterId = @ChapterId ORDER BY CM.DisplayOrder ASC            
     ORDER BY CM.DisplayOrder ASC            
                
    SELECT Distinct  C.MemberId            
    ,(C.FirstName + ' ' + C.LastName) As Name            
    ,C.MobilePhone            
    ,C.Address            
    ,C.City            
    ,C.State            
    ,C.Email            
    ,C.ProfileImage            
    ,CM.DisplayOrder            
    ,C.IsApproved            
    ,C.Occupation            
    ,CC.UpdatedBy            
    ,CC.UpdatedTime            
    ,CC.CategoryName            
    ,CC.CommitteeCategoryId            
    ,CC.Type             
    ,CM.Designation               
     ,CC.* FROM  Members C            
     INNER JOIN CommitteeMembers CM ON CM.MemberId = C.MemberId            
     INNER JOIN CommitteeCategories CC ON CC.CommitteeCategoryId= CM.CommitteeCategoryId            
     LEFT JOIN ChapterCommittees CO ON CO.CommitteeCategoryId= CM.CommitteeCategoryId            
     WHERE dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') = dbo.RemoveSpecialChar(@Type, '^a-z0-9')               
     AND CM.IsActive=1 AND CC.Year = @Year             
     --AND CM.ChapterId = @ChapterId ORDER BY CM.DisplayOrder ASC            
     ORDER BY CM.DisplayOrder ASC            
            
   --  SELECT Distinct Type from CommitteeCategories CC            
   --INNER JOIN ChapterCommittees CO ON CO.CommitteeCategoryId= CC.CommitteeCategoryId            
   --where CC.Type <> 'Leadership' AND CO.ChapterId = @ChapterId            
            
   SELECT Type            
   FROM (            
     SELECT Type, MAX(DisplayOrder) AS DisplayOrder            
     FROM CommitteeCategories  where Type <> 'Leadership' AND Type <> 'Other Officials' AND Type <> 'Past Leadership'            
     GROUP BY Type            
   ) t            
   ORDER BY DisplayOrder DESC            
            
   if(@ChapterId = 1)            
   BEGIN            
    Select CC.*,             
    (Select COUNT(*) From CommitteeMembers CM Where CM.CommitteeCategoryId = CC.CommitteeCategoryId) as CommitteeCount             
    From CommitteeCategories CC             
    LEFT Join ChapterCommittees CO ON CO.CommitteeCategoryId = CC.CommitteeCategoryId            
    Where dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') = dbo.RemoveSpecialChar(@Type, '^a-z0-9')             
    --AND dbo.RemoveSpecialChar(CC.Type, '^a-z0-9') = dbo.RemoveSpecialChar(@Type, '^a-z0-9')            
    AND CC.IsActive=1 AND CC.Year = @Year            
    --AND CO.ChapterId = @ChapterId AND CC.IsActive=1              
    ORDER BY DisplayOrder ASC            
    END            
    ELSE            
    BEGIN            
    Select CC.*,             
    (Select COUNT(*) From CommitteeMembers CM Where CM.CommitteeCategoryId = CC.CommitteeCategoryId) as CommitteeCount             
    From CommitteeCategories CC             
    LEFT Join ChapterCommittees CO ON CO.CommitteeCategoryId = CC.CommitteeCategoryId            
    Where dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') <> dbo.RemoveSpecialChar('Leadership', '^a-z0-9')             
    AND dbo.RemoveSpecialChar(CC.Type, '^a-z0-9') = dbo.RemoveSpecialChar(@Type, '^a-z0-9')            
    AND CC.IsActive=1 AND CC.Year = @Year            
    --AND CO.ChapterId = @ChapterId AND CC.IsActive=1              
    ORDER BY CC.DisplayOrder ASC            
    END            
     SELECT @QStatus = 1;            
    END TRY            
    BEGIN CATCH            
   SELECT @QStatus = -1;            
    END CATCH             
              
END            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
            
GO
