CREATE PROCEDURE [dbo].[FEDonationOrderListByEmail]  
     @Email nvarchar(256)  
	 ,@ChapterId bigint
     ,@QStatus int output  
          
AS  
BEGIN  
  
 
   
 SET NOCOUNT ON;  
  
      
    BEGIN TRY    
      
  
  SELECT   
       D.ServiceDonationId  
      ,D.MemberId  
      ,D.ServiceId  
      ,D.IsActive  
      ,D.Amount  
      ,D.TransactionId  
      ,PM.PaymentMethod  
      ,PS.PaymentStatus  
      ,D.OrderDate   
      ,D.PaymentBy  
      ,D.UpdatedDate    
      ,K.FirstName          
      ,K.LastName  
      ,K.Field3 
	
      ,(select ServiceTitle from services where ServiceId=D.ServiceId) as DonationCause  
      FROM ServiceDonations D  
      LEFT JOIN ServiceDonationInfo K ON D.ServiceDonationId=K.ServiceDonationId   
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId  
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId  
      WHERE K.Email= @Email and ChapterId=@ChapterId
  
  
  SELECT @QStatus = 1;   
    END TRY  
    BEGIN CATCH  
   SELECT @QStatus = -1;  
    END CATCH  
       
END  
  

