CREATE  PROCEDURE [dbo].[FEDonorsGetById]
	(@DonorId bigint
    ,@QStatus int OUTPUT)    
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
   SET NOCOUNT ON;

    BEGIN TRY 
    
		 SELECT D.*,PM.PaymentMethod,PS.PaymentStatus, DC.DonationCategoryId,DC.CategoryName
		 
		 FROM Donors D
		 LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId = D.PaymentMethodId
		 LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId = D.PaymentStatusId
		 LEFT JOIN DonationCategories DC ON DC.ChapterId = D.ChapterId
		 WHERE DonorId=@DonorId

		 SELECT @QStatus = 1;
		 
    END TRY
    
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH	
	 
END


















