CREATE PROCEDURE [dbo].[FEDonorsGetList]
	 (@Search nvarchar(126)
	 ,@Type nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,DonorId bigint
				,FirstName nvarchar(128)
				,LastName nvarchar(128)
				,Email nvarchar(128)
				,PhoneNo nvarchar(20)
				,IsActive bit
				,DonationProgram nvarchar(2048)
				,OrderDate datetime
				,Amount decimal(15,2)
				,InsertedDate datetime)
				

				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
		 SELECT   D.DonorId
	            ,D.FirstName
	            ,D.LastName
	            ,D.Email
	            ,D.PhoneNo
	            ,D.IsActive
				,D.DonationProgram
	            ,D.OrderDate
				,D.Amount
	            ,D.InsertedDate 
		FROM Donors D
	 
		WHERE D.DonorId <> 0'
		
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  D.FirstName LIKE ''%' + @Search + '%'' OR D.LastName LIKE ''%' + @Search + '%'''
		END
			
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END











