CREATE PROCEDURE [dbo].[FEDonorsMemberIdGetList] 
	 (@MemberId bigint
	 ,@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,ServiceDonationId bigint
				,MemberId bigint
				,ServiceId bigint
				,DonationCause  nvarchar(2048)
				,IsActive bit
				,Amount decimal(15,2)
				,TransactionId nvarchar(512)
				,PaymentStatusId bigint
				,PaymentMethodId bigint
				,OrderDate datetime
			    ,PaymentBy nvarchar(512)
				,UpdatedDate datetime
				,UpdatedBy nvarchar(512)
				,PaymentMethod nvarchar(156)
				,PaymentStatus nvarchar(156)
				,FirstName nvarchar(512)
				,LastName nvarchar(512)
				,Email nvarchar(512)
				,IsDisplay bit )
				

				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
	      SELECT D.ServiceDonationId
				,D.MemberId
				,D.ServiceId
	            ,D.DonationCause
	            ,D.IsActive
	            ,D.Amount
	            ,D.TransactionId
	            ,D.PaymentStatusId
				,D.PaymentMethodId
	            ,D.OrderDate
				,D.PaymentBy
				,D.UpdatedDate
				,D.UpdatedBy
	            ,PM.PaymentMethod
	            ,PS.PaymentStatus
	            ,k.FirstName
				,k.LastName
				,k.Email
				,(Select IsDisplay from Services S Where S.ServiceId = D.ServiceId) As IsDisplay
	            FROM ServiceDonations D
				LEFT JOIN ServiceDonationInfo K ON D.ServiceDonationId=K.ServiceDonationId 
	            LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId
	            LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId
	            WHERE D.ServiceDonationId <> 0 AND D.Amount <> 0'


	    IF(@MemberId <> 0)
		BEGIN
			SET @Query=@Query + ' AND D.MemberId = ' + CAST(@MemberId AS nvarchar(30))
		END  
		
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  D.FirstName LIKE ''%' + @Search + '%'' OR D.LastName LIKE ''%' + @Search + '%'''
		END
			
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END







