/****** Object:  StoredProcedure [dbo].[FEEventsGetList2015Bkp]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create PROCEDURE [dbo].[FEEventsGetList2015Bkp]  
(  
    @ChapterId bigint,  
    @Type nvarchar(256),  
    @Search nvarchar(126),  
    @Sort nvarchar(216),  
    @PageNo int,  
    @Items int,  
    @Total int OUTPUT  
)  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    BEGIN TRY  
        SET NOCOUNT ON;  
  
        DECLARE @Start int, @End INT;  
        DECLARE @Query nvarchar(max);  
  
        CREATE TABLE #temp  
        (  
            Rid INT PRIMARY KEY IDENTITY(1, 1),  
            EventId bigint,  
            EventName nvarchar(128),  
            StartDate datetime,  
            EndDate datetime,  
            RegistrationStartDate datetime,  
            RegistrationEndDate datetime,  
            BannerUrl nvarchar(156),  
            EventCategoryId bigint,  
            MemberCount int,  
            Location nvarchar(512),  
            City nvarchar(64),  
            StateName nvarchar(64),  
            ZipCode nvarchar(25),  
            EventDetails nvarchar(max),  
            ContactEmail nvarchar(64),  
            IsRegistration bit,  
            PageTitle nvarchar(512),  
            MetaDescription nvarchar(max),  
            MetaKeywords nvarchar(max),  
            TopLine nvarchar(512),  
            UpdatedBy nvarchar(30),  
            UpdatedTime datetime,  
            EventCategory nvarchar(156),  
            ChapterId bigint  
        );  
  
        SELECT @Start = (@PageNo - 1) * @Items;  
        SELECT @End = @Start + @Items;  
  
        SET @Query = '  
            INSERT INTO #temp  
            SELECT DISTINCT  
                E.EventId,  
                E.EventName,  
                A.StartDate,  
                A.EndDate,  
                E.RegistrationStartDate,  
                E.RegistrationEndDate,  
                E.BannerUrl,  
                E.EventCategoryId,  
                E.MemberCount,  
                E.Location,  
                E.City,  
                E.StateName,  
                E.ZipCode,  
                E.EventDetails,  
                E.ContactEmail,  
                E.IsRegistration,  
                E.PageTitle,  
                E.MetaDescription,  
                E.MetaKeywords,  
                E.TopLine,  
                E.UpdatedBy,  
                E.UpdatedTime,  
                EC.EventCategory,  
                Ec.ChapterId  
            FROM  
                Events E  
            LEFT JOIN  
                Eventdates A ON A.EventId = E.EventId  
            LEFT JOIN  
                EventCategories EC ON E.EventCategoryId = EC.EventCategoryId  
            LEFT JOIN  
                ChapterEvents CE ON CE.EventId = E.EventId  
            WHERE  
                E.EventId <> 0';  
  
        IF (@Search <> '')  
        BEGIN  
            SET @Query = @Query + ' AND EventName LIKE ''%' + @Search + '%''';  
        END;  
  
        IF (@ChapterId <> 0)  
        BEGIN  
            IF (@ChapterId <> 1)  
            BEGIN  
                SET @Query = @Query + ' AND CE.ChapterId = ' + CAST(@ChapterId AS nvarchar(64));  
            END;  
        END;  
  
        IF (@Type = 'upcoming')  
        BEGIN  
            SET @Query = @Query + '  
                AND EXISTS (  
                    SELECT *  
                    FROM Eventdates ED  
                    WHERE ED.EventId = E.EventId  
                        AND (  
                            (CONVERT(DATE, ED.EndDate) >= CONVERT(DATE, GETDATE()) OR ED.EndDate IS NULL)  
                            AND (ED.EndDate IS NULL OR ED.EndDate > CONVERT(DATE, GETDATE()))  
                        )  
                )';  
        END;  
  IF(@Type = 'past')              
  BEGIN                  
            
    SET @Query = @Query + ' AND E.EventId in (Select Ed.EventId from Eventdates ED Where CONVERT (DATE, ED.EndDate)  < CONVERT (DATE, GETDATE()))'              
          
  END      
       
  
        IF (@Sort <> '')  
        BEGIN  
            SET @Query = @Query + ' ORDER BY ' + @Sort;  
        END;  
  
        EXEC sp_ExecuteSQL @Query;  
  
        SELECT @Total = COUNT(Rid) FROM #temp;  
  
        SELECT * FROM #temp WHERE Rid > @Start AND Rid <= @End;  
  
        DROP TABLE #temp;  
    END TRY  
  
    BEGIN CATCH  
        SELECT @Total = -1;  
    END CATCH;  
END;  


GO
