      ,E.MetaDescription            
      ,E.MetaKeywords           
      ,E.TopLine           
      ,E.UpdatedBy           
      ,E.UpdatedTime          
      ,EC.EventCategory           
      ,Ec.ChapterId          
      FROM Events  E  
	 LEFT JOIN Eventdates A ON A.EventId = E.EventId 
      LEFT JOIN EventCategories EC ON E.EventCategoryId = EC.EventCategoryId           
      LEFT JOIN ChapterEvents CE ON CE.EventId = E.EventId '          
        
     
  IF (@Type ='upcoming')  
BEGIN      
    SET @Query = @Query + ' AND E.EventId IN (
        SELECT ED.EventId 
        FROM Eventdates ED 
        WHERE (
            (CONVERT(DATE, ED.StartDate) >= CONVERT(DATE, GETDATE()) OR ED.StartDate IS NULL)
            AND (ED.EndDate IS NULL OR ED.EndDate > CONVERT(DATE, GETDATE()))
        )
    )'      
END  
 
IF(@Type = 'past')            
  BEGIN                
          
    SET @Query = @Query + ' AND E.EventId in (Select Ed.EventId from Eventdates ED Where CONVERT (DATE, ED.EndDate)  < CONVERT (DATE, GETDATE()))'            
        
  END    
    --IF(@Type = 'past')          
