    --        Where Convert(Date, EndDate) >= Convert(Date, GetDate())) A on A.RowNo = 1 AND A.EventId = E.EventId '          
    -- END          
    ELSE          
     BEGIN          
      SET @Query = @Query + ' LEFT JOIN (Select EventId, StartDate, EndDate, ROW_NUMBER() OVER(Partition By EventId ORDER BY StartDate DESC) AS RowNo From Events) A ON A.RowNo = 1 AND A.EventId = E.EventId  '          
     END         
      
      
               
    SET @Query = @Query + ' WHERE E.EventId <> 0 '          
          
      IF(@Search <> '')          
     BEGIN          
      SET @Query = @Query + ' AND  EventName LIKE ''%' + @Search + '%'''          
     END          
          
      IF(@ChapterId <> 0)          
     BEGIN          
      If(@ChapterId <> 1)           
       BEGIN          
        Set @Query = @Query + ' AND CE.ChapterId = ' + CAST(@ChapterId as nvarchar(64))          
       END          
     END          
          
       
        
   IF(@Type = 'past')          
    BEGIN        
      SET @Query = @Query + ' AND CONVERT (DATE, A.EndDate)  < CONVERT (DATE, GETDATE())'          
      
        END          
   ELSE IF(@Type = 'upcoming')          
    BEGIN          
   SET @Query = @Query + ' AND E.EventId in (Select Ed.EventId from Eventdates ED Where (CONVERT (DATE,ED.StartDate)  >= CONVERT (DATE,GETDATE()) OR ED.StartDate IS NULL OR CONVERT (DATE, ED.StartDate)  <=  CONVERT (DATE, GETDATE()) OR ED.StartDate IS NULL     
    
   OR ED.EndDate IS NULL) AND ED.EndDate > CONVERT (DATE, GETDATE())) '            
      
    END          
   --ELSE IF(@Type = '')          
   -- BEGIN          
   --  SET @Query = @Query + ' AND E.EventId in (Select Ed.EventId from Events ED Where CONVERT (DATE, ED.StartDate)  <=  CONVERT (DATE, GETDATE()) AND CONVERT (DATE, ED.EndDate)  >= CONVERT (DATE, GETDATE()))'          
   -- END          
                
   IF(@Sort <> '')          
   BEGIN          
    SET @Query = @Query + ' ORDER BY ' + @Sort          
   END          
          
   EXEC sp_ExecuteSQL @Query;          
             
   SELECT @Total = COUNT(Rid) from #temp           
               
   SELECT  *  FROM #temp WHERE Rid > @Start AND  Rid <= @End          
             
   DROP TABLE #temp          
            
    END TRY          
          
    BEGIN CATCH          
   SELECT @Total = -1;          
    END CATCH            
            
END          
          
 


