CREATE PROCEDURE [dbo].[FEEventsRegistrationGetListByEmail]
	(@Email nvarchar(256),
	@ChapterId bigint,
	@QStatus int OUTPUT)    
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
   SET NOCOUNT ON;

    -- Insert statements for procedure here

   BEGIN TRY 
			 
			  --SELECT * FROM EventUserInfo WHERE Email = @Email
			  
			 
				
				SELECT  DISTINCT  EUI.EventUserInfoId  
      ,E.EventId   
      ,E.EventName        
      ,EUI.FirstName  
      ,EUI.LastName  
      ,EUI.Email  
      ,EUI.Gender  
      ,EUI.Address  
      ,EUI.City  
      ,EUI.State  
      ,EUI.Mobile  
      ,EUI.ItemName   
      ,EUI.ItemCategory   
      ,EUI.ItemDescription   
      ,EUI.ItemDuration   
      ,EUI.IsApproved  
      ,EUI.DocumentUrl  
      ,EUI.UpdatedBy  
      ,EUI.UpdatedTime  
      ,EUI.InsertedTime    
      ,EC.EventCategory   
      ,PM.PaymentMethod   
      ,PS.PaymentStatus   
      ,EUI.AmountPaid  
      ,EUI.TransactionId  
      ,EUI.PaymentDate   
    
      FROM Events  E   
	  -- INNER JOIN Events EUI ON E.EventId = EUI.EventId   
      INNER JOIN EventUserInfo EUI ON E.EventId = EUI.EventId   
      LEFT JOIN EventCategories EC ON EC.EventCategoryId = E.EventCategoryId   
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId = EUI.PaymentMethodId   
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId = EUI.PaymentStatusId 
	  Left join chapterEvents CE On CE.EventId=E.EventId   
     WHERE EUI.Email = @Email and CE.ChapterId=@ChapterId
				
					 
			  
		    SELECT @QStatus = 1;
		
    END TRY
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH		
	 
END















