CREATE PROCEDURE [dbo].[FEExibhitsRegistrationsGetList]
	(@Search nvarchar(126)
	 ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)    
        
AS
BEGIN
	
	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,ExibhitsRegistrationId bigint
				,ExhibitType nvarchar(256)
				,VendorName nvarchar(256)
				,FirstName nvarchar(256)
				,LastName nvarchar(256)
				,Email nvarchar(128)
	            ,PhoneNo nvarchar(20)
	            ,Address nvarchar(1024)
	            ,City nvarchar(128)
	            ,State nvarchar(128)
	            ,ZipCode nvarchar(128)
	            ,IsActive bit
	            ,NoofBooths int
	            ,BoothSize nvarchar(128)
	            ,Amount decimal(15,2)
	            ,TransactionId nvarchar(128)
	            ,OrderDate datetime
	            ,PaymentBy nvarchar(2048)
	            ,InsertedDate datetime
	            ,UpdatedDate datetime
	            ,PaymentStatus nvarchar(128))
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             D.ExibhitsRegistrationId
	            ,D.ExhibitType
	            ,D.VendorName
	            ,D.FirstName
	            ,D.LastName
	            ,D.Email
	            ,D.PhoneNo
	            ,D.Address
	            ,D.City
	            ,D.State
	            ,D.ZipCode
	            ,D.IsActive
	            ,D.NoofBooths
	            ,D.BoothSize
	            ,D.Amount
	            ,D.TransactionId
	            ,D.OrderDate
	            ,D.PaymentBy 
	            ,D.InsertedDate
	            ,D.UpdatedDate 
	            ,PS.PaymentStatus  
	            FROM ExibhitsRegistrations D
	            LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId
				WHERE PS.PaymentStatus= ''Completed'' AND D.IsActive = 1 AND D.Amount <> 0 '
		
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  D.ExhibitType LIKE ''%' + @Search + '%'''
		END		
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH 	 
END
















