				,@PaymentMethodId
				,@PaymentDate
				,@TransactionId
				,@AmountPaid
				,@BankName
				,@ChequeNo 
				,@ChequeDate  
				,@AdminComments  
				,@Field1  
				,@Field2  
				,@Field3 
				,@InstertedBy 
				,@InsertedDate 
				,@UpdatedBy 
				,@UpdatedDate 
				)		
			Select @CompetitionRegistrationId = SCOPE_IDENTITY()	
			SELECT @QStatus = 1;	
		END
	ELSE
		BEGIN
			UPDATE Form1
			   SET EventId=@EventId, 
				   RegistrationCategoryId=@RegistrationCategoryId,
				   MemberId=@MemberId,
				   FirstName =@FirstName,
				   LastName=@LastName,
