CREATE PROCEDURE [dbo].[FEGetActiveServicesList]
    @ChapterId bigint,
    @QStatus int output
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY    
    
		IF (@ChapterId= 1)
			BEGIN
				Select  Top(14) S.ServiceId,S.ServiceTitle ,S.EstimationAmount,S.ShortDescription,S.Description
				,(Select Top(1) ImageUrl from ServiceImages SI Where SI.ServiceId = S.ServiceId)  as ImageUrl
				,(Select sum(SD.Amount) from ServiceDonations SD Where SD.ServiceId = S.ServiceId  AND PaymentStatusId = 1)  as TotalAmount
				 from Services S where S.IsDisplay=1 ORDER BY UpdatedDate ASC
			END
		ELSE
			 BEGIN
		 		 Select Top(14) S.ServiceId,S.ServiceTitle ,S.EstimationAmount,S.ShortDescription,S.Description
				,(Select Top(1) ImageUrl from ServiceImages SI Where SI.ServiceId = S.ServiceId)  as ImageUrl
				,(Select sum(SD.Amount) from ServiceDonations SD Where SD.ServiceId = S.ServiceId AND PaymentStatusId = 1)  as TotalAmount
				 from Services S where S.IsDisplay=1  ORDER BY UpdatedDate ASC
			 END
		SELECT @QStatus = 1;	
		
    END TRY

    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH
    	
END
























