CREATE PROCEDURE [dbo].[FEGetCommitteeMembersList]
    @ChapterId bigint,
    @QStatus int output
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY    
    
		 SELECT Distinct Top(1) C.MemberId
				,(C.FirstName + ' ' + C.LastName) As Name
				,C.MobilePhone
				,C.Address
				,C.City
				,C.State
				,C.Email
				,C.ProfileImage
				,CM.DisplayOrder
				,C.IsApproved
				,C.Occupation
				,CC.UpdatedBy
				,CC.UpdatedTime
				,CC.CategoryName
				,CC.CommitteeCategoryId
				,CC.Type	
				,CM.Designation			
			    ,CC.* FROM  Members C
			    INNER JOIN CommitteeMembers CM ON CM.MemberId = C.MemberId
			    INNER JOIN CommitteeCategories CC ON CC.CommitteeCategoryId= CM.CommitteeCategoryId
			    INNER JOIN ChapterCommittees CO ON CO.CommitteeCategoryId= CM.CommitteeCategoryId WHERE 
			    dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') IN (dbo.RemoveSpecialChar('NATS Helpline', '^a-z0-9')) AND 
			    CC.IsActive=1 AND 
			    CM.ChapterId = 1 AND (CM.Designation = 'Chairwoman') 

			  UNION

			   SELECT Distinct Top(1) C.MemberId
				,(C.FirstName + ' ' + C.LastName) As Name
				,C.MobilePhone
				,C.Address
				,C.City
				,C.State
				,C.Email
				,C.ProfileImage
				,CM.DisplayOrder
				,C.IsApproved
				,C.Occupation
				,CC.UpdatedBy
				,CC.UpdatedTime
				,CC.CategoryName
				,CC.CommitteeCategoryId
				,CC.Type	
				,CM.Designation			
			    ,CC.* FROM  Members C
			    INNER JOIN CommitteeMembers CM ON CM.MemberId = C.MemberId
			    INNER JOIN CommitteeCategories CC ON CC.CommitteeCategoryId= CM.CommitteeCategoryId
			    INNER JOIN ChapterCommittees CO ON CO.CommitteeCategoryId= CM.CommitteeCategoryId WHERE 
			    dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') IN (dbo.RemoveSpecialChar('NATS Helpline', '^a-z0-9')) AND 
			    CC.IsActive=1 AND 
			    CM.ChapterId = 1 AND (CM.Designation = 'President') ORDER BY CM.DisplayOrder ASC

		SELECT @QStatus = 1;	

		
		
    END TRY

    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH
    	
END
























