/****** Object:  StoredProcedure [dbo].[FEGetEventByCategoryId]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FEGetEventByCategoryId]
	(@EventId bigint
	,@RegistrationCategoryId bigint
	,@EventName nvarchar(1024)
    ,@QStatus int OUTPUT)    
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
   SET NOCOUNT ON;

   BEGIN TRY 
   
		IF(@EventId=0)
		BEGIN
			SET @EventId= (SELECT EventId FROM Events WHERE dbo.RemoveSpecialChar(EventName, '^a-z0-9')= dbo.RemoveSpecialChar(@EventName, '^a-z0-9'))
		END

		Declare @StartDate datetime;
		Declare @EndDate datetime;

		Select @StartDate = StartDate, @EndDate = EndDate from 
		(Select EventId, StartDate, EndDate, ROW_NUMBER() OVER(Partition By EventId ORDER BY StartDate ASC) AS RowNo From EventDates
		 Where Convert(Date, EndDate) >= Convert(Date, GetDate())) A where A.RowNo = 1 AND A.EventId = @EventId 

      IF(@StartDate is NULL AND @EndDate is NULL)
		  BEGIN
		  Select @StartDate = StartDate, @EndDate = EndDate from (Select EventId, StartDate, EndDate, ROW_NUMBER() OVER(Partition By EventId ORDER BY StartDate DESC) AS RowNo From EventDates) A where A.RowNo = 1 AND A.EventId = @EventId 
		  END

      IF(@EventId!=0)
		BEGIN
			SELECT  @StartDate As StartDate,@EndDate As EndDate, E.*
						,EC.EventCategory
						,(Select MemberAmount from EventRegCategoriesList EL where EL.RegistrationCategoryId = @RegistrationCategoryId AND EL.EventId = @EventId) As MemberAmount 
						,(Select NAmount from EventRegCategoriesList EL where EL.RegistrationCategoryId = @RegistrationCategoryId AND EL.EventId = @EventId) As NAmount 
						,(Select CategoryName from RegistrationCategories RC where RC.RegistrationCategoryId = @RegistrationCategoryId) As CategoryName 
			FROM Events  E 
			LEFT JOIN EventCategories EC ON E.EventCategoryId = EC.EventCategoryId
			WHERE E.EventId  = @EventId

			SELECT * FROM EventRegistrationTypes WHERE EventId=@EventId 

			SELECT *,(Select RC.CategoryName from RegistrationCategories RC Where RC.RegistrationCategoryId = EL.RegistrationCategoryId) As CategoryName FROM EventRegCategoriesList EL WHERE EL.EventId = @EventId 
	   END
		    SELECT @QStatus = 1;
		
    END TRY

    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH		
	 
END







