CREATE PROCEDURE [dbo].[FEGetPhotoList]   
  @QStatus int output 
  ,@ChapterId bigint 
  ,@Year int  
       
AS  
BEGIN  
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
   
 SET NOCOUNT ON;  
 DECLARE @Query NVARCHAR(max);  
   
 BEGIN TRY  
    
  /*====================================================================*/  
  /*              Photos List                          */  
  /*====================================================================*/  
    
  SELECT *   
FROM Photos P  
INNER JOIN PhotoCategories CC ON CC.PhotoCategoryId = P.PhotoCategoryId  
  
WHERE CC.Year = @Year AND P.IsActive = 1  
   
  
  
  
  /*====================================================================*/  
  /*              Photo Categories List                     */  
  /*====================================================================*/  
    
  SELECT *,(SELECT COUNT(*) FROM Photos PC WHERE P.PhotoCategoryId=PC.PhotoCategoryId AND PC.IsActive=1) AS PhotosCount FROM PhotoCategories P   
  WHERE P.Year = @Year  and P.ChapterId=@ChapterId
   ORDER BY  P.Year ASC    


 
  
  
  SELECT @QStatus = 1;  
      
 END TRY  
      
    BEGIN CATCH    
       SELECT @QStatus = -1;  
    END CATCH   
END  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  

