/****** Object:  StoredProcedure [dbo].[FEGetPromocodeValidate]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[FEGetPromocodeValidate]
(
    @PromoCode NVARCHAR(128),
    @QStatus INT OUTPUT
)
AS
BEGIN
    BEGIN TRY
        SET NOCOUNT ON;

        DECLARE @Today DATE = CONVERT(DATE, GETUTCDATE());

        -- Check if promo code exists
        IF NOT EXISTS (SELECT 1 FROM PromoCodes WHERE PromoCode = @PromoCode)
        BEGIN
            SET @QStatus = 0; -- Invalid code
            RETURN;
        END

        -- Check expired
        IF EXISTS (
            SELECT 1
            FROM PromoCodes
            WHERE PromoCode = @PromoCode
              AND CONVERT(DATE, EndDate) < @Today
        )
        BEGIN
            SET @QStatus = 2; -- Expired
            RETURN;
        END

        -- Check valid
        IF EXISTS (
            SELECT 1
            FROM PromoCodes
            WHERE PromoCode = @PromoCode
              AND IsActive = 1
              AND CONVERT(DATE, StartDate) <= @Today
              AND CONVERT(DATE, EndDate) >= @Today
        )
        BEGIN
            SELECT *
            FROM PromoCodes
            WHERE PromoCode = @PromoCode
              AND IsActive = 1
              AND CONVERT(DATE, StartDate) <= @Today
              AND CONVERT(DATE, EndDate) >= @Today;

            SET @QStatus = 1; -- Valid
            RETURN;
        END

        -- fallback
        SET @QStatus = -1;

    END TRY
    BEGIN CATCH
        SET @QStatus = -1;
    END CATCH
END
