/****** Object:  StoredProcedure [dbo].[FEGetSponsorsList]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[FEGetSponsorsList] 
	 (@ChapterId bigint
	 ,@QStatus int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	DECLARE @Query NVARCHAR(max);
	
	BEGIN TRY	 
		
		/*====================================================================*/
		/*				          Sponsors List                     			  */
		/*====================================================================*/
		
	    SELECT * FROM Sponsors S	
		INNER JOIN SponsorCategories SC on SC.SponsorCategoryId = S.SponsorCategoryId	
		WHERE S.IsActive = 1 
		ORDER BY  SC.SponsorCategoryId ASC
		/*====================================================================*/
		/*				          Sponsors Categories List                  	  */
		/*====================================================================*/
		
	--SELECT *,(SELECT COUNT(*) FROM Sponsors S WHERE SC.SponsorCategoryId = S.SponsorCategoryId AND S.IsActive=1 ) AS SponsorsCount FROM SponsorCategories SC WHERE    SC.IsActive = 1  ORDER BY  SC.SponsorCategoryId desc

	


	If (@ChapterId=1)
		begin		 
			       
             SELECT *,(SELECT COUNT(*) FROM Sponsors P WHERE P.SponsorCategoryId=PC.SponsorCategoryId AND IsActive=1 ) AS SponsorsCount     
                FROM SponsorCategories PC WHERE PC.CategoryName<>'Sponsors'   AND PC.IsActive = 1    Order by PC.updatedtime ASC  
		end
		else
		begin

			IF((Select Count(*) FROM SponsorCategories S WHERE S.IsActive = 1 And S.ChapterId = @ChapterId) = 0)
			BEGIN
				 SELECT *,(SELECT COUNT(*) FROM Sponsors P WHERE P.SponsorCategoryId=PC.SponsorCategoryId AND IsActive=1 ) AS SponsorsCount     
                 FROM SponsorCategories PC WHERE PC.CategoryName<>'Sponsors'   AND PC.IsActive = 1    Order by PC.updatedtime ASC  
			END
			ELSE
			begin		 
				
				
				SELECT *,(SELECT COUNT(*) FROM Sponsors P WHERE P.SponsorCategoryId=PC.SponsorCategoryId AND IsActive=1 ) AS SponsorsCount     
                   FROM SponsorCategories PC WHERE PC.CategoryName<>'Sponsors'   AND PC.IsActive = 1  And  PC.ChapterId =@ChapterId  Order by PC.updatedtime ASC  

				
				
							       
               
	
			end
		end













		SELECT @QStatus = 1;
				
	END TRY
    
    BEGIN CATCH  
       SELECT @QStatus = -1;
    END CATCH 
END









