CREATE PROCEDURE [dbo].[FEGetVideoList]
	(@ChapterId bigint
	 ,@QStatus int output)
     
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
	SET NOCOUNT ON;
	DECLARE @Query NVARCHAR(max);
	
	BEGIN TRY	 
		
		
		/*====================================================================*/
		/*				          Videos List                     			  */
		/*====================================================================*/
		
		SELECT *FROM Videos V		
		WHERE V.IsActive = 1 ORDER BY  V.DisplayOrder ASC	
		/*====================================================================*/
		/*				          Videos Categories List                  	  */
		/*====================================================================*/
		
		SELECT *,(SELECT COUNT(*) FROM Videos VC WHERE V.VideoCategoryId=VC.VideoCategoryId AND VC.IsActive=1) AS VideosCount FROM VideoCategories V 		
		where V.ChapterId= @ChapterId  ORDER BY  V.Year DESC	
		
		
		
	 

		SELECT @QStatus = 1;
				
	END TRY
    
    BEGIN CATCH  
       SELECT @QStatus = -1;
    END CATCH 
END










