CREATE PROCEDURE [dbo].[FEGetVideosList]
    @ChapterId bigint,
    @QStatus int output
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY    
    
		IF (@ChapterId=1)
			BEGIN 
				SELECT Top(4) * FROM VideoCategories V	
				INNER JOIN Videos VC on VC.VideoCategoryId = V.VideoCategoryId	
				WHERE Vc.IsActive = 1 
				ORDER BY  VC.VideoCategoryId ASC 
			END
		ELSE
			BEGIN
				IF((Select Count(*) FROM VideoCategories V INNER JOIN Videos VC on VC.VideoCategoryId = V.VideoCategoryId WHERE Vc.IsActive = 1 And ChapterId = @ChapterId) <> 0)
					BEGIN
						SELECT Top(4) * FROM VideoCategories V	
						INNER JOIN Videos VC on VC.VideoCategoryId = V.VideoCategoryId	
						WHERE Vc.IsActive = 1 And ChapterId = @ChapterId
						ORDER BY  VC.VideoCategoryId ASC 
					END
				ELSE
					BEGIN 
						SELECT Top(4) * FROM VideoCategories V	
						INNER JOIN Videos VC on VC.VideoCategoryId = V.VideoCategoryId	
						WHERE Vc.IsActive = 1 
						ORDER BY  VC.VideoCategoryId ASC 
					END
			END

		SELECT @QStatus = 1;	
		
    END TRY
    BEGIN CATCH
    
		 SELECT @QStatus = -1;
		 
    END CATCH
    	
END
























