/****** Object:  StoredProcedure [dbo].[FEGeUpcommingEventsList]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
    
    
    
CREATE PROCEDURE [dbo].[FEGeUpcommingEventsList]   
    @ChapterId bigint,    
    @QStatus int output    
            
AS    
BEGIN    
    
 -- SET NOCOUNT ON added to prevent extra result sets from    
     
 SET NOCOUNT ON;    
        
    BEGIN TRY        
    
 IF (@ChapterId=1)    
    BEGIN    
        
 SELECT TOP(2) A.StartDate ,A.EndDate, * FROM Events E    
 Inner JOIN ChapterEvents CE ON CE.EventId = E.EventId      
  LEFT Join (Select EventId, StartDate, EndDate, ROW_NUMBER() OVER(Partition By EventId ORDER BY StartDate ASC) AS RowNo From Events    
  Where Convert(Date, EndDate) >= Convert(Date, GetDate())) A on A.RowNo = 1 AND A.EventId = E.EventId    
  WHERE (CONVERT (DATE,A.StartDate)  >= CONVERT (DATE,GETDATE()) OR A.StartDate IS NULL OR CONVERT (DATE, A.StartDate)  <=  CONVERT (DATE, GETDATE()) OR A.StartDate IS NULL OR A.EndDate IS NULL) AND A.EndDate >= CONVERT (DATE, GETDATE()) AND CE.ChapterId 
  
= 1 AND E.IsActive = 1 ORDER BY  A.StartDate ASC     
    
    
   END    
  ELSE    
   BEGIN       
    IF((Select Count(*) FROM ChapterEvents WHERE ChapterId = @ChapterId) <> 0)    
      BEGIN    
    
    SELECT TOP(2) A.StartDate ,A.EndDate, * FROM Events E    
    Inner JOIN ChapterEvents CE ON CE.EventId = E.EventId      
  LEFT Join (Select EventId, StartDate, EndDate, ROW_NUMBER() OVER(Partition By EventId ORDER BY StartDate ASC) AS RowNo From Events    
  Where Convert(Date, EndDate) >= Convert(Date, GetDate())) A on A.RowNo = 1 AND A.EventId = E.EventId    
  WHERE (CONVERT (DATE,A.StartDate)  >= CONVERT (DATE,GETDATE()) OR A.StartDate IS NULL OR CONVERT (DATE, A.StartDate)  <=  CONVERT (DATE, GETDATE()) OR A.StartDate IS NULL OR A.EndDate IS NULL) AND A.EndDate >= CONVERT (DATE, GETDATE()) AND CE.ChapterId 
  
= @ChapterId  AND E.IsActive = 1 ORDER BY  A.StartDate ASC     
    
      
    
   END    
    
    ELSE    
      BEGIN    
        
 SELECT TOP(2) A.StartDate ,A.EndDate, * FROM Events E    
 Inner JOIN ChapterEvents CE ON CE.EventId = E.EventId      
  LEFT Join (Select EventId, StartDate, EndDate, ROW_NUMBER() OVER(Partition By EventId ORDER BY StartDate ASC) AS RowNo From Events    
    
  Where Convert(Date, EndDate) >= Convert(Date, GetDate())) A on A.RowNo = 1 AND A.EventId = E.EventId    
  WHERE (CONVERT (DATE,A.StartDate)  >= CONVERT (DATE,GETDATE()) OR A.StartDate IS NULL OR CONVERT (DATE, A.StartDate)  <=  CONVERT (DATE, GETDATE()) OR A.StartDate IS NULL OR A.EndDate IS NULL) AND A.EndDate >= CONVERT (DATE, GETDATE())  AND CE.ChapterId
  
 = 1   AND E.IsActive = 1 ORDER BY  A.StartDate DESC     
    
    
   END     
   END    
    
  SELECT @QStatus = 1;     
      
    END TRY    
    BEGIN CATCH    
        
   SELECT @QStatus = -1;    
       
    END CATCH    
         
END    
    
    
    
    
    
    
    
  
    
  
