/****** Object:  StoredProcedure [dbo].[FEHelplineCommitteesGetList]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FEHelplineCommitteesGetList]
	(@Type nvarchar(128)
	,@ChapterId bigint
    ,@QStatus int OUTPUT)    
        
AS
BEGIN

   SET NOCOUNT ON;

   Declare @CID bigint 

   
   BEGIN TRY  

			 SELECT Distinct  C.MemberId
				,(C.FirstName + ' ' + C.LastName) As Name
				,C.MobilePhone
				,C.Address
				,C.City
				,C.State
				,C.Email
				,C.ProfileImage
				,CM.DisplayOrder
				,C.IsApproved
				,C.Occupation
				,CC.UpdatedBy
				,CC.UpdatedTime
				,CC.CategoryName
				,CC.CommitteeCategoryId
				,CC.Type	
				,CM.Designation			
			    ,CC.* FROM  Members C
			    INNER JOIN CommitteeMembers CM ON CM.MemberId = C.MemberId
			    INNER JOIN CommitteeCategories CC ON CC.CommitteeCategoryId= CM.CommitteeCategoryId
			    INNER JOIN ChapterCommittees CO ON CO.CommitteeCategoryId= CM.CommitteeCategoryId
			    WHERE dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') = dbo.RemoveSpecialChar('NATS Helpline', '^a-z0-9') AND CC.IsActive=1 
			    AND CM.ChapterId = 1 ORDER BY CM.DisplayOrder ASC

			  SELECT @QStatus = 1;
    END TRY

    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH	
	 
END


























