/****** Object:  StoredProcedure [dbo].[FEInsertEventUserInfo]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
    
    
    
CREATE PROCEDURE [dbo].[FEInsertEventUserInfo]    
    (@EventId bigint     
    ,@MemberId bigint     
 ,@EventUserInfoId bigint output        
 ,@FirstName nvarchar(156)    
 ,@LastName nvarchar(156)    
 ,@Email nvarchar(156)    
 ,@Gender nvarchar(50)    
 ,@Address nvarchar(156)    
 ,@City nvarchar(156)    
 ,@State nvarchar(156)    
 ,@Mobile nvarchar(15)    
 ,@ItemName nvarchar(1024)    
 ,@ItemCategory nvarchar(1024)    
 ,@ItemDescription nvarchar(1024)    
 ,@ItemDuration int    
 ,@IsApproved bit    
 ,@ApprovedDate datetime    
 ,@DocumentUrl nvarchar(156) output    
 ,@UpdatedBy nvarchar(64)    
 ,@UpdatedTime datetime    
 ,@PaymentStatusId bigint    
 ,@PaymentStatus nvarchar(2048)    
 ,@PaymentMethod nvarchar(2048)    
 ,@PaymentMethodId bigint    
 ,@OtherPaymentId nvarchar(max)    
 ,@AmountPaid decimal(15,2)    
 ,@ChildCount int    
 ,@AdultCount int    
 ,@CoupleCount int    
 ,@FamilyCount int    
 ,@VIPCount int    
 ,@VIPSingleAdultCount int    
 ,@VIPCoupleCount int    
 ,@VIPChildCount int    
 ,@Comments nvarchar(max)    
 ,@InsertedBy nvarchar(30)    
 ,@InsertedTime datetime    
 ,@QStatus int output    
 ,@XMLRegistrationsCounts nvarchar(max)    
 ,@Zelle nvarchar(512)    
  ,@ReceiptUrl nvarchar(max) output    
  ,@ZellePartnerName nvarchar(512)    
  ,@ChequeHolderName nvarchar(512))      
            
AS    
BEGIN    
    
 -- SET NOCOUNT ON added to prevent extra result sets from    
 -- interfering with SELECT statements.    
     
 SET NOCOUNT ON;    
    
    -- Insert statements for procedure here    
        
    --BEGIN TRY    
    --BEGIN TRANSACTION    
        
 IF(@PaymentStatus IS NOT NULL)    
     BEGIN    
      SELECT @PaymentStatusId = PaymentStatusId FROM PaymentStatus WHERE PaymentStatus = @PaymentStatus    
         
      IF(@PaymentStatusId IS NULL OR @PaymentStatusId='')    
      BEGIN    
        INSERT INTO PaymentStatus VALUES(@PaymentStatus,1)    
        SELECT @PaymentStatusId=SCOPE_IDENTITY()    
      END    
      IF(@PaymentMethod IS NOT NULL)    
      BEGIN    
      SELECT @PaymentMethodId = PaymentMethodId FROM PaymentMethods WHERE PaymentMethod = @PaymentMethod    
      END    
     END    
    
  IF((SELECT COUNT(*) FROM EventUserInfo WHERE EventUserInfoId = @EventUserInfoId) = 0)    
  BEGIN    
   INSERT INTO EventUserInfo VALUES    
      (    
      @EventId    
      ,@MemberId    
      ,@FirstName     
      ,@LastName     
      ,@Email     
      ,@Gender     
      ,@Address     
      ,@City     
      ,@State     
      ,@Mobile    
      ,@IsApproved    
      ,@ApprovedDate    
      ,Null    
      ,Null    
      ,Null    
      ,@OtherPaymentId    
      ,Null    
      ,@AmountPaid    
      ,Null    
      ,@ItemName     
      ,@ItemCategory    
      ,@ItemDescription    
      ,@ItemDuration    
      ,NULL    
      ,@Comments    
      ,@InsertedBy    
      ,@InsertedTime     
      ,@UpdatedBy     
      ,@UpdatedTime    
      ,@Zelle,    
      null,    
      @ZellePartnerName,    
      @ChequeHolderName)    
         
   SET @EventUserInfoId = SCOPE_IDENTITY()      
    IF(@DocumentUrl <> 'NA')    
BEGIN    
    UPDATE EventUserInfo    
    SET DocumentUrl = CAST(@EventUserInfoId AS nvarchar(12)) + '-' + 
                      dbo.RemoveSpecialChar(@FirstName, '^a-z0-9') + '.' + @DocumentUrl
    WHERE EventUserInfoId = @EventUserInfoId     
    SELECT @DocumentUrl = CAST(@EventUserInfoId AS nvarchar(12)) + '-' + 
                          dbo.RemoveSpecialChar(@FirstName, '^a-z0-9') + '.' + @DocumentUrl      
END
   --IF(@DocumentUrl <> 'NA')    
   --BEGIN    
   -- UPDATE EventUserInfo    
   --  SET  DocumentUrl= CAST(@EventUserInfoId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(GETDATE(), '^a-z0-9') + @DocumentUrl    
   --  WHERE EventUserInfoId = @EventUserInfoId     
   -- SELECT @DocumentUrl =  (SELECT DocumentUrl FROM EventUserInfo WHERE EventUserInfoId=@EventUserInfoId)    
        
   --END     
   ELSE    
   BEGIN    
    SELECT @DocumentUrl=''    
   END     
    
    
    IF(@ReceiptUrl <> 'NA')      
    BEGIN      
      UPDATE EventUserInfo SET ReceiptUrl = CAST(@EventUserInfoId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@FirstName, '^a-z0-9') + '.' + @ReceiptUrl  WHERE EventUserInfoId = @EventUserInfoId      
      SELECT @ReceiptUrl = CAST(@EventUserInfoId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@FirstName, '^a-z0-9') + '.' + @ReceiptUrl      
    END       
   ELSE    
    BEGIN    
     SELECT @ReceiptUrl=''    
    END     
    
    
   -- IF(@ReceiptUrl <> 'NA')    
   --BEGIN    
   -- UPDATE EventUserInfo    
   --  SET  ReceiptUrl= CAST(@EventUserInfoId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(GETDATE(), '^a-z0-9') + @ReceiptUrl    
   --  WHERE EventUserInfoId = @EventUserInfoId     
   -- SELECT @ReceiptUrl =  (SELECT ReceiptUrl FROM EventUserInfo WHERE EventUserInfoId=@EventUserInfoId)    
        
   --END     
   --ELSE    
   --BEGIN    
   -- SELECT @ReceiptUrl=''    
   --END     
    
    
    
    
   IF(@XMLRegistrationsCounts<>'')    
BEGIN        
       DECLARE @XML1 AS XML                 
       SELECT @XML1 = @XMLRegistrationsCounts        
        
       /*---------------ClassifiedRegistrationCounts Insert -------*/        
       CREATE TABLE #temp1(    
           Rid INT PRIMARY KEY IDENTITY(1,1),        
           EventRegistrationTypeId BIGINT,        
           Count INT    
       )        
            
       DECLARE @RowCount1 AS int        
       DECLARE @CurrentRow1 AS int         
            
       INSERT INTO #temp1(EventRegistrationTypeId,Count)        
       SELECT         
           M.Item.value('EventRegistrationTypeId[1]','bigint'),        
           M.Item.value('Count[1]','int')        
       FROM @XML1.nodes('/ArrayOfEventRegistrationCounts/EventRegistrationCounts') AS M(Item)        
             
       SET @RowCount1 = @@ROWCOUNT         
       SET @CurrentRow1 = 1        
            
       WHILE @CurrentRow1 <= @RowCount1        
       BEGIN         
           IF((SELECT EventRegistrationTypeId FROM #temp1 WHERE Rid = @CurrentRow1) IS NOT NULL     
              AND (SELECT EventRegistrationTypeId FROM #temp1 WHERE Rid = @CurrentRow1) <> '')        
           BEGIN        
               DECLARE @MemberAmount decimal(15, 2)        
               DECLARE @CurTypeId BIGINT    
               DECLARE @CurCount INT    
                   
               SELECT @CurTypeId = EventRegistrationTypeId,     
                      @CurCount = Count     
               FROM #temp1 WHERE Rid = @CurrentRow1        
    
               -- Calculate amount    
               IF(@MemberId <> 0)        
               BEGIN        
                   SET @MemberAmount = (SELECT E.MemberAmount     
                                        FROM EventRegistrationTypes E     
                                        WHERE E.EventRegistrationTypeId = @CurTypeId) * @CurCount        
               END        
               ELSE        
               BEGIN        
                   SET @MemberAmount = (SELECT E.NonMemberAmount     
                                        FROM EventRegistrationTypes E     
                                        WHERE E.EventRegistrationTypeId = @CurTypeId) * @CurCount        
               END        
  
      
               -- Insert into EventRegistrationCounts (summary)    
               IF(@CurCount > 0)        
               BEGIN        
                   INSERT INTO EventRegistrationCounts         
                   (EventId, EventUserInfoId, EventRegistrationTypeId, Count, Amount)        
                   VALUES (@EventId, @EventUserInfoId, @CurTypeId, @CurCount, @MemberAmount)        
    
                   DECLARE @EventRegCountId BIGINT = SCOPE_IDENTITY()    
    
                   -- Insert into EventRegDetails (expanded rows)    
                   DECLARE @i INT = 1    
    
       DECLARE @TicketSeed INT    
    
     -- Get the current max TicketId number (numeric part) and start from next    
     SELECT @TicketSeed = ISNULL(MAX(CAST(SUBSTRING(TicketId, 5, LEN(TicketId)) AS INT)), 1000) + 1    
     FROM EventRegTickets    
    
                   WHILE @i <= @CurCount    
                   BEGIN    
                       INSERT INTO EventRegTickets    
                       (EventRegCountId, EventId, EventUserInfoId, EventRegistrationTypeId, SequenceNo, Status, GeneratedDate, InsertedBy, TicketId)    
                       VALUES    
                       (@EventRegCountId, @EventId, @EventUserInfoId, @CurTypeId, @i, 'Registered', GETDATE(), @InsertedBy, 'TKT-' + CAST(@TicketSeed AS VARCHAR(10)))    
    
        SET @TicketSeed += 1    
                       SET @i += 1    
                   END    
               END    
           END           
           SET @CurrentRow1 = @CurrentRow1 + 1        
       END         
            
       DROP TABLE #temp1        
   END        
        
   SELECT @QStatus = 1;      
  END    
    
     ELSE    
      
  BEGIN   
     UPDATE EventUserInfo    
      SET     
         EventId                      =       @EventId,    
         MemberId      =      @MemberId,    
      FirstName       =  @FirstName ,    
      LastName      =  @LastName ,    
      Email      =  @Email ,    
      Gender      =  @Gender ,    
      Address      =  @Address ,    
       City      =  @City ,    
      State     =  @State ,    
      Mobile    =  @Mobile ,    
