CREATE PROCEDURE [dbo].[FEInsertSportsEventUserInfo]  
    (@EventId bigint   
     ,@MemberId bigint   
	 ,@SportsEventUserInfoId bigint output      
	 ,@FirstName nvarchar(156)  
	 ,@LastName nvarchar(156)  
	 ,@Email nvarchar(156)  
	 ,@Gender nvarchar(50)  
	 ,@Address nvarchar(156)  
	 ,@City nvarchar(156)  
	 ,@State nvarchar(156) 
	 ,@Mobile nvarchar(15)  
	 ,@ItemName nvarchar(1024)  
	 ,@ItemCategory nvarchar(1024)  
	 ,@ItemDescription nvarchar(1024)  
	 ,@ItemDuration int  
	 ,@IsApproved bit  
	 ,@ApprovedDate datetime  
	 ,@DocumentUrl nvarchar(156) output  
	 ,@UpdatedBy nvarchar(64)  
	 ,@UpdatedTime datetime  
	 ,@PaymentStatusId bigint  
	 ,@PaymentStatus nvarchar(2048)  
	 ,@PaymentMethod nvarchar(2048)  
	 ,@PaymentMethodId bigint  
	 ,@OtherPaymentId nvarchar(max)  
	 ,@AmountPaid decimal(15,2)  
	 ,@ChildCount int  
	 ,@AdultCount int  
	 ,@CoupleCount int  
	 ,@FamilyCount int 
	 ,@VIPCount int  
	 ,@VIPSingleAdultCount int  
	 ,@VIPCoupleCount int  
	 ,@VIPChildCount int  
	 ,@Comments nvarchar(max)  
	 ,@InsertedBy nvarchar(30)  
	 ,@InsertedTime datetime  
	 ,@QStatus int output  
	 ,@XMLRegistrationsCounts nvarchar(max))    
          
AS  
BEGIN  
  
   
 SET NOCOUNT ON; 
      
    BEGIN TRY  
    BEGIN TRANSACTION  
      
		 IF(@PaymentStatus IS NOT NULL)  
			 BEGIN  
			  SELECT @PaymentStatusId = PaymentStatusId FROM PaymentStatus WHERE PaymentStatus = @PaymentStatus  
				  IF(@PaymentStatusId IS NULL OR @PaymentStatusId='')  
					  BEGIN  
						INSERT INTO PaymentStatus VALUES(@PaymentStatus,1)  
						SELECT @PaymentStatusId=SCOPE_IDENTITY()  
					  END  
				  IF(@PaymentMethod IS NOT NULL)  
					  BEGIN  
						SELECT @PaymentMethodId = PaymentMethodId FROM PaymentMethods WHERE PaymentMethod = @PaymentMethod  
					  END  
			 END  
  
		  IF((SELECT COUNT(*) FROM SportsEventUserInfo WHERE SportsEventUserInfoId = @SportsEventUserInfoId) = 0)  
		  BEGIN  
		   INSERT INTO SportsEventUserInfo VALUES  
			  (@EventId  
			  ,@MemberId  
			  ,@FirstName   
			  ,@LastName   
			  ,@Email   
			  ,@Gender   
			  ,@Address   
			  ,@City   
			  ,@State   
			  ,@Mobile  
			  ,@IsApproved  
			  ,@ApprovedDate  
			  ,Null  
			  ,Null  
			  ,Null  
			  ,@OtherPaymentId  
			  ,Null  
			  ,@AmountPaid  
			  ,Null  
			  ,@ItemName   
			  ,@ItemCategory  
			  ,@ItemDescription  
			  ,@ItemDuration  
			  ,NULL  
			  ,@Comments  
			  ,@InsertedBy  
			  ,@InsertedTime   
			  ,@UpdatedBy   
			  ,@UpdatedTime)  
       
		   SET @SportsEventUserInfoId = SCOPE_IDENTITY()    
  
		   IF(@DocumentUrl <> 'NA')  
			   BEGIN  
					UPDATE SportsEventUserInfo  
					SET  DocumentUrl= CAST(@SportsEventUserInfoId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(GETDATE(), '^a-z0-9') + @DocumentUrl  
					WHERE SportsEventUserInfoId = @SportsEventUserInfoId   
					SELECT @DocumentUrl =  (SELECT DocumentUrl FROM SportsEventUserInfo WHERE SportsEventUserInfoId=@SportsEventUserInfoId )  
			   END   
		   ELSE  
			   BEGIN  
				SELECT @DocumentUrl=''  
			   END   
  
		  IF(@XMLRegistrationsCounts<>'')  
		  BEGIN  
		  DECLARE @XML1 AS XML           
		  SELECT @XML1 = @XMLRegistrationsCounts  
  
		  /*---------------ClassifiedRegistrationCounts Insert -------*/  
          
		  CREATE TABLE #temp1(Rid INT PRIMARY KEY IDENTITY(1,1),  
		  EventRegistrationTypeId nvarchar(max),  
		  Count nvarchar(max))  
      
		  DECLARE @RowCount1 AS int  
		  DECLARE @CurrentRow1 AS int   
      
		  INSERT INTO #temp1(EventRegistrationTypeId,Count)  
		  select   
		  M.Item.value('EventRegistrationTypeId[1]','nvarchar(max)'),  
		  M.Item.value('Count[1]','nvarchar(max)')  
		  FROM @XML1.nodes('/ArrayOfSportsEventRegistrationCounts/SportsEventRegistrationCounts') AS M(Item)  
       
		  SET @RowCount1 = @@ROWCOUNT   
		  SELECT @RowCount1  
		  SET @CurrentRow1 = 1  


		  WHILE @CurrentRow1 < @RowCount1 + 1  
			  BEGIN   
				   IF((SELECT EventRegistrationTypeId FROM #temp1 WHERE Rid = @CurrentRow1) IS NOT NULL AND  (SELECT EventRegistrationTypeId FROM #temp1 WHERE Rid = @CurrentRow1)<>'')  
				   BEGIN  
					   Declare @MemberAmount decimal(15, 2) 

					   IF(@MemberId <> 0)  
						   BEGIN  
							Set @MemberAmount = (SELECT E.MemberAmount FROM EventRegistrationTypes E WHERE E.EventRegistrationTypeId = (Select T2.EventRegistrationTypeId FROM #temp1 T2 Where T2.Rid = @CurrentRow1))  
							Set @MemberAmount = @MemberAmount * (Select T2.Count FROM #temp1 T2 Where T2.Rid = @CurrentRow1)  
						   END  
					   ELSE  
						   BEGIN  
							Set @MemberAmount = (SELECT E.NonMemberAmount FROM EventRegistrationTypes E WHERE E.EventRegistrationTypeId = (Select T2.EventRegistrationTypeId FROM #temp1 T2 Where T2.Rid = @CurrentRow1))  
							Set @MemberAmount = @MemberAmount * (Select T2.Count FROM #temp1 T2 Where T2.Rid = @CurrentRow1)  
						   END  
						IF((SELECT Count FROM #temp1 WHERE Rid = @CurrentRow1)<>0)  
							BEGIN  
								 INSERT INTO SportsEventRegistrationCounts  SELECT @EventId,@SportsEventUserInfoId,T.EventRegistrationTypeId,T.Count, @MemberAmount  
								 FROM #temp1 T WHERE T.Rid = @CurrentRow1    
							END     
					END     
			        SET @CurrentRow1 = @CurrentRow1 + 1  
			  END   
		      DROP TABLE #temp1  
		END  
  
		  END  
  
		  SELECT @QStatus = 1;  
    
	COMMIT TRANSACTION     
	END TRY  
      
	BEGIN CATCH   
		ROLLBACK TRANSACTION       
	    SELECT @QStatus = -1;      
	END CATCH     
      
END  
  
  
  
  
  
  
  
  
  
  
  
  


GO
/****** Object:  StoredProcedure [dbo].[FEKidsRegistrationsGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROCEDURE [dbo].[FEKidsRegistrationsGetListByVariable]  
  (@Search nvarchar(126)  
  ,@Email nvarchar(512)   
  ,@Sort nvarchar(216)  
  ,@PageNo int  
     ,@Items int  
     ,@Total int OUTPUT)  
AS  
BEGIN  
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
   
 SET NOCOUNT ON;  
   
 BEGIN TRY  
   
 DECLARE @Start int, @End INT ;  
 DECLARE @Query nvarchar(max);  
   
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)  
    ,KidsRegistrationsId bigint  
    ,ChapterId bigint  
    ,RegestrationID nvarchar(512)  
    ,FirstName nvarchar(512)  
    ,LastName nvarchar(512)  
    ,EmailId nvarchar(512)  
    ,DOB datetime  
    ,IsActive bit      
    ,ChapterName nvarchar(512)  
    ,TransactionId nvarchar(128)  
    ,PaymentStatus nvarchar(512)  
    ,OrderDate datetime  
    ,TotalAmount decimal(15,2)  
    ,EventId bigint  
    ,RegistrationCategoryId bigint  
    ,CategoryName nvarchar(512)  
    ,EventName nvarchar(512)  
    ,CompetitionCategory1 nvarchar(512)  
    ,PaymentStatusId bigint  
    )  
      
 SELECT @Start = (@PageNo - 1) * @Items    
      
 SELECT @End = @Start + @Items   
   
 SET @Query = 'INSERT INTO #temp SELECT   
              E.KidsRegistrationsId  
    ,E.ChapterId  
             ,E.RegestrationID  
             ,E.FirstName  
             ,E.LastName  
             ,E.EmailId  
             ,E.DOB  
    ,E.IsActive     
    ,C.ChapterName  
    ,E.TransactionId  
    ,PS.PaymentStatus  
    ,E.OrderDate  
    ,E.TotalAmount  
    ,E.EventId   
    ,E.RegistrationCategoryId   
    ,(SELECT CategoryName FROM RegistrationCategories RC WHERE Rc.RegistrationCategoryId=E.RegistrationCategoryId) AS CategoryName  
    ,(SELECT EventName FROM Events EV WHERE EV.EventId=E.EventId) AS EventName  
    ,E.CompetitionCategory1  
    ,E.PaymentStatusId  
              FROM KidsRegistrations E  
     Left JOIN Chapters C ON C.ChapterId = E.ChapterId  
     Left JOIN PaymentStatus PS ON PS.PaymentStatusId = E.PaymentStatusId  
     Left JOIN  RegistrationCategories RC ON RC.RegistrationCategoryId=E.RegistrationCategoryId      
           WHERE E.KidsRegistrationsId <> 0 AND E.EmailId IN (SELECT Email FROM Members WHERE Email = ''' + @Email +''')'  
    
    
  IF(@Search <> '')  
  BEGIN  
   SET @Query = @Query + ' AND  E.FirstName LIKE ''%' + @Search + '%'''  
  END  
  
  IF(@Sort <> '')  
  BEGIN  
   SET @Query = @Query + ' ORDER BY E.InsertedDate DESC'  
  END  
   
  EXEC sp_ExecuteSQL @Query;  
    
  SELECT @Total = COUNT(Rid) from #temp   
      
  SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End  
   
  DROP TABLE #temp  
  
 END TRY  
      
    BEGIN CATCH    
       SELECT @Total = -1;        
    END CATCH     
END  
  
  
  
  
  
  
  

GO
