/****** Object:  StoredProcedure [dbo].[FEMemberGetFullDetailsByEmail]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[FEMemberGetFullDetailsByEmail]
	(@Email nvarchar(512)
    ,@QStatus int OUTPUT)    
        
AS
BEGIN
	
   SET NOCOUNT ON;

    BEGIN TRY 

    DECLARE @MemberId bigint;
	DECLARE @Type nvarchar(512);

		IF((SELECT COUNT(*) FROM Members WHERE Email=@Email)<>0)
			BEGIN
			SET @MemberId=(SELECT top(1) MemberId FROM Members WHERE Email=@Email)
			END
		ELSE
			BEGIN
			SET @MemberId=0
			END
		SET @Type = (SELECT MembershipType FROM MembershipTypes WHERE MembershipTypeId = (SELECT MembershipTypeId FROM Members WHERE MemberId = @MemberId));

	
		IF(@MemberId <> 0)
			BEGIN
					IF(@Type = 'Life Membership')
						BEGIN
						 SELECT  M.*,   MT.Price AS MemberAmount,					
										MT.MembershipTypeId ,
										NULL AS ExpiryDate,
										MT.MembershipType	
							FROM Members M 
							INNER JOIN MembershipOrders MO ON MO.MemberId= M.MemberId
							INNER JOIN PaymentStatus PS ON PS.PaymentStatusId= MO.PaymentStatusId
							LEFT JOIN MembershipTypes MT ON MT.MembershipTypeId=M.MembershipTypeId
							WHERE M.MemberId=@MemberId AND Ps.PaymentStatus = 'Completed'
						END
			   ELSE IF(@Type <> 'Life Membership')
				   BEGIN
    				 SELECT     M.*,
								MT.Price AS MemberAmount,					
								MT.MembershipTypeId ,
								(SELECT MO.ExpiryDate FROM MembershipOrders MO WHERE MO.MembershipTypeId=MT.MembershipTypeId AND M.MemberId=MO.MemberId) AS ExpiryDate,
								MT.MembershipType	
								FROM Members M 
								INNER JOIN MembershipOrders MO ON MO.MemberId= M.MemberId
								INNER JOIN PaymentStatus PS ON PS.PaymentStatusId= MO.PaymentStatusId
								LEFT JOIN MembershipTypes MT ON MT.MembershipTypeId=M.MembershipTypeId
								WHERE M.MemberId=@MemberId AND Ps.PaymentStatus = 'Completed' AND CONVERT(DATE,MO.ExpiryDate) >= CONVERT(DATE,GETDATE())

		
					END
	       END

		ELSE
		   BEGIN
				SELECT   M.*,MT.Price AS MemberAmount,MT.MembershipTypeId ,(SELECT MO.ExpiryDate FROM MembershipOrders MO WHERE MO.MembershipTypeId=MT.MembershipTypeId AND M.MemberId=MO.MemberId) AS ExpiryDate,MT.MembershipType	
				FROM Members M 
				INNER JOIN MembershipOrders MO ON MO.MemberId= M.MemberId
				INNER JOIN PaymentStatus PS ON PS.PaymentStatusId= MO.PaymentStatusId
				LEFT JOIN MembershipTypes MT ON MT.MembershipTypeId=M.MembershipTypeId
				WHERE M.MemberId=@MemberId AND Ps.PaymentStatus = 'Completed'
		   END
		
				SELECT * FROM ChildrenInfo WHERE MemberId=@MemberId
		
				SELECT *,PM.PaymentMethod,PS.PaymentStatus,MT.MembershipType,(CASE WHEN CONVERT(DATE,MO.ExpiryDate) < CONVERT(DATE,GETDATE()) THEN 0 ELSE 1 END) AS Expiry FROM MembershipOrders MO 
				INNER JOIN PaymentMethods PM ON PM.PaymentMethodId=MO.PaymentMethodId 
				INNER JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId 
				INNER JOIN MembershipTypes MT ON MT.MembershipTypeId=MO.MembershipTypeId WHERE MO.MemberId=@MemberId
		 
		 SELECT @QStatus = 1;
		 
    END TRY
    
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH	
	 
END

















