CREATE PROCEDURE [dbo].[FEMembersGetListByVariable]  
  (@Search nvarchar(126)  
  ,@Sort nvarchar(126)  
  ,@PageNo int  
  ,@Items int  
  ,@MembershipTypeId bigint  
  ,@Total int output)  
AS  
BEGIN  
  
 SET NOCOUNT ON;  
   
 --BEGIN TRY  
   
 DECLARE @Start int, @End INT ;  
 DECLARE @Query nvarchar(max);  
      
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)  
    ,MemberId bigint  
    ,Title nvarchar(64)  
    ,Email nvarchar(128)  
    ,Password nvarchar(256)  
    ,FirstName nvarchar(150)  
    ,LastName nvarchar(150)  
    ,ProfileImage nvarchar(512)  
    ,Occupation nvarchar(256)  
    ,SpouseFirstName nvarchar(150)  
    ,SpouseLastName nvarchar(150)  
    ,SpouseOccupation nvarchar(256)  
    ,SpouseEmail nvarchar(128)  
    ,SpouseCell nvarchar(64)  
    ,Address nvarchar(512)  
    ,City nvarchar(128)  
    ,State nvarchar(128)  
    ,ZipCode nvarchar(64)  
    ,HomePhone nvarchar(64)  
    ,MobilePhone nvarchar(64)  
    ,IsApproved bit  
    ,IsLockedOut bit  
    ,IsActivated bit  
	,Memberskils    nvarchar(max)
    ,DateActivated datetime  
    ,RegistrationGUID uniqueidentifier  
    ,FailedPasswordAttemptCount int  
    ,LastPasswordChangedDate datetime  
    ,LastActivityDate datetime  
    ,MembershipTypeId bigint  
    ,IsVolunteer bit  
    ,IsTeluguorigin bit  
    ,Comments nvarchar(2048)  
    ,ReferredBy nvarchar(512)  
    ,Amount decimal(15,2)  
    ,TransactionId nvarchar(64)  
    ,PaymentStatusId bigint  
    ,PaymentMethodId bigint  
    ,PaymentMethod nvarchar(128)  
    ,PaymentStatus nvarchar(128)  
    ,AdminComment nvarchar(2048)  
    ,UserComment nvarchar(2048)  
    ,OrderDate datetime  
    ,ExpiryDate datetime  
    ,BankName nvarchar(128)  
    ,ChequeNo nvarchar(128)  
    ,ChequeDate datetime  
    ,InsertedTime datetime  
    ,UpdatedTime datetime  
    ,Fax nvarchar(64)  
    ,WebsiteAddress nvarchar(64)  
    ,Address2 nvarchar(512)  
    ,MembershipType nvarchar(256))  
  
 SELECT @Start = (@PageNo - 1) * @Items    
      
 SELECT @End = @Start + @Items   
   
 SET @Query = 'INSERT INTO #temp   
   SELECT  M.MemberId   
    ,Title   
    ,Email   
    ,Password   
    ,FirstName   
    ,LastName   
    ,ProfileImage   
    ,Occupation   
    ,SpouseFirstName   
    ,SpouseLastName   
    ,SpouseOccupation   
    ,SpouseEmail   
    ,SpouseCell   
    ,Address   
    ,City   
    ,State   
    ,ZipCode   
    ,HomePhone   
	
    ,MobilePhone   
    ,IsApproved   
    ,IsLockedOut   
    ,IsActivated   
	 ,Memberskils   
    ,DateActivated   
    ,RegistrationGUID   
    ,FailedPasswordAttemptCount  
    ,LastPasswordChangedDate   
    ,LastActivityDate   
    ,MT.MembershipTypeId   
    ,IsVolunteer   
    ,IsTeluguorigin   
    ,Comments   
    ,ReferredBy  
    ,Amount   
    ,TransactionId   
    ,MO.PaymentStatusId   
    ,PaymentMethodId   
    ,(SELECT PaymentMethod FROM PaymentMethods pm1 WHERE pm1.PaymentMethodId=MO.PaymentMethodId) AS PaymentMethod  
    ,(SELECT PaymentStatus FROM PaymentStatus ps WHERE ps.PaymentStatusId=MO.PaymentStatusId) AS PaymentStatus  
    ,AdminComment   
    ,UserComment   
    ,OrderDate   
    ,ExpiryDate  
    ,BankName   
    ,ChequeNo   
    ,ChequeDate   
    ,InsertedTime   
    ,M.UpdatedTime   
    ,Fax  
    ,WebsiteAddress  
    ,Address2  
    ,MT.MembershipType   
    FROM Members M  
    INNER JOIN MembershipTypes MT ON MT.MembershipTypeId=M.MembershipTypeId   
    LEFT JOIN MembershipOrders MO ON MO.MemberId=M.MemberId LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId    
    WHERE M.MemberId <> 0 AND M.IsApproved = 1 and  MO.PaymentStatusId=1 '  
	
    
  IF(@Search <> '')  
   BEGIN  
    SET @Query = @Query + ' AND (M.Memberskils LIKE ''%' + @Search + '%'' OR M.FirstName LIKE ''%' + @Search + '%'' OR M.LastName LIKE ''%' + @Search + '%'' OR  M.Email LIKE ''%' + @Search + '%'' OR  M.MobilePhone LIKE ''%' + @Search + '%'')'  
   END  
  
  IF(@MembershipTypeId<> 0)  
   BEGIN  
    SET @Query= @Query + ' AND M.MembershipTypeId = ' + CAST(@MembershipTypeId as nvarchar(50))  
   END  
  
  IF(@Sort <> '')  
   BEGIN  
    SET @Query = @Query + ' ORDER BY ' + @Sort  
   END  
  
  EXEC sp_ExecuteSQL @Query;  
    
  SELECT @Total = COUNT(Rid) from #temp   
      
  SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End  
   
  DROP TABLE #temp  
  
 --END TRY  
      
    --BEGIN CATCH    
    --   SELECT @Total = -1;        
    --END CATCH     
END  
  
  
  
  
  
  
  
  
  
  
  

