			  SELECT @QStatus = 1;	
			--ELSE IF(@MembershipType = 'Annual Family')
			--BEGIn

			--	Select @MemberIdString = (Select Top(1) SpouseCell From Members Where MembershipTypeId = @MembershipTypeId Order By SpouseCell DESC) 

			--	Select @MemberCount = Cast(REPLACE(@MemberIdString, CAST(year(GetDate()) as nvarchar(64))+'-', '') as bigint)
