		END	
		ELSE BEGIN
		
			UPDATE Members
			   SET 
				     ChapterId                      =       @ChapterId,
				     Title						=		    @Title,
					 Email							=		@Email ,
					 Password						=		@Password ,
					 FirstName						=		@FirstName ,
