CREATE PROCEDURE [dbo].[FENewsGetListByVariable]
	 (@Search nvarchar(126)
	 ,@NewsId bigint
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output
	 ,@ChapterId bigint) 
AS
BEGIN

	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,NewsId bigint
				,Title nvarchar(256)
				,NewsText nvarchar(max)
				,ImageUrl nvarchar(256)
				,PostDate datetime
				,OrderNo int
				,IsActive bit
				,UpdatedBy nvarchar(64)
				,UpdatedTime datetime)
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             E.NewsId
	            ,E.Title
	            ,E.NewsText
	            ,E.ImageUrl
	            ,E.PostDate
	            ,E.OrderNo
	            ,E.IsActive
	            ,E.UpdatedBy
	            ,E.UpdatedTime	             
	            FROM News E
		WHERE E.NewsId <> 0 AND E.IsActive=1'
		
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  E.Title LIKE ''%' + @Search + '%'''
		END

		IF(@NewsId<>0)
		BEGIN
			SET @Query=@Query + ' AND E.NewsId = ' + CAST(@NewsId as nvarchar(50))
		END

		IF(@ChapterId<>0)
		BEGIN
			SET @Query=@Query + ' AND E.ChapterId = ' + CAST(@ChapterId as nvarchar(50))
		END

		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END







































