CREATE PROCEDURE [dbo].[FEPastCommitteesGetList] 
	(@Type nvarchar(128)
	,@Year nvarchar(256)
	,@ChapterId bigint
    ,@QStatus int OUTPUT)    
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
   SET NOCOUNT ON;

    -- Insert statements for procedure here

   Declare @CID bigint 

   
   BEGIN TRY   

			   SELECT Distinct  C.MemberId
				,(C.FirstName + ' ' + C.LastName) As Name
				,C.MobilePhone
				,C.Address
				,C.City
				,C.State
				,C.Email
				,C.ProfileImage
				,CM.DisplayOrder
				,C.IsApproved
				,C.Occupation
				,CC.UpdatedBy
				,CC.UpdatedTime
				,CC.CategoryName
				,CC.CommitteeCategoryId
				,CC.Type	
				,CM.Designation			
			  ,CC.* FROM  Members C
			  INNER JOIN CommitteeMembers CM ON CM.MemberId = C.MemberId
			  INNER JOIN CommitteeCategories CC ON CC.CommitteeCategoryId= CM.CommitteeCategoryId
			  INNER JOIN ChapterCommittees CO ON CO.CommitteeCategoryId= CM.CommitteeCategoryId
			  WHERE dbo.RemoveSpecialChar(CC.Type, '^a-z0-9') = dbo.RemoveSpecialChar('Past Leadership', '^a-z0-9') AND C.IsApproved=1 
			  AND CM.ChapterId = 1 AND CC.Year = 2020 ORDER BY CM.DisplayOrder ASC

			 
			Select CC.*, 
			(Select COUNT(*) From CommitteeMembers CM Where CM.CommitteeCategoryId = CC.CommitteeCategoryId) as CommitteeCount 
			From CommitteeCategories CC
			Inner Join ChapterCommittees CO ON CO.CommitteeCategoryId = CC.CommitteeCategoryId
			Where dbo.RemoveSpecialChar(CC.Type, '^a-z0-9') = dbo.RemoveSpecialChar('Past Leadership', '^a-z0-9')
			AND CC.Year = @Year AND CO.ChapterId = @ChapterId ORDER BY DisplayOrder ASC
			 


			SELECT @QStatus = 1;
    END TRY
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH	
	 
END










