             ,E.Title  
             ,E.BannerUrl  
             ,E.DocumentUrl  
             ,E.OrderNo  
             ,E.IsActive  
    ,E.Field1  
    ,E.Field2  
    ,E.Field3  
       ,E.InsertedBy  
             ,E.InsertedTime  
             ,E.UpdatedBy  
             ,E.UpdatedTime  
    ,C.ChapterName  
              FROM PatrikaRegistrations E  
     Left JOIN Chapters C ON C.ChapterId = E.ChapterId  
  WHERE E.PatrikaId <> 0 AND E.IsActive = 1'  
    
  IF(@Type <> '')  
