  SET @Query=@Query + 'AND E.Title LIKE ''%' + CAST(@Year AS nvarchar(30)) + '%'''  
       
  END    
  
  IF(@Search <> '')  
  BEGIN  
   SET @Query = @Query + ' AND  E.Title LIKE ''%' + @Search + '%'''  
  END  
  
  IF(@Sort <> '')  
  BEGIN  
   SET @Query = @Query + ' ORDER BY E.OrderNo DESC'   
  END  
   
  EXEC sp_ExecuteSQL @Query;  
    
  SELECT @Total = COUNT(Rid) from #temp   
      
  SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End  
   
  DROP TABLE #temp  
  
 END TRY  
      
    BEGIN CATCH    
       SELECT @Total = -1;        
    END CATCH     
