CREATE PROCEDURE [dbo].[FETOP4GetVideosList]	
	 (@QStatus int output,
	 @Year nvarchar(256),
	 @ChapterId bigint)
     
AS
Begin

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
	SET NOCOUNT ON;
	DECLARE @Query NVARCHAR(max);
	
	BEGIN TRY
		 
		
		
		/*====================================================================*/
		/*				          Photos List                     			  */
		/*====================================================================*/			
		IF(@Year <> '0')
		BEGIN
		select V.VideoId,
       V.VideoCategoryId,
       V.Heading,
	   V.VideoUrl,
	   V.VideoDescription,
	   V.DisplayOrder,
	   V.IsHome,
	   V.IsActive,	   
	   V.UpdatedBy,
	   V.UpdatedTime	   
	 from (
     select V.VideoId,
		   V.VideoCategoryId,
		   V.Heading,
		   V.VideoUrl,
		   V.VideoDescription,
		   V.DisplayOrder,
		   V.IsHome,
		   V.IsActive,		  
		   V.UpdatedBy,
		   V.UpdatedTime,		   
            row_number() over(partition by V.VideoCategoryId order by V.UpdatedTime desc) as rn
     from dbo.Videos as V
     ) as V
     where V.rn <= 2 AND V.IsActive = 1 AND V.VideoCategoryId IN (SELECT VideoCategoryId FROM VideoCategories WHERE Year = @Year);
	 END
	 ELSE
	 BEGIN
	 select V.VideoId,
       V.VideoCategoryId,
       V.Heading,
	   V.VideoUrl,
	   V.VideoDescription,
	   V.DisplayOrder,
	   V.IsHome,
	   V.IsActive,	   
	   V.UpdatedBy,
	   V.UpdatedTime	   
	 from (
     select V.VideoId,
		   V.VideoCategoryId,
		   V.Heading,
		   V.VideoUrl,
		   V.VideoDescription,
		   V.DisplayOrder,
		   V.IsHome,
		   V.IsActive,		  
		   V.UpdatedBy,
		   V.UpdatedTime,		   
            row_number() over(partition by V.VideoCategoryId order by V.UpdatedTime desc) as rn
     from dbo.Videos as V
     ) as V
     where V.rn <= 2 AND V.IsActive = 1 AND V.VideoCategoryId IN (SELECT VideoCategoryId FROM VideoCategories);
	 END

		/*====================================================================*/
		/*				          Photo Categories List                  	  */
		/*====================================================================*/
		IF(@Year <> '0')
		BEGIN
		SELECT *,(SELECT COUNT(*) FROM Videos PC WHERE P.VideoCategoryId=PC.VideoCategoryId AND PC.IsActive=1) AS VideosCount FROM VideoCategories P
		WHERE P.ChapterId= @ChapterId AND P.Year = @Year And (SELECT COUNT(*) FROM Videos PC WHERE P.VideoCategoryId=PC.VideoCategoryId AND PC.IsActive=1) <> 0 ORDER BY  P.Year DESC		
		END
		ELSE
		BEGIN
		SELECT *,(SELECT COUNT(*) FROM Videos PC WHERE P.VideoCategoryId=PC.VideoCategoryId AND PC.IsActive=1) AS VideosCount FROM VideoCategories P
		WHERE P.ChapterId= @ChapterId And (SELECT COUNT(*) FROM Videos PC WHERE P.VideoCategoryId=PC.VideoCategoryId AND PC.IsActive=1) <> 0 ORDER BY  P.Year DESC		
		END


		SELECT @QStatus = 1;
				
	END TRY
    
    BEGIN CATCH  
       SELECT @QStatus = -1;
    END CATCH 
END









