CREATE PROCEDURE [dbo].[FEVolunteerInsert]
    (@VolunteerId bigint 
	,@VolunteerCategoryId bigint
	,@EventId bigint
	,@FirstName nvarchar(128)
	,@LastName nvarchar(128)
	,@Email nvarchar(128)
	,@PhoneNo nvarchar(20)
	,@Address nvarchar(1024)
	,@Comments nvarchar(2048)
	,@HoursSpent nvarchar(256)
	,@Field1 nvarchar(512)
	,@Field2 nvarchar(256)
	,@IsActive bit
	,@InsertedBy nvarchar(30)
	,@InsertedDate datetime
	,@UpdatedBy nvarchar(30)
	,@UpdatedDate datetime
	,@MemberId bigint
	,@Country nvarchar(512)
	,@QStatus int output
    ,@City nvarchar(512)
    ,@State nvarchar(512)
    ,@ZipCode nvarchar(512)
    ,@Address2 nvarchar(max)
    ,@ChapterId bigint
	,@SelfCity nvarchar(512)
	,@SelfDistrict nvarchar(512)
	,@SelfPhoneNo nvarchar(512)
	,@SelfName nvarchar(512)
	,@SelfRelation nvarchar(512)
	,@VolunteerCategories nvarchar(max))  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;

    BEGIN TRY
    BEGIN TRANSACTION

    
		IF((SELECT COUNT(*) FROM Volunteers WHERE Email = @Email) = 0)
			BEGIN
				INSERT INTO Volunteers VALUES
					   (@VolunteerCategoryId
						,null
						,@FirstName
						,@LastName 
						,@Email
						,@PhoneNo 
						,@Address 
						,@Comments
						,@HoursSpent
						,@Field1
						,@Field2 
						,@IsActive 
						,@InsertedBy 
						,@InsertedDate 
						,@UpdatedBy
						,@UpdatedDate
						,@MemberId 
						,@Country 
						,@City 
						,@State 
						,@ZipCode 
						,@Address2 
						,@ChapterId )
						SELECT @QStatus = 1;

						Set @VolunteerId = Scope_Identity()
					  
			END
		ELSE
			BEGIN
				Update Volunteers Set 
					FirstName		= @FirstName,
					LastName		= @LastName,
					Email			= @Email,
					PhoneNo			= @PhoneNo,
					Address			= @Address,
					Comments		= @Comments,
					HoursSpent		= @HoursSpent,
					Field1			= @Field1,
					Filed2			= @Field2,
					IsActive		= @IsActive,
					UpdatedBy		= @UpdatedBy,
					UpdatedDate		= @UpdatedDate,
					MemberId		= @MemberId,
					Country			= @Country,
					City			= @City,
					State			= @State,
					ZipCode			= @ZipCode,
					Address2		= @Address2,
					ChapterId		= @ChapterId
			  Where Email			= @Email

				Select Top(1) @VolunteerId = VolunteerId From Volunteers Where Email = @Email
			END
		 

		 --If(@VolunteerCategories <> '')
		 --BEGIN
			--Delete VolunteerIntrests Where VolunteerId = @VolunteerId

			--Insert into VolunteerIntrests 
			--Select @VolunteerId, part, null from SplitString(@VolunteerCategories)
		 --END
		  
		  IF(@EventId <> 0)
			  BEGIN
			  Insert into EventVolunteers
			  Select @EventId,
					 @VolunteerId,
					 @MemberId
 
			  SELECT @QStatus = 3;	
			  END

		 SELECT @QStatus = 1;
		 
		COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH  
    
		ROLLBACK TRANSACTION   
		SELECT @QStatus = -1;    
		
    END CATCH   
    
END




















