CREATE PROCEDURE [dbo].[FEVolunteersGetListByVariableBKPLIST]  
  (@VolunteerCategoryId bigint    
  ,@EventId bigint    
   ,@Email nvarchar(128)    
  ,@PageNo int    
     ,@Items int    
     ,@Search nvarchar(126)    
     ,@Total int output    
     ,@Sort nvarchar(126))    
AS    
BEGIN    
    
			 -- SET NOCOUNT ON added to prevent extra result sets from    
			 SET NOCOUNT ON;    
     
			 DECLARE @Start int, @End INT ;    
			 DECLARE @Query nvarchar(max);    
        
				CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)    
				,VolunteerId bigint    
				,VolunteerCategoryId bigint    
				,EventId bigint    
				,FirstName nvarchar(128)    
				,LastName nvarchar(128)      
				,Email nvarchar(128)    
				,HoursSpent nvarchar(256)     
				,PhoneNo nvarchar(20)    
				,Address nvarchar(1024)    
				,IsActive bit        
				,UpdatedBy nvarchar(64)    
				,UpdatedDate datetime    
			    ,CategoryName nvarchar(256))    
     
			 SELECT @Start = (@PageNo - 1) * @Items         
			 SELECT @End = @Start + @Items     
     
			 SET @Query = 'INSERT INTO #temp     
			   SELECT  V.VolunteerId     
				,V.VolunteerCategoryId    
				,V.EventId    
				,V.FirstName    
				,V.LastName    
				,V.Email     
				,V.HoursSpent    
				,V.PhoneNo      
				,V.Address      
				,V.IsActive      
				,V.UpdatedBy    
				,V.UpdatedDate    
			    ,VC.CategoryName  
			    FROM Volunteers V     
			    LEFT JOIN VolunteerCategories VC ON VC.VolunteerCategoryId=V.VolunteerCategoryId   
			    LEFT Join EventVolunteers EV ON EV.VolunteerId = V.VolunteerId    
			    WHERE V.VolunteerId <> 0' 
  

			 IF(@Search <> '')
				BEGIN
				 SET @Query = @Query + ' AND  V.FirstName LIKE ''%' + @Search + '%'' OR V.LastName LIKE ''%' + @Search + '%'''
				END
	
			 IF(@VolunteerCategoryId <> 0)    
				BEGIN    
			  SET @Query = @Query + ' AND V.VolunteerCategoryId= '+CAST(@VolunteerCategoryId as nvarchar(250))    
				END    
    
			 IF(@EventId <> 0)    
				BEGIN    
			      SET @Query = @Query + ' AND EV.EventId= '+CAST(@EventId as nvarchar(250))    
				END    
    
			 IF(@Sort <> '')    
				 BEGIN    
				    SET @Query = @Query + ' ORDER BY ' + @Sort    
				 END    
     
		     EXEC sp_ExecuteSQL @Query;    
     
			 SELECT @Total = COUNT(Rid) from #temp     
       
			 SELECT *  FROM #temp WHERE Rid > @Start AND  Rid <= @End    
     
			 DROP TABLE #temp    
    
END    


