CREATE PROCEDURE [dbo].[FEVolunteersList]
      @MemberId bigint
	 ,@QStatus int output
     
AS
BEGIN
	
	SET NOCOUNT ON;
	DECLARE @Query NVARCHAR(max);
	
	BEGIN TRY	 
		SELECT *,(Select EventName from Events E Where E.EventId = V.EventId) As EventName 
		,(Select StartDate from Events E Where E.EventId = V.EventId) As StartDate 
		,(Select CategoryName from VolunteerCategories VC Where VC.VolunteerCategoryId = V.VolunteerCategoryId) As CategoryName FROM Volunteers V WHERE MemberId =@MemberId  ORDER BY  V.UpdatedDate DESC	
		 
		SELECT @QStatus = 1;
	END TRY
    
    BEGIN CATCH  
       SELECT @QStatus = -1;
    END CATCH 
END







