/****** Object:  StoredProcedure [dbo].[Form1ExportToExcel]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Form1ExportToExcel]
	 (@Search nvarchar(126)
	 ,@Sort nvarchar(216)
	 ,@EventId bigint 
	 ,@RegistrationCategoryId bigint 
	 ,@MemberId bigint
	 ,@PaymentMethodId bigint 
	 ,@PaymentStatusId bigint 
	 ,@Total int OUTPUT )
        
AS
BEGIN

	BEGIN TRY 
	
			SET NOCOUNT ON;
			
			DECLARE @Start int, @End INT ;
			DECLARE @Query nvarchar(max);
		
			SET @Query = 'SELECT F.CompetitionRegistrationId AS [Competition RegistrationId]
				,F.EventId AS [Event Id]
		        ,RC.CategoryName As [Category Name]
				,E.EventName As [Event Name]	 
				,F.FirstName AS [Player First Name]
				,F.LastName  AS [Player Last Name]
				,F.DateofBirth AS [Date of Birth] 
				,F.GradeinSchool AS [Gender]  
				,F.SchoolName  AS [Class Attending]
				,F.ContactFullName AS [Parent Name] 
				,F.ContactPhone AS [Contact Phone]
				,F.ContactEmail AS [Contact Email]  
				,PM.PaymentMethod AS [Payment Method]
	            ,PS.PaymentStatus AS [Payment Status] 
				,F.PaymentDate AS [Payment Date]
				,F.TransactionId AS [Transaction Id] 
				,F.AmountPaid AS [Amount Paid] 
				,F.UpdatedBy AS [Updated By]
				,F.UpdatedDate AS [Updated Date] 
				FROM Form1 F
				INNER JOIN RegistrationCategories RC ON RC.RegistrationCategoryId = F.RegistrationCategoryId
				LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=F.PaymentMethodId
				LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=F.PaymentStatusId
				INNER JOIN Events E ON E.EventId=F.EventId  	
				WHERE F.CompetitionRegistrationId <> 0'
			 
		IF(@EventId<>0)
		BEGIN
			SET @Query=@Query + ' AND F.EventId = ' + CAST(@EventId as nvarchar(50))
		END

		IF(@RegistrationCategoryId<>0)
		BEGIN
			SET @Query=@Query + ' AND F.RegistrationCategoryId = ' + CAST(@RegistrationCategoryId as nvarchar(50))
		END

		IF(@MemberId<>0)
		BEGIN
			SET @Query=@Query + ' AND F.MemberId = ' + CAST(@MemberId as nvarchar(50))
		END

		IF(@PaymentStatusId<>0)
		BEGIN
			SET @Query=@Query + ' AND F.PaymentStatusId = ' + CAST(@PaymentStatusId as nvarchar(50))
		END

		IF(@PaymentMethodId<>0)
		BEGIN
			SET @Query=@Query + ' AND F.PaymentMethodId = ' + CAST(@PaymentMethodId as nvarchar(50))
		END	
			 			
		IF(@Search <> '')	
		BEGIN
			SET @Query = @Query + ' AND  (F.FirstName LIKE ''%' + @Search + '%'' OR F.ContactEmail LIKE ''%' + @Search  + '%'')' 
		END
		
		EXEC sp_ExecuteSQL @Query;
		SELECT @Total = 1;
			
    END TRY
    BEGIN CATCH
		 SELECT @Total = -1;
    END CATCH
	 
END
















