CREATE PROCEDURE [dbo].[Form1GetListByVariable]
	 (@EventId bigint 
	 ,@RegistrationCategoryId bigint 
	 ,@PaymentMethodId bigint 
	 ,@PaymentStatusId bigint 
	 ,@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,CompetitionRegistrationId bigint
				,EventId bigint
				,RegistrationCategoryId bigint
				,MemberId bigint
				,FirstName nvarchar(512)
				,LastName nvarchar(512)
				,DateofBirth datetime
				,GradeinSchool nvarchar(512)
				,SchoolName nvarchar(512)
				,ContactFullName nvarchar(512)
				,ContactPhone nvarchar(512)
				,ContactEmail nvarchar(512)
				,Notes nvarchar(max)
				,TermsandConditions bit
				,IsApproved bit
				,ApprovedDate datetime
				,PaymentStatusId bigint
				,PaymentMethodId bigint
				,PaymentDate datetime
				,TransactionId nvarchar(256)
				,AmountPaid decimal(15,2)
				,BankName nvarchar(256)
				,ChequeNo nvarchar(256)
				,ChequeDate datetime
				,AdminComments nvarchar(512)
				,Field1 nvarchar(512)
				,Field2 nvarchar(512) 
				,Field3 nvarchar(512)
				,InstertedBy nvarchar(512)
				,InsertedDate datetime
				,UpdatedBy nvarchar(512)
				,UpdatedDate datetime
				,PaymentStatus nvarchar(512)
				,PaymentMethod nvarchar(512)
				,CategoryName nvarchar(512)
				,EventName nvarchar(512))

				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
		 SELECT  F.CompetitionRegistrationId 
				,F.EventId 
				,F.RegistrationCategoryId 
				,F.MemberId 
				,F.FirstName 
				,F.LastName 
				,F.DateofBirth 
				,F.GradeinSchool 
				,F.SchoolName 
				,F.ContactFullName 
				,F.ContactPhone 
				,F.ContactEmail 
				,F.Notes 
				,F.TermsandConditions 
				,F.IsApproved 
				,F.ApprovedDate 
				,F.PaymentStatusId 
				,F.PaymentMethodId 
				,F.PaymentDate 
				,F.TransactionId 
				,F.AmountPaid 
				,F.BankName 
				,F.ChequeNo 
				,F.ChequeDate 
				,F.AdminComments 
				,F.Field1 
				,F.Field2  
				,F.Field3 
				,F.InstertedBy 
				,F.InsertedDate 
				,F.UpdatedBy 
				,F.UpdatedDate 
				,(SELECT PaymentStatus FROM PaymentStatus ps WHERE ps.PaymentStatusId=F.PaymentStatusId) AS PaymentStatus
				,(SELECT PaymentMethod FROM PaymentMethods pm1 WHERE pm1.PaymentMethodId=F.PaymentMethodId) AS PaymentMethod
				,(SELECT CategoryName FROM RegistrationCategories RC WHERE Rc.RegistrationCategoryId=F.RegistrationCategoryId) AS CategoryName
				,(SELECT EventName FROM Events E WHERE E.EventId=F.EventId) AS EventName
				FROM Form1 F
				INNER JOIN  RegistrationCategories RC ON RC.RegistrationCategoryId=F.RegistrationCategoryId  		
				WHERE F.CompetitionRegistrationId <> 0'
		
		IF(@EventId<>0)
			BEGIN
				SET @Query=@Query + ' AND F.EventId = ' + CAST(@EventId as nvarchar(50))
			END
		IF(@RegistrationCategoryId<>0)
			BEGIN
				SET @Query=@Query + ' AND F.RegistrationCategoryId = ' + CAST(@RegistrationCategoryId as nvarchar(50))
			END

		IF(@PaymentStatusId<>0)
			BEGIN
				SET @Query=@Query + ' AND F.PaymentStatusId = ' + CAST(@PaymentStatusId as nvarchar(50))
			END

		IF(@PaymentMethodId<>0)
			BEGIN
				SET @Query=@Query + ' AND F.PaymentMethodId = ' + CAST(@PaymentMethodId as nvarchar(50))
			END
	
		IF(@Search <> '')
			BEGIN
				SET @Query = @Query + ' AND  F.FirstName LIKE ''%' + @Search + '%'' OR F.ContactEmail LIKE ''%' + @Search  + '%'' OR F.ContactPhone LIKE ''%' + @Search  + '%'''
			END


		IF(@Sort <> '')
			BEGIN
				SET @Query = @Query + ' ORDER BY ' + @Sort
			END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END



































