CREATE PROCEDURE [dbo].[Form1Insert]
    (@CompetitionRegistrationId bigint
    ,@EventId bigint
	,@RegistrationCategoryId bigint
	,@MemberId bigint
	,@FirstName nvarchar(512)
	,@LastName nvarchar(512)
	,@DateofBirth datetime
	,@GradeinSchool nvarchar(512)
	,@SchoolName nvarchar(512)
	,@ContactFullName nvarchar(512)
	,@ContactPhone nvarchar(512)
	,@ContactEmail nvarchar(512)
	,@Notes nvarchar(max)
	,@TermsandConditions bit
	,@IsApproved bit
	,@ApprovedDate datetime
	,@PaymentStatusId bigint
	,@PaymentMethodId bigint
	,@PaymentDate datetime
	,@TransactionId nvarchar(256)
	,@AmountPaid decimal(15,2)
	,@BankName nvarchar(256)
	,@ChequeNo nvarchar(256)
	,@ChequeDate datetime
	,@AdminComments nvarchar(512)
	,@Field1 nvarchar(512)
	,@Field2 nvarchar(512) 
	,@Field3 nvarchar(512)
	,@InstertedBy nvarchar(512)
	,@InsertedDate datetime
	,@UpdatedBy nvarchar(512)
	,@UpdatedDate datetime
	,@QStatus int output)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;

    BEGIN TRY
    BEGIN TRANSACTION
			IF((SELECT COUNT(*) FROM Form1 WHERE CompetitionRegistrationId = @CompetitionRegistrationId) = 0)
				BEGIN
					INSERT INTO Form1 VALUES
						(@EventId 
						,@RegistrationCategoryId
						,@MemberId
						,@FirstName 
						,@LastName
						,@DateofBirth
						,@GradeinSchool
						,@SchoolName
						,@ContactFullName
						,@ContactPhone
						,@ContactEmail
						,@Notes
						,@TermsandConditions
						,@IsApproved
						,@ApprovedDate
						,@PaymentStatusId
						,@PaymentMethodId
						,@PaymentDate
						,@TransactionId
						,@AmountPaid 
						,@BankName
						,@ChequeNo
						,@ChequeDate
						,@AdminComments
						,@Field1
						,@Field2  
						,@Field3  
						,@InstertedBy 
						,@InsertedDate 
						,@UpdatedBy 
						,@UpdatedDate)		
					SET @CompetitionRegistrationId = SCOPE_IDENTITY()	
					SELECT @QStatus = 1;	
				END
			ELSE
				BEGIN
					UPDATE Form1
					   SET EventId					=	@EventId, 
						   RegistrationCategoryId	=	@RegistrationCategoryId,
						   MemberId					=	@MemberId,
						   FirstName				=	@FirstName,
						   LastName					=	@LastName,
						   DateofBirth				=	@DateofBirth,
						   GradeinSchool			=	@GradeinSchool,
						   SchoolName				=	@SchoolName,
						   ContactFullName			=	@ContactFullName,
						   ContactPhone				=	@ContactPhone,
						   ContactEmail				=	@ContactEmail,
						   Notes					=	@Notes,
						   TermsandConditions		=	@TermsandConditions,
						   ApprovedDate				=	@ApprovedDate,
						   PaymentStatusId			=	@PaymentStatusId,
						   PaymentMethodId			=	@PaymentMethodId,
						   PaymentDate				=	@PaymentDate,
						   TransactionId			=	@TransactionId,
						   AmountPaid				=	@AmountPaid, 
						   BankName					=	@BankName,
						   ChequeNo					=	@ChequeNo,
						   ChequeDate				=	@ChequeDate,
						   AdminComments			=	@AdminComments,
						   Field1					=	@Field1,  
						   Field2					=	@Field2, 
						   Field3					=	@Field3,
						   InstertedBy				=	@InstertedBy,
						   InsertedDate				=	@InsertedDate,
						   UpdatedBy				=	@UpdatedBy,
						   UpdatedDate				=	@UpdatedDate 
					 WHERE CompetitionRegistrationId =  @CompetitionRegistrationId
		 		 
					 SELECT @QStatus = 2;	
		      END
      COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH    
    ROLLBACK TRANSACTION
		SELECT @QStatus = -1;    
    END CATCH    
END


































