CREATE PROCEDURE [dbo].[Form1UpdateStatus]
    (@CompetitionRegistrationId bigint
    ,@QStatus int output)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY    
    BEGIN TRANSACTION
    
		IF((SELECT IsApproved FROM Form1 WHERE CompetitionRegistrationId = @CompetitionRegistrationId) = 1)
			BEGIN
				UPDATE Form1 SET IsApproved = 0 WHERE CompetitionRegistrationId = @CompetitionRegistrationId
			END
		ELSE
			BEGIN
				UPDATE Form1 SET IsApproved = 1 WHERE CompetitionRegistrationId = @CompetitionRegistrationId
			END		
		
		SELECT @QStatus = 1;
		
	COMMIT TRANSACTION
    END TRY

    BEGIN CATCH
         ROLLBACK TRANSACTION
		 SELECT @QStatus = -1;
    END CATCH
    	
END



































