/****** Object:  StoredProcedure [dbo].[GetAPINewsListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[GetAPINewsListByVariable]
	 (@ChapterId bigint
	 ,@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output
	 ,@MemberId bigint)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,NewsId bigint
				,Title nvarchar(256)
				,NewsText nvarchar(max)
				,ImageUrl nvarchar(256)
				,PostDate datetime
				,OrderNo int
				,IsActive bit
				,UpdatedBy nvarchar(64)
				,UpdatedTime datetime
				,ChapterId bigint)
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             E.NewsId
	            ,E.Title
	            ,E.NewsText
	            ,E.ImageUrl
	            ,E.PostDate
	            ,E.OrderNo
	            ,E.IsActive
	            ,E.UpdatedBy
	            ,E.UpdatedTime
				,E.ChapterId
	            FROM News E 
				Inner Join ChapterNews CN ON CN.NewsId = E.NewsId
				WHERE E.NewsId <> 0
				and IsActive=1 AND E.UpdatedBy <> ''Blog''' 

	
		
	IF(@ChapterId <> 0 AND @ChapterId <> 1) 
			BEGIN
			IF((Select Count(*) FROM News N Inner Join ChapterNews CN ON CN.NewsId = N.NewsId WHERE N.IsActive=1 AND CN.ChapterId = @ChapterId) <> 0)
			    BEGIN
				  SET @Query=@Query + ' AND CN.ChapterId = ' + CAST(@ChapterId as nvarchar(50))
				END
			ELSE 
			    BEGIN
				   SET @Query=@Query + ' AND CN.ChapterId = ' + CAST(1 as nvarchar(50))
				END
			END
			 
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  E.Title LIKE ''%' + @Search + '%'''
		END
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY E.PostDate DESC'
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END












