/****** Object:  StoredProcedure [dbo].[GetBreadCrumbListByUrl]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[GetBreadCrumbListByUrl]
	 (@PageUrl nvarchar(512)   
     ,@QStatus int output)
AS
BEGIN

	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Query nvarchar(max);
	Declare @PageDetailId bigint
	Declare @MenuItemId bigint

	IF((@PageUrl = 'nats-helpline') OR (@PageUrl Like '%news%') OR (@PageUrl = 'nats-global/aksharadeepika'))
		BEGIN
			SELECT @MenuItemId =(Select Top(1) MenuItemId from MenuPages Where PageDetailId = (select PageDetailId from PageDetails Where OtherUrl = @PageUrl))
		END
	ELSE
		BEGIN
			SELECT @MenuItemId =(Select MenuItemId from MenuPages Where PageDetailId = (select PageDetailId from PageDetails Where OtherUrl = @PageUrl))
		END

	Select 
	M.DisplayName,
	(Select DisplayName From MenuItems Where MenuItemId = M.PageParentId) as ParentName,
	M.PageParentId,
	(Select isnull(Case When OtherUrl = '' then NULL else OtherUrl end,PageUrl) From PageDetails P Inner Join MenuPages MP ON MP.PageDetailId = P.PageDetailId Where MP.MenuItemId = M.PageParentId) as ParentUrl,
	M.MenuItemId
	From MenuItems M
	Where MenuItemId = @MenuItemId

	 
	SELECT @QStatus = 1; 
		
	END TRY    
    BEGIN CATCH  
       SELECT @QStatus = -1; 		   
    END CATCH   
END









