GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[GetEventCommitteeByChapterId]
	(@ChapterId bigint
    ,@QStatus int OUTPUT)    
        
AS
BEGIN
	
   SET NOCOUNT ON;

    BEGIN TRY 
	          Select 
	          (SELECT CAST((SELECT Top(1) CAST(Email as nvarchar(80))
	          FROM  Members C
			  INNER JOIN CommitteeMembers CM ON CM.MemberId = C.MemberId
			  INNER JOIN CommitteeCategories CC ON CC.CommitteeCategoryId= CM.CommitteeCategoryId
			  INNER JOIN ChapterCommittees CO ON CO.CommitteeCategoryId= CM.CommitteeCategoryId
			  WHERE dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') <> dbo.RemoveSpecialChar('Leadership', '^a-z0-9')   
			  and (dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') = dbo.RemoveSpecialChar('Secretary', '^a-z0-9') or dbo.RemoveSpecialChar(CC.CategoryName, '^a-z0-9') = dbo.RemoveSpecialChar('National Coordinators', '^a-z0-9'))  
			  AND CC.IsActive=1 
			  AND CM.ChapterId = 1 ORDER BY CM.DisplayOrder ASC FOR XML PATH('')) AS NVARCHAR(max))) As SecretaryEmail
     
		 SELECT @QStatus = 1;
    END TRY
    
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH	
	 
END











































