/****** Object:  StoredProcedure [dbo].[GetMemberSubscriptionByEmail]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- ✅ Find subscription by Member Email
CREATE PROCEDURE [dbo].[GetMemberSubscriptionByEmail]
    @Email   NVARCHAR(256),
    @QStatus INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    -- ✅ Join MemberSubscriptions with Members to find by email
    SELECT TOP 1
        ms.MemberId,
        ms.SubscriotionId,
        ms.ProfileId,
        ms.PaymentProfileId,
        ms.RecurringType,
        ms.RecurringAmount,
        ms.RecurringStartTime
    FROM [dbo].[MemberSubscriptions] ms
    INNER JOIN [dbo].[Members] m ON m.MemberId = ms.MemberId
    WHERE m.Email = @Email
    AND ms.SubscriotionId IS NOT NULL    -- ✅ only active subscriptions
    ORDER BY ms.DonorSubscriotionId DESC -- ✅ latest subscription

    SET @QStatus = @@ROWCOUNT
END
GO
/****** Object:  StoredProcedure [dbo].[GetMemberSubscriptionByProfileId]    Script Date: 6/16/2026 1:20:33 PM ******/
