-- ✅ Find subscription by CustomerId (ProfileId)
CREATE PROCEDURE [dbo].[GetMemberSubscriptionByProfileId]
    @ProfileId  NVARCHAR(128),
    @QStatus    INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1
        MemberId,
        SubscriotionId,
        ProfileId,
        PaymentProfileId,
        RecurringType,
        RecurringAmount,
        RecurringStartTime
    FROM [dbo].[MemberSubscriptions]
    WHERE [ProfileId] = @ProfileId  -- ✅ ProfileId = Square CustomerId
    ORDER BY DonorSubscriotionId DESC

    SET @QStatus = @@ROWCOUNT
END
