CREATE PROCEDURE [dbo].[GetMemberSubscriptionBySubId]
    @SubscriptionId  NVARCHAR(128),
    @QStatus         INT OUTPUT
AS  
BEGIN  
    SET NOCOUNT ON;  

    SELECT TOP 1  
        MemberId, SubscriotionId, ProfileId,
        PaymentProfileId, RecurringType,
        RecurringAmount, RecurringStartTime  
    FROM [dbo].[MemberSubscriptions]  
    WHERE [SubscriotionId] = @SubscriptionId

    SET @QStatus = @@ROWCOUNT
END
