/****** Object:  StoredProcedure [dbo].[GetServiceDonarsListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[GetServiceDonarsListByVariable] 
    (@ServiceId BIGINT,
     @Search NVARCHAR(126), 
     @PaymentStatus BIGINT,
     @PaymentMethod BIGINT,
     @Sort NVARCHAR(126),
     @PageNo INT,
     @Items INT,
     @Total INT OUTPUT,
	 @ChapterId bigint
	 
	 )
AS
BEGIN
    SET NOCOUNT ON;

    --BEGIN TRY
        DECLARE @Start INT, @End INT;
        DECLARE @Query NVARCHAR(MAX);

        -- Creating a temporary table
        CREATE TABLE #temp (
            Rid INT PRIMARY KEY IDENTITY(1,1),
			
            Email NVARCHAR(512),
            ServiceDonationIds NVARCHAR(MAX),
            FirstName NVARCHAR(512),
            LastName NVARCHAR(512),
            PhoneNo NVARCHAR(512),
            ContributionsCount BIGINT,
            LastOrderDate DATETIME
        );

        SELECT @Start = (@PageNo - 1) * @Items;
        SELECT @End = @Start + @Items;

        SET @Query = '
            WITH RankedData AS (
                SELECT 
				   
                    K.Email,
                    D.ServiceDonationId,
                    K.FirstName,
                    K.LastName,
                    K.PhoneNo,
                    D.OrderDate,
                    ROW_NUMBER() OVER (PARTITION BY K.Email ORDER BY D.OrderDate ASC) AS MinRowNum,
                    ROW_NUMBER() OVER (PARTITION BY K.Email ORDER BY D.OrderDate DESC) AS MaxRowNum
                FROM 
                    ServiceDonations D
                LEFT JOIN 
                    ServiceDonationInfo K ON D.ServiceDonationId = K.ServiceDonationId
                WHERE 
                    D.ServiceDonationId <> 0
                    AND K.Email IS NOT NULL
                    ';

					
IF(@ChapterId<>0)
				BEGIN
					SET @Query=@Query + ' AND K.ChapterId = ' + CAST(@ChapterId as nvarchar(50))
				END



        -- Apply search filters
        IF @Search <> ''
        BEGIN
            SET @Query = @Query + ' AND (K.FirstName LIKE ''%' + @Search + '%'' 
                                    OR K.LastName LIKE ''%' + @Search + '%'' 
                                    OR K.Email LIKE ''%' + @Search + '%'' 
                                    OR CAST(D.Amount AS NVARCHAR(MAX)) LIKE ''%' + @Search + '%'' 
                                    OR D.TransactionId LIKE ''%' + @Search + '%'')';
        END

        -- Close CTE and perform grouping
        SET @Query = @Query + '
            )
            INSERT INTO #temp
            SELECT 
                R.Email,
                STRING_AGG(R.ServiceDonationId, '','') AS ServiceDonationIds,
                MIN(CASE WHEN R.MinRowNum = 1 THEN R.FirstName END) AS FirstName, -- Take FirstName from the first OrderDate
                MIN(CASE WHEN R.MinRowNum = 1 THEN R.LastName END) AS LastName,   -- Take LastName from the first OrderDate
                MIN(CASE WHEN R.MinRowNum = 1 THEN R.PhoneNo END) AS PhoneNo,     -- Take PhoneNo from the first OrderDate
                COUNT(R.ServiceDonationId) AS ContributionsCount,
                MAX(R.OrderDate) AS LastOrderDate -- Get the most recent OrderDate
            FROM 
                RankedData R
            GROUP BY 
                R.Email';

        -- Apply sorting
        IF (@Sort <> '')
        BEGIN
            SET @Query = @Query + ' ORDER BY ' + @Sort;
        END

        EXEC sp_executesql @Query;
        PRINT @Query;

        SELECT @Total = COUNT(Rid) FROM #temp;

        SELECT * 
        FROM #temp 
        WHERE Rid > @Start AND Rid <= @End;

        -- Drop the table after using it
        DROP TABLE #temp;
   -- END TRY
    --BEGIN CATCH
    --    SELECT @Total = -1;
    --    IF OBJECT_ID('tempdb..#temp') IS NOT NULL
    --    BEGIN
    --        DROP TABLE #temp;
    --    END
    --END CATCH
END;


