CREATE PROCEDURE [dbo].[HomeAPI]    
   @ChapterId bigint    
  ,@QStatus int output    
  ,@Type nvarchar(256)    
         
AS    
BEGIN    
    
 -- SET NOCOUNT ON added to prevent extra result sets from    
     
 SET NOCOUNT ON;    
     
