   /*====================================================================*/    
  /*         App Info       */    
  /*====================================================================*/    
    
  Select AP.*, (SELECT CASE WHEN IsActive = 1 THEN 'Yes' ELSE 'No' END AS chapterStatus FROM AdminMenuItems WHERE MenuItemId = (SELECT MenuItemId FROM AdminMenuItems WHERE DisplayName = 'Chapters')) as chapterStatus From AppInfo AP 
  where TollFreeNumber = @Type    
    
