--WHERE RowNum = 1 AND ChapterId = 1; -- Use ChapterId from the CTE, not PC.ChapterId



;WITH RankedPhotos AS (
    SELECT 
        P.*, 
        PC.CategoryName, 
        PC.ChapterId,
        ROW_NUMBER() OVER (PARTITION BY P.PhotoCategoryId ORDER BY P.PhotoId ASC) AS RowNum
    FROM Photos P
    JOIN PhotoCategories PC ON P.PhotoCategoryId = PC.PhotoCategoryId
),
LimitedCategories AS (
    SELECT *, ROW_NUMBER() OVER (ORDER BY PhotoCategoryId) AS CatRank
    FROM RankedPhotos
    WHERE RowNum = 1 AND ChapterId = @ChapterId
)
SELECT *
FROM LimitedCategories
WHERE CatRank <= 5;






    
  /*====================================================================*/    
  /*               Video Gallery                              */    
  /*====================================================================*/    
    
  --SELECT TOP(3) * FROM Videos V      
  --WHERE V.IsActive = 1 ORDER BY  V.UpdatedTime DESC    




  SELECT TOP(4) V.*
FROM Videos V
INNER JOIN VideoCategories VC ON V.VideoCategoryId = VC.VideoCategoryId
WHERE V.IsActive = 1
  AND VC.ChapterId = @ChapterId
ORDER BY V.UpdatedTime DESC;



/*====================================================================*/
		/*								 Chapters Info					  */
		/*====================================================================*/

		SELECT  * FROM WebsiteBanners WHERE IsActive=1 and ChapterId = @ChapterId ORDER BY Orderno ASC

  SELECT @QStatus = 1;    
        
 END TRY    
        
    BEGIN CATCH      
       SELECT @QStatus = -1;    
    END CATCH     
END    
    
    
    
    
    
    


