CREATE PROCEDURE [dbo].[InnerPageCategoriesGetByLevel]
	(@PageLevel int
    ,@QStatus int OUTPUT)    
        
AS
BEGIN
	
	SET NOCOUNT ON;

   BEGIN TRY 
		SELECT * FROM InnerPageCategories  WHERE PageLevel = @PageLevel
