    ,TransactionId nvarchar(128)  
    ,PaymentStatus nvarchar(512)  
    ,OrderDate datetime  
    ,TotalAmount decimal(15,2)  
    ,EventId bigint  
    ,RegistrationCategoryId bigint  
    ,CategoryName nvarchar(512)  
    ,EventName nvarchar(512)  
    ,CompetitionCategory1 nvarchar(512)  
    ,PaymentStatusId bigint)  
      
 SELECT @Start = (@PageNo - 1) * @Items    
      
 SELECT @End = @Start + @Items   
   
 SET @Query = 'INSERT INTO #temp SELECT   
              E.KidsRegistrationsId  
    ,E.ChapterId  
             ,E.RegestrationID  
             ,E.FirstName  
             ,E.LastName  
             ,E.EmailId  
             ,E.DOB  
    ,E.IsActive     
    ,C.ChapterName  
    ,E.TransactionId  
    ,PS.PaymentStatus  
    ,E.OrderDate  
    ,E.TotalAmount  
    ,E.EventId   
    ,E.RegistrationCategoryId   
    ,(SELECT CategoryName FROM RegistrationCategories RC WHERE Rc.RegistrationCategoryId=E.RegistrationCategoryId) AS CategoryName  
    ,(SELECT EventName FROM Events EV WHERE EV.EventId=E.EventId) AS EventName  
    ,E.CompetitionCategory1  
    ,E.PaymentStatusId  
              FROM KidsRegistrations E  
     Left JOIN Chapters C ON C.ChapterId = E.ChapterId  
     Left JOIN PaymentStatus PS ON PS.PaymentStatusId = E.PaymentStatusId  
     Left JOIN  RegistrationCategories RC ON RC.RegistrationCategoryId=E.RegistrationCategoryId      
  WHERE E.KidsRegistrationsId <> 0'  
    
  IF(@ChapterId <> 0)  
   BEGIN  
    SET @Query=@Query + 'AND E.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))  
   END    
  IF(@PaymentStatusId <> 0)  
   BEGIN  
    SET @Query=@Query + 'AND E.PaymentStatusId = ' + CAST(@PaymentStatusId AS nvarchar(30))  
   END    
  IF(@CompetitionCategory1 <> '')  
   BEGIN  
    set @CompetitionCategory1 = replace(@CompetitionCategory1, ',', ''',''')  
    SET @Query = @Query + ' AND E.CompetitionCategory1 in ('''+@CompetitionCategory1+''')'  
   END  
  IF(@EventId<>0)  
   BEGIN  
    SET @Query=@Query + ' AND E.EventId = ' + CAST(@EventId as nvarchar(50))  
   END  
  IF(@RegistrationCategoryId<>0)  
   BEGIN  
    SET @Query=@Query + ' AND E.RegistrationCategoryId = ' + CAST(@RegistrationCategoryId as nvarchar(50))  
   END  
  IF(@Search <> '')  
   BEGIN  
    SET @Query = @Query + ' AND  E.FirstName LIKE ''%' + @Search + '%'''  
   END  
  IF(@Sort <> '')  
   BEGIN  
    SET @Query = @Query + ' ORDER BY E.InsertedDate DESC'  
   END  
   
  EXEC sp_ExecuteSQL @Query;  
    
  SELECT @Total = COUNT(Rid) from #temp   
      
  SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End  
   
  DROP TABLE #temp  
END  
  
  
  
  
  
  
  

