/****** Object:  StoredProcedure [dbo].[MemberGetFullDetailsByEmail]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
          
          
CREATE PROCEDURE [dbo].[MemberGetFullDetailsByEmail]      
 (@Email nvarchar(512)          
    ,@QStatus int OUTPUT)              
                  
AS          
BEGIN          
           
   SET NOCOUNT ON;          
          
    BEGIN TRY           
    DECLARE @MemberId bigint          
  IF((SELECT COUNT(*) FROM Members WHERE Email=@Email)<>0)          
   BEGIN          
   SET @MemberId=(SELECT top(1) MemberId FROM Members WHERE Email=@Email)          
   END          
  ELSE          
   BEGIN          
   SET @MemberId=0          
   END          
          
         SELECT   M.*,          
      MT.Price AS MemberAmount,               
      MT.MembershipTypeId ,          
      (SELECT MO.ExpiryDate FROM MembershipOrders MO WHERE MO.MembershipTypeId=MT.MembershipTypeId AND M.MemberId=MO.MemberId) AS ExpiryDate,          
      MT.MembershipType,            
      (Select Count(*) from Users Where Email = @Email) AS UserCount,          
       MI.SelfCity          
      ,MI.SelfDistrict          
      ,MI.SelfPhoneNo          
      ,MI.SelfName          
      ,MI.SelfRelation          
      ,MI.SpouseCity          
      ,MI.SpouseDistrict          
      ,MI.SpousePhoneNo          
      ,MI.SpouseName          
      ,MI.SpouseRelation          
      ,MI.MBachelors          
      ,MI.MAdvanced          
      ,MI.SPouseBachelors          
      ,MI.SPouseAdvanced          
       --,MI.chapterid       
    ,CP.CHAPTERname      
 ,M.MemberSkils     
   FROM Members M           
   LEFT JOIN MembershipTypes MT ON MT.MembershipTypeId=M.MembershipTypeId          
      INNER JOIN CHAPTERS CP ON CP.chapterid=M.chapterid          
   LEFT JOIN MembersInfo MI ON MI.MemberId= M.MemberId          
   WHERE M.MemberId = @MemberId          
             
   SELECT * FROM ChildrenInfo WHERE MemberId=@MemberId          
            
   SELECT *,PM.PaymentMethod,PS.PaymentStatus,MT.MembershipType,(CASE WHEN CONVERT(DATE,MO.ExpiryDate) < CONVERT(DATE,GETDATE()) THEN 0 ELSE 1 END) AS Expiry FROM MembershipOrders MO           
        
   INNER JOIN PaymentMethods PM ON PM.PaymentMethodId=MO.PaymentMethodId           
   INNER JOIN PaymentStatus PS ON PS.PaymentStatusId=MO.PaymentStatusId           
   INNER JOIN MembershipTypes MT ON MT.MembershipTypeId=MO.MembershipTypeId WHERE MO.MemberId=@MemberId           
               SELECT   
            MS.SubscriotionId   , -- use this as subscriptionId for Square API
			  MS.Recurringtype
        FROM MemberSubscriptions MS  
        WHERE MS.MemberId = @MemberId  
        AND MS.SubscriotionId IS NOT NULL  -- ✅ skip NULL rows like row 4  
  
   SELECT @QStatus = 1;          
             
    END TRY          
              
    BEGIN CATCH          
   SELECT @QStatus = -1;          
    END CATCH           
            
END          
          
          
          
          
          
GO
/****** Object:  StoredProcedure [dbo].[MemberGetFullDetailsById]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[MemberGetFullDetailsById]   
    (@MemberId bigint,
     @QStatus int OUTPUT)      
AS  
BEGIN  
    SET NOCOUNT ON;  
    BEGIN TRY   

        -- existing query 1
        SELECT TOP(1) M.*, MT.Price AS MemberAmount, MT.MembershipTypeId,
               MT.MembershipType, C.ChapterName    
        FROM Members M 
        INNER JOIN MembershipTypes MT ON MT.MembershipTypeId = M.MembershipTypeId 
        LEFT JOIN Chapters C ON C.ChapterId = M.ChapterId  
        WHERE M.MemberId = @MemberId  

        -- existing query 2
        SELECT * FROM ChildrenInfo WHERE MemberId = @MemberId  

        -- existing query 3
        SELECT *, PM.PaymentMethod, PS.PaymentStatus, MT.MembershipType 
        FROM MembershipOrders MO 
        LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId = MO.PaymentMethodId 
        LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId = MO.PaymentStatusId 
        INNER JOIN MembershipTypes MT ON MT.MembershipTypeId = MO.MembershipTypeId 
        WHERE MO.MemberId = @MemberId  

        -- existing query 4
        SELECT * FROM MembersInfo WHERE MemberId = @MemberId  

        -- ✅ NEW: Get Subscription details by MemberId
        SELECT 
            MS.SubscriotionId    -- use this as subscriptionId for Square API
        FROM MemberSubscriptions MS
        WHERE MS.MemberId = @MemberId
        AND MS.SubscriotionId IS NOT NULL  -- ✅ skip NULL rows like row 4

        SELECT @QStatus = 1;  
    END TRY  

    BEGIN CATCH  
        SELECT @QStatus = -1;  
    END CATCH   
END
