AS
BEGIN
	
    SET NOCOUNT ON;

    BEGIN TRY 
    DECLARE @MemberId bigint

    IF((SELECT COUNT(*) FROM Members WHERE dbo.RemoveSpecialChar(MobilePhone, '^a-z0-9') = dbo.RemoveSpecialChar(@MobilePhone, '^a-z0-9'))<>0)
		BEGIN
		SET @MemberId=(SELECT top(1) MemberId FROM Members WHERE dbo.RemoveSpecialChar(MobilePhone, '^a-z0-9') = dbo.RemoveSpecialChar(@MobilePhone, '^a-z0-9'))
