create PROCEDURE [dbo].[MemberOrderInsertRenewalbkp]      
    (@MemberId bigint output      
 ,@MembershipTypeId bigint      
 ,@PaymentStatusId bigint      
 ,@PaymentMethodId bigint      
 ,@MembershipOrderId bigint      
 ,@Amount decimal(15,2)      
 ,@TransactionId nvarchar(2048)      
 ,@PaymentStatus nvarchar(2048)      
 ,@PaymentMethod nvarchar(2048)      
 ,@PaymentBy nvarchar(2048)      
 ,@AdminComment nvarchar(2048)      
 ,@UserComment nvarchar(2048)      
 ,@BankName nvarchar(2048)      
 ,@OrderType nvarchar(2048)      
 ,@ChequeNo nvarchar(2048)      
 ,@ChequeDate datetime      
 ,@OrderDate datetime      
 ,@ExpiryDate datetime      
 ,@IsVolunteer bit      
 ,@UpdatedTime datetime      
 ,@UpdatedBy nvarchar(64)    
 ,@ReceiptUrl nvarchar(max) output      
  
  
 ,@QStatus int output)        
              
AS      
BEGIN      
      
       
 SET NOCOUNT ON;      
          
    BEGIN TRY      
    BEGIN TRANSACTION      
     IF(@PaymentStatus IS NOT NULL)      
     BEGIN      
      SELECT @PaymentStatusId = PaymentStatusId FROM PaymentStatus WHERE PaymentStatus = @PaymentStatus      
      IF(@PaymentStatusId IS NULL OR @PaymentStatusId='')      
       BEGIN      
          INSERT INTO PaymentStatus VALUES(@PaymentStatus,1)      
          SELECT @PaymentStatusId  =  SCOPE_IDENTITY()      
       END      
      IF(@PaymentMethod IS NOT NULL)      
       BEGIN      
        SELECT @PaymentMethodId = PaymentMethodId FROM PaymentMethods WHERE PaymentMethod = @PaymentMethod      
       END      
     END      
      
           
     declare @ValidityMonth nvarchar(512);      
     declare @ValidityDay nvarchar(512);      
     declare @ValidityYear nvarchar(512);      
     declare @expiry nvarchar(512);      
      
     DECLARE @Active NVARCHAR(512);      
                    DECLARE @Day INT;      
     DECLARE @R1Time INT;      
                    DECLARE @R2Time INT;      
      
      
           
     SELECT @ValidityMonth = (SELECT DATEPART(MONTH, DATEADD(MONTH, 12, GETDATE())));      
     SELECT @ValidityDay = (SELECT DATEPART(DAY, DATEADD(MONTH, 12, GETDATE())));      
     SELECT @ValidityYear = (SELECT DATEPART(YEAR, DATEADD(MONTH, 12, GETDATE())));      
           
      
     SELECT @Active=(SELECT      
          CASE      
           WHEN DATEDIFF(day, GETDATE(), (SELECT CONVERT(date, Expirydate) FROM membershiporders WHERE MemberId = 177721)) > 0 THEN 'Membership Active'      
           ELSE 'Membership Expired'      
          END AS MembershipStatus)      
      
      
        PRINT @Active      
      
     IF(@Active='Membership Active')      
      BEGIN       
       SELECT @Day = (SELECT DATEDIFF(day, GETDATE(),(SELECT CONVERT(date, Expirydate) FROM membershiporders WHERE MemberId = @MemberId)) AS DaysUntilExpiry);      
      
       -- Calculate the expiration date, 61 days from today      
       DECLARE @ExpiryDate1 DATE;      
       SET @ExpiryDate1 = DATEADD(DAY, @Day, @ExpiryDate);      
      
       -- Add one year to the expiration date      
       DECLARE @NewExpiryDate DATE;      
       SET @NewExpiryDate = DATEADD(YEAR, 1, @ExpiryDate1);      
      
       -- Store the results in the variables      
       SET @R1Time = DATEDIFF(DAY, GETDATE(), @ExpiryDate1);      
       SET @R2Time = DATEDIFF(DAY, GETDATE(), @NewExpiryDate);      
      
       -- Convert @R2Time days to a date      
       DECLARE @R2Date DATE;      
       SET @R2Date = DATEADD(DAY, @R2Time, GETDATE());      
      
       -- Convert @R2Date to a specific format (dd/mm/yyyy)      
       DECLARE @R2FormattedDate VARCHAR(10);      
      
       -- Convert @R2Date to the custom format "yyyy/mm/dd"      
       SET @expiry = CONVERT(VARCHAR(4), YEAR(@R2Date)) + '-' + RIGHT('0' + CONVERT(VARCHAR(2), MONTH(@R2Date)), 2) + '-' + RIGHT('0' + CONVERT(VARCHAR(2), DAY(@R2Date)), 2);      
      END      
     Else      
      BEGIN       
         SET @expiry =  @ValidityYear + '-' + @ValidityMonth + '-' + @ValidityDay;      
                        End      
      
     IF((SELECT COUNT(*) FROM MembershipOrders WHERE MemberId = @MemberId) = 0)      
      BEGIN      
      INSERT INTO MembershipOrders VALUES      
      (@MemberId      
      ,@MembershipTypeId      
      ,@Amount      
      ,@TransactionId      
      ,@PaymentStatusId      
      ,@PaymentMethodId       
      ,@PaymentBy      
      ,@AdminComment      
      ,@UserComment      
      ,@OrderDate      
      ,(SELECT CASE WHEN (SELECT Validity FROM MembershipTypes WHERE MembershipTypeId=@MembershipTypeId) <> 0 THEN @expiry ELSE NULL END)      
      ,@BankName      
      ,@ChequeNo      
      ,@ChequeDate      
      ,@UpdatedTime      
      ,@UpdatedBy)       
     END       
    ELSE      
     BEGIN      
     UPDATE Members SET MembershipTypeId=@MembershipTypeId,IsVolunteer=@IsVolunteer WHERE MemberId = @MemberId      
    
      
     UPDATE MembershipOrders SET      
       MembershipTypeId  = @MembershipTypeId      
      ,Amount     = @Amount      
      ,TransactionId   = @TransactionId      
      ,PaymentStatusId  = @PaymentStatusId      
      ,PaymentMethodId  = @PaymentMethodId       
      ,PaymentBy    = @PaymentBy      
      ,AdminComment   = @AdminComment      
      ,UserComment   = @UserComment      
      ,OrderDate    = @OrderDate      
      ,BankName    = @BankName      
      ,ChequeNo    = @ChequeNo      
      ,ChequeDate    = @ChequeDate      
      ,UpdatedTime   = @UpdatedTime      
      ,UpdatedBy    = @UpdatedBy      
       WHERE MemberId   = @MemberId      
      
       IF(@OrderType='renewal')      
        BEGIN      
         UPDATE MembershipOrders       
         SET ExpiryDate=(SELECT CASE WHEN (SELECT Validity FROM MembershipTypes WHERE MembershipTypeId=@MembershipTypeId) <> 0 THEN @expiry ELSE NULL END)      
         WHERE MemberId = @MemberId      
        END      
       ELSE      
        BEGIN      
          UPDATE MembershipOrders       
          SET ExpiryDate=(SELECT CASE WHEN (SELECT Validity FROM MembershipTypes WHERE MembershipTypeId=@MembershipTypeId) <> 0 THEN @expiry ELSE NULL END)      
          WHERE MemberId = @MemberId      
        END     
    IF(@ReceiptUrl <> 'NA')    
    BEGIN    
      UPDATE Members SET ReceiptUrl = CAST(@MemberId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@OrderType, '^a-z0-9') + '.' + @ReceiptUrl  WHERE MemberId = @MemberId    
      SELECT @ReceiptUrl = CAST(@MemberId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@OrderType, '^a-z0-9') + '.' + @ReceiptUrl    
    END     
   ELSE  
    BEGIN  
     SELECT @ReceiptUrl=''  
    END   
  --IF(@ReceiptUrl <> 'NA')        
  --  BEGIN      
   
  --    UPDATE Members SET ReceiptUrl = CAST(@MemberId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@OrderType, '^a-z0-9') + '.' + @ReceiptUrl  WHERE MemberId = @MemberId        
  --    SELECT @ReceiptUrl = CAST(@MemberId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@OrderType, '^a-z0-9') + '.' + @ReceiptUrl        
  --  END         
  -- ELSE      
  --  BEGIN      
  --   SELECT @ReceiptUrl=''      
  --  END       
    END      
      
   SELECT @QStatus = 1;      
   COMMIT TRANSACTION      
   END TRY      
          
    BEGIN CATCH       
    ROLLBACK TRANSACTION       
       SELECT @QStatus = -1;       
    END CATCH         
          
END      
      
      
      
      
      
      
      
      
      
      
      
      
      
      


