CREATE PROCEDURE [dbo].[MemberProfileUpdate]    
    (@MemberId bigint     
 ,@ChapterId bigint    
 ,@Title nvarchar(64)    
 ,@FirstName nvarchar(150)    
 ,@LastName nvarchar(150)    
 ,@Occupation nvarchar(256)    
 ,@MemberSkils nvarchar(256)    
 ,@SpouseFirstName nvarchar(150)    
 ,@SpouseLastName nvarchar(150)    
 ,@SpouseOccupation nvarchar(256)    
 ,@SpouseEmail nvarchar(128)    
 ,@SpouseCell nvarchar(64)    
 ,@SpouseSkils nvarchar(256)    
 ,@Address nvarchar(512)    
 ,@City nvarchar(128)    
 ,@State nvarchar(128)    
 ,@ZipCode nvarchar(64)    
 ,@HomePhone nvarchar(64)    
 ,@MobilePhone nvarchar(64)    
 ,@MembershipTypeId bigint    
 ,@IsVolunteer bit    
 ,@Comments nvarchar(2048)    
 ,@ReferredBy nvarchar(512)    
 ,@UpdatedTime datetime    
 ,@UpdatedBy nvarchar(64)    
 ,@Fax nvarchar(64)    
 ,@WebsiteAddress nvarchar(64)    
 ,@Address2 nvarchar(512)    
 ,@QStatus int output    
 ,@SpousePhoneNo nvarchar(512)     
 ,@SPouseBachelors nvarchar(512)    
 ,@SPouseAdvanced nvarchar(512)    
 ,@SelfCity nvarchar(512)    
 ,@SelfDistrict nvarchar(512)    
 ,@SelfPhoneNo nvarchar(512)    
 ,@SelfName nvarchar(512)    
 ,@SelfRelation nvarchar(512)    
 ,@SpouseCity nvarchar(512)    
 ,@SpouseDistrict nvarchar(512)     
 ,@SpouseName nvarchar(512)    
 ,@SpouseRelation nvarchar(512)    
 ,@MBachelors nvarchar(512)    
 ,@MAdvanced nvarchar(512))      
            
AS    
BEGIN    
     
 SET NOCOUNT ON;    
    
 DECLARE @MembershipType nvarchar(256)    
    
 SET @MembershipType = (SELECT MembershipType from MembershipTypes where MembershipTypeId= @MembershipTypeId)    
    
    BEGIN TRY    
    BEGIN TRANSACTION    
        
   UPDATE Members    
      SET       
      Title                          =       @Title,    
      FirstName      =  @FirstName ,    
      LastName      =  @LastName ,    
      Occupation      =  @Occupation ,    
      --MemberSkils     =  @MemberSkils ,    
      SpouseFirstName    =  @SpouseFirstName ,    
      SpouseLastName     =  @SpouseLastName ,    
      SpouseOccupation    =  @SpouseOccupation ,    
      SpouseEmail     =  @SpouseEmail ,    
      SpouseCell      =  @SpouseCell,     
      SpouseSkils     =  @SpouseSkils ,    
      Address      =  @Address,     
      City       =  @City ,    
      State       =  @State ,    
      ZipCode      =  @ZipCode ,    
      HomePhone      =  @HomePhone ,    
      MobilePhone     =  @MobilePhone ,    
      IsVolunteer     =  @IsVolunteer ,    
      Comments      =  @Comments ,    
      ReferredBy      =  @ReferredBy,    
      UpdatedTime     =  @UpdatedTime ,    
      Fax       =  @Fax,    
      WebsiteAddress     =  @WebsiteAddress,    
      Address2      =  @Address2    
      WHERE MemberId      =  @MemberId    
    
    Update MembersInfo SET  MBachelors   = @MBachelors,    
          MAdvanced   = @MAdvanced,     
          SPouseBachelors = @SPouseBachelors,    
          SPouseAdvanced  = @SPouseAdvanced,    
          SpousePhoneNo  = @SpousePhoneNo,     
          SelfCity   = @SelfCity    
          ,SelfDistrict  = @SelfDistrict    
          ,SelfPhoneNo  = @SelfPhoneNo    
          ,SelfName   = @SelfName    
          ,SelfRelation  = @SelfRelation    
          ,SpouseCity  = @SpouseCity    
          ,SpouseDistrict = @SpouseDistrict     
          ,SpouseName  = @SpouseName    
          ,SpouseRelation = @SpouseRelation    
        Where MemberId   = @MemberId    
    
    
    IF(@MembershipType = 'Life Membership')    
    BEGIN    
    Update Members Set SpouseCell = 'BATA'+Cast(@MemberId as nvarchar(64)) Where MemberId= @MemberId    
    END    
   ELSE IF(@MembershipType = 'Individual Yearly Membership')    
    BEGIn    
    Update Members Set SpouseCell = 'BATA'+Cast(year(GETDATE()) as nvarchar(64))+Cast(@MemberId as nvarchar(64)) Where MemberId= @MemberId    
    END    
   ELSE IF(@MembershipType = 'Family Yearly Membership')    
    BEGIn    
    Update Members Set SpouseCell = 'BATA'+Cast(year(GETDATE()) as nvarchar(64))+Cast(@MemberId as nvarchar(64)) Where MemberId= @MemberId    
    END     
 ELSE IF(@MembershipType = 'Life membership single')    
    BEGIn    
    Update Members Set SpouseCell = 'BATA'+Cast(@MemberId as nvarchar(64)) Where MemberId= @MemberId    
    END     
   SELECT @QStatus = 1;     
   COMMIT TRANSACTION    
      END TRY    
        
    BEGIN CATCH     
    ROLLBACK TRANSACTION     
       SELECT @QStatus = -1;     
    END CATCH       
        
END    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    

