/****** Object:  StoredProcedure [dbo].[MembersBulkUpload]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[MembersBulkUpload]
    (@ShipmentsXML			nvarchar(max)	 
	,@Summery				nvarchar(max) output
	,@QStatus				int output)  
        
AS
BEGIN

	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
		Declare @Id bigint;
		DECLARE @MemberId bigint; 
		
			IF(@ShipmentsXML<>'')
			BEGIN				
				DECLARE @XML1 AS XML	        
				SELECT @XML1 = @ShipmentsXML 
				CREATE TABLE #temp1(Rid INT PRIMARY KEY IDENTITY(1,1),	 
									Email nvarchar(max),
									Password nvarchar(max))
				
				DECLARE @RowCount1 AS int
				DECLARE @CurrentRow1 AS int	
				
				INSERT INTO #temp1(Email,Password)

				SELECT  
					M.Item.value('Email[1]','nvarchar(max)'),
					M.Item.value('Password[1]','nvarchar(max)')						
				FROM @XML1.nodes('/ArrayOfMembers/Members') AS M(Item)
					
				SET @RowCount1 = @@ROWCOUNT	
				
				SET @CurrentRow1 = 1
				WHILE @CurrentRow1 < @RowCount1 + 1
				BEGIN 	
				
				UPDATE Members 
				SET	Password = (Select Password from #temp1 WHERE Rid = @CurrentRow1)
				Where Email = (Select Email from #temp1 WHERE Rid = @CurrentRow1)
		
					
				SET @Summery=@Summery + (CASE WHEN (Select Email From #temp1 WHERE Rid = @CurrentRow1) is null THEN '' ELSE (Select Email From #temp1 WHERE Rid = @CurrentRow1) END)+ +' - Added Successfully \\r\\n'
					 
				SET @CurrentRow1 = @CurrentRow1 + 1
				END		
				DROP TABLE #temp1			
				SELECT @QStatus = 1;	
			END
    COMMIT TRANSACTION
    END TRY 


    BEGIN CATCH    
    ROLLBACK TRANSACTION
		SELECT @QStatus = -1;    
    END CATCH    
END



















