CREATE PROCEDURE [dbo].[MembersChangePassword]
    (@MemberId bigint
    ,@Password nvarchar(256)
    ,@QStatus int output
	,@FType nvarchar(512))  
        
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @Email nvarchar(512);

	SET @Email = (Select Email from Members Where MemberId = @MemberId)
    
    BEGIN TRY	
		IF(@FType = 'Yes')	
			BEGIN
				UPDATE Members 
				SET Password = @Password, 
					LastPasswordChangedDate = GETDATE(),
					Fax = @FType
				WHERE MemberId =@MemberId	
			END
		ELSE
			BEGIN
				UPDATE Members 
				SET Password = @Password,LastPasswordChangedDate = GETDATE(),Fax = 'No' WHERE MemberId =@MemberId	
			END	
				Update Users SET Password = @Password Where Email = @Email
				SELECT @QStatus = 1;
    END TRY

    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH
    	
END







































