/****** Object:  StoredProcedure [dbo].[MembersGetFullDetailsByEmail]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[MembersGetFullDetailsByEmail] 
	(@Email nvarchar(128)
    ,@QStatus int OUTPUT)    
        
AS
BEGIN
	
    SET NOCOUNT ON;

    BEGIN TRY 
		DECLARE @MemberId bigint

		IF((SELECT COUNT(*) FROM Members WHERE Email=@Email)<>0)
			BEGIN
			SET @MemberId=(SELECT top(1) MemberId FROM Members WHERE Email=@Email AND MembershipTypeId <> 0)
			END
    
			 SELECT Top(1)  
						M.*,
						MT.Price AS MemberAmount,					
						MT.MembershipTypeId ,
						MT.MembershipType,
						C.ChapterName
						FROM Members M 
						Left JOIN MembershipTypes MT ON MT.MembershipTypeId=M.MembershipTypeId
						Left JOIN Chapters C ON C.ChapterId=M.ChapterId  
						WHERE M.MemberId= @MemberId
		
			SELECT * FROM ChildrenInfo WHERE MemberId=@MemberId
		
			SELECT top(1) * FROM MembershipOrders WHERE MemberId=@MemberId

			SELECT * FROM MembersInfo WHERE MemberId=@MemberId
		 
			SELECT @QStatus = 1;
    END TRY
    
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH	
	 
END







