/****** Object:  StoredProcedure [dbo].[MembersGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

  
CREATE PROCEDURE [dbo].[MembersGetListByVariable]    
  (@MembershipTypeId bigint    
  ,@PaymentStatusId bigint    
  ,@StartDate nvarchar(126)    
  ,@EndDate nvarchar(126)    
  ,@ExpiryDate nvarchar(126)    
  ,@IsVolunteer nvarchar(50)    
  ,@Search nvarchar(126)    
     ,@Sort nvarchar(126)    
  ,@PageNo int    
     ,@Items int    
     ,@Total int output    
  ,@ChapterId bigint    
  ,@type nvarchar(256))    
AS    
BEGIN    
     
 SET NOCOUNT ON;    
     
 --BEGIN TRY    
     
 DECLARE @Start int, @End INT ;    
 DECLARE @Query nvarchar(max);    
        
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)    
    ,MemberId bigint    
    ,ChapterId bigint    
    ,Title nvarchar(64)    
    ,Email nvarchar(128)    
    ,Password nvarchar(256)    
    ,FirstName nvarchar(150)    
    ,LastName nvarchar(150)    
    ,ProfileImage nvarchar(512)    
    ,Occupation nvarchar(256)    
    ,SpouseFirstName nvarchar(150)    
    ,SpouseLastName nvarchar(150)    
    ,SpouseOccupation nvarchar(256)    
    ,SpouseEmail nvarchar(128)    
    ,SpouseCell nvarchar(64)    
    ,Address nvarchar(512)    
    ,City nvarchar(128)    
    ,State nvarchar(128)    
    ,ZipCode nvarchar(64)    
    ,HomePhone nvarchar(64)    
    ,MobilePhone nvarchar(64)    
    ,IsApproved bit    
    ,IsLockedOut bit    
    ,IsActivated bit    
    ,DateActivated datetime    
    ,RegistrationGUID uniqueidentifier    
    ,FailedPasswordAttemptCount int    
    ,LastPasswordChangedDate datetime    
    ,LastActivityDate datetime    
    ,MembershipTypeId bigint    
    ,IsVolunteer bit    
    ,IsTeluguorigin bit    
    ,Comments nvarchar(2048)    
    ,ReferredBy nvarchar(512)    
    ,Amount decimal(15,2)    
    ,TransactionId nvarchar(Max)    
    ,PaymentStatusId bigint    
    ,PaymentMethodId bigint    
    ,PaymentMethod nvarchar(128)    
    ,PaymentStatus nvarchar(128)    
    ,AdminComment nvarchar(2048)    
    ,UserComment nvarchar(2048)    
    ,OrderDate datetime    
    ,ExpiryDate datetime    
    ,BankName nvarchar(128)    
    ,ChequeNo nvarchar(128)    
    ,ChequeDate datetime    
    ,InsertedTime datetime    
    ,UpdatedTime datetime    
    ,Fax nvarchar(64)    
    ,WebsiteAddress nvarchar(64)    
    ,Address2 nvarchar(512)    
    ,MembershipType nvarchar(256)    
    ,MemberSkils nvarchar(256))    
    
        
  SELECT @Start = (@PageNo - 1) * @Items      
        
  SELECT @End = @Start + @Items    
     
  IF(@type = 'active')    
  BEGIN    
  set @Query = 'INSERT INTO #temp     
