create PROCEDURE [dbo].[MembershipTypesGetListByVariable2024BKP]
	 (@ChapterId bigint
	 ,@PageNo int
     ,@Items int
     ,@Search nvarchar(126)
     ,@Total int output
     ,@Sort nvarchar(126))
AS
BEGIN
	
	SET NOCOUNT ON;
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,MembershipTypeId bigint
				,ChapterId bigint
				,MembershipType nvarchar(256)
				,Price decimal(15,2)
				,Validity int 
				,DisplayOrder int
				,IsActive bit
				,UpdatedBy nvarchar(64)
				,UpdatedTime datetime
				,ChapterName nvarchar(512)
				,FormattedField nvarchar(512)
				,MemberCount bigint)
	
	SELECT @Start = (@PageNo - 1) * @Items     
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
		 SELECT  MT.MembershipTypeId 
		        ,MT.ChapterId
				,MT.MembershipType 
				,MT.Price 
				,MT.Validity
				,MT.DisplayOrder
				,MT.IsActive
				,MT.UpdatedBy
				,MT.UpdatedTime
				,C.ChapterName
				,MT.FormattedField
				,COUNT(M.MemberId) AS MemberCount
				FROM MembershipTypes MT  
				INNER JOIN Chapters C ON C.ChapterId = MT.ChapterId
				Left JOIN Members M ON M.MembershipTypeId = MT.MembershipTypeId	
				WHERE MT.MembershipTypeId <> 0
		GROUP BY
					MT.MembershipTypeId,
					MT.ChapterId,
					MT.MembershipType,
					MT.Price,
					MT.Validity,
					MT.DisplayOrder,
					MT.IsActive,
					MT.UpdatedBy,
					MT.UpdatedTime,
					C.ChapterName,
					MT.FormattedField '
	
		IF(@ChapterId <> 0)
		BEGIN
			SET @Query=@Query + 'AND MT.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))
		END  

	
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  MT.MembershipType LIKE ''%' + @Search + '%'''
		END
	
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
		
		EXEC sp_ExecuteSQL @Query;
		Print @Query;
	
		SELECT @Total = COUNT(Rid) from #temp 
			
	    SELECT Rid
		  	,MembershipTypeId
			,ChapterId 
			,MembershipType
			,Price		
			,Validity	
			,DisplayOrder
			,IsActive
			,UpdatedBy
			,UpdatedTime   
			,ChapterName 
			,FormattedField
			,MemberCount
	  FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
	  DROP TABLE #temp

END












