/****** Object:  StoredProcedure [dbo].[MembershipTypesInsert]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
    
CREATE PROCEDURE [dbo].[MembershipTypesInsert]    
    (@MembershipTypeId bigint    
 ,@ChapterId bigint    
 ,@MembershipType nvarchar(256)    
 ,@Price decimal(15,2)     
 ,@Validity int     
 ,@DisplayOrder bigint    
 ,@IsActive bit    
 ,@UpdatedBy nvarchar(64)    
 ,@UpdatedTime datetime    
 ,@FormattedField nvarchar(512)    
 ,@QStatus int output)      
            
AS    
BEGIN    
    
 -- SET NOCOUNT ON added to prevent extra result sets from    
 -- interfering with SELECT statements.    
     
 SET NOCOUNT ON;    
    
    -- Insert statements for procedure here    
        
    --BEGIN TRY    
    BEGIN TRANSACTION    
        
  IF((SELECT COUNT(*) FROM MembershipTypes WHERE MembershipTypeId = @MembershipTypeId) = 0)    
  BEGIN    
      
   INSERT INTO MembershipTypes VALUES    
           (@ChapterId,    
     @MembershipType    
           ,@Price    
           ,@Validity    
     ,@DisplayOrder    
     ,@IsActive    
     ,@UpdatedBy    
     ,@UpdatedTime    
     ,@FormattedField    
     )    
   SELECT @QStatus = 1;    
       
  END    
      
  ELSE BEGIN    
      
   UPDATE MembershipTypes    
      SET    
         ChapterId=@ChapterId  
     ,MembershipType=@MembershipType    
     ,Price=@Price    
     ,Validity=@Validity    
     ,DisplayOrder=@DisplayOrder    
     ,UpdatedBy=@UpdatedBy    
     ,UpdatedTime=@UpdatedTime    
      ,FormattedField=@FormattedField    
    
    WHERE MembershipTypeId = @MembershipTypeId       
   SELECT @QStatus = 2;    
    
   Update Members Set MembershipTypeId =@MembershipTypeId where MembershipTypeId =@MembershipTypeId    
    
   Update MembershipOrders set MembershipTypeId=@MembershipTypeId , ExpiryDate = (SELECT CASE WHEN (SELECT Validity FROM MembershipTypes WHERE MembershipTypeId=@MembershipTypeId) <> 0 THEN dateadd(month,datediff(month,0,getdate())+(SELECT Validity FROM MembershipTypes WHERE MembershipTypeId=@MembershipTypeId),0) ELSE NULL END) where  MembershipTypeId =@MembershipTypeId    
       
   END    
       
    COMMIT TRANSACTION    
  --  END TRY    
        
  --  BEGIN CATCH     
        
  --      ROLLBACK TRANSACTION       
  --SELECT @QStatus = -1;        
      
  --  END CATCH       
        
END    
    
    
    
    
    
    
    
    
    


