CREATE PROCEDURE [dbo].[MembershipTypesUpdateStatus]
    (@MembershipTypeId bigint
    ,@QStatus int output)  
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
    BEGIN TRY    
    BEGIN TRANSACTION
		IF((SELECT IsActive FROM MembershipTypes WHERE MembershipTypeId = @MembershipTypeId) = 1)
			BEGIN
				UPDATE MembershipTypes SET IsActive = 0 WHERE MembershipTypeId = @MembershipTypeId
			END
		ELSE
			BEGIN
				UPDATE MembershipTypes SET IsActive = 1 WHERE MembershipTypeId = @MembershipTypeId
			END		
		SELECT @QStatus = 1;
		
	COMMIT TRANSACTION
    END TRY

    BEGIN CATCH
         ROLLBACK TRANSACTION
		 SELECT @QStatus = -1;
    END CATCH
    	
END










