 )  
  
          
AS  
BEGIN  
   
 SET NOCOUNT ON;  
  
    DECLARE @MembershipType nvarchar(256)  
  
 SET @MembershipType = (SELECT MembershipType from MembershipTypes where MembershipTypeId= @MembershipTypeId)  
  
 IF(@Email <> '' AND @Email IS Not NULL)  
 BEGIN  
 SET @MemberId = (SELECT top(1) MemberId FROM Members WHERE Email=@Email)  
 END  
  
    --BEGIN TRY  
    --BEGIN TRANSACTION  
      
   IF((SELECT COUNT(*) FROM Members WHERE MemberId = @MemberId) = 0)  
   BEGIN  
   INSERT INTO Members VALUES  
           (@ChapterId,  
      @Title ,  
      @Email ,  
      @Password ,  
      @FirstName ,  
      @LastName ,  
      NULL ,  
      @Occupation ,  
      @MemberAge,  
      @MemberSkils,  
      @SpouseFirstName ,  
