    declare @formaterid nvarchar(256);  
    SET @formaterid = (select FormattedField from MembershipTypes where MembershipTypeId = @MembershipTypeId);  
  
    IF(@MemberIdString <> '')  
     BEGIN  
     Select @MemberCount = Cast(REPLACE(@MemberIdString, @formaterid, '') as bigint)  
     END  
    ELSE  
     BEGIN  
     SELECT @MemberCount = 0;  
     END  
    Select @MemberCount = @MemberCount + 1;  
    Update Members Set MemberSkils = (CASE WHEN @MemberCount < 10 then @formaterid + '00000'+CAST(@MemberCount as nvarchar(64)) ELSE (CASE WHEN @MemberCount<100 then @formaterid + '0000'+CAST(@MemberCount as nvarchar(64)) ELSE (CASE WHEN @MemberCount<1000
 then @formaterid + '000'+CAST(@MemberCount as nvarchar(64)) ELSE (CASE WHEN @MemberCount<10000 then @formaterid + '00'+CAST(@MemberCount as nvarchar(64)) ELSE (CASE WHEN @MemberCount<100000 then @formaterid + '0'+CAST(@MemberCount as nvarchar(64)) ELSE (
CASE WHEN @MemberCount<1000000 then @formaterid +CAST(@MemberCount as nvarchar(64))END) END) END) END) END) END) Where MemberId= @MemberId  
   END  
     
  
           DECLARE @ValidityMonth nvarchar(512);  
