      ,@UniversityName  
      ,@VolunteerOrganization   
      ,@AuthorNATS   
      ,@AdressNATS   
      ,@PhoneNoNATS   
      ,@EmailNATS   
      ,@KnowledgeNATS  
      ,@Field1  
      ,@Field2  
      ,@Field3  
        
      )  
  
     
  
             
   IF(@ProfileImage <> 'NA')  
    BEGIN  
       UPDATE Members  
       SET  ProfileImage= CAST(@MemberId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@Title, '&^a-z0-9') + '.' + @ProfileImage  
       WHERE MemberId = @MemberId   
       
      SELECT @ProfileImage = CAST(@MemberId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@Title, '&^a-z0-9') + '.' + @ProfileImage  
    END  
   ELSE  
    BEGIN  
     SELECT @ProfileImage=''  
    END  
       
   IF(@ReceiptUrl <> 'NA')    
    BEGIN    
      UPDATE Members SET ReceiptUrl = CAST(@MemberId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@FirstName, '^a-z0-9') + '.' + @ReceiptUrl  WHERE MemberId = @MemberId    
      SELECT @ReceiptUrl = CAST(@MemberId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@FirstName, '^a-z0-9') + '.' + @ReceiptUrl    
    END     
   ELSE  
    BEGIN  
     SELECT @ReceiptUrl=''  
    END   
    
  END   
  
  ELSE  
    
  BEGIN  
    
   UPDATE Members  
      SET   
         ChapterId                      =       @ChapterId,  
         Title      =      @Title,  
      Email       =  @Email ,  
      Password      =  @Password ,  
      FirstName      =  @FirstName ,  
      LastName      =  @LastName ,  
      Occupation      =  @Occupation ,  
       MemberAge      =  @MemberAge ,  
      MemberSkils     =  @MemberSkils ,  
      SpouseFirstName    =  @SpouseFirstName ,  
      SpouseLastName     =  @SpouseLastName ,  
      SpouseOccupation    =  @SpouseOccupation ,  
      SpouseEmail     =  @SpouseEmail ,  
      SpouseCell      =  @SpouseCell,   
      Address      =  @Address,   
      SpouseSkils     =  @SpouseSkils ,  
      City       =  @City ,  
      State       =  @State ,  
      ZipCode      =  @ZipCode ,  
      HomePhone      =  @HomePhone ,  
      MobilePhone     =  @MobilePhone ,  
      IsLockedOut     =  @IsLockedOut,  
      IsActivated     =  @IsActivated ,  
      DateActivated     =  @DateActivated ,  
      RegistrationGUID    =  @RegistrationGUID ,  
      FailedPasswordAttemptCount  =  @FailedPasswordAttemptCount ,  
      LastPasswordChangedDate  =  @LastPasswordChangedDate ,  
      LastActivityDate    =  @LastActivityDate ,  
