/****** Object:  StoredProcedure [dbo].[MembersOrderDetailsGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[MembersOrderDetailsGetListByVariable]
	 (
	  @Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,MembershipOrderId bigint
				,MemberId bigint
				,FirstName nvarchar(64)
				,MembershipTypeId bigint
				,MembershipType nvarchar(256)
				,Amount decimal(15,2)
				,TransactionId nvarchar(max)
				,PaymentStatusId bigint
				,PaymentMethodId bigint
				,PaymentBy nvarchar(2048)
				,PaymentMethod nvarchar(128)
				,PaymentStatus nvarchar(128)
				,AdminComment nvarchar(2048)
				,UserComment nvarchar(2048)
				,OrderDate datetime
				,ExpiryDate datetime
				,BankName nvarchar(128)
				,ChequeNo nvarchar(128)
				,ChequeDate datetime
				,InsertedTime datetime
				,UpdatedTime datetime
				,SpouseCell nvarchar(64) 
				,MemberSkils nvarchar(256)	
				,Email nvarchar(128))

				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
		 SELECT	 MO.MembershipOrderId
				,M.MemberId 
				,M.FirstName 
				,MT.MembershipTypeId 
				,MT.MembershipType 
				,Amount 
				,TransactionId 
				,PaymentStatusId 
				,PaymentMethodId 
				,PaymentBy
				,(SELECT PaymentMethod FROM PaymentMethods pm1 WHERE pm1.PaymentMethodId=MO.PaymentMethodId)
				,(SELECT PaymentStatus FROM PaymentStatus ps WHERE ps.PaymentStatusId=MO.PaymentStatusId)
				,AdminComment 
				,UserComment 
				,OrderDate 
				,ExpiryDate 
				,BankName 
				,ChequeNo 
				,ChequeDate 
				,InsertedTime 
				,M.UpdatedTime
				,M.SpouseCell 
				,MemberSkils 
				,M.Email
				FROM Members M
				INNER JOIN MembershipTypes MT ON MT.MembershipTypeId=M.MembershipTypeId 
				LEFT JOIN MembershipOrders MO ON MO.MemberId=M.MemberId 		
				WHERE MO.MembershipOrderId <> 0 '
		
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  M.MemberId LIKE ''%' + @Search + '%'' OR  M.FirstName LIKE ''%' + @Search + '%'' OR  TransactionId LIKE ''%' + @Search + '%'''
		END
		
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END












GO
