CREATE PROCEDURE [dbo].[MembersProfileImage]
    @MemberId bigint,
    @ProfileImage nvarchar(512) output,
    @QStatus int output 
        
AS
BEGIN

	DECLARE @UserName nvarchar(756)
    SET @UserName=(SELECT FirstName FROM Members WHERE MemberId=@MemberId) 
	
	SET NOCOUNT ON;


    BEGIN TRY
		
		 UPDATE Members SET ProfileImage = CAST(@MemberId  AS nvarchar(12)) + '-' + REPLACE(@UserName,' ','-') + '.' + @ProfileImage 
		 WHERE MemberId = @MemberId
	
		 SELECT @ProfileImage = CAST(@MemberId  AS nvarchar(12)) + '-' + REPLACE(@UserName,' ','-') + '.' + @ProfileImage 
		 SELECT @QStatus = 1
    END TRY
    
    BEGIN CATCH
		SELECT @QStatus = -1    
    END CATCH
	 
END

















