CREATE PROCEDURE [dbo].[MembersUnlock]
    (@MemberId bigint
    ,@QStatus int output )  
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
    BEGIN TRY    
		UPDATE Members SET IsLockedOut = 0 WHERE MemberId =@MemberId
		SELECT @QStatus = 1;		
    END TRY

    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH
    	
END









