       DECLARE @ValidityMonth nvarchar(512);    
       DECLARE @ValidityDay nvarchar(512);    
       DECLARE @ValidityYear nvarchar(512);    
       DECLARE @expiry nvarchar(512);    
       DECLARE @validity bigint;    
    
       SET @validity = (SELECT Validity FROM MembershipTypes WHERE MembershipTypeId = @MembershipTypeId);    
         
       SELECT @ValidityMonth = (SELECT DATEPART(MONTH, DATEADD(MONTH, @validity, GETDATE())));    
       SELECT @ValidityDay = (SELECT DATEPART(DAY, DATEADD(MONTH, @validity, GETDATE())));    
       SELECT @ValidityYear = (SELECT DATEPART(YEAR, DATEADD(MONTH, @validity, GETDATE())));    
       SET @expiry =  @ValidityYear + '-' + @ValidityMonth + '-' + @ValidityDay;    
    
       UPDATE MembershipOrders SET ExpiryDate = (SELECT CASE WHEN (SELECT Validity FROM MembershipTypes WHERE MembershipTypeId=@MembershipTypeId) <> 0 THEN @expiry ELSE NULL END) Where MemberId= @MemberId    
       END    
    
      
