            SELECT @QStatus = 2;    
       
    END     
     ELSE    
    BEGIN    
     UPDATE   MembershipOrders SET    
        MembershipTypeId  = @MembershipTypeId    
       ,Amount     = @Amount    
	   ,expirydate     = @expirydate    
       ,TransactionId   = @TransactionId    
