   UPDATE MembersInfo    
      SET     
            MemberId           = @MemberId      , MBachelors        = @MBachelors      , MAdvanced         = @MAdvanced      , SPouseBachelors   = @SPouseBachelors      , SPouseAdvanced    = @SPouseAdvanced      , SelfCity          = @SelfCity      ,   
     
