/****** Object:  StoredProcedure [dbo].[MemberUpdateStatus]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[MemberUpdateStatus]
    (@MemberId bigint
    ,@QStatus int output)  
        
AS
BEGIN

	
	SET NOCOUNT ON;
    
    BEGIN TRY    
    BEGIN TRANSACTION
    
		IF((SELECT IsApproved FROM Members WHERE MemberId = @MemberId) = 1)
			BEGIN
				UPDATE Members SET IsApproved = 0 WHERE MemberId = @MemberId
			END
		ELSE
			BEGIN
				UPDATE Members SET IsApproved = 1 WHERE MemberId = @MemberId

				Declare @MembershipType nvarchar(128)
				Declare @MemberIdString nvarchar(128)
				Declare @MemberCount bigint
				Declare @MembershipTypeId bigint

				Select @MembershipType = (Select MT.MembershipType from MembershipTypes MT 
		        where MT.MembershipTypeId = (Select M.MembershipTypeId from Members M Where M.MemberId = @MemberId))

		        Select @MembershipTypeId = (Select M.MembershipTypeId from Members M Where M.MemberId = @MemberId)

				 IF(@MembershipType = 'Lifetime Member')
					BEGIN
						Select @MemberIdString = (Select Top(1) SpouseCell From Members Where MembershipTypeId = @MembershipTypeId Order By SpouseCell DESC) 

						Select @MemberCount = Cast(REPLACE(@MemberIdString, 'LM', '') as bigint)
						Select @MemberCount = @MemberCount + 1

						Update Members Set SpouseCell = 'LM'+(CASE WHEN @MemberCount < 10 then '00'+CAST(@MemberCount as nvarchar(64)) ELSE (CASE WHEN @MemberCount<100 then '0'+CAST(@MemberCount as nvarchar(64)) ELSE (CAST(@MemberCount as nvarchar(64))) END) END) Where MemberId= @MemberId
			        END

				ELSE IF((@MembershipType = 'Annual Individual') OR (@MembershipType = 'Annual Family'))
					BEGIn
			 
					 Select @MemberIdString = (Select Top(1) SpouseCell From Members Where MembershipTypeId in (15, 4) Order By SpouseCell DESC) 

						Select @MemberCount = Cast(SUBSTRING(@MemberIdString, 6, (Select (LEN(@MemberIdString)-5))) as bigint)
						Select @MemberCount = @MemberCount + 1

						Update Members Set SpouseCell = CAST(year(GetDate()) as nvarchar(64))+'-'+(CASE WHEN @MemberCount < 10 then '00'+CAST(@MemberCount as nvarchar(64)) ELSE (CASE WHEN @MemberCount<100 then '0'+CAST(@MemberCount as nvarchar(64)) ELSE (CAST(@MemberCount as nvarchar(64))) END) END) Where MemberId= @MemberId
					END 
				ELSE IF(@MembershipType = 'Life membership single')
					BEGIN
					Update Members Set SpouseCell = 'HTCA'+Cast(@MemberId as nvarchar(64)) Where MemberId= @MemberId
					END 
		  END		
		
		  SELECT @QStatus = 1;
		
	  COMMIT TRANSACTION
      END TRY

      BEGIN CATCH
         ROLLBACK TRANSACTION
		 SELECT @QStatus = -1;
      END CATCH
    	
END




















