CREATE PROCEDURE [dbo].[MobileAppInfoInsert]
    (@AppsettingId bigint
	,@IOSApp nvarchar(128)
	,@Androidapp nvarchar(128)
	,@Iosversion nvarchar(128)
	,@AppAndroidVersion nvarchar(128)
    ,@SplashMiddle nvarchar(1024) output
	,@SplashBottom nvarchar(1024) output
	,@HomeTopHeader nvarchar(1024) output
	,@Customloader nvarchar(1024) output
	,@OtherclasssHeader  nvarchar(1024) output
	,@NotificationAppId nvarchar(1024)
	,@ServerKey nvarchar(max)
	,@Androidchannelid nvarchar(1024)
	,@QStatus int output
	
	
	)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;

		IF((SELECT COUNT(*) FROM Appsettings WHERE AppsettingId = @AppsettingId) = 1)
		BEGIN
			UPDATE Appsettings
			   SET   IOSApp=@IOSApp,
			         Androidapp=@Androidapp,
					 Iosversion=@Iosversion,
					 AppAndroidVersion=@AppAndroidVersion,
					NotificationAppId=@NotificationAppId,
					ServerKey=@ServerKey,
					Androidchannelid=@Androidchannelid


			 WHERE AppsettingId = @AppsettingId				
				
			SELECT @QStatus = 2;
			
			
			
			
			IF(@SplashMiddle <> 'NA')
			BEGIN
				UPDATE Appsettings
				   SET  SplashMiddle= CAST(@AppsettingId  AS nvarchar(12)) + '-SplashMiddle-' + dbo.RemoveSpecialChar('app', '^a-z0-9') + '.' + @SplashMiddle
				   WHERE AppsettingId = @AppsettingId	
			  
				  SELECT @SplashMiddle = CAST(@AppsettingId AS nvarchar(12)) + '-SplashMiddle-' + dbo.RemoveSpecialChar('app', '^a-z0-9') + '.' + @SplashMiddle	
			END	
		ELSE
			BEGIN
			  SELECT @SplashMiddle=''
			END	

	
		      IF(@SplashBottom <> 'NA')
			BEGIN
				UPDATE Appsettings
				   SET  SplashBottom= CAST(@AppsettingId  AS nvarchar(12)) + '-SplashBottom-' + dbo.RemoveSpecialChar('app', '^a-z0-9') + '.' + @SplashBottom
				   WHERE AppsettingId = @AppsettingId	
			  
				  SELECT @SplashBottom = CAST(@AppsettingId AS nvarchar(12)) + '-SplashBottom-' + dbo.RemoveSpecialChar('app', '^a-z0-9') + '.' + @SplashBottom	
			END	
		ELSE
			BEGIN
			  SELECT @SplashBottom=''
			END	




				IF(@HomeTopHeader  <> 'NA' )
			BEGIN
				UPDATE Appsettings
				   SET  HomeTopHeader= CAST(@AppsettingId  AS nvarchar(12)) + '-HomeTopHeader-' + dbo.RemoveSpecialChar('app', '^a-z0-9') + '.' + @HomeTopHeader
				   WHERE AppsettingId = @AppsettingId	
			  
				  SELECT @HomeTopHeader  = CAST(@AppsettingId AS nvarchar(12)) + '-HomeTopHeader-' + dbo.RemoveSpecialChar('app', '^a-z0-9') + '.' + @HomeTopHeader	
			END	
		ELSE
			BEGIN
			  SELECT @HomeTopHeader =''
			END	


			     IF(@Customloader  <> 'NA' )
			BEGIN
				UPDATE Appsettings
				   SET  Customloader= CAST(@AppsettingId  AS nvarchar(12)) + '-Customloader-' + dbo.RemoveSpecialChar('app', '^a-z0-9') + '.' + @Customloader
				   WHERE AppsettingId = @AppsettingId	
			  
				  SELECT @Customloader  = CAST(@AppsettingId AS nvarchar(12)) + '-Customloader-' + dbo.RemoveSpecialChar('app', '^a-z0-9') + '.' + @Customloader	
			END	
		ELSE
			BEGIN
			  SELECT @Customloader =''
			END	

			   IF(@OtherclasssHeader  <> 'NA' )
			BEGIN
				UPDATE Appsettings
				   SET  OtherclasssHeader= CAST(@AppsettingId  AS nvarchar(12)) + '-OtherclasssHeader-' + dbo.RemoveSpecialChar('app', '^a-z0-9') + '.' + @OtherclasssHeader
				   WHERE AppsettingId = @AppsettingId	
			  
				  SELECT @OtherclasssHeader  = CAST(@AppsettingId AS nvarchar(12)) + '-OtherclasssHeader-' + dbo.RemoveSpecialChar('app', '^a-z0-9') + '.' + @OtherclasssHeader	
			END	
		ELSE
			BEGIN
			  SELECT @OtherclasssHeader =''
			END	


		END



		ELSE
		BEGIN
			 INSERT INTO Appsettings VALUES
				(  
				       @IOSApp,
			           @Androidapp,
					   @Iosversion,
					   @AppAndroidVersion,
					   @SplashMiddle ,
	                   @SplashBottom ,
	                   @HomeTopHeader ,
					   @Customloader,
					   @OtherclasssHeader,@NotificationAppId,@ServerKey,@Androidchannelid

					
					)	
			 		 
			 SELECT @QStatus = 1;	
		END

END













