CREATE PROCEDURE [dbo].[NewMembersBulkImport]
    (@ShipmentsXML nvarchar(max),
     @Summary nvarchar(max) output,
     @QStatus int output)
AS
BEGIN
    SET NOCOUNT ON;

    -- BEGIN TRY
    -- BEGIN TRANSACTION

    IF (@ShipmentsXML <> '')
    BEGIN
        DECLARE @XML1 AS XML

        SELECT @XML1 = @ShipmentsXML

        CREATE TABLE #temp1 (Rid INT PRIMARY KEY IDENTITY(1, 1),
		    ChapterId  nvarchar(max),
            FirstName nvarchar(max),
            LastName nvarchar(max),
            Email nvarchar(max),
			Password nvarchar(max),
			MemberSkils nvarchar(max),
            SpouseFirstName nvarchar(max),
            SpouseLastName nvarchar(max),
            SpouseEmail nvarchar(max),
            SpouseCell nvarchar(max),
			Address nvarchar(max),
			Address2 nvarchar(max),
            City nvarchar(max),
            State nvarchar(max),
            ZipCode nvarchar(max),
            HomePhone nvarchar(max),
            MobilePhone nvarchar(max),
			
            MembershipType nvarchar(max),
			
            TransactionId nvarchar(max),
            PaymentStatus nvarchar(max),
            PaymentMethod nvarchar(max),
            ExpiryDate nvarchar(max)

        )

        DECLARE @RowCount1 AS int
        DECLARE @CurrentRow1 AS int

        INSERT INTO #temp1 (
            ChapterId,
            FirstName,
            LastName,
            Email,
			Password,
			MemberSkils,
            SpouseFirstName,
            SpouseLastName,
            SpouseEmail,
            SpouseCell,
			Address,
			Address2,
            City,
            State,
            ZipCode,
            HomePhone,
            MobilePhone,
			
            MembershipType,
			
            TransactionId,
            PaymentStatus,
            PaymentMethod,
            ExpiryDate

        )
        SELECT

		    M.Item.value('ChapterId[1]', 'nvarchar(max)'),
            M.Item.value('FirstName[1]', 'nvarchar(max)'),
            M.Item.value('LastName[1]', 'nvarchar(max)'),
            M.Item.value('Email[1]', 'nvarchar(max)'),
		    M.Item.value('Password[1]', 'nvarchar(max)'),
            M.Item.value('MemberSkils[1]', 'nvarchar(max)'),
            M.Item.value('SpouseFirstName[1]', 'nvarchar(max)'),
            M.Item.value('SpouseLastName[1]', 'nvarchar(max)'),
            M.Item.value('SpouseEmail[1]', 'nvarchar(max)'),
            M.Item.value('SpouseCell[1]', 'nvarchar(max)'),
            M.Item.value('Address[1]', 'nvarchar(max)'),
			M.Item.value('Address2[1]', 'nvarchar(max)'),
            M.Item.value('City[1]', 'nvarchar(max)'),
            M.Item.value('State[1]', 'nvarchar(max)'),
            M.Item.value('ZipCode[1]', 'nvarchar(max)'),
            M.Item.value('HomePhone[1]', 'nvarchar(max)'),
            M.Item.value('MobilePhone[1]', 'nvarchar(max)'),
          
            M.Item.value('MembershipType[1]', 'nvarchar(max)'),
			
            M.Item.value('TransactionId[1]', 'nvarchar(max)'),
			M.Item.value('PaymentStatus[1]', 'nvarchar(max)'),
			M.Item.value('PaymentMethod[1]', 'nvarchar(max)'),
		    M.Item.value('ExpiryDate[1]', 'nvarchar(max)')



        FROM @XML1.nodes('/ArrayOfMembers/Members') AS M(Item)

        SET @RowCount1 = @@ROWCOUNT

        SET @CurrentRow1 = 1

		
         DECLARE @MemberId bigint
		 DECLARE @FailedCount bigint
		  DECLARE @successCount bigint
         SET @successCount =0
		SET @FailedCount=0

		DECLARE @InsertedSummary NVARCHAR(MAX) = ''
         DECLARE @FailedSummary NVARCHAR(MAX) = ''

        WHILE @CurrentRow1 < @RowCount1 + 1
        BEGIN

			  DECLARE @MembershipTypeId bigint
			  declare @formaterid nvarchar(256);

	SET @MembershipTypeId = (SELECT MembershipTypeId from MembershipTypes where MembershipType = (Select MembershipType From #temp1 Where Rid = @CurrentRow1))
	SET @formaterid = (select FormattedField from MembershipTypes where MembershipTypeId = @MembershipTypeId);

	declare @expiry nvarchar(512);

				declare @validity int;
				set @validity = (SELECT Validity FROM MembershipTypes WHERE MembershipTypeId=@MembershipTypeId);
				
				SET @expiry = (SELECT DATEADD(MONTH, @validity, GETDATE()));

           -- IF ((SELECT COUNT(*) FROM Members WHERE Email = (SELECT Email FROM #temp1 WHERE Rid = @CurrentRow1)) = 0)
		   If((Select Count(*) From Members  Where  Email = (Select Email From #temp1 Where Rid = @CurrentRow1)) = 0)

			
				
            BEGIN
                INSERT INTO Members (
                   


					   ChapterId,
                        FirstName,
                         LastName,
                         Email,
						Password,
						MemberSkils,
						SpouseFirstName,
						SpouseLastName,
						SpouseEmail,
						SpouseCell,
						Address,
						Address2,
						City,
						State,
						ZipCode,
						HomePhone,
						MobilePhone,
						IsApproved,
						IsActivated,
						 MembershipTypeId,
						InsertedTime,
                         UpdatedTime



                )
                SELECT
                    

					   1,
                        FirstName,
                         LastName,
                         Email,
						Password,
						MemberSkils,
						SpouseFirstName,
						SpouseLastName,
						SpouseEmail,
						SpouseCell,
						Address,
						Address2,
						City,
						State,
						ZipCode,
						HomePhone,
						MobilePhone,
						1,
						1,
						(SELECT MembershipTypeId FROM MembershipTypes WHERE MembershipType = (SELECT MembershipType FROM #temp1 WHERE Rid = @CurrentRow1)),
						 GetDate(),
                         GetDate()

                FROM #temp1
                WHERE Rid = @CurrentRow1

                SELECT @MemberId = Scope_Identity();

				UPDATE Members 
				SET MemberSkils = @formaterid + CAST(@MemberId AS NVARCHAR(64))
				WHERE MemberId = @MemberId;

                INSERT INTO MembershipOrders
                SELECT
                    @MemberId,
                    (SELECT MembershipTypeId FROM MembershipTypes WHERE MembershipType = (SELECT MembershipType FROM #temp1 WHERE Rid = @CurrentRow1)),
                    (SELECT Price FROM MembershipTypes WHERE MembershipType = (SELECT MembershipType FROM #temp1 WHERE Rid = @CurrentRow1)),
                    TransactionId,
                    (SELECT PaymentStatusId FROM PaymentStatus WHERE PaymentStatus = (SELECT PaymentStatus FROM #temp1 WHERE Rid = @CurrentRow1)),
				    (SELECT PaymentMethodId FROM PaymentMethods WHERE PaymentMethod = (SELECT PaymentMethod FROM #temp1 WHERE Rid = @CurrentRow1)),
						
                    null,
                    null,
                    null,
                    GETUTCDATE(),
					@expiry,
                     null,
                     null,
                    GETUTCDATE(),
                    GETUTCDATE(),
                    'Administrator'
                FROM #temp1
                WHERE Rid = @CurrentRow1

               -- SET @Summary = @Summary + (SELECT FirstName FROM #temp1 WHERE Rid = @CurrentRow1) + ' Inserted Members Successfully \r\n'

				--SET @Summary = @Summary + (SELECT Email FROM #temp1 WHERE Rid = @CurrentRow1) + ' Inserted Member Successfully \r\n';
                --SET @successCount = @successCount + 1;
				SET @InsertedSummary = @InsertedSummary + (SELECT Email FROM #temp1 WHERE Rid = @CurrentRow1) + CHAR(13)
                SET @successCount = @successCount + 1


            END
			 ELSE 
				BEGIN
					 --SET @Summary = @Summary + (SELECT Email FROM #temp1 WHERE Rid = @CurrentRow1) + ' Inserted Member  Failed\r\n'
					 --SET @FailedCount = @FailedCount + 1;

					 SET @FailedSummary = @FailedSummary + (SELECT Email FROM #temp1 WHERE Rid = @CurrentRow1) + CHAR(13)
                        SET @FailedCount = @FailedCount + 1

				END


            SET @CurrentRow1 = @CurrentRow1 + 1
        END

	--SET @Summary = @Summary + CHAR(13) + 'Total Success: ' + CAST(@successCount AS VARCHAR) + CHAR(13) + 'Total Failed: ' + CAST(@FailedCount AS VARCHAR);

SET @Summary = 
'Members added successfully:' + CHAR(13) + CHAR(10) +
@InsertedSummary + CHAR(13) + CHAR(10) +
'Member addition failed:' + CHAR(13) + CHAR(10) +
@FailedSummary + CHAR(13) + CHAR(10) +
'Final Summary:' + CHAR(13) + CHAR(10) +
'Success Count: ' + CAST(@successCount AS VARCHAR) + CHAR(13) + CHAR(10) +
'Failed Count: ' + CAST(@FailedCount AS VARCHAR);

        DROP TABLE #temp1

        SELECT @QStatus = 1;
    END

    -- COMMIT TRANSACTION
    -- END TRY

    -- BEGIN CATCH
    -- ROLLBACK TRANSACTION
    -- SELECT @QStatus = -1;
    -- END CATCH
END






