CREATE PROCEDURE [dbo].[NewsGetListByVariable]
	 (@ChapterId bigint
	, @Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output
	 ,@MemberId bigint
	 ,@Type nvarchar(512))
AS
BEGIN
	
	SET NOCOUNT ON;
	
	--BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,NewsId bigint
				,Title nvarchar(256)
				,NewsText nvarchar(max)
				,ImageUrl nvarchar(256)
				,PostDate datetime
				,OrderNo int
				,IsActive bit
				,UpdatedBy nvarchar(64)
				,UpdatedTime datetime
				,ChapterId bigint
				,ExpiryDate datetime)
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
	SELECT 
	             E.NewsId
	            ,E.Title
	            ,E.NewsText
	            ,E.ImageUrl
	            ,E.PostDate
	            ,E.OrderNo
	            ,E.IsActive
	            ,E.UpdatedBy
	            ,E.UpdatedTime
				,E.ChapterId
				,E.ExpiryDate
	            FROM News E
				--LEFT JOIN ChapterNews CN ON CN.NewsId = E.NewsId
				 WHERE E.NewsId <> 0'



		--IF(@ChapterId <> 0)
  --  BEGIN
		--SET @Query = @Query + ' AND CN.ChapterId= '+CAST(@ChapterId as nvarchar(250))
  --  END


	IF(@ChapterId <> 0)
			BEGIN
			    IF(@ChapterId = 1000)
				BEGIN
				SET @Query=@Query + 'AND E.NewsId NOT in (Select NewsId from ChapterNews)'
				END
				ELSE 
				BEGIN
				SET @Query=@Query + 'AND E.NewsId in (Select NewsId from ChapterNews Where ChapterId = ' + CAST(@ChapterId AS nvarchar(30))+')'
				END
			END  




		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  E.Title LIKE ''%' + @Search + '%'''
		END

		IF(@Type <> '')
		BEGIN
			SET @Query = @Query + ' AND  E.UpdatedBy LIKE ''%' + @Type + '%'''
		END

		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		Print  @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	--END TRY
    
 --   BEGIN CATCH  
 --      SELECT @Total = -1; 		   
 --   END CATCH   
END








