/****** Object:  StoredProcedure [dbo].[NewsInsert]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[NewsInsert]
    (@NewsId bigint
	,@Title nvarchar(256)
	,@NewsText nvarchar(max)
	,@ImageUrl nvarchar(256) output
	,@PostDate datetime
	,@OrderNo int
	,@IsActive bit
	,@UpdatedBy nvarchar(64)
	,@UpdatedTime datetime
	,@QStatus int output
	,@ChapterIds nvarchar(2048)
	,@ExpiryDate datetime)  
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
   BEGIN TRY
    BEGIN TRANSACTION
		IF((SELECT COUNT(*) FROM News WHERE NewsId = @NewsId) = 0)
			BEGIN
				INSERT INTO News VALUES
					(@Title
					,@NewsText
					,NULL
					,@PostDate
					,@OrderNo
					,@IsActive
					,@UpdatedBy
					,@UpdatedTime
					,NULL
					,@ExpiryDate)	
			
				SET @NewsId=SCOPE_IDENTITY()			
			
				SELECT @QStatus = 1;	
			END
		ELSE
			BEGIN
				UPDATE News
				   SET  Title=@Title,
					   NewsText=@NewsText,
					   PostDate=@PostDate,
					   OrderNo=@OrderNo ,
					   UpdatedBy=@UpdatedBy,
					   UpdatedTime=@UpdatedTime,
					   ExpiryDate=@ExpiryDate
				 WHERE NewsId = @NewsId
		 		 
				 SELECT @QStatus = 2;	
			END
	    IF(@ImageUrl <> 'NA')
			BEGIN
				UPDATE News
				   SET  ImageUrl= CAST(@NewsId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@Title, '^a-z0-9') + '.' + @ImageUrl
				   WHERE NewsId = @NewsId	
			  
				  SELECT @ImageUrl = CAST(@NewsId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@Title, '^a-z0-9') + '.' + @ImageUrl	
			END	
		ELSE
			BEGIN
			  SELECT @ImageUrl=''
			END	

		IF(@ChapterIds<>'')
	    BEGIN
			DECLARE @RowCount1 AS int
			DECLARE @CurrentRow1 AS int	
			DECLARE @table1 TABLE (RowID int not null primary key identity(1,1), col1 int )  
			INSERT into @table1 (col1) SELECT part FROM SplitString(@ChapterIds)

			DELETE ChapterNews WHERE NewsId = @NewsId

			IF((Select Count(*) From @table1) <> 0)
				BEGIN
					Set @RowCount1 = (Select Count(*) From @table1)
					SET @CurrentRow1 = 1
					WHILE @CurrentRow1 < @RowCount1 + 1 
					BEGIN
						INSERT INTO ChapterNews VALUES 
						(@NewsId,(select col1 from @table1 where RowID = @CurrentRow1))
						SET @CurrentRow1 = @CurrentRow1 + 1
				    END
		        END 
         END

    COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH    
    ROLLBACK TRANSACTION
		SELECT @QStatus = -1;    
    END CATCH    
END





















