CREATE PROCEDURE [dbo].[NewsLetterGetListByVariable]
	 (@PageNo int
     ,@Items int
     ,@Search nvarchar(126)
     ,@Total int output
     ,@Sort nvarchar(126))
AS
BEGIN
	
	SET NOCOUNT ON;
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,LetterId bigint 
				,EmailId nvarchar(128)
				,RegisteredDate datetime
				,IsActive bit)
	
	SELECT @Start = (@PageNo - 1) * @Items 
	    
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
		 SELECT  N.LetterId 
				,N.EmailId 
				,N.RegisteredDate
				,N.IsActive FROM NewsLetters N WHERE N.LetterId <> 0 '
	
	IF(@Search <> '')
    BEGIN
		SET @Query = @Query + ' AND  EmailId LIKE ''%' + @Search + '%'''
    END
	
	IF(@Sort <> '')
	BEGIN
		SET @Query = @Query + ' ORDER BY ' + @Sort
	END
	
	EXEC sp_ExecuteSQL @Query;
	
	SELECT @Total = COUNT(Rid) from #temp 
			
	SELECT Rid
		  	,LetterId 
			,EmailId
			,RegisteredDate
			,IsActive FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
	DROP TABLE #temp

END









