CREATE PROCEDURE [dbo].[NewsLetterInsert]
    (@LetterId bigint 
	,@EmailId nvarchar(128)
	,@RegisteredDate datetime
	,@IsActive bit 
	,@QStatus int output)  
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
    
		 IF((SELECT COUNT(*) FROM NewsLetters WHERE LetterId = @LetterId) = 0)
		    BEGIN
				INSERT INTO NewsLetters VALUES
						(@EmailId
						,@RegisteredDate
						,@IsActive)					
				SELECT @QStatus = 1;
		    END
		ELSE 
			BEGIN
			IF((SELECT COUNT(*) FROM NewsLetters WHERE LetterId <> @LetterId) = 0)
				BEGIN
					UPDATE NewsLetters
					  SET EmailId         = @EmailId
						 ,RegisteredDate  = @RegisteredDate
						 ,IsActive        = @IsActive

					 WHERE LetterId = @LetterId
			 		 
					 SELECT @QStatus = 2;
			 
				 END
		    END
		 COMMIT TRANSACTION
	     END TRY
    
    BEGIN CATCH 
	   ROLLBACK TRANSACTION 
       SELECT @QStatus = -1; 
    END CATCH   
    
END









