CREATE PROCEDURE [dbo].[NewsLetterUpdateStatus]
       (@LetterId bigint
       ,@QStatus bigint OUTPUT)
        
AS
BEGIN

	SET NOCOUNT ON;
	
	BEGIN TRY
		IF((SELECT IsActive FROM NewsLetters WHERE LetterId = @LetterId) = 'True')
			BEGIN
			
			UPDATE NewsLetters SET IsActive = 'False' WHERE LetterId = @LetterId
			END
			
		ELSE
		
			BEGIN
			UPDATE NewsLetters SET IsActive = 'True' WHERE LetterId = @LetterId
			END	
			
	    SELECT @QStatus = 1;
	
	END TRY
    BEGIN CATCH
    
		 SELECT @QStatus = -1;
		 
    END CATCH  
    
END




















