create PROCEDURE [dbo].[NotificationGetListByVariable]
	 (@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
	SET NOCOUNT ON;
	
	--BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    -- Insert statements for procedure here
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1),
				 NotificationID BIGINT,
		         Title NVARCHAR(512),
		         Body NVARCHAR(512),
		         ActivityTobeopen NVARCHAR(512),
		         [Values] NVARCHAR(512),       -- FIXED
		         UpdatedBy NVARCHAR(512),
		         UpdatedTime NVARCHAR(512),
		         ImageUrl NVARCHAR(512),
		          TotalCount BIGINT,
              )
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
      n.NotificationID,
      n.Title,
      n.Body,
      n.ActivityTobeopen,
      n.[Values],
      n.UpdatedBy,
      n.UpdatedTime,
      n.ImageUrl,
	   (
        SELECT COUNT(NU.NotificationID)
        FROM Notification N
        LEFT JOIN NotificationUser NU 
            ON N.NotificationID = NU.NotificationID
      ) AS TotalCount

FROM Notification n
WHERE n.NotificationID <> 0 '
		

		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  Title LIKE ''%' + @Search + '%'''
		END
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	--END TRY
    
 --   BEGIN CATCH  
 --      SELECT @Total = -1; 		   
 --   END CATCH   
END
















































