/****** Object:  StoredProcedure [dbo].[PatrikaRegistrationsGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROCEDURE [dbo].[PatrikaRegistrationsGetListByVariable]  
  (@ChapterId bigint  
  ,@Search nvarchar(126)  
     ,@Sort nvarchar(126)  
  ,@PageNo int  
     ,@Items int  
     ,@Total int output)  
AS  
BEGIN  
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
   
 SET NOCOUNT ON;  
   
 BEGIN TRY  
   
 DECLARE @Start int, @End INT ;  
 DECLARE @Query nvarchar(max);  
      
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)  
    ,PatrikaId bigint  
    ,ChapterId bigint  
    ,Title nvarchar(256)  
    ,BannerUrl nvarchar(128)  
    ,DocumentUrl nvarchar(max)  
    ,OrderNo int  
    ,IsActive bit  
    ,Field1 nvarchar(max)  
    ,Field2 nvarchar(max)  
    ,Field3 nvarchar(max)  
    ,InsertedBy nvarchar(64)  
    ,InsertedTime datetime  
    ,UpdatedBy nvarchar(64)  
    ,UpdatedTime datetime  
    ,ChapterName nvarchar(512))  
      
    SELECT @Start = (@PageNo - 1) * @Items    
      
    SELECT @End = @Start + @Items   
   
  SET @Query = 'INSERT INTO #temp SELECT   
      E.PatrikaId  
     ,E.ChapterId  
     ,E.Title  
     ,E.BannerUrl  
     ,E.DocumentUrl  
     ,E.OrderNo  
     ,E.IsActive  
     ,E.Field1  
     ,E.Field2  
     ,E.Field3  
     ,E.InsertedBy  
     ,E.InsertedTime  
     ,E.UpdatedBy  
     ,E.UpdatedTime  
     ,C.ChapterName  
      FROM PatrikaRegistrations E  
      Left JOIN Chapters C ON C.ChapterId = E.ChapterId  
      WHERE E.PatrikaId <> 0'  
    
  IF(@ChapterId <> 0)  
  BEGIN  
   SET @Query=@Query + 'AND E.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))  
  END    
  IF(@Search <> '')  
  BEGIN  
   SET @Query = @Query + ' AND  E.Title LIKE ''%' + @Search + '%'''  
  END  
  IF(@Sort <> '')  
  BEGIN  
   SET @Query = @Query + ' ORDER BY E.OrderNo DESC'  
  END  
   
  EXEC sp_ExecuteSQL @Query;  
    
  SELECT @Total = COUNT(Rid) from #temp   
      
  SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End  
   
  DROP TABLE #temp  
  
 END TRY  
      
    BEGIN CATCH    
       SELECT @Total = -1;        
    END CATCH     
END  
  
  
  
  
  

