CREATE PROCEDURE [dbo].[PatrikaRegistrationsInsert]  
 (@PatrikaId bigint  
 ,@ChapterId bigint  
 ,@Title nvarchar(256)  
 ,@BannerUrl nvarchar(1024) output  
 ,@DocumentUrl nvarchar(max)  
 ,@OrderNo int  
 ,@IsActive bit  
 ,@Field1 nvarchar(max)  
 ,@Field2 nvarchar(max)  
 ,@Field3 nvarchar(max)  
 ,@InsertedBy nvarchar(64)  
 ,@InsertedTime datetime  
 ,@UpdatedBy nvarchar(64)  
 ,@UpdatedTime datetime  
 ,@QStatus int output)    
          
AS  
BEGIN  
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
   
 SET NOCOUNT ON;  
  
    IF((SELECT COUNT(*) FROM PatrikaRegistrations WHERE PatrikaId = @PatrikaId) = 0)  
  BEGIN  
   INSERT INTO PatrikaRegistrations VALUES  
    (@ChapterId  
    ,@Title  
    ,NULL  
    ,@DocumentUrl  
    ,@OrderNo  
    ,@IsActive  
    ,@Field1  
    ,@Field2  
    ,@Field3  
    ,@InsertedBy  
    ,@InsertedTime  
    ,@UpdatedBy  
    ,@UpdatedTime)  
     
   SET @PatrikaId=SCOPE_IDENTITY()    
     
   SELECT @QStatus = 1;   
  END  
 ELSE  
  BEGIN  
   UPDATE PatrikaRegistrations SET  ChapterId=@ChapterId,  
            Title=@Title,  
            DocumentUrl=@DocumentUrl,  
            Field1 = @Field1,  
            OrderNo=@OrderNo,  
            UpdatedBy=@UpdatedBy,  
            UpdatedTime=@UpdatedTime  
            WHERE PatrikaId = @PatrikaId  
        
    SELECT @QStatus = 2;   
      END  
   
  IF(@BannerUrl <> '')  
   BEGIN  
    UPDATE PatrikaRegistrations SET  BannerUrl= CAST(@PatrikaId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@Title, '^a-z0-9') + '.' + @BannerUrl WHERE PatrikaId = @PatrikaId   
       
    SELECT @BannerUrl = CAST(@PatrikaId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@Title, '^a-z0-9') + '.' + @BannerUrl   
   END   
  ELSE  
   BEGIN  
     SELECT @BannerUrl=''  
   END     
END  
  
  
  
  
  
  
  
  

