CREATE PROCEDURE [dbo].[PatrikaRegistrationsUpdateStatus]  
    (@PatrikaId bigint  
    ,@QStatus int output)    
          
AS  
BEGIN  
  
 -- SET NOCOUNT ON added to prevent extra result sets from  
 SET NOCOUNT ON;  
      
    BEGIN TRY      
    BEGIN TRANSACTION  
      
  IF((SELECT IsActive FROM PatrikaRegistrations WHERE PatrikaId = @PatrikaId) = 1)  
   BEGIN  
    UPDATE PatrikaRegistrations SET IsActive = 0 WHERE PatrikaId = @PatrikaId  
   END  
  ELSE  
   BEGIN  
    UPDATE PatrikaRegistrations SET IsActive = 1 WHERE PatrikaId = @PatrikaId  
   END    
  SELECT @QStatus = 1;  
    
 COMMIT TRANSACTION  
    END TRY  
    BEGIN CATCH  
      
         ROLLBACK TRANSACTION  
   SELECT @QStatus = -1;  
     
    END CATCH  
       
END  
  
  
  
  
  
  
  
  
  

