				UPDATE PaymentSettings SET IsActive = 0 WHERE PaymentSettingId =@PaymentSettingId 
			END
		
		SELECT @QStatus = 1;
		
    END TRY
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH
	
	END






















