create PROCEDURE [dbo].[PaymentSettingsDetails]
    (@PaymentMethod nvarchar(512)
    ,@QStatus int OUTPUT)  
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
    BEGIN TRY
		IF(@PaymentMethod <> '')
			BEGIN			
				SELECT * FROM PaymentSettings PS LEFT JOIN CurrencyCodes CC ON CC.CurrencyCodeId=PS.CurrencyCodeId 
				INNER JOIN PaymentMethods PM ON PM.PaymentMethodId=PS.PaymentMethodId WHERE PM.PaymentMethod=@PaymentMethod AND PS.IsActive=1
			END
		
        SELECT @QStatus = 1;
    END TRY
    
    BEGIN CATCH    
		SELECT @QStatus = -1;    
    END CATCH
    
END




































