/****** Object:  StoredProcedure [dbo].[PaymentSettingsGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PaymentSettingsGetListByVariable]
     @search nvarchar(500)
    ,@PageNo int
    ,@ItemsPerPage int
    ,@Total int output
        
AS
BEGIN
	
	 DECLARE @Query nvarchar(max);
	 DECLARE @Start int, @End INT ;
    
     SET NOCOUNT ON;

	 BEGIN TRY
	 CREATE TABLE #temp(RId INT PRIMARY KEY IDENTITY(1,1)
			,PaymentSettingId int
			,PaymentMethodId bigint
			,PaymentMethod nvarchar(256)
			,PaymentUrl nvarchar(256)
			,PaymentEmail nvarchar(128)
			,PaymentPassword nvarchar(256)
			,CurrencyCodeId bigint
			,CurrencyCode nvarchar(256)
			,SuccessUrl nvarchar(256)
			,CancelUrl nvarchar(256)
			,NotifyUrl nvarchar(256)
			,TokenNo nvarchar(128)
			,AccountType nvarchar(30)
			,IsActive bit
			,Mode bit)
      
			SELECT @Start = (@PageNo - 1) * @ItemsPerPage     
			SELECT @End = @Start + @ItemsPerPage 
    
			SET @Query = 'INSERT INTO #temp SELECT
					 PS.PaymentSettingId 
					,PS.PaymentMethodId 
					,PM.PaymentMethod
					,PS.PaymentUrl 
					,PS.PaymentEmail 
					,PS.PaymentPassword 
					,PS.CurrencyCodeId 
					,CC.CurrencyCode
					,PS.SuccessUrl 
					,PS.CancelUrl 
					,PS.NotifyUrl 
					,PS.TokenNo 
					,PS.AccountType 
					,PS.IsActive
					,PS.Mode
			        FROM PaymentSettings PS left JOIN CurrencyCodes CC ON CC.CurrencyCodeId=PS.CurrencyCodeId 
				    INNER JOIN PaymentMethods PM ON PM.PaymentMethodId=PS.PaymentMethodId WHERE PS.PaymentSettingId != 0' 
       
		    IF(@search<>'')
				BEGIN
					SET @Query=@Query + ' AND PM.PaymentMethod LIKE ''%' + @search + '%'''
				END

			EXEC sp_ExecuteSQL @Query;

			SELECT @Total = COUNT(RId) from #temp
		
			SELECT   RId
					,PaymentSettingId 
					,PaymentMethodId 
					,PaymentMethod
					,PaymentUrl 
					,PaymentEmail 
					,PaymentPassword 
					,CurrencyCodeId 
					,CurrencyCode
					,SuccessUrl 
					,CancelUrl 
					,NotifyUrl 
					,TokenNo 
					,AccountType 
					,IsActive
					,Mode
			        FROM #temp WHERE RId > @Start AND RId <=@End       
		   DROP TABLE #temp  
	 END TRY

	 BEGIN CATCH
	    SELECT @Total=-1;
	 END CATCH

END










