CREATE PROCEDURE [dbo].[PerformanceCategoryGetListByVariable]  
     (@PageNo int  
     ,@Items int  
     ,@Search nvarchar(126)  
     ,@Total int output  
     ,@Sort nvarchar(126))  
AS  
BEGIN  
  
 SET NOCOUNT ON;  
   
 DECLARE @Start int, @End INT ;  
 DECLARE @Query nvarchar(max);  
      
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)  
    ,PerformanceCategoryID bigint  
    ,CategoryName   nvarchar(1024)  
    ,MemberAmount   decimal  
    ,NonMemberAmount  decimal  
    ,OrderNo    int  
    ,IsActive    bit  
    ,InsertedBy    nvarchar(128)  
    ,InsertedDate   datetime  
    ,UpdatedBy    nvarchar(128)  
    ,UpdatedDate   datetime)  
  
   
 SELECT @Start = (@PageNo - 1) * @Items       
 SELECT @End = @Start + @Items   
   
 SET @Query = 'INSERT INTO #temp   
   SELECT  PC.PerformanceCategoryID  
    ,PC.CategoryName  
    ,PC.MemberAmount  
    ,PC.NonMemberAmount  
    ,PC.OrderNo  
    ,PC.IsActive  
    ,PC.InsertedBy  
    ,PC.InsertedDate  
    ,PC.UpdatedBy  
    ,PC.UpdatedDate  
     
  FROM PerformanceCategory PC   
  WHERE PC.PerformanceCategoryID <> 0 '  
   
   
 IF(@Search <> '')  
    BEGIN  
  SET @Query = @Query + ' AND  PC.CategoryName LIKE ''%' + @Search + '%'''  
    END  
   
 IF(@Sort <> '')  
 BEGIN  
  SET @Query = @Query + ' ORDER BY ' + @Sort  
 END  
   
    EXEC sp_ExecuteSQL @Query;  
   
 SELECT @Total = COUNT(Rid) from #temp   
     
 SELECT *  FROM #temp WHERE Rid > @Start AND  Rid <= @End  
   
   DROP TABLE #temp  
  
END  
  
  
  
  
  
  
  

