CREATE PROCEDURE [dbo].[PerformanceCategoryInsert]  
    (@PerformanceCategoryID bigint  
 ,@CategoryName   nvarchar(1024)  
 ,@MemberAmount   decimal  
 ,@NonMemberAmount  decimal  
 ,@OrderNo    int  
 ,@IsActive    bit  
 ,@InsertedBy   nvarchar(128)  
 ,@InsertedDate   datetime  
 ,@UpdatedBy    nvarchar(128)  
 ,@UpdatedDate   datetime  
 ,@QStatus    int output)    
          
AS  
BEGIN  
   
 SET NOCOUNT ON;  
      
    BEGIN TRY  
    BEGIN TRANSACTION  
      
  IF((SELECT COUNT(*) FROM PerformanceCategory WHERE PerformanceCategoryID = @PerformanceCategoryID) = 0)  
   BEGIN  
    
    INSERT INTO PerformanceCategory VALUES  
        (@CategoryName  
      ,@MemberAmount  
      ,@NonMemberAmount  
      ,@OrderNo  
      ,@IsActive  
      ,@InsertedBy  
      ,@InsertedDate  
      ,@UpdatedBy  
      ,@UpdatedDate)  
      SET @PerformanceCategoryID=SCOPE_IDENTITY()   
  
      SELECT @QStatus = 1;  
       
   END  
  ELSE   
   BEGIN  
    UPDATE PerformanceCategory  
       SET    
      CategoryName   = @CategoryName,  
      MemberAmount   = @MemberAmount,  
      NonMemberAmount   = @NonMemberAmount,  
      OrderNo     = @OrderNo,  
      InsertedBy    = @InsertedBy,  
      InsertedDate   = @InsertedDate,  
      UpdatedBy    = @UpdatedBy,  
      UpdatedDate    = @UpdatedDate  
  
     WHERE PerformanceCategoryID = @PerformanceCategoryID  
         
     SELECT @QStatus = 2;  
      
    END  
     
  COMMIT TRANSACTION  
    END TRY  
      
    BEGIN CATCH    
      
  ROLLBACK TRANSACTION     
  SELECT @QStatus = -1;      
    
    END CATCH     
      
END  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
