CREATE PROCEDURE [dbo].[PhotoCategoriesGetListByVariable]
	 (@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
	 ,@ChapterId bigint
     ,@Total int output)
AS
BEGIN
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
		DECLARE @Start int, @End INT ;
		DECLARE @Query nvarchar(max);
    
		CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
					,PhotoCategoryId bigint
					,CategoryName nvarchar(512)
					,Year bigint
					,UpdatedBy nvarchar(512)
					,UpdatedTime datetime
					,PhotosCount bigint)

				
		SELECT @Start = (@PageNo - 1) * @Items  
	   
		SELECT @End = @Start + @Items 
	
		SET @Query = 'INSERT INTO #temp SELECT
					 PC.PhotoCategoryId
					,PC.CategoryName
					,PC.Year
					,PC.UpdatedBy
					,PC.UpdatedTime
					,(SELECT COUNT(*) FROM Photos P WHERE P.PhotoCategoryId = PC.PhotoCategoryId) AS PhotosCount
					FROM PhotoCategories PC	WHERE PC.PhotoCategoryId <> 0 '
		
		
		IF(@ChapterId <> 0)
	BEGIN
		SET @Query=@Query + 'AND PC.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))
	END  
		
		
		
		
		IF(@Search <> '')
		
		BEGIN
			SET @Query = @Query + ' AND  PC.CategoryName LIKE ''%' + @Search + '%'''
		END

		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END







































