CREATE PROCEDURE [dbo].[PhotosGetListByVariable]
	 (@PhotoCategoryId bigint
     ,@PageNo int
     ,@Items int
     ,@Search nvarchar(126)
     ,@Total int output
     ,@Sort nvarchar(126))
AS
BEGIN
	
	SET NOCOUNT ON;
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,PhotoId bigint
				,PhotoCategoryId bigint
				,ImageUrl nvarchar(128)
				,AlbumLink nvarchar(max) 
				,ImageDescription nvarchar(1024)
				,DefaultImage bit
				,DisplayOrder int
				,IsActive bit
				,IsHome bit				
				,UpdatedBy nvarchar(64)
				,UpdatedTime datetime
				,CategoryName nvarchar(256))
	
	SELECT @Start = (@PageNo - 1) * @Items     
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
		 SELECT  P.PhotoId 
				,P.PhotoCategoryId
				,P.ImageUrl 
				,P.AlbumLink
				,P.ImageDescription 
				,P.DefaultImage
				,P.DisplayOrder
				,P.IsActive
				,P.IsHome				
				,P.UpdatedBy
				,P.UpdatedTime
				,PC.CategoryName
				FROM Photos P  
				INNER JOIN PhotoCategories PC ON PC.PhotoCategoryId = P.PhotoCategoryId
				WHERE P.PhotoId <> 0 '
	
	IF(@PhotoCategoryId <> 0)
    BEGIN
		SET @Query = @Query + ' AND P.PhotoCategoryId= '+CAST(@PhotoCategoryId as nvarchar(250))
    END
	
	IF(@Search <> '')
    BEGIN
		SET @Query = @Query + ' AND  p.Title LIKE ''%' + @Search + '%'''
    END
	
	IF(@Sort <> '')
	BEGIN
		SET @Query = @Query + ' ORDER BY ' + @Sort
	END
	
    EXEC sp_ExecuteSQL @Query;
	
	SELECT @Total = COUNT(Rid) from #temp 
			
	SELECT *  FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
	DROP TABLE #temp

END





































