CREATE PROCEDURE [dbo].[PhotosImageSettings]
    (@PhotosSettingsid bigint
	,@Eventsize nvarchar(512)
	,@Photosize  nvarchar(512)
	,@Sponsorsize nvarchar(512)
	,@Bannersize nvarchar(512)
	,@Newssize nvarchar(512)
	,@committeesize nvarchar(512)
	,@Field1   nvarchar(512)
	,@Field2 nvarchar(512)
	,@Field3 nvarchar(512)
	,@InsertedBy   nvarchar(512)
	,@InsertedDate datetime
	,@UpdatedBy    nvarchar(512)
	,@UpdatedDate  datetime  
	,@QStatus int output 
	,@IsCultural nvarchar(256)
	,@IsSports nvarchar(256)
	,@TimeZone nvarchar(512)
	,@IsHelpDocument nvarchar(256)
	,@IsFeaturesDocument nvarchar(256))  
        
AS
BEGIN

	
	SET NOCOUNT ON;
	BEGIN TRY
	BEGIN TRANSACTION
		IF((SELECT COUNT(*) FROM PhotosSettings WHERE PhotosSettingsid = @PhotosSettingsid) = 1)
			BEGIN
				UPDATE PhotosSettings
				   SET   
					Eventsize=@Eventsize
				   ,Photosize=@Photosize
				   ,Sponsorsize=@Sponsorsize
					,Bannersize=@Bannersize
				   ,Newssize=@Newssize
				   ,committeesize=@committeesize
				   ,Field1=@Field1
				   ,Field2=@Field2
				   ,Field3=@Field3
				   ,InsertedBy=@InsertedBy
				   ,InsertedDate =@InsertedDate
				   ,UpdatedBy=@UpdatedBy
				   ,UpdatedDate =@UpdatedDate
				   ,IsCultural=@IsCultural
				   ,IsSports=@IsSports
				   ,TimeZone=@TimeZone
				   ,IsHelpDocument=@IsHelpDocument
				   ,IsFeaturesDocument=@IsFeaturesDocument

				 WHERE PhotosSettingsid = @PhotosSettingsid				
				
				SELECT @QStatus = 2;	
			END
		ELSE
			BEGIN
				 INSERT INTO PhotosSettings VALUES
					(
					  @Eventsize 
					 ,@Photosize
					 ,@Sponsorsize 
					 ,@Bannersize 
					 ,@Newssize 
					 ,@committeesize 
					 ,@Field1  
					 ,@Field2 
					 ,@Field3 
					 ,@InsertedBy   
					 ,@InsertedDate 
					 ,@UpdatedBy    
					 ,@UpdatedDate
					  ,@IsCultural
					   ,@IsSports
					   ,@TimeZone
					   ,@IsHelpDocument
					   ,@IsFeaturesDocument)	
			 		 
				 SELECT @QStatus = 1;	
			END
    COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH    
    ROLLBACK TRANSACTION
		SELECT @QStatus = -1;    
    END CATCH    
END


















