/****** Object:  StoredProcedure [dbo].[PhotosInsert]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PhotosInsert]
      (@PhotoId bigint
      ,@PhotoCategoryId bigint
      ,@ImageUrl nvarchar(128) output
      ,@ImageDescription nvarchar(1024)
      ,@DefaultImage bit
      ,@DisplayOrder int
      ,@IsActive bit
      ,@IsHome bit
      ,@UpdatedBy nvarchar(64)
      ,@UpdatedTime datetime
	  ,@AlbumLink nvarchar(max) 
	  ,@QStatus int output)  
        
AS
BEGIN

	
	SET NOCOUNT ON;
    
    BEGIN TRY
	BEGIN TRANSACTION
		DECLARE @CategoryName nvarchar(756)
		SET @CategoryName=(SELECT CategoryName FROM PhotoCategories WHERE PhotoCategoryId=@PhotoCategoryId) 
    
		IF((SELECT COUNT(*) FROM Photos WHERE PhotoId = @PhotoId) = 0)
		  BEGIN
			IF(@ImageUrl <> 'NA')
				BEGIN
					INSERT INTO Photos VALUES
						  (@PhotoCategoryId 
						  ,NULL 
						  ,@ImageDescription
						  ,@DefaultImage
						  ,@DisplayOrder
						  ,1
						  ,@IsHome
						  ,@UpdatedBy
						  ,@UpdatedTime
						  ,@AlbumLink)	  
						  SET @PhotoId=SCOPE_IDENTITY();
			  
						   UPDATE Photos
						   SET  ImageUrl= CAST(@PhotoId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@CategoryName, '^a-z0-9') + '.' + @ImageUrl
						   WHERE PhotoId = @PhotoId	
			  
					   SELECT @ImageUrl = CAST(@PhotoId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@CategoryName, '^a-z0-9') + '.' + @ImageUrl
				END
			ELSE
				BEGIN
				   SELECT @ImageUrl=''
				END
				SELECT @QStatus = 1;	
		  END
		ELSE 
		  BEGIN
			 IF(@ImageUrl <> 'NA')
				BEGIN
					UPDATE Photos
					   SET 
						  PhotoCategoryId=@PhotoCategoryId
						  ,ImageUrl= CAST(@PhotoId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@CategoryName, '^a-z0-9') + '.' + @ImageUrl  
						  ,ImageDescription=@ImageDescription
						  ,DefaultImage=@DefaultImage
						  ,DisplayOrder=@DisplayOrder
						  ,IsHome=@IsHome
						  ,UpdatedBy=@UpdatedBy
						  ,UpdatedTime=@UpdatedTime
						  ,AlbumLink=@AlbumLink	
					 WHERE PhotoId = @PhotoId		
					 SELECT @ImageUrl = CAST(@PhotoId AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@CategoryName, '^a-z0-9') + '.' + @ImageUrl 
				 END
			ELSE
				 BEGIN
				 UPDATE Photos
				   SET 
					  PhotoCategoryId=@PhotoCategoryId
					  ,ImageDescription=@ImageDescription
					  ,DefaultImage=@DefaultImage
					  ,DisplayOrder=@DisplayOrder
					  ,IsHome=@IsHome
					  ,UpdatedBy=@UpdatedBy
					  ,UpdatedTime=@UpdatedTime
					  ,AlbumLink=@AlbumLink	
				 WHERE PhotoId = @PhotoId	
				 SELECT @ImageUrl = ''
				 END
			 SELECT @QStatus = 2;
		 
		END
	  COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH 
		ROLLBACK TRANSACTION     
		SELECT @QStatus = -1;
    END CATCH
END






































