/****** Object:  StoredProcedure [dbo].[PromoCodesGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PromoCodesGetListByVariable]  
	  (@StartDate nvarchar(128)
	  ,@EndDate nvarchar(128)
	  ,@Search nvarchar(128)
      ,@Sort nvarchar(126)
	  ,@PageNo int
      ,@Items int
      ,@Total int output)
AS
BEGIN

	SET NOCOUNT ON;
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1),
	                    PromoCodeId bigint,
						PromoCode nvarchar(128),
						Message nvarchar(2048),
						StartDate datetime,
						EndDate datetime,
						NoOfUsers bigint,
						MinimumOrderAmount decimal(15,2),
						Discount decimal(15,2),
						DiscountType nvarchar(128),
						MaxDiscountAmount decimal(15,2),
						RepeatUsage nvarchar(128),
						NoOfRepeatUsage bigint,
						Status nvarchar(128),
						IsActive bit,
						ServiceId bigint,
						Field1 nvarchar(512),
						Field2 nvarchar(512),
						Field3 nvarchar(512),
						InsertedBy nvarchar(512),
						InsertedDate datetime,
						UpdatedBy nvarchar(512),
						UpdatedDate datetime)
	
	SELECT @Start = (@PageNo - 1) * @Items     
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
		            SELECT
					        w.PromoCodeId,
							w.PromoCode,
							w.Message,
							w.StartDate,
							w.EndDate,
							w.NoOfUsers,
							w.MinimumOrderAmount,
							w.Discount,
							w.DiscountType,
							w.MaxDiscountAmount,
							w.RepeatUsage,
							w.NoOfRepeatUsage,
							w.Status,
							w.IsActive,
							w.ServiceId,
							w.Field1,
							w.Field2,
							w.Field3,
							w.InsertedBy,
							w.InsertedDate,
							w.UpdatedBy,
							w.UpdatedDate
						    FROM PromoCodes  W   WHERE W.PromoCodeId <> 0 '
	
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND (W.PromoCode LIKE ''%' + @Search + '%'' OR W.Message  LIKE ''%' + @Search + '%'')'
		END

		IF(@StartDate <> '' and @EndDate <> '')
		BEGIN
			SET @Query = @Query + ' AND Convert(Date, convert(varchar, convert(datetime, w.StartDate, 103), 101)) >= Convert(Date, convert(varchar, convert(datetime, '''+@StartDate+''', 103), 101)) and  Convert(Date, convert(varchar, convert(datetime, w.EndDate, 103), 101)) <= Convert(Date, convert(varchar, convert(datetime, '''+@EndDate+''', 103), 101)) '
		END

		ELSE IF(@StartDate <> '' and @EndDate = '')
		BEGIN
			SET @Query = @Query + ' AND Convert(Date, convert(varchar, convert(datetime, w.StartDate, 103), 101)) >= Convert(Date, convert(varchar, convert(datetime, '''+@StartDate+''', 103), 101)) '
		END

		ELSE IF(@StartDate = '' and @EndDate <> '')
		BEGIN
			SET @Query = @Query + ' AND Convert(Date, convert(varchar, convert(datetime, w.EndDate, 103), 101)) <= Convert(Date, convert(varchar, convert(datetime, '''+@EndDate+''', 103), 101)) '
		END

		IF(@Sort <> '')
		BEGIN
