  CREATE PROCEDURE [dbo].[PromoCodesInsert]
                       (@PromoCodeId bigint,
						@PromoCode nvarchar(128),
						@Message nvarchar(2048),
						@StartDate datetime,
						@EndDate datetime,
						@NoOfUsers bigint,
						@MinimumOrderAmount decimal(15,2),
						@Discount decimal(15,2),
						@DiscountType nvarchar(128),
						@MaxDiscountAmount decimal(15,2),
						@RepeatUsage nvarchar(128),
						@NoOfRepeatUsage bigint,
						@Status nvarchar(128),
						@IsActive bit,
						@ServiceId bigint,
						@Field1 nvarchar(512),
						@Field2 nvarchar(512),
						@Field3 nvarchar(512),
						@InsertedBy nvarchar(512),
						@InsertedDate datetime,
						@UpdatedBy nvarchar(512),
						@UpdatedDate datetime,
					    @QStatus int output)  
        
	AS
	BEGIN

	 SET NOCOUNT ON;

     BEGIN TRY
     BEGIN TRANSACTION
    
		IF((SELECT COUNT(*) FROM PromoCodes  WHERE PromoCodeId  = @PromoCodeId ) = 0)
			BEGIN
				INSERT INTO PromoCodes  VALUES
			           
							(@PromoCode,
							@Message,
							@StartDate,
							@EndDate,
							@NoOfUsers,
							@MinimumOrderAmount,
							@Discount,
							@DiscountType,
							@MaxDiscountAmount,
							@RepeatUsage,
							@NoOfRepeatUsage,
							@Status,
							@IsActive,
							@ServiceId,
							@Field1,
							@Field2,
							@Field3,
							@InsertedBy,
							@InsertedDate,
							@UpdatedBy,
							@UpdatedDate)
					 SELECT @QStatus = 1;
			END
		ELSE 
			BEGIN
				UPDATE PromoCodes
				   SET 
						PromoCode            = @PromoCode,
						Message              = @Message,
						StartDate            = @StartDate,
						EndDate              = @EndDate,
						NoOfUsers            = @NoOfUsers,
						MinimumOrderAmount   = @MinimumOrderAmount,
						Discount             = @Discount,
						DiscountType         = @DiscountType,
						MaxDiscountAmount    = @MaxDiscountAmount,
						RepeatUsage          = @RepeatUsage,
						NoOfRepeatUsage      = @NoOfRepeatUsage,
						Status               = @Status,
						IsActive             = @IsActive,
						ServiceId            = @ServiceId,
						Field1               = @Field1,
						Field2               = @Field2,
						Field3               = @Field3,
						InsertedBy           = @InsertedBy,
						InsertedDate         = @InsertedDate,
						UpdatedBy            = @UpdatedBy,
						UpdatedDate          = @UpdatedDate


				
						WHERE PromoCodeId = @PromoCodeId
				 SELECT @QStatus = 2;
			 END
	COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH  
		ROLLBACK TRANSACTION   
		SELECT @QStatus = -1;    
    END CATCH   
    
END







