/****** Object:  StoredProcedure [dbo].[PromocodeValidateAPI]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PromocodeValidateAPI] 
     @PromoCode NVARCHAR(128)
	,@Amount decimal(15,2)
	,@ServiceId bigint
	,@CustomerId bigint
    ,@QStatus int output    
        
AS
BEGIN

	BEGIN TRY
	SET NOCOUNT ON;

		IF((Select Count(*) from PromoCodes P Where P.PromoCode=@PromoCode COLLATE SQL_Latin1_General_CP1_CS_AS AND P.IsActive = 1 AND Convert(date, P.StartDate) <= Convert(date, Getdate()) AND Convert(date, P.EndDate) >= Convert(date, Getdate())) <> 0)
			BEGIN
				Declare @SId bigint, @NoofUsers bigint, @PromocodeId bigint, @RepeatUsage nvarchar(256), @NoOfRepeatUsage bigint
				Declare @MinAmount decimal(15,2), @MaxDiscount decimal(15,2)

			
			
			
				Select @SId = ServiceId, @MinAmount=MinimumOrderAmount, @MaxDiscount = MaxDiscountAmount, @NoofUsers=NoOfUsers, @PromocodeId=PromoCodeId, @RepeatUsage= RepeatUsage, @NoOfRepeatUsage=NoOfRepeatUsage From  PromoCodes P Where P.PromoCode=@PromoCode COLLATE SQL_Latin1_General_CP1_CS_AS AND P.IsActive = 1 AND Convert(date, P.StartDate) <= Convert(date, Getdate()) AND Convert(date, P.EndDate) >= Convert(date, Getdate())

				IF(@MinAmount<=@Amount AND (Select Count(*) From Bookings Where CouponCode = @PromoCode COLLATE SQL_Latin1_General_CP1_CS_AS) < @NoofUsers)
					BEGIN
						IF(@RepeatUsage = 'Yes')
							BEGIN
								IF((Select Count(*) From Bookings Where CustomerId = @CustomerId and CouponCode=@PromoCode COLLATE SQL_Latin1_General_CP1_CS_AS) < @NoOfRepeatUsage)
									BEGIN
										IF(@SId is null OR @SId = @ServiceId)
											BEGIN
												/*-- Promocode is Valid --*/
												Select 
												CAST(ROUND((MinimumOrderAmount * Discount / 100.0),2) AS DECIMAL(10,2)) as TotalDiscountAmount
												,* From  PromoCodes P Where P.PromoCodeId = @PromocodeId
												SELECT @QStatus = 1;
											END
										ELSE
											BEGIN 
												/*-- Promocode is not Valid for selected service --*/
												SELECT @QStatus = 2;
											END
									END
								ELSE
									BEGIN
										/*-- You already reached the Max Limit of Coupon Usage --*/
										SELECT @QStatus = 3;
									END
							END
						ELSE
							BEGIN
								IF((Select Count(*) From Bookings Where CustomerId = @CustomerId and CouponCode=@PromoCode COLLATE SQL_Latin1_General_CP1_CS_AS) = 0)
									BEGIN
										IF(@SId is null OR @SId = @ServiceId)
											BEGIN
												/*-- Promocode is Valid --*/
												Select 
												CAST(ROUND((MinimumOrderAmount * Discount / 100.0),2) AS DECIMAL(10,2)) as TotalDiscountAmount,
												* From  PromoCodes P Where P.PromoCodeId = @PromocodeId
												SELECT @QStatus = 1;
											END
										ELSE
											BEGIN 
												/*-- Promocode is not Valid for selected service --*/
												SELECT @QStatus = 2;
											END
									END
								ELSE
									BEGIN
										/*-- You already reached the Max Limit of Coupon Usage --*/
										SELECT @QStatus = 3;
									END
							END
					END 
				ELSE
					BEGIN 
						/*-- Order Amount Less than Min Amount / Expired --*/
						SELECT @QStatus = 4;
					END
			END 

		ELSE
			BEGIN
				/*-- Coupon Code Not Valid / Expired --*/
				SELECT @QStatus = 5;
			END
		
	 END TRY

	 BEGIN CATCH
		SELECT @QStatus = -1;
	 END CATCH
END 









