						,@FileName
						,@IsActive
						,@OrderNo
						,@InsertedBy
						,@InsertedDate
						,@UpdatedBy
						,@UpdatedDate)

		SET @QrCodeId=SCOPE_IDENTITY()	
				
		SELECT @QStatus = 1;	
	END
	ELSE
	BEGIN
