Create PROCEDURE [dbo].[RegistrationCategoriesDropDownGetListByVariable]
	 (@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	
	SET NOCOUNT ON;
	
	--BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    -- Insert statements for procedure here
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,RegistrationCategoriesCategoryId bigint
				,CategoryName nvarchar(128)
				,Title nvarchar(128)
				,OrderNo int
				,IsActive bit
				,Price decimal(15,2)
				,Field1 nvarchar(128)
				,Field2 nvarchar(128)
				,InsertedBy nvarchar(128)
				,InsertedTime Datetime
				)
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             DC.RegistrationCategoriesCategoryId
				,DC.CategoryName
	            ,DC.Title
	            ,DC.OrderNo
	            ,DC.IsActive 
				,DC.Price
				,DC.Field1
				,DC.Field2
				,DC.InsertedBy
				,DC.InsertedTime
				FROM RegistrationCategoriesDropDown DC
		WHERE DC.RegistrationCategoriesCategoryId <> 0'
		
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  DC.CategoryName LIKE ''%' + @Search + '%'''
		END
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	--END TRY
    
 --   BEGIN CATCH  
 --      SELECT @Total = -1; 		   
 --   END CATCH   
END











