CREATE PROCEDURE [dbo].[RegistrationCategoriesGetListByVariable] 
	 (@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
    
    CREATE TABLE #temp(RId INT PRIMARY KEY IDENTITY(1,1)
	            ,RegistrationCategoryId bigint
				,CategoryName nvarchar(512)
				,Type nvarchar(512)
				,Description nvarchar(Max)
				,OrderNo int
				,IsActive bit
				,InstertedBy nvarchar(512)
				,InsertedDate datetime
				,UpdatedBy nvarchar(512)
				,UpdatedDate datetime
				,Form1Count int
				,Form2Count int
				,Form3Count int
				,Form4Count int
				,Form5Count int
				,Form6Count int)
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
	SELECT
			     RC.RegistrationCategoryId 
			    ,RC.CategoryName
				,RC.Type
				,RC.Description
				,RC.OrderNo
				,RC.IsActive	
				,RC.InstertedBy
				,RC.InsertedDate
				,RC.UpdatedBy
				,RC.UpdatedDate
				,(SELECT COUNT(*) FROM Form1 WHERE RegistrationCategoryId=RC.RegistrationCategoryId) AS Form1Count
				,(SELECT COUNT(*) FROM Form2 WHERE RegistrationCategoryId=RC.RegistrationCategoryId) AS Form2Count
				,(SELECT COUNT(*) FROM Form3 WHERE RegistrationCategoryId=RC.RegistrationCategoryId) AS Form3Count
				,(SELECT COUNT(*) FROM Form4 WHERE RegistrationCategoryId=RC.RegistrationCategoryId) AS Form4Count
				,(SELECT COUNT(*) FROM Form5 WHERE RegistrationCategoryId=RC.RegistrationCategoryId) AS Form5Count
				,(SELECT COUNT(*) FROM Form6 WHERE RegistrationCategoryId=RC.RegistrationCategoryId) AS Form6Count			 		
				FROM RegistrationCategories RC  		
				WHERE RC.RegistrationCategoryId <> 0 '
		
		IF(@Search <> '')
		BEGIN
			SET @Query = @Query + ' AND  RC.CategoryName LIKE ''%' + @Search + '%'''
		END
				
		IF(@Sort <> '')
		BEGIN
			SET @Query = @Query + ' ORDER BY ' + @Sort
		END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END











