CREATE PROCEDURE [dbo].[RegistrationCategoriesInsert]
    (@RegistrationCategoryId bigint Output
	,@CategoryName nvarchar(512)
	,@Type nvarchar(512)
	,@IsPayment bit
	,@Description nvarchar(max)
	,@OrderNo int
	,@IsActive bit
	,@InstertedBy nvarchar(512)
	,@InsertedDate datetime
	,@UpdatedBy nvarchar(512)
	,@UpdatedDate datetime
	,@QStatus int output)  
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
    BEGIN TRY

    BEGIN TRANSACTION

    IF((SELECT Count(*) FROM RegistrationCategories WHERE RegistrationCategoryId = @RegistrationCategoryId) = 0)
		BEGIN
			INSERT INTO RegistrationCategories VALUES
				(@CategoryName
				,@Type
				,@IsPayment
				,@Description
				,@OrderNo
				,@IsActive
				,@InstertedBy 
				,@InsertedDate 
				,@UpdatedBy 
				,@UpdatedDate 
				)		
			SET @RegistrationCategoryId =  SCOPE_IDENTITY()	
			SELECT @QStatus = 1;	
		END
	ELSE 
		BEGIN
		
			UPDATE RegistrationCategories
			   SET   CategoryName    = @CategoryName
					, Type           = @Type
					, IsPayment      = @IsPayment 
					, Description    = @Description
					, OrderNo        = @OrderNo
					, InstertedBy    = @InstertedBy
					, InsertedDate   = @InsertedDate
					, UpdatedBy      = @UpdatedBy
					, UpdatedDate    = @UpdatedDate

			 WHERE RegistrationCategoryId = @RegistrationCategoryId
		 		 
			 SELECT @QStatus = 2;	
		 END
		 
    COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH    
    ROLLBACK TRANSACTION
		SELECT @QStatus = -1;    
    END CATCH    
END




































