/****** Object:  StoredProcedure [dbo].[RegistrationEventUserInfoGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[RegistrationEventUserInfoGetListByVariable]
	 (@Search nvarchar(126)
	 ,@EventId bigint
	 ,@EventCategory nvarchar(64)
	 ,@Sort nvarchar(216)
	 ,@PageNo int
     ,@Items int
     ,@Total int OUTPUT)
        
AS
BEGIN
	
	BEGIN TRY 
	
			SET NOCOUNT ON;
			
			DECLARE @Start int, @End INT ;
			DECLARE @Query nvarchar(max);
		    
			CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
						,EventUserInfoId bigint
						,EventId bigint 
						,EventName nvarchar(128)
						,FirstName nvarchar(156)
						,LastName nvarchar(156)
						,Email nvarchar(156)
						,Gender nvarchar(50)
						,Address nvarchar(156)
						,City nvarchar(156)
						,State nvarchar(156)
						,Mobile nvarchar(15)
						,ItemName nvarchar(1024)
						,ItemCategory nvarchar(1024)
						,ItemDescription nvarchar(1024)
						,ItemDuration int
						,IsApproved bit
						,DocumentUrl nvarchar(156)
						,UpdatedBy nvarchar(64)
						,UpdatedTime datetime 
						,InsertedTime datetime
						,EventCategory nvarchar(156)
						,PaymentMethod nvarchar(156)
						,PaymentStatus nvarchar(156))
			
			SELECT @Start = (@PageNo - 1) * @Items     
			SELECT @End = @Start + @Items 
			
			SET @Query = 'INSERT INTO #temp 
				 SELECT  DISTINCT  EUI.EventUserInfoId
						,E.EventId 
						,E.EventName						
						,EUI.FirstName
						,EUI.LastName
						,EUI.Email
						,EUI.Gender
						,EUI.Address
						,EUI.City
						,EUI.State
						,EUI.Mobile
						,EUI.ItemName 
						,EUI.ItemCategory 
						,EUI.ItemDescription 
						,EUI.ItemDuration 
						,EUI.IsApproved
						,EUI.DocumentUrl
						,EUI.UpdatedBy
						,EUI.UpdatedTime
						,EUI.InsertedTime  
						,EC.EventCategory 
						,PM.PaymentMethod 
						,PS.PaymentStatus      
						FROM Events  E 
						INNER JOIN EventUsers EU ON E.EventId = EU.EventId 
						INNER JOIN EventUserInfo EUI ON EU.EventUserInfoId = EUI.EventUserInfoId 
						INNER JOIN EventCategories EC ON EC.EventCategoryId = E.EventCategoryId 
						LEFT JOIN EventOrderDetails EO ON EO.EventUserInfoId = EUI.EventUserInfoId
						LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId = EO.PaymentMethodId 
						LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId = EO.PaymentStatusId  
						WHERE E.EventId <> 0 AND EO.PaymentMethodID IS NULL  AND EUI.DocumentUrl IS NOT NULL'
			 

			IF(@EventId<>0)
			BEGIN
				SET @Query=@Query + ' AND E.EventId = ' + CAST(@EventId as nvarchar(50))
			END
			
			IF(@Search <> '')
			BEGIN
				SET @Query = @Query + ' AND  EUI.FirstName LIKE ''%' + @Search + '%'' OR  EUI.LastName LIKE ''%' + @Search + '%'''
			END

			IF(@EventCategory <> '')
			BEGIN
				SET @Query = @Query + ' AND  EC.EventCategory LIKE ''%' + @EventCategory + '%'''
			END
			
			IF(@Sort <> '')
			BEGIN
				SET @Query = @Query + ' ORDER BY ' + @Sort
			END
			
			EXEC sp_ExecuteSQL @Query;
			
			SELECT @Total = COUNT(Rid) from #temp 
					
			SELECT  *  FROM #temp WHERE Rid > @Start AND  Rid <= @End
			
		    DROP TABLE #temp
				
    END TRY
    BEGIN CATCH
		 SELECT @Total = -1;
    END CATCH
	 
END










