CREATE PROCEDURE [dbo].[RemoveRoleMenuAccess]
	(@QStatus int OUTPUT
	,@RoleMenuMasterId bigint
	,@UserId bigint
	,@ParentId bigint)    
        
AS
BEGIN
	
   SET NOCOUNT ON;

    BEGIN TRY 





	DECLARE @RoleId bigint;
	SET @RoleId = (SELECT RoleId FROM Role_Menu_Master WHERE RoleMenuMasterId = @RoleMenuMasterId);

	if(@UserId<>0)
	BEGIN

	DELETE UserRoles where UserId=@UserId and MenuId = @ParentId 
	End
	ELSE
	BEGIN
	DECLARE @count int;
	SET @count = (SELECT COUNT(*) FROM Role_Menu_Master where MenuId IN (SELECT MenuItemId FROM AdminMenuItems WHERE PageParentId = @ParentId) AND RoleId = @RoleId);

	IF(@count > 1)
	BEGIN
	DELETE Role_Menu_Master WHERE RoleMenuMasterId = @RoleMenuMasterId;
	END
	ELSE
	BEGIN
	DELETE Role_Menu_Master WHERE RoleMenuMasterId = @RoleMenuMasterId;
	DELETE Role_Menu_Master WHERE MenuId = @ParentId AND RoleId = @RoleId;
	END
	END
		
		 SELECT @QStatus = 1;
    END TRY
    
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH	
	 
END

