/****** Object:  StoredProcedure [dbo].[RolesGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[RolesGetListByVariable]
	 (
	 @Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,RoleId bigint
				,RoleName nvarchar(128)
				,UpdatedTime datetime
				,IsActive bit
				,UpdatedBy nvarchar(256)
				,UserCount bigint)
				
	SELECT @Start = (@PageNo - 1) * @Items  
	   
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp SELECT 
	             DC.RoleId
	            ,DC.RoleName
	            ,DC.UpdatedTime
	            ,DC.IsActive
				,DC.UpdatedBy
				,(select count(*) from Users where DC.RoleName=RoleName and UserId<>51) as UserCount
				FROM Roles DC
				
		        WHERE DC.RoleId <> 0'
		
		
		IF(@Search <> '')
			BEGIN
				SET @Query = @Query + ' AND  DC.RoleName LIKE ''%' + @Search + '%'''
			END
		IF(@Sort <> '')
			BEGIN
				SET @Query = @Query + ' ORDER BY ' + @Sort
			END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

END













