SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[RolesInsert]
    (@RoleId bigint
	,@RoleName nvarchar(128)
	,@UpdatedTime datetime
	,@UpdatedBy nvarchar(128)
	,@IsActive bit
	,@QStatus int output)  
        
AS
BEGIN

	-- SET NOCOUNT ON added to prevent extra result sets from
	
	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
    IF((SELECT COUNT(*) FROM Roles WHERE RoleId = @RoleId OR RoleName=@RoleName) = 0)
		BEGIN
			INSERT INTO Roles VALUES
				(
				 @RoleName
				,@IsActive
				,@UpdatedTime
                ,@UpdatedBy
				,null)		
			
			SELECT @QStatus = 1;	
		END
	ELSE 
		BEGIN
			IF((SELECT COUNT(*) FROM Roles WHERE RoleName=@RoleName AND RoleId <> @RoleId) = 0)
				BEGIN
				UPDATE Roles
				   SET 
					  RoleName =@RoleName,
					  UpdatedTime=@UpdatedTime,
					  UpdatedBy=@UpdatedBy
				 WHERE RoleId = @RoleId
		 		 
				 SELECT @QStatus = 2;	
				END
			 ELSE
				BEGIN
				SELECT @QStatus = 3; 
				END 
			END
    COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH    
    ROLLBACK TRANSACTION
		SELECT @QStatus = -1;    
    END CATCH    
END


























