/****** Object:  StoredProcedure [dbo].[ServiceDonationsBulkUpload]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[ServiceDonationsBulkUpload]    
(    
    @ShipmentsXML   NVARCHAR(MAX),    
    @Summery        NVARCHAR(MAX) OUTPUT,    
    @QStatus        INT           OUTPUT    
)    
AS    
BEGIN    
    SET NOCOUNT ON;    
    SET @Summery = '';    
    SET @QStatus = 0;    
    
    IF ISNULL(@ShipmentsXML, '') = ''    
    BEGIN    
        SET @QStatus = -1;    
        RETURN;    
    END    
    
    BEGIN TRY    
        BEGIN TRANSACTION;    
    
        CREATE TABLE #temp1    
        (    
            Rid           INT IDENTITY(1,1) PRIMARY KEY,    
            FirstName     NVARCHAR(128),    
            LastName      NVARCHAR(128),    
            Email         NVARCHAR(256),    
            PhoneNo       NVARCHAR(50),    
            Country       NVARCHAR(256),    
            ZipCode       NVARCHAR(50),    
            Address       NVARCHAR(MAX),    
            DonationCause NVARCHAR(1024),    
            TransactionId NVARCHAR(256),    
            PaymentStatus NVARCHAR(128),    
            PaymentMethod NVARCHAR(128),    
            Amount        DECIMAL(15,2),    
            OrderDate     DATETIME,    
            IsActive      BIT    
        );    
    
        DECLARE @XML AS XML = @ShipmentsXML;    
    
        INSERT INTO #temp1 (    
            FirstName, LastName, Email, PhoneNo, Country, ZipCode,    
            Address, DonationCause, TransactionId, PaymentStatus,    
            PaymentMethod, Amount, OrderDate, IsActive    
        )    
        SELECT    
            M.Item.value('FirstName[1]',     'NVARCHAR(128)'),    
            M.Item.value('LastName[1]',      'NVARCHAR(128)'),    
            M.Item.value('Email[1]',         'NVARCHAR(256)'),    
            M.Item.value('PhoneNo[1]',       'NVARCHAR(50)'),    
            M.Item.value('Country[1]',       'NVARCHAR(256)'),    
            M.Item.value('ZipCode[1]',       'NVARCHAR(50)'),    
            M.Item.value('Address[1]',       'NVARCHAR(MAX)'),    
            M.Item.value('DonationCause[1]', 'NVARCHAR(1024)'),    
            M.Item.value('TransactionId[1]', 'NVARCHAR(256)'),    
            M.Item.value('PaymentStatus[1]', 'NVARCHAR(128)'),    
            M.Item.value('PaymentMethod[1]', 'NVARCHAR(128)'),    
            M.Item.value('Amount[1]',        'DECIMAL(15,2)'),    
            M.Item.value('OrderDate[1]',     'DATETIME'),    
            M.Item.value('IsActive[1]',      'BIT')    
        FROM @XML.nodes('/ArrayOfServiceDonations/ServiceDonations') AS M(Item);    
    
        DECLARE @RowCount   INT = (SELECT COUNT(*) FROM #temp1);    
        DECLARE @CurrentRow INT = 1;    
        DECLARE @ServiceDonationId BIGINT;    
    
        WHILE @CurrentRow <= @RowCount    
        BEGIN    
            DECLARE @Email         NVARCHAR(256)  = (SELECT Email         FROM #temp1 WHERE Rid = @CurrentRow);    
            DECLARE @FirstName     NVARCHAR(128)  = (SELECT FirstName     FROM #temp1 WHERE Rid = @CurrentRow);    
            DECLARE @LastName      NVARCHAR(128)  = (SELECT LastName      FROM #temp1 WHERE Rid = @CurrentRow);    
            DECLARE @PaymentStatus NVARCHAR(128)  = (SELECT PaymentStatus FROM #temp1 WHERE Rid = @CurrentRow);    
            DECLARE @PaymentMethod NVARCHAR(128)  = (SELECT PaymentMethod FROM #temp1 WHERE Rid = @CurrentRow);  
            DECLARE @DonationCause NVARCHAR(1024) = (SELECT DonationCause FROM #temp1 WHERE Rid = @CurrentRow);  
            DECLARE @TransactionId NVARCHAR(256)  = (SELECT TransactionId FROM #temp1 WHERE Rid = @CurrentRow);  
  
            -- ✅ NO duplicate check — always insert every row  
            INSERT INTO ServiceDonations    
            (    
                MemberId,    
                ServiceId,    
                DonationCause,    
                IsActive,    
                Amount,    
                TransactionId,    
                PaymentStatusId,    
                PaymentMethodId,    
                OrderDate,    
                PaymentBy,  
                UpdatedDate  
            )    
            SELECT    
                (SELECT TOP 1 MemberId FROM Members WHERE Email = @Email),    
                ISNULL(  
                    (SELECT TOP 1 ServiceId FROM Services WHERE ServiceTitle = @DonationCause),  
                    1  
                ),  
                DonationCause,    
                1,    
                Amount,    
                TransactionId,    
            -- With ISNULL fallbacks:
ISNULL((SELECT TOP 1 PaymentStatusId FROM PaymentStatus  WHERE PaymentStatus = @PaymentStatus), 1),
ISNULL((SELECT TOP 1 PaymentMethodId FROM PaymentMethods WHERE PaymentMethod = @PaymentMethod), 1), 
                OrderDate,    
                @FirstName,  
                GETUTCDATE()  
            FROM #temp1 WHERE Rid = @CurrentRow;    
    
            SET @ServiceDonationId = SCOPE_IDENTITY();    
    
            INSERT INTO ServiceDonationInfo    
            (    
                ServiceDonationId,  
                ChapterId,  
                FirstName,  
                LastName,  
                Email,    
                PhoneNo,  
                Address,  
                Country,  
                ZipCode    
            )    
            SELECT    
                @ServiceDonationId,  
                1,  
                FirstName,  
                LastName,  
                Email,    
                PhoneNo,  
                Address,  
                Country,  
                ZipCode    
            FROM #temp1 WHERE Rid = @CurrentRow;    
    
            SET @Summery = @Summery + ISNULL(@FirstName, '') + ' ' +    
                           ISNULL(@LastName, '') + ' - Added Successfully\r\n';    
    
            SET @CurrentRow = @CurrentRow + 1;    
        END    
    
        DROP TABLE #temp1;    
        SET @QStatus = 2;    
        COMMIT TRANSACTION;    
    
    END TRY    
    BEGIN CATCH    
        IF @@TRANCOUNT > 0    
            ROLLBACK TRANSACTION;    
    
        SET @QStatus = -1;    
        SET @Summery = ERROR_MESSAGE();    
    END CATCH    
END
GO
