CREATE PROCEDURE [dbo].[ServiceDonationsGetById]
	(@ServiceDonationId bigint
    ,@QStatus int OUTPUT)    
        
	AS
	BEGIN

	   SET NOCOUNT ON;

		BEGIN TRY 
    
			 SELECT  Distinct  Top(1) s.*,(select ServiceTitle from services where Serviceid=s.Serviceid) as ServiceTitle ,PM.PaymentMethod,PS.PaymentStatus  FROM ServiceDonations S
			 LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId  = s.PaymentMethodId
			 LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId   = s.PaymentStatusId

			 WHERE ServiceDonationId=@ServiceDonationId

			 Select Distinct Top(1)  * from ServiceDonationInfo WHERE ServiceDonationId=@ServiceDonationId


		

			 SELECT @QStatus = 1;
		 
		END TRY
    
		BEGIN CATCH
			 SELECT @QStatus = -1; 
		END CATCH	
	 
	END









