	 ,@Search nvarchar(126)  
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)


	AS
	BEGIN
	
		SET NOCOUNT ON;
	
		BEGIN TRY
	
			DECLARE @Start int, @End INT ;
			DECLARE @Query nvarchar(max);
	
			CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
						,ServiceDonationId bigint
						,MemberId bigint
						,ServiceId bigint
						,DonationCause  nvarchar(2048)
						,IsActive bit
						,Amount decimal(15,7)
						,TransactionId nvarchar(512)
						,PaymentStatusId bigint
						,PaymentMethodId bigint
						,OrderDate datetime 
						,PaymentBy nvarchar(512)
						,UpdatedDate datetime 
						 ,FirstName nvarchar(512)
						 ,LastName nvarchar(512)
						 ,Field3 nvarchar(512))
				
			SELECT @Start = (@PageNo - 1) * @Items  
	   
			SELECT @End = @Start + @Items 
	
			SET @Query = 'INSERT INTO #temp SELECT 
						 D.ServiceDonationId
					    ,D.MemberId
						,D.ServiceId
						,D.DonationCause
						,D.IsActive
						,D.Amount
						,D.TransactionId
						,D.PaymentStatusId
						,D.PaymentMethodId
						,D.OrderDate 
						,D.PaymentBy
						,D.UpdatedDate  
						,K.FirstName								
						,K.LastName
						,K.Field3 
						FROM ServiceDonations D
						LEFT JOIN ServiceDonationInfo K ON D.ServiceDonationId=K.ServiceDonationId 
						LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId
						LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId
						WHERE D.ServiceDonationId <> 0 AND D.PaymentStatusId = 1 AND D.Amount <> 0 AND D.Amount Is Not NULL
						AND D.ServiceDonationId NOT IN (Select DISTINCT ServiceDonationId from ServiceContributions Where NewServiceDonationId IS NOT NULL and ServiceDonationId <> NewServiceDonationId) '
		
				IF(@Search <> '')
				BEGIN
					SET @Query = @Query + ' AND  K.FirstName  LIKE ''%' + @Search + '%'' OR  K.LastName LIKE ''%' + @Search + '%'' OR  K.Email LIKE ''%' + @Search + '%'' OR  D.Amount LIKE ''%' + @Search + '%'' OR  D.TransactionId LIKE ''%' + @Search + '%'''
				END

				 IF(@ServiceId <> 0)
				 BEGIN
					  IF(@ServiceId = 10)
						  BEGIN
							 SET @Query=@Query + 'AND D.ServiceId = ' + CAST(@ServiceId AS nvarchar(30)) + ' AND Year(D.OrderDate) >= (Year(GetDate())-6)' 
						  END
					  ELSE 
						  BEGIN
							SET @Query=@Query + 'AND D.ServiceId = ' + CAST(@ServiceId AS nvarchar(30))
						  END
				  END 
		 
				IF(@Sort <> '')
				BEGIN
					SET @Query = @Query + ' ORDER BY ' + @Sort
				END
	
				EXEC sp_ExecuteSQL @Query;
				print @Query;
				SELECT @Total = COUNT(Rid) from #temp 
				
				SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
				DROP TABLE #temp

		END TRY
    
		BEGIN CATCH  
		   SELECT @Total = -1; 		   
		END CATCH   
	END








GO
