CREATE PROCEDURE [dbo].[ServiceDonationsGetListByVariableId]     
  (@ServiceId bigint    
  ,@ServiceDonationId bigint    
  ,@Search nvarchar(126)     
  ,@PaymentStatus bigint    
  ,@PaymentMethod bigint    
     ,@Sort nvarchar(126)    
  ,@PageNo int    
  ,@StartDate nvarchar(126)    
  ,@EndDate nvarchar(126)    
     ,@Items int    
     ,@Total int output    
  ,@SumofDonation bigint output    
  ,@nofofdonors bigint output  
  ,@ChapterId bigint)    
    
    
 AS    
 BEGIN    
     
  SET NOCOUNT ON;    
     
  --BEGIN TRY    
     
   DECLARE @Start int, @End INT ;    
   DECLARE @Query nvarchar(max);    
     
        
   CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)    
      ,ServiceDonationId bigint   
   ,ChapterId bigint   
      ,MemberId bigint    
      ,ServiceId bigint    
      ,DonationCause  nvarchar(2048)    
      ,IsActive bit    
      ,Amount decimal(15,7)    
      ,TransactionId nvarchar(512)    
      ,PaymentStatusId bigint    
      ,PaymentMethodId bigint    
      ,OrderDate datetime    
      --,CardNumber nvarchar(512)    
      --,CSVExpiry nvarchar(512)    
      ,PaymentBy nvarchar(512)    
      ,UpdatedDate datetime    
      ,UpdatedBy nvarchar(512)  
	  ,Zelle  nvarchar(512)  
      ,PaymentMethod nvarchar(156)    
      ,PaymentStatus nvarchar(156)    
       ,FirstName nvarchar(512)    
       ,LastName nvarchar(512)    
       ,Email nvarchar(512)    
       ,PhoneNo nvarchar(64))    
        
   SELECT @Start = (@PageNo - 1) * @Items      
        
   SELECT @End = @Start + @Items     
     
   SET @Query = 'INSERT INTO #temp     
   SELECT     
       D.ServiceDonationId   
    ,K.ChapterId    
       ,D.MemberId    
      ,D.ServiceId    
      --,D.DonationCause    
      ,(select ServiceTitle from services where ServiceId=D.ServiceId) as DonationCause    
      ,D.IsActive    
      ,D.Amount    
      ,D.TransactionId    
      ,D.PaymentStatusId    
      ,D.PaymentMethodId    
      ,D.OrderDate    
      --,D.CardNumber    
        -- ,D.CSVExpiry    
      ,D.PaymentBy    
      ,D.UpdatedDate    
      ,D.UpdatedBy   
	   ,D.Zelle 
      ,PM.PaymentMethod    
      ,PS.PaymentStatus    
      ,K.FirstName    
      ,K.LastName    
      ,K.Email     
      ,K.PhoneNo     
      FROM ServiceDonations D    
      LEFT JOIN ServiceDonationInfo K ON D.ServiceDonationId=K.ServiceDonationId     
      LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId    
      LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId     
      WHERE D.ServiceDonationId <> 0     
          
      '    
      
  
  
  
 IF(@ChapterId<>0)  
    BEGIN  
     SET @Query=@Query + ' AND K.ChapterId = ' + CAST(@ChapterId as nvarchar(50))  
    END  
  
  
  
  
    IF(@Search <> '')    
    BEGIN    
     SET @Query = @Query + ' AND  ((K.FirstName + '' '' + K.LastName)  LIKE ''%' + @Search + '%'' OR  K.Email LIKE ''%' + @Search + '%'' OR  D.Amount LIKE ''%' + @Search + '%'' OR  D.TransactionId LIKE ''%' + @Search + '%'')'    
    END    
    
     IF(@ServiceId <> 0)    
      BEGIN    
     SET @Query=@Query + 'AND D.ServiceId = ' + CAST(@ServiceId AS nvarchar(30))    
    END     
    
    --IF(@StartDate <> '' OR @EndDate <> '')    
    --BEGIN    
    -- IF(@StartDate <> '' AND @EndDate <> '')    
    -- BEGIN    
    --  SET @Query = @Query + ' AND  (D.UpdatedDate BETWEEN ''' + @StartDate + ''' AND ''' + @EndDate + ''')'    
    -- END    
       
    -- IF(@StartDate <> '' AND @EndDate = '')    
    -- BEGIN    
    --  SET @Query = @Query + ' AND  D.UpdatedDate = '+CAST(@StartDate as nvarchar(50))    
    -- END    
    --END    
    
    IF(@StartDate <> '' AND @EndDate <> '')    
     BEGIN    
      SET @Query = @Query + ' AND D.OrderDate >= '''+CAST(@StartDate as nvarchar(50))+''' and  D.OrderDate <= '''+CAST(@EndDate as nvarchar(50))+''' '    
     END    
    ELSE IF(@StartDate <> '' AND @EndDate = '')    
     BEGIN    
      SET @Query = @Query + ' AND D.OrderDate >= '''+CAST(@StartDate as nvarchar(50))+''''    
     END    
    ELSE IF(@StartDate = '' AND @EndDate <> '')    
     BEGIN    
      SET @Query = @Query + ' AND D.OrderDate <= '''+CAST(@EndDate as nvarchar(50))+''''    
     END     
       
    IF(@ServiceDonationId <> 0)    
     BEGIN    
      SET @Query=@Query + 'AND D.ServiceDonationId IN (' + CAST(@ServiceDonationId AS nvarchar(30))+')'    
     END     
    
        IF(@PaymentMethod <> 0)    
     BEGIN    
       SET @Query=@Query + 'AND D.PaymentMethodId = ' + CAST(@PaymentMethod AS nvarchar(30))    
     END     
    
     IF(@PaymentStatus <> 0)    
      BEGIN    
     SET @Query=@Query + 'AND D.PaymentStatusId = ' + CAST(@PaymentStatus AS nvarchar(30))    
       END     
       
    IF(@Sort <> '')    
    BEGIN    
     SET @Query = @Query + ' ORDER BY ' + @Sort    
    END    
      
    EXEC sp_ExecuteSQL @Query;    
       
    print @Query;     
    
    SELECT @Total = COUNT(Rid) from #temp     
        
    SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End    
    
    IF((SELECT SUM(Amount) from #temp WHERE PaymentStatus = 'Completed') <> 0)    
    
     BEGIN    
      SELECT @SumofDonation = SUM(Amount) from #temp WHERE PaymentStatus = 'Completed';    
     END    
    ELSE    
     BEGIN    
      SELECT @SumofDonation = 0;    
     END    
    
    SELECT @nofofdonors = COUNT(Rid) from #temp WHERE PaymentStatus = 'Completed';    
     
    DROP TABLE #temp    
    
  --END TRY    
        
  --BEGIN CATCH      
  --   SELECT @Total = -1;          
  --END CATCH       
 END    
    
    
    
    
    
    
  
GO
