CREATE PROCEDURE [dbo].[ServiceDonationsGetsById] 
	(@ServiceDonationId bigint
    ,@QStatus int OUTPUT)    
        
AS
BEGIN
	
   SET NOCOUNT ON;

    BEGIN TRY 
    
		 SELECT  Distinct  Top(1) s.*,PM.PaymentMethod,PS.PaymentStatus,k.FirstName,K.LastName,k.Email, k.Field3,k.FrequencyofDonation,k.NoofPayments,k.Field1,k.Field2,k.PhoneNo, k.Address, k.Country, k.ZipCode
		  ,S.ReceiptUrl
		  ,(select ServiceTitle from services where ServiceId=S.ServiceId) as DonationCauses
		  FROM ServiceDonations S
		 LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId = s.PaymentMethodId
		 LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId = s.PaymentStatusId
		 LEFT JOIN ServiceDonationInfo k ON k.ServiceDonationId = S.ServiceDonationId
		 WHERE S.ServiceDonationId=@ServiceDonationId

		 SELECT *, S.ServiceTitle 
		 FROM ServiceContributions SC 
		 INNER Join Services S On SC.ServiceId = S.ServiceId 
		 WHERE SC.ServiceDonationId=@ServiceDonationId

		 
		 SELECT @QStatus = 1;
		 
     END TRY
    
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH	
	 
END







