CREATE PROCEDURE [dbo].[ServiceDonationsInsertByAdmin]
    (@ServiceDonationId bigint output
	,@MemberId bigint
	,@ServiceId bigint
	,@DonationCause nvarchar(1024)
	,@IsActive bit
	,@Amount decimal(15,2)
	,@TransactionId nvarchar(128)
	,@PaymentStatusId bigint
	,@PaymentMethodId bigint
	,@OrderDate datetime
	,@PaymentBy nvarchar(128)
	,@UpdatedDate datetime
	,@UpdatedBy nvarchar(128)
	,@Zelle nvarchar(512)
	,@ReceiptUrl nvarchar(512)
	,@ZellePartnerName nvarchar(512)
	,@ChequeHolderName nvarchar(512)
	,@QStatus int output
	,@DonorInfoId bigint
	,@ChapterId bigint
	,@FirstName nvarchar(128)
	,@LastName nvarchar(128)
	,@Email nvarchar(128)
	,@PhoneNo nvarchar(20)
	,@Address nvarchar(1024)
	,@Country nvarchar(512)
	,@City  nvarchar(512)
	,@State  nvarchar(512)
	,@ZipCode  nvarchar(512)
	,@Spouse  nvarchar(512)
	,@FrequencyofDonation nvarchar(512)
	,@NoofPayments bigint
	,@TypeofCard   nvarchar(512)
	,@CardNumber  nvarchar(512)
	,@ExipryMonth  nvarchar(512)
	,@ExipryYear  nvarchar(512)
	,@Cvv  nvarchar(512)
	,@SameBilling  nvarchar(512)
	,@BillingAdress   nvarchar(max)
	,@BillingCountry nvarchar(512)
	,@BillingCity nvarchar(512)
	,@BillingState nvarchar(512)
	,@BillingZipCode nvarchar(512)
	,@KnowledgeAcurate nvarchar(512)
	,@Field1 nvarchar(max)
	,@Field2 nvarchar(max)
	,@Field3  nvarchar(max))  
        
AS
BEGIN

	SET NOCOUNT ON;

    
    BEGIN TRY
    BEGIN TRANSACTION
    
		IF((SELECT COUNT(*) FROM ServiceDonations WHERE ServiceDonationId = @ServiceDonationId) = 0)
				BEGIN
					INSERT INTO ServiceDonations VALUES
								(@MemberId
								,@ServiceId
								,@DonationCause
								,@IsActive
								,@Amount
								,@TransactionId
								,@PaymentStatusId
								,@PaymentMethodId
								,@OrderDate
								,@PaymentBy
								,@UpdatedDate
								,@UpdatedBy
								,@Zelle
								,@ReceiptUrl
								,@ZellePartnerName
								,@ChequeHolderName)
			              
						 SET @ServiceDonationId=SCOPE_IDENTITY()	


					 INSERT INTO ServiceDonationInfo  Values
								(@ServiceDonationId
								,@ChapterId
								,@FirstName
								,@LastName 
								,@Email
								,@PhoneNo 
								,@Address 
								,@Country
								,@City
								,@State
								,@ZipCode
								,@Spouse
								,@FrequencyofDonation
								,@NoofPayments
								,@TypeofCard
								,@CardNumber
								,@ExipryMonth
								,@ExipryYear
								,@Cvv
								,@SameBilling
								,@BillingAdress
								,@BillingCountry
								,@BillingCity
								,@BillingState
								,@BillingZipCode
								,@KnowledgeAcurate
								,@Field1
								,@Field2
								,@Field3)

	
				SELECT @QStatus = 1;

				END

			ELSE 

				BEGIN	
						UPDATE ServiceDonations
					   SET 
							MemberId            =   @MemberId,
							ServiceId			=	@ServiceId,
							--DonationCause		=	@DonationCause,
							--Amount				=	@Amount,
							TransactionId		=	@TransactionId ,
							PaymentStatusId		=	@PaymentStatusId ,
							PaymentMethodId		=	@PaymentMethodId ,
							OrderDate			=	@OrderDate ,
							PaymentBy			=	@PaymentBy,
							UpdatedBy			=	@UpdatedBy,
							UpdatedDate			=	@UpdatedDate

					 WHERE ServiceDonationId = @ServiceDonationId



	IF((SELECT COUNT(*) FROM ServiceDonationInfo WHERE ServiceDonationId = @ServiceDonationId) = 0)

			BEGIN

					 INSERT INTO ServiceDonationInfo  Values
									(@ServiceDonationId
									,@ChapterId
									,@FirstName
									,@LastName 
									,@Email
									,@PhoneNo 
									,@Address 
									,@Country
									,@City
									,@State
									,@ZipCode
									,@Spouse
									,@FrequencyofDonation
									,@NoofPayments
									,@TypeofCard
									,@CardNumber
									,@ExipryMonth
									,@ExipryYear
									,@Cvv
									,@SameBilling
									,@BillingAdress
									,@BillingCountry
									,@BillingCity
									,@BillingState
									,@BillingZipCode
									,@KnowledgeAcurate
									,@Field1
									,@Field2
									,@Field3)

			END


			 UPDATE ServiceDonationInfo
				   SET  
						ChapterId           =   @ChapterId,
						FirstName           =   @FirstName,
						LastName            =   @LastName,
						Email               =   @Email,
						PhoneNo             =   @PhoneNo,
						Address             =   @Address,
						Country             =   @Country,
						City			    =	@City,
						State			    =	@State,
						ZipCode				=	@ZipCode,
						Spouse				=	@Spouse,
						FrequencyofDonation =   @FrequencyofDonation,
						NoofPayments		=	@NoofPayments,
						TypeofCard          =   @TypeofCard,
						CardNumber		    =	@CardNumber,
						ExipryMonth		    =	@ExipryMonth,
						ExipryYear			=	@ExipryYear,
						Cvv		            =	@Cvv ,
						SameBilling         =   @SameBilling,
						BillingAdress		=	@BillingAdress ,
						BillingCountry		=	@BillingCountry ,
						BillingCity			=	@BillingCity ,
						BillingState		=	@BillingState,
						BillingZipCode		=	@BillingZipCode,
						KnowledgeAcurate    =   @KnowledgeAcurate,
						Field1				=	@Field1,
						Field2				=	@Field2,
						Field3				=	@Field3

				        WHERE ServiceDonationId = @ServiceDonationId

			SELECT @QStatus = 2;	

			END

		COMMIT TRANSACTION
		END TRY
    
		BEGIN CATCH  
			ROLLBACK TRANSACTION   
			SELECT @QStatus = -1;    
		END CATCH   
    
END
















