CREATE PROCEDURE [dbo].[ServiceDonationsRegistrationsExportToExcel] 
	 (@ServiceId bigint
	 ,@Search nvarchar(126)
	 ,@Sort nvarchar(216)
	 ,@PaymentStatusId bigint
	 ,@PaymentMethodId bigint	 
     ,@Total int OUTPUT)
        
AS
BEGIN
	
	 BEGIN TRY 
	
			SET NOCOUNT ON;
			
			DECLARE @Start int, @End INT ;
			DECLARE @Query nvarchar(max);
			
			-- Insert statements for procedure here

			SET @Query = '
				  SELECT 
					 D.ServiceDonationId
					,D.MemberId
					,D.ServiceId
					,D.DonationCause
					,D.IsActive
					,D.Amount
					,D.TransactionId
					,D.PaymentStatusId
					,D.PaymentMethodId
					,D.OrderDate
					--,D.CardNumber
				   -- ,D.CSVExpiry
					,D.PaymentBy
					,D.UpdatedDate
					,D.UpdatedBy
					,PM.PaymentMethod
					,PS.PaymentStatus
					,k.FirstName
					,k.LastName
					,k.Email
					FROM ServiceDonations D
					LEFT JOIN ServiceDonationInfo K ON D.ServiceDonationId=K.ServiceDonationId 
					LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=D.PaymentMethodId
					LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=D.PaymentStatusId
					WHERE D.ServiceDonationId <> 0'
			 
			
			IF(@PaymentMethodId<>0)
				BEGIN
					SET @Query=@Query + ' AND D.PaymentMethodId = ' + CAST(@PaymentMethodId as nvarchar(50))
				END
			IF(@PaymentStatusId<>0)
				BEGIN
					SET @Query=@Query + ' AND D.PaymentStatusId = ' + CAST(@PaymentStatusId as nvarchar(50))
				END	

			 IF(@ServiceId <> 0)
				BEGIN
					SET @Query=@Query + 'AND D.ServiceId = ' + CAST(@ServiceId AS nvarchar(30))
				END 
			

			IF(@Search <> '')
				BEGIN
					SET @Query = @Query + ' AND  E.DonationCause LIKE ''%' + @Search + '%'' OR E.MemberId LIKE ''%' + @Search + '%'''
				END
			
			IF(@Sort <> '')
				BEGIN
					SET @Query = @Query + ' ORDER BY ' + @Sort
				END
			
			EXEC sp_ExecuteSQL @Query;
			SELECT @Total = 1;
			
		END TRY
		BEGIN CATCH
			 SELECT @Total = -1;
		END CATCH
	 
END










