/****** Object:  StoredProcedure [dbo].[ServiceDonationsRegistrationsExportToExcel_V1]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

  
CREATE PROCEDURE [dbo].[ServiceDonationsRegistrationsExportToExcel_V1]   
  (@ServiceId bigint  
  ,@Search nvarchar(126)  
  ,@PaymentStatusId bigint  
  ,@PaymentMethodId bigint    
  ,@StartDate nvarchar(512)  
  ,@EndDate nvarchar(512)  
  ,@Sort nvarchar(216)
  ,@chapterId  bigint
  ,@Total int OUTPUT)  
          
AS  
BEGIN  
  
   
 BEGIN TRY   
   
   SET NOCOUNT ON;  
     
   DECLARE @Start int, @End INT ;  
   DECLARE @Query nvarchar(max);  
     
  
   SET @Query = '  
      SELECT     
      DI.FirstName  
      ,DI.LastName  
      ,(DI.Email) AS EmailAddress  
      ,DI.PhoneNo  
      ,(DI.Address) AS Address  
      ,DI.Country  
      ,DI.ZipCode  
     --,E.DonationCause 
	    --,E.ServiceId
	   ,(select ServiceTitle from services where ServiceId=E.ServiceId) as DonationCause  

      ,E.Amount  as DonationAmount  
      ,E.UpdatedDate  
      ,(Select PaymentStatus from PaymentStatus PS Where PS.PaymentStatusId= E.PaymentStatusId) As PaymentStatus  
      ,(Select PaymentMethod from PaymentMethods PM Where PM.PaymentMethodId= E.PaymentMethodId) As PaymentMethod  
      ,E.TransactionId  
       FROM ServiceDonations E   
       LEFT JOIN ServiceDonationInfo DI ON E.ServiceDonationId = DI.ServiceDonationId    
       LEFT JOIN ServiceContributions SC ON E.ServiceDonationId = SC.NewServiceDonationId   
       --LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId= E.PaymentStatusId   
        WHERE E.ServiceDonationId <> 0'  

		

   IF(@PaymentMethodId<>0)  
    BEGIN  
     SET @Query=@Query + ' AND E.PaymentMethodId = ' + CAST(@PaymentMethodId as nvarchar(50))  
    END  
   IF(@PaymentStatusId<>0)  
    BEGIN  
     SET @Query=@Query + ' AND E.PaymentStatusId = ' + CAST(@PaymentStatusId as nvarchar(50))  
    END   
  
  
  IF(@ChapterId <> 0)
	BEGIN
		SET @Query = @Query + ' AND DI.ChapterId = ' + CAST(@ChapterId AS nvarchar(30));
	END 


  
  IF(@StartDate <> '' AND @EndDate <> '')  
   BEGIN  
    SET @Query = @Query + ' AND E.OrderDate >= '''+CAST(@StartDate as nvarchar(50))+''' and  E.OrderDate <= '''+CAST(@EndDate as nvarchar(50))+''' '  
   END  
  ELSE IF(@StartDate <> '' AND @EndDate = '')  
   BEGIN  
    SET @Query = @Query + ' AND E.OrderDate >= '''+CAST(@StartDate as nvarchar(50))+''''  
   END  
  
  ELSE IF(@StartDate = '' AND @EndDate <> '')  
   BEGIN  
    SET @Query = @Query + ' AND E.OrderDate <= '''+CAST(@EndDate as nvarchar(50))+''''  
   END   
  
    IF(@ServiceId <> 0)  
    BEGIN  
      SET @Query=@Query + 'AND E.ServiceId = ' + CAST(@ServiceId AS nvarchar(30))  
    END   
     
  
   IF(@Search <> '')  
    BEGIN  
     SET @Query = @Query + ' AND  E.DonationCause LIKE ''%' + @Search + '%'' OR E.MemberId LIKE ''%' + @Search + '%''OR DI.FirstName LIKE ''%' + @Search + '%''OR DI.LastName LIKE ''%' + @Search + '%''OR DI.Email LIKE ''%' + @Search + '%'''  
    END  
     
   IF(@Sort <> '')  
    BEGIN  
     SET @Query = @Query + ' ORDER BY ' + @Sort  
    END  
     
   EXEC sp_ExecuteSQL @Query;  
   SELECT @Total = 1;  
     
    END TRY  
    BEGIN CATCH  
   SELECT @Total = -1;  
    END CATCH  
    
END  
  
  
  
  
  

