/****** Object:  StoredProcedure [dbo].[ServiceDonationsUpdate]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[ServiceDonationsUpdate]
    (@ServiceDonationId bigint 
	,@Amount decimal(15,7)
	,@TransactionId nvarchar(128)
	,@PaymentStatusId bigint
	,@PaymentMethodId bigint
	,@PaymentStatus nvarchar(2048)
	,@PaymentMethod nvarchar(2048)
	,@OrderDate datetime
	,@UpdatedBy nvarchar(30)
	,@UpdatedDate datetime
	,@QStatus int output)  
        
AS
BEGIN

	SET NOCOUNT ON;

   
		BEGIN TRY
		BEGIN TRANSACTION
				IF(@PaymentStatus IS NOT NULL)
					BEGIN
						SELECT @PaymentStatusId = PaymentStatusId FROM PaymentStatus WHERE PaymentStatus = @PaymentStatus
				
						IF(@PaymentStatusId IS NULL OR @PaymentStatusId='')
							BEGIN
								 INSERT INTO PaymentStatus VALUES(@PaymentStatus,1)
								 SELECT @PaymentStatusId=SCOPE_IDENTITY()
							END

						IF(@PaymentStatus = 'STPPaymentStatus' OR @PaymentStatus = 'STPPaymentStatus(rawValue: 2)' OR @PaymentStatus = 'STPPaymentStatus(rawValue: 0)')
							BEGIN
								SELECT @PaymentStatusId=1;
							END

						IF(@PaymentMethod IS NOT NULL)
							BEGIN
								SELECT @PaymentMethodId = PaymentMethodId FROM PaymentMethods WHERE PaymentMethod = @PaymentMethod
							END
					END
    		
				UPDATE ServiceDonations
				   SET 
						--Amount				=	@Amount,
						TransactionId		=	@TransactionId ,
						PaymentStatusId		=	@PaymentStatusId ,
						PaymentMethodId		=	@PaymentMethodId ,
						OrderDate			=	@OrderDate ,
						UpdatedBy			=	@UpdatedBy,
						UpdatedDate			=	@UpdatedDate

				 WHERE ServiceDonationId = @ServiceDonationId
			 		 
				 SELECT @QStatus = 1;
		
			 IF((Select Count(*) from ServiceContributions Where ServiceDonationId = @ServiceDonationId) <> 0)
			 BEGIN
				 UPDATE ServiceDonations
					   SET 
							--Amount				=	@Amount,
							TransactionId		=	@TransactionId ,
							PaymentStatusId		=	@PaymentStatusId ,
							PaymentMethodId		=	@PaymentMethodId ,
							OrderDate			=	@OrderDate ,
							UpdatedBy			=	@UpdatedBy,
							UpdatedDate			=	@UpdatedDate

					 WHERE ServiceDonationId in (Select NewServiceDonationId from ServiceContributions Where ServiceDonationId = @ServiceDonationId)

			 END


		COMMIT TRANSACTION
		END TRY
    
    BEGIN CATCH  
    
		ROLLBACK TRANSACTION   
		SELECT @QStatus = -1;    
		
    END CATCH   
    
END






















