CREATE PROCEDURE [dbo].[ServiceDonationsUpdateStatus]
    (@ServiceDonationId bigint
    ,@QStatus int output)  
        
AS
BEGIN

	SET NOCOUNT ON;
    
    BEGIN TRY    
    BEGIN TRANSACTION
    
		IF((SELECT IsActive FROM ServiceDonations WHERE ServiceDonationId = @ServiceDonationId) = 1)
			BEGIN
				UPDATE ServiceDonations SET IsActive = 0 WHERE ServiceDonationId = @ServiceDonationId
			END
		ELSE
			BEGIN
				UPDATE ServiceDonations SET IsActive = 1 WHERE ServiceDonationId = @ServiceDonationId
			END		
		
		SELECT @QStatus = 1;
		
	COMMIT TRANSACTION
    END TRY

    BEGIN CATCH
         ROLLBACK TRANSACTION
		 SELECT @QStatus = -1;
    END CATCH
    	
END






















