CREATE PROCEDURE [dbo].[ServicesInsert]
    (@ServiceId bigint
	,@ChapterId bigint
	,@CategoryId bigint
	,@ServiceTitle nvarchar(256)
	,@ServiceType nvarchar(256)
	,@OrganisedBy nvarchar(256)
	,@Purpose nvarchar(1024) 
	,@Description nvarchar(max) 
	,@ShortDescription nvarchar(1024)
	,@DocumentUrl nvarchar(1024) output
	,@ExpiryDate datetime 
	,@EstimationAmount decimal(15,2) 
	,@ServiceStatus nvarchar(1024)
	,@IsDisplay bit
	,@Field1 nvarchar(max) 
	,@Field2 nvarchar(max) 
	,@UpdatedDate datetime
	,@UpdatedBy nvarchar(64)
	,@DisplayOrder int
	,@QStatus int output)  
        
AS
BEGIN

	SET NOCOUNT ON;

    BEGIN TRY
    BEGIN TRANSACTION

			IF((SELECT COUNT(*) FROM Services WHERE ServiceId = @ServiceId) = 0)
				BEGIN
					INSERT INTO Services VALUES
						(@ChapterId 
						,@CategoryId 
						,@ServiceTitle 
						,@ServiceType 
						,@OrganisedBy
						,@Purpose 
						,@Description
						,@ShortDescription 
						,null 
						,@ExpiryDate  
						,@EstimationAmount 
						,@ServiceStatus 
						,@IsDisplay 
						,@Field1 
						,@Field2  
						,@UpdatedDate 
						,@UpdatedBy
						,@DisplayOrder )		
						SET @ServiceId=SCOPE_IDENTITY(); 
					SELECT @QStatus = 1;	
				 END
			ELSE
				BEGIN
					UPDATE Services
					   SET ChapterId=@ChapterId, 
						   CategoryId=@CategoryId ,
						   ServiceTitle = @ServiceTitle,
						   ServiceType =@ServiceType,
						   OrganisedBy=@OrganisedBy ,
						   Purpose = @Purpose,
						   Description=@Description ,
						   ShortDescription=@ShortDescription,
						   ExpiryDate=@ExpiryDate ,  
						   EstimationAmount=@EstimationAmount,
						   ServiceStatus=@ServiceStatus ,
						   IsDisplay=@IsDisplay,
						   Field1=@Field1,
						   Field2=@Field2,
						   UpdatedDate=@UpdatedDate,
						   UpdatedBy=@UpdatedBy
						   ,DisplayOrder=@DisplayOrder  
					 WHERE ServiceId = @ServiceId
		 		 
					 SELECT @QStatus = 2;	
				END

			IF(@DocumentUrl <> 'N/A')
				BEGIN
					UPDATE Services
						SET  DocumentUrl= CAST(@ServiceId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@ServiceTitle, '^a-z0-9') + @DocumentUrl
						WHERE ServiceId = @ServiceId
			  
						SELECT @DocumentUrl = CAST(@ServiceId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(@ServiceTitle, '^a-z0-9') + @DocumentUrl	
				END	
			ELSE
				BEGIN
					SELECT @DocumentUrl=''
				END

	


    COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH    
    ROLLBACK TRANSACTION
		SELECT @QStatus = -1;    
    END CATCH   
	 
END











