/****** Object:  StoredProcedure [dbo].[ServiceTypesGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[ServiceTypesGetListByVariable]   
	 (@Search nvarchar(126)
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output)
AS
BEGIN

	SET NOCOUNT ON;
	
	BEGIN TRY
	
		DECLARE @Start int, @End INT ;
		DECLARE @Query nvarchar(max);
	
		CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
							,ServiceTypeId bigint
							,ServiceType nvarchar(512)
							,Descriptione nvarchar(max)
							,IsActive bit
							,OrderNo bigint	
							,UpdateDate datetime
							,UpdatedBy nvarchar(128))
				
		SELECT @Start = (@PageNo - 1) * @Items  
	   
		SELECT @End = @Start + @Items 
	
		SET @Query = 'INSERT INTO #temp SELECT
						 S.ServiceTypeId
						,S.ServiceType
						,S.Descriptione
						,S.IsActive
						,S.OrderNo
						,S.UpdateDate
						,S.UpdatedBy
						FROM ServiceTypes S 		
						WHERE s.ServiceTypeId <> 0 '
		
			IF(@Search <> '')
				BEGIN
					SET @Query = @Query + ' AND  S.ServiceType LIKE ''%' + @Search + '%'''
				END
				
			IF(@Sort <> '')
				BEGIN
					SET @Query = @Query + ' ORDER BY ' + @Sort
				END
	
			EXEC sp_ExecuteSQL @Query;
		
			SELECT @Total = COUNT(Rid) from #temp 
				
			SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
			DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END










