/****** Object:  StoredProcedure [dbo].[SP_AssihnMenu_GetSubMenu]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_AssihnMenu_GetSubMenu]
    (@MenuItemId int,
	 @UserId int,
	 @QStatus int output,
	 @Roleid int)  
        
AS
BEGIN

	SET NOCOUNT ON;

    BEGIN TRY    
    BEGIN TRANSACTION

		/****************************** Main Menu *****************************/

			select distinct DisplayName, MenuItemId,(select count(*) from AdminMenuItems AM where A.MenuItemId in(AM.PageParentId)) as MenuItemCount,
			(SELECT STRING_AGG(CAST(MenuItemId AS VARCHAR), ',') FROM AdminMenuItems RO WHERE A.MenuItemId in(RO.PageParentId))AS comma_separated_ids 
			
			from AdminMenuItems A where PageLevel=1
	

		/*********************************Sub Menu *******************************/

		select distinct DisplayName,MenuItemId, PageParentId from AdminMenuItems where PageLevel=2 


		if(@UserId<>0)
		Begin
			select distinct(UR.MenuId),UR.IsEdit,UR.IsAdd,UR.IsView,UR.IsDelete,UR.IsExport,(select top(1) RoleMenuMasterId
		from Role_Menu_Master where MenuId=UR.MenuId) as RoleMenuMasterId
		
		
		 
		from UserRoles UR 
		
		where RoleId=@Roleid and userid=@UserId
		End
		Else
		Begin
		select distinct(MenuId),IsEdit,IsAdd,IsView,IsDelete,IsExport,RoleMenuMasterId from Role_Menu_Master where RoleId=@Roleid
	
		end
		
		SELECT @QStatus = 1;
		
	COMMIT TRANSACTION
    END TRY

    BEGIN CATCH
         ROLLBACK TRANSACTION     
		 SELECT @QStatus = -1;
    END CATCH
    	
END








