/****** Object:  StoredProcedure [dbo].[SponsorCategoriesGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SponsorCategoriesGetListByVariable]  
			  (@ChapterId bigint  
			  ,@Search nvarchar(126)  
			  ,@Sort nvarchar(126)  
			  ,@PageNo int  
			  ,@Items int  
    		  ,@Total int output)  
AS  
BEGIN  
  
 SET NOCOUNT ON;  
   
	 BEGIN TRY  
   
	 DECLARE @Start int, @End INT ;  
	 DECLARE @Query nvarchar(max);  
   
		 CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)  
					,SponsorCategoryId bigint  
					,ChapterId bigint  
					,CategoryName nvarchar(512)  
					,UpdatedBy nvarchar(512)  
					,UpdatedTime datetime  
					,SponsorsCount bigint  
					,ChapterName nvarchar(512)
					,IsActive bit 
					,DisplayOrder int
					)  
  
      
		 SELECT @Start = (@PageNo - 1) * @Items    
      
		 SELECT @End = @Start + @Items   
   
		 SET @Query = 'INSERT INTO #temp   
		   SELECT  SC.SponsorCategoryId  
				  ,sc.ChapterId  
			      ,SC.CategoryName  
			      ,SC.UpdatedBy  
			      ,SC.UpdatedTime  
			      ,(SELECT COUNT(*) FROM Sponsors S WHERE S.SponsorCategoryId=SC.SponsorCategoryId) AS SponsorsCount  
			      ,C.ChapterName  
				  ,SC.IsActive
				  ,SC.DisplayOrder
		           FROM SponsorCategories SC   
		           LEFT JOIN Chapters C ON C.ChapterId = Sc.ChapterId   
		           WHERE SC.SponsorCategoryId <> 0 '  
     
     
		IF(@ChapterId <> 0)  
		  BEGIN  
		   SET @Query=@Query + 'AND Sc.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))  
		  END    
  
		IF(@Search <> '')  
		  BEGIN  
		   SET @Query = @Query + ' AND  SC.CategoryName LIKE ''%' + @Search + '%'''  
		  END  
		IF(@Sort <> '')  
		  BEGIN  
		   SET @Query = @Query + ' ORDER BY ' + @Sort  
		  END  
   
		EXEC sp_ExecuteSQL @Query;  
    
		SELECT @Total = COUNT(Rid) from #temp   
		
	    SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End  
   
		DROP TABLE #temp  
  
	END TRY  
      
    BEGIN CATCH    
       SELECT @Total = -1;        
    END CATCH     
END  
  
  
  
  


GO
