CREATE PROCEDURE [dbo].[SponsorsGetListByVariable]
	 (@Search nvarchar(126)
	 ,@SponsorCategoryId bigint
     ,@Sort nvarchar(126)
	 ,@PageNo int
     ,@Items int
     ,@Total int output
	 ,@MemberId bigint)
AS
BEGIN
	
	SET NOCOUNT ON;
	
	BEGIN TRY
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
		CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
					,SponsorId bigint
					,SponsorCategoryId bigint
					,LogoUrl nvarchar(512)
					,RedirectUrl nvarchar(512)
					,IsActive bit
					,DisplayOrder int
					,Target nvarchar(30)
					,InsertedTime datetime
					,InsertedBy nvarchar(64)
					,CategoryName nvarchar(512))

				
		SELECT @Start = (@PageNo - 1) * @Items  
	   
		SELECT @End = @Start + @Items 
	
		SET @Query = 'INSERT INTO #temp 
					  SELECT S.SponsorId
							,S.SponsorCategoryId
							,S.LogoUrl
							,S.RedirectUrl
							,S.IsActive
							,S.DisplayOrder
							,S.Target
							,S.InsertedTime
							,S.InsertedBy
							,SC.CategoryName
							FROM Sponsors S
							INNER JOIN SponsorCategories SC ON SC.SponsorCategoryId=S.SponsorCategoryId 		
							WHERE S.SponsorId <> 0'
		
		IF(@SponsorCategoryId <> 0)
			BEGIN
				SET @Query = @Query + ' AND SC.SponsorCategoryId= '+CAST(@SponsorCategoryId as nvarchar(250))
			END

		IF(@Search <> '')
			BEGIN
				SET @Query = @Query + ' AND  SC.CategoryName LIKE ''%' + @Search + '%'''
			END

		IF(@Sort <> '')
			BEGIN
				SET @Query = @Query + ' ORDER BY ' + @Sort
			END
	
		EXEC sp_ExecuteSQL @Query;
		
		SELECT @Total = COUNT(Rid) from #temp 
				
		SELECT * FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
		DROP TABLE #temp

	END TRY
    
    BEGIN CATCH  
       SELECT @Total = -1; 		   
    END CATCH   
END















