/****** Object:  StoredProcedure [dbo].[SponsorsInsert]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROCEDURE [dbo].[SponsorsInsert]  
    (@SponsorId bigint  
    ,@SponsorCategoryId bigint  
 ,@LogoUrl nvarchar(512) output  
 ,@RedirectUrl nvarchar(512)  
 ,@IsActive bit  
 ,@DisplayOrder int  
 ,@Target nvarchar(30)  
 ,@InsertedTime datetime  
 ,@InsertedBy nvarchar(64)  
 ,@QStatus int output)    
          
AS  
BEGIN  
   
 SET NOCOUNT ON;  
  
    BEGIN TRY  
    BEGIN TRANSACTION  
  
  IF((SELECT COUNT(*) FROM Sponsors WHERE SponsorId = @SponsorId) = 0)  
   BEGIN  
    INSERT INTO Sponsors VALUES  
     (@SponsorCategoryId   
     ,NULL   
     ,@RedirectUrl   
     ,@IsActive   
     ,@DisplayOrder   
     ,@Target  
     ,@InsertedTime   
     ,@InsertedBy   
     )   
    SET @SponsorId=SCOPE_IDENTITY()   
      
    SELECT @QStatus = 1;   
   END  
  ELSE  
   BEGIN  
    UPDATE Sponsors  
       SET SponsorCategoryId=@SponsorCategoryId,  
        RedirectUrl =@RedirectUrl ,  
        DisplayOrder=@DisplayOrder ,  
        InsertedTime=@InsertedTime , 
		 Target =@Target ,
        InsertedBy=@InsertedBy   
     WHERE SponsorId = @SponsorId  
        
     SELECT @QStatus = 1;   
   END  
  IF(@LogoUrl <> '')  
   BEGIN  
    UPDATE Sponsors  
       SET  LogoUrl= CAST(@SponsorId  AS nvarchar(12)) + '-' + dbo.RemoveSpecialChar(GETDATE(), '^a-z0-9') + '.' + @LogoUrl  
       WHERE SponsorId = @SponsorId   
  
    SELECT @LogoUrl =  (SELECT LogoUrl FROM Sponsors WHERE SponsorId=@SponsorId )  
   END   
  ELSE  
   BEGIN  
     SELECT @LogoUrl=''  
   END   
  
    COMMIT TRANSACTION  
    END TRY  
      
    BEGIN CATCH      
    ROLLBACK TRANSACTION  
  SELECT @QStatus = -1;      
    END CATCH      
END  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
