CREATE PROCEDURE [dbo].[SportsEventUserInfoGetById]  
 (@SportsEventUserInfoId bigint  
    ,@QStatus int OUTPUT)     
          
AS  
BEGIN  
  
   SET NOCOUNT ON;  
  
	   BEGIN TRY    
    
			 SELECT  DISTINCT  EUI.SportsEventUserInfoId
							  ,E.EventId   
							  ,E.EventName        
							  ,EUI.FirstName  
							  ,EUI.LastName  
							  ,EUI.Email  
							  ,EUI.Gender  
							  ,EUI.Address  
							  ,EUI.City  
							  ,EUI.State  
							  ,EUI.Mobile  
							  ,EUI.ItemName   
							  ,EUI.ItemCategory   
							  ,EUI.ItemDescription   
							  ,EUI.ItemDuration   
							  ,EUI.IsApproved  
							  ,EUI.DocumentUrl  
							  ,EUI.UpdatedBy  
							  ,EUI.UpdatedTime   
							  ,EC.EventCategory  
							  ,EC.EventCategoryId       
							  ,EUI.TransactionId  
							  ,EUI.AmountPaid  
							  ,PS.PaymentStatus  
							  FROM Events  E   
							 --INNER JOIN EventUsers EU ON E.EventId = EU.EventId   
							  INNER JOIN SportsEventUserInfo EUI ON E.EventId = EUI.EventId  
							  LEFT JOIN PaymentMethods PM ON PM.PaymentMethodId=EUI.PaymentMethodId   
							  LEFT JOIN PaymentStatus PS ON PS.PaymentStatusId=EUI.PaymentStatusId     
							  INNER JOIN EventCategories EC ON EC.EventCategoryId = E.EventCategoryId   
							  WHERE  EUI.SportsEventUserInfoId=@SportsEventUserInfoId  
    
		  SELECT @QStatus = 1;  
    
		END TRY  
    BEGIN CATCH  
   SELECT @QStatus = -1;  
    END CATCH    
    
END  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  
  


