	,@State nvarchar(156)
	,@Mobile nvarchar(15)
	,@ItemName nvarchar(1024)
	,@ItemCategory nvarchar(1024)
	,@ItemDescription nvarchar(1024)
	,@ItemDuration int
	,@IsApproved bit
	,@DocumentUrl nvarchar(156) 
	,@UpdatedBy nvarchar(64)
	,@UpdatedTime datetime
	,@EventOrderId bigint
	,@EventId bigint
	,@PaymentStatusId bigint
	,@PaymentDate datetime
	,@PaymentMethodId bigint
	,@TransactionId nvarchar(64)
	,@AmountPaid decimal(15,2)
	,@IsAttended bit
	,@ChildCount int
	,@AdultCount int
	,@CoupleCount int
	,@FamilyCount int
	,@VIPCount int
	,@VIPSingleAdultCount int
	,@VIPCoupleCount int
	,@VIPChildCount int
	,@InsertedBy nvarchar(30)
	,@InsertedDate datetime
	,@QStatus int output)  
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
    
		IF((SELECT COUNT(*) FROM SportsEventUserInfo WHERE SportsEventUserInfoId = @SportsEventUserInfoId) <> 0)
		BEGIN
			UPDATE SportsEventUserInfo
			   SET
					 FirstName				=	@FirstName 
					,LastName				=	@LastName 
					,Email					=	@Email 
					,Gender					=	@Gender 
					,Address				=	@Address 
					,City					=	@City 
					,State					=	@State 
					,Mobile					=	@Mobile 
					,ItemName				=	@ItemName
					,ItemCategory			=	@ItemCategory
					,ItemDescription		=	@ItemDescription
					,ItemDuration			=	@ItemDuration	 
					,DocumentUrl			=	@DocumentUrl 
					,UpdatedBy				=	@UpdatedBy 
					,UpdatedTime			=	@UpdatedTime
					,IsApproved				=	@IsApproved 
					,PaymentStatusId		=	@PaymentStatusId 
					,PaymentDate			=	@PaymentDate 
					,PaymentMethodId		=	@PaymentMethodId 
					,TransactionId			=	@TransactionId 
					,AmountPaid				=	@AmountPaid 
					,IsAttended				=	@IsAttended
			WHERE SportsEventUserInfoId	    =   @SportsEventUserInfoId
					
		SELECT @QStatus = 2;
		 
		END
		
	COMMIT TRANSACTION   
    END TRY
    
    BEGIN CATCH 
		ROLLBACK TRANSACTION     
		SELECT @QStatus = -1;    
    END CATCH   
    
END














