/****** Object:  StoredProcedure [dbo].[UpdateMemberOrderExpiryBySubId]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[UpdateMemberOrderExpiryBySubId]    
    @MemberId    BIGINT,    
    @ExpiryDate  DATETIME,  
    @QStatus     BIGINT OUTPUT  
AS    
BEGIN    
    SET NOCOUNT ON;    

    -- ✅ Only UPDATE ExpiryDate in latest order row
    -- No INSERT — just update existing row by MemberId
    UPDATE [dbo].[MembershipOrders]
    SET    [ExpiryDate] = @ExpiryDate
    WHERE  [MembershipOrderid] = (
        SELECT TOP 1 [MembershipOrderid]
        FROM   [dbo].[MembershipOrders]
        WHERE  [MemberId] = @MemberId
        ORDER  BY [OrderDate] DESC  -- ✅ latest order row
    )

    SET @QStatus = CASE WHEN @@ROWCOUNT > 0 THEN 1 ELSE 0 END
END
GO
/****** Object:  StoredProcedure [dbo].[UpdateMemberSubscriptions]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[UpdateMemberSubscriptions]  
    @MemberId           BIGINT,  
    @SubscriptionId     NVARCHAR(128),
    @ProfileId          NVARCHAR(128),  
    @PaymentProfileId   NVARCHAR(128),  
    @RecurringType      NVARCHAR(128),  
    @RecurringAmount    DECIMAL(15, 2),  
    @RecurringStartTime DATETIME,  
    @QStatus            INT OUTPUT  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    -- =============================================  
    -- Upsert MemberSubscriptions  
    -- =============================================  
    IF EXISTS (SELECT 1 FROM [dbo].[MemberSubscriptions] WHERE [MemberId] = @MemberId)  
    BEGIN  
        UPDATE [dbo].[MemberSubscriptions]  
        SET  
            [SubscriotionId]     = @SubscriptionId,
            [ProfileId]          = @ProfileId,  
            [PaymentProfileId]   = @PaymentProfileId,  
            [RecurringType]      = @RecurringType,  
            [RecurringAmount]    = @RecurringAmount,  
            [RecurringStartTime] = @RecurringStartTime  
        WHERE  
            [MemberId] = @MemberId;  
  
        SET @QStatus = CASE WHEN @@ROWCOUNT > 0 THEN 1 ELSE 0 END;  
    END  
    ELSE  
    BEGIN  
        INSERT INTO [dbo].[MemberSubscriptions]  
        (  
            [MemberId],  
            [SubscriotionId],
            [ProfileId],  
            [PaymentProfileId],  
            [RecurringType],  
            [RecurringAmount],  
            [RecurringStartTime]  
        )  
        VALUES  
        (  
            @MemberId,  
            @SubscriptionId,
            @ProfileId,  
            @PaymentProfileId,  
            @RecurringType,  
            @RecurringAmount,  
            @RecurringStartTime  
        );  
  
        SET @QStatus = CASE WHEN @@ROWCOUNT > 0 THEN 1 ELSE 0 END;  
    END  
  
    -- =============================================  
    -- ✅ FIX: Update ONLY the latest order row
    -- =============================================  
    UPDATE [dbo].[MembershipOrders]
    SET    [ExpiryDate] = @RecurringStartTime
    WHERE  [MembershipOrderid] = (
        SELECT TOP 1 [MembershipOrderid] 
        FROM [dbo].[MembershipOrders]
        WHERE [MemberId] = @MemberId
        ORDER BY [OrderDate] DESC  -- ✅ picks the most recent order
    );
  
END
