CREATE PROCEDURE [dbo].[UpdatePaymentMode]
    @PaymentSettingId INT,
    @AccountType NVARCHAR(10),
	@QStatus int output,
	@PaymentMethodId bigint
AS
BEGIN

SET NOCOUNT ON;
    
    BEGIN TRY 

    IF(@AccountType = 'Online')
    BEGIN
        UPDATE PaymentSettings 
        SET IsActive = 1 
        WHERE AccountType = 'Online' AND PaymentMethodId = @PaymentMethodId;

        UPDATE PaymentSettings 
        SET IsActive = 0
        WHERE AccountType = 'Test' AND PaymentMethodId = @PaymentMethodId;
    END
    ELSE IF(@AccountType = 'Test')
    BEGIN
        UPDATE PaymentSettings 
        SET IsActive = 1
        WHERE AccountType = 'Test' AND PaymentMethodId = @PaymentMethodId;

        UPDATE PaymentSettings 
        SET IsActive = 0
        WHERE AccountType = 'Online' AND PaymentMethodId = @PaymentMethodId;
    END

	SELECT @QStatus = 1;

	END TRY

    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH
END


