CREATE PROCEDURE [dbo].[UpdateSubscriptionNextDate]
    @MemberId        BIGINT,
    @SubscriptionId  NVARCHAR(128),
    @NextDate        DATETIME,
    @QStatus         INT OUTPUT     -- ✅ INT not BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE [dbo].[MemberSubscriptions]
    SET    [RecurringStartTime] = @NextDate
