/****** Object:  StoredProcedure [dbo].[UpdateSubscriptionStatus]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- ✅ FIX — add @QStatus OUTPUT
CREATE PROCEDURE [dbo].[UpdateSubscriptionStatus]
    @MemberId       BIGINT,
    @SubscriptionId NVARCHAR(128),
    @Status         NVARCHAR(50),
    @QStatus        INT OUTPUT      -- ✅ ADD THIS
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PaymentStatusId INT
    SET @PaymentStatusId = CASE
        WHEN @Status = 'CANCELED'    THEN 2
        WHEN @Status = 'DEACTIVATED' THEN 2
        WHEN @Status = 'ACTIVE'      THEN 1
        WHEN @Status = 'Completed'   THEN 1
        ELSE 2
    END

    UPDATE [dbo].[MemberSubscriptions]
    SET    [RecurringType] = @Status
    WHERE  [MemberId]       = @MemberId
    AND    [SubscriotionId] = @SubscriptionId

    UPDATE [dbo].[MembershipOrders]
    SET    [PaymentStatusId] = @PaymentStatusId
    WHERE  [MembershipOrderid] = (
        SELECT TOP 1 [MembershipOrderid]
        FROM   [dbo].[MembershipOrders]
        WHERE  [MemberId] = @MemberId
        ORDER  BY [OrderDate] DESC
    )

    -- ✅ ADD THIS
    SET @QStatus = CASE WHEN @@ROWCOUNT > 0 THEN 1 ELSE 0 END
END
GO
