CREATE PROCEDURE [dbo].[UserRolesGetList]
	(@QStatus int OUTPUT
	,@keyword nvarchar(512))    
        
AS
BEGIN
	
   SET NOCOUNT ON;
   
    BEGIN TRY 
	IF(@keyword <> '')
	BEGIN
	SELECT  R.*, (SELECT COUNT(*) FROM Roles UR WHERE R.RoleId IN(UR.ParentId)) AS SubRoleCount, (SELECT STRING_AGG(CAST(RoleId AS VARCHAR), ',') FROM Roles RO WHERE R.RoleId IN(RO.ParentId)) AS comma_separated_ids FROM Roles R WHERE R.RoleName<>'SuperAdmin' AND R.RoleName<>'DeveloperAdmin' AND R.IsActive = 1 AND R.ParentId IS NULL AND R.RoleName LIKE '%' + @keyword + '%' ORDER BY R.UpdatedTime DESC
	END
	ELSE
	BEGIN
		 SELECT  R.*, (SELECT COUNT(*) FROM Roles UR WHERE R.RoleId IN(UR.ParentId)) AS SubRoleCount, (SELECT STRING_AGG(CAST(RoleId AS VARCHAR), ',') FROM Roles RO WHERE R.RoleId IN(RO.ParentId)) AS comma_separated_ids FROM Roles R WHERE R.RoleName<>'SuperAdmin' AND R.RoleName<>'DeveloperAdmin' AND R.IsActive = 1 AND R.ParentId IS NULL ORDER BY R.UpdatedTime DESC
	END	 
	SELECT @QStatus = 1;
    END TRY
    
    BEGIN CATCH
		 SELECT @QStatus = -1;
    END CATCH	
	 
END







