/****** Object:  StoredProcedure [dbo].[UsersProfileInsert]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[UsersProfileInsert]  
    (@UserId int  
    ,@ChapterId BIGINT  
    ,@UserName nvarchar(64)  
    ,@RoleName nvarchar(128)  
    ,@Email nvarchar(128)  
    ,@Designation nvarchar(1024)  
    ,@MobilePhone nvarchar(64)  
    ,@IsApproved bit  
    ,@IsLockedOut bit  
    ,@IsActivated bit  
    ,@DateActivated datetime  
    ,@RegistrationGUID uniqueidentifier   
    ,@FailedPasswordAttemptCount int  
    ,@LastPasswordChangedDate datetime  
    ,@LastLoginDate datetime  
    ,@InsertedTime datetime  
    ,@InsertedBy nvarchar(64)  
    ,@UpdatedTime datetime  
    ,@UpdatedBy nvarchar(64)  
    ,@MemberId BIGINT  
    ,@ChapterIds nvarchar(max)   
    ,@RoleId BIGINT  
    ,@QStatus int output)    
AS  
BEGIN  
    SET NOCOUNT ON;  

    -- Check if user already exists
    IF((SELECT COUNT(*) FROM Users WHERE UserId = @UserId) = 0)  
    BEGIN  

        -- Insert into Users table
        INSERT INTO Users VALUES  
            (@ChapterId  
            ,@UserName  
            ,@Email  
            -- FIXED: Safe password lookup with TOP 1 and ISNULL fallback
            ,ISNULL((SELECT TOP 1 Password FROM Members M WHERE M.Email = @Email), NULL)
            ,NULL  
            ,@Designation  
            ,@MobilePhone  
            ,@IsApproved  
            ,@IsLockedOut  
            ,@IsActivated  
            ,@DateActivated  
            ,@RegistrationGUID  
            ,@FailedPasswordAttemptCount  
            ,@LastPasswordChangedDate  
            ,@LastLoginDate  
            ,@InsertedTime  
            ,@InsertedBy  
            ,@UpdatedTime  
            ,@UpdatedBy  
            ,(SELECT TOP 1 RoleName FROM Roles WHERE RoleId = @RoleId)  
            )  

        -- Get the newly inserted UserId
        SELECT @UserId = SCOPE_IDENTITY()    

        -- Insert user roles from Role_Menu_Master
        INSERT INTO UserRoles
            (UserId, RoleId, IsEdit, IsAdd, IsView, IsDelete, IsExport, MenuId)
        SELECT 
            @UserId, RoleId, IsEdit, IsAdd, IsView, IsDelete, IsExport, MenuId 
        FROM Role_Menu_Master 
        WHERE RoleId = @RoleId

        -- FIXED: ChapterIds block moved INSIDE main BEGIN/END
        IF(@ChapterIds IS NOT NULL AND @ChapterIds <> '')  
        BEGIN  
            -- Remove existing chapter associations
            DELETE FROM ChapterUsers WHERE UserId = @UserId  

            -- Parse ChapterIds and insert
            DECLARE @table1 TABLE 
                (RowID int NOT NULL PRIMARY KEY IDENTITY(1,1), col1 int)    

            INSERT INTO @table1 (col1) 
            SELECT part FROM SplitString(@ChapterIds)  

            IF((SELECT COUNT(*) FROM @table1) > 0)  
            BEGIN  
                DECLARE @RowCount1 AS int  
                DECLARE @CurrentRow1 AS int   

                SET @RowCount1 = (SELECT COUNT(*) FROM @table1)  
                SET @CurrentRow1 = 1  

                WHILE @CurrentRow1 <= @RowCount1   
                BEGIN  
                    INSERT INTO ChapterUsers VALUES   
                    (
                        (SELECT col1 FROM @table1 WHERE RowID = @CurrentRow1)
                        ,@UserId
                    )  
                    SET @CurrentRow1 = @CurrentRow1 + 1  
                END  
            END   
        END  

        -- FIXED: QStatus = 1 only after everything succeeds
        SELECT @QStatus = 1  

    END  
    ELSE  
    BEGIN
        -- User already exists
        SELECT @QStatus = 0  
    END

END
