CREATE PROCEDURE [dbo].[UsersUpdateStatus]
    (@UserId bigint
    ,@QStatus int output)  
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
    BEGIN TRY    
    BEGIN TRANSACTION
    
		IF((SELECT IsApproved FROM Users WHERE UserId = @UserId) = 1)
			BEGIN
