/****** Object:  StoredProcedure [dbo].[VideoCategoriesGetListByVariable]    Script Date: 6/16/2026 1:20:33 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[VideoCategoriesGetListByVariable]
	 (@ChapterId bigint
	 ,@PageNo int
     ,@Items int
     ,@Search nvarchar(126)
     ,@Total int output
     ,@Sort nvarchar(126))
AS
BEGIN
	
	SET NOCOUNT ON;
	
	DECLARE @Start int, @End INT ;
	DECLARE @Query nvarchar(max);
	
    
    CREATE TABLE #temp(Rid INT PRIMARY KEY IDENTITY(1,1)
				,VideoCategoryId bigint
				,ChapterId bigint
				,CategoryName nvarchar(512) 
				,Year bigint
				,UpdatedBy nvarchar(64)
				,UpdatedTime datetime
				,VideosCount bigint
				,ChapterName nvarchar(512))
	
	SELECT @Start = (@PageNo - 1) * @Items     
	SELECT @End = @Start + @Items 
	
	SET @Query = 'INSERT INTO #temp 
		 SELECT  V.VideoCategoryId
		        ,V.ChapterId 
				,V.CategoryName
				,V.Year 
				,V.UpdatedBy
				,V.UpdatedTime
				,(SELECT COUNT(*) FROM Videos VV WHERE V.VideoCategoryId = VV.VideoCategoryId) AS VideosCount
				,C.ChapterName
		        FROM VideoCategories V  
		        INNER JOIN Chapters C ON C.ChapterId = V.ChapterId
		        WHERE V.VideoCategoryId <> 0 '
	
	
	IF(@ChapterId <> 0)
	BEGIN
		SET @Query=@Query + 'AND V.ChapterId = ' + CAST(@ChapterId AS nvarchar(30))
	END  

	IF(@Search <> '')
    BEGIN
		SET @Query = @Query + ' AND  CategoryName LIKE ''%' + @Search + '%'''
    END
	
	IF(@Sort <> '')
	BEGIN
		SET @Query = @Query + ' ORDER BY ' + @Sort
	END
	
    EXEC sp_ExecuteSQL @Query;
	
	SELECT @Total = COUNT(Rid) from #temp 
			
	SELECT *  FROM #temp WHERE Rid > @Start AND  Rid <= @End
	
	DROP TABLE #temp

END

























