CREATE PROCEDURE [dbo].[VolunteerCategoriesInsert]
    (@VolunteerCategoryId bigint
	,@ChapterId bigint
	,@CategoryName nvarchar(128)
	,@OrderNo int
	,@IsActive bit
	,@QStatus int output
	,@VolunteerHours int)  
        
AS
BEGIN

	SET NOCOUNT ON;
    
    BEGIN TRY
		BEGIN TRANSACTION
		IF((SELECT COUNT(*) FROM VolunteerCategories WHERE VolunteerCategoryId = @VolunteerCategoryId OR CategoryName=@CategoryName) = 0)
			BEGIN
				INSERT INTO VolunteerCategories VALUES
					(@ChapterId
					,@CategoryName
					,@OrderNo
					,@IsActive
					,@VolunteerHours)		
			
				SELECT @QStatus = 1;	
			END
		ELSE 
			BEGIN
				IF((SELECT COUNT(*) FROM VolunteerCategories WHERE CategoryName=@CategoryName AND VolunteerCategoryId <> @VolunteerCategoryId) = 0)
				BEGIN
					UPDATE VolunteerCategories
					   SET ChapterId=@ChapterId,
						  CategoryName =@CategoryName,
						   OrderNo=@OrderNo,
						   VolunteerHours=@VolunteerHours
			  
					 WHERE VolunteerCategoryId = @VolunteerCategoryId
		 		 
					 SELECT @QStatus = 2;	
					END
				ELSE
					BEGIN
					SELECT @QStatus = 3; 
					END 
			END
		COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH    
        ROLLBACK TRANSACTION
		SELECT @QStatus = -1;    
    END CATCH    
END

















