CREATE PROCEDURE [dbo].[VolunteersInsert]
    (@VolunteerId bigint 
	,@VolunteerCategoryId bigint
	,@EventId bigint
	,@FirstName nvarchar(128)
	,@LastName nvarchar(128)
	,@Email nvarchar(128)
	,@PhoneNo nvarchar(20)
	,@Address nvarchar(1024)
	,@Comments nvarchar(2048)
	,@HoursSpent nvarchar(256)
	,@Field1 nvarchar(512)
	,@Field2 nvarchar(256)
	,@IsActive bit
	,@InsertedBy nvarchar(30)
	,@InsertedDate datetime
	,@UpdatedBy nvarchar(30)
	,@UpdatedDate datetime
	,@MemberId bigint
	,@QStatus int output
	,@Country nvarchar(512)
    ,@City nvarchar(512)
    ,@State nvarchar(512)
    ,@ZipCode nvarchar(512)
    ,@Address2 nvarchar(max)
    ,@ChapterId bigint)  
        
AS
BEGIN
	
	SET NOCOUNT ON;
    
    BEGIN TRY
    BEGIN TRANSACTION
    
		IF((SELECT COUNT(*) FROM Volunteers WHERE VolunteerId = @VolunteerId) = 0)
			BEGIN
				INSERT INTO Volunteers VALUES
					   (@VolunteerCategoryId
					   ,@EventId
						,@FirstName
						,@LastName 
						,@Email
						,@PhoneNo 
						,@Address 
						,@Comments
						,@HoursSpent
						,@Field1
						,@Field2 
						,@IsActive 
						,@InsertedBy 
						,@InsertedDate 
						,@UpdatedBy
						,@UpdatedDate
						,@MemberId 
						,@Country 
						,@City 
						,@State 
						,@ZipCode 
						,@Address2 
						,@ChapterId)
						SELECT @QStatus = 1;
			END
		ELSE 
			BEGIN
				UPDATE Volunteers
				   SET 
						VolunteerCategoryId = @VolunteerCategoryId,
						EventId = @EventId,
						FirstName=@FirstName,
						LastName=@LastName ,
						Email=@Email ,
						PhoneNo=@PhoneNo ,
						Address=@Address ,
						Comments=@Comments ,
						HoursSpent = @HoursSpent,
						UpdatedBy=@UpdatedBy,
						UpdatedDate=@UpdatedDate,
						MemberId = @MemberId,
						Country=@Country ,
						City =@City ,
						State=@State ,
						ZipCode =@ZipCode,
						Address2 =@Address2,
						ChapterId=@ChapterId 

				 WHERE VolunteerId = @VolunteerId
			 		 
				 SELECT @QStatus = 2;
			 
			 END

		 IF(@EventId <> 0)
			  BEGIN
			  Insert into EventVolunteers
			  Select @EventId,
					 @VolunteerId,
					 @MemberId
 
			  END
		 
		COMMIT TRANSACTION
    END TRY
    
    BEGIN CATCH  
    
		ROLLBACK TRANSACTION   
		SELECT @QStatus = -1;    
		
    END CATCH   
    
END




















